window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["SNG"]={"book":"SNG","editions":{"hbo-source":[[1,1,"שִׁ֥יר הַ⁠שִּׁירִ֖ים אֲשֶׁ֥ר לִ⁠שְׁלֹמֹֽה׃","şǐ֥yr ha⁠şi̇̌yri֖ym ʼàşě֥r li⁠şĕ̌lòmòֽh׃"],[1,2,"יִשָּׁקֵ֨⁠נִי֙ מִ⁠נְּשִׁיק֣וֹת פִּ֔י⁠הוּ כִּֽי־טוֹבִ֥ים דֹּדֶ֖י⁠ךָ מִ⁠יָּֽיִן׃","yişá̇̌qé֨⁠niy֙ mi⁠nĕ̇şǐyq֣wòţ pi̇֔y⁠hẇ kiֽ̇y-twòbi֥ym dò̇de֖y⁠ká mi⁠yáֽ̇yin׃"],[1,3,"לְ⁠רֵ֨יחַ֙ שְׁמָנֶ֣י⁠ךָ טוֹבִ֔ים שֶׁ֖מֶן תּוּרַ֣ק שְׁמֶ֑⁠ךָ עַל־כֵּ֖ן עֲלָמ֥וֹת אֲהֵבֽוּ⁠ךָ׃","lĕ⁠ré֨yẖa֙ şĕ̌máne֣y⁠ká twòbi֔ym şě֖men ţ̇ẇra֣q şĕ̌me֑⁠ká ʻal-ké֖̇n ʻàlám֥wòţ ʼàhébֽẇ⁠ká׃"],[1,4,"מָשְׁכֵ֖⁠נִי אַחֲרֶ֣י⁠ךָ נָּר֑וּצָה הֱבִיאַ֨⁠נִי הַ⁠מֶּ֜לֶךְ חֲדָרָ֗י⁠ו נָגִ֤ילָה וְ⁠נִשְׂמְחָה֙ בָּ֔⁠ךְ נַזְכִּ֤ירָה דֹדֶ֨י⁠ךָ֙ מִ⁠יַּ֔יִן מֵישָׁרִ֖ים אֲהֵבֽוּ⁠ךָ׃ס","máşĕ̌ké֖⁠niy ʼaẖàre֣y⁠ká ná̇r֑ẇẕáh hèbiyʼa֨⁠niy ha⁠mė֜lekĕ ẖàdárá֗y⁠w nági֤yláh wĕ⁠nişĕ̂mĕẖáh֙ bá̇֔⁠kĕ nazĕki֤̇yráh dòde֨y⁠ká֙ mi⁠yȧ֔yin méyşá̌ri֖ym ʼàhébֽẇ⁠ká׃s"],[1,5,"שְׁחוֹרָ֤ה אֲנִי֙ וְֽ⁠נָאוָ֔ה בְּנ֖וֹת יְרוּשָׁלִָ֑ם כְּ⁠אָהֳלֵ֣י קֵדָ֔ר כִּ⁠ירִיע֖וֹת שְׁלֹמֹֽה׃","şĕ̌ẖwòrá֤h ʼàniy֙ wĕֽ⁠náʼwá֔h bĕ̇n֖wòţ yĕrẇşá̌liá֑m kĕ̇⁠ʼáholé֣y qédá֔r ki̇⁠yriyʻ֖wòţ şĕ̌lòmòֽh׃"],[1,6,"אַל־תִּרְא֨וּ⁠נִי֙ שֶׁ⁠אֲנִ֣י שְׁחַרְחֹ֔רֶת שֶׁ⁠שֱּׁזָפַ֖תְ⁠נִי הַ⁠שָּׁ֑מֶשׁ בְּנֵ֧י אִמִּ֣⁠י נִֽחֲרוּ־בִ֗⁠י שָׂמֻ֨⁠נִי֙ נֹטֵרָ֣ה אֶת־הַ⁠כְּרָמִ֔ים כַּרְמִ֥⁠י שֶׁ⁠לִּ֖⁠י לֹ֥א נָטָֽרְתִּי׃","ʼal-ţi̇rĕʼ֨ẇ⁠niy֙ şě⁠ʼàni֣y şĕ̌ẖarĕẖò֔reţ şě⁠şè̇̌zápa֖ţĕ⁠niy ha⁠şá֑̇̌meş̌ bĕ̇né֧y ʼimi֣̇⁠y niֽẖàrẇ-bi֗⁠y şá̂mu֨⁠niy֙ nòtérá֣h ʼeţ-ha⁠kĕ̇rámi֔ym kȧrĕmi֥⁠y şě⁠li֖̇⁠y lò֥ʼ nátáֽrĕţi̇y׃"],[1,7,"הַגִּ֣ידָ⁠ה לִּ֗⁠י שֶׁ֤⁠אָהֲבָה֙ נַפְשִׁ֔⁠י אֵיכָ֣ה תִרְעֶ֔ה אֵיכָ֖ה תַּרְבִּ֣יץ בַּֽ⁠צָּהֳרָ֑יִם שַׁ⁠לָּ⁠מָ֤ה אֶֽהְיֶה֙ כְּ⁠עֹ֣טְיָ֔ה עַ֖ל עֶדְרֵ֥י חֲבֵרֶֽי⁠ךָ׃","hagi֣̇ydá⁠h li̇֗⁠y şě֤⁠ʼáhàbáh֙ napĕşǐ֔⁠y ʼéyká֣h ţirĕʻe֔h ʼéyká֖h ţȧrĕbi֣̇yẕ bȧֽ⁠ẕá̇horá֑yim şǎ⁠lá̇⁠má֤h ʼeֽhĕyeh֙ kĕ̇⁠ʻò֣tĕyá֔h ʻa֖l ʻedĕré֥y ẖàbéreֽy⁠ká׃"],[1,8,"אִם־לֹ֤א תֵדְעִי֙ לָ֔⁠ךְ הַ⁠יָּפָ֖ה בַּ⁠נָּשִׁ֑ים צְֽאִי־לָ֞⁠ךְ בְּ⁠עִקְבֵ֣י הַ⁠צֹּ֗אן וּ⁠רְעִי֙ אֶת־גְּדִיֹּתַ֔יִ⁠ךְ עַ֖ל מִשְׁכְּנ֥וֹת הָ⁠רֹעִֽים׃ס","ʼim-lò֤ʼ ţédĕʻiy֙ lá֔⁠kĕ ha⁠yá̇pá֖h bȧ⁠ná̇şǐ֑ym ẕĕֽʼiy-lá֞⁠kĕ bĕ̇⁠ʻiqĕbé֣y ha⁠ẕò̇֗ʼn ẇ⁠rĕʻiy֙ ʼeţ-gĕ̇diyò̇ţa֔yi⁠kĕ ʻa֖l mişĕ̌kĕ̇n֥wòţ há⁠ròʻiֽym׃s"],[1,9,"לְ⁠סֻסָתִ⁠י֙ בְּ⁠רִכְבֵ֣י פַרְעֹ֔ה דִּמִּיתִ֖י⁠ךְ רַעְיָתִֽ⁠י׃","lĕ⁠susáţi⁠y֙ bĕ̇⁠rikĕbé֣y parĕʻò֔h di̇mi̇yţi֖y⁠kĕ raʻĕyáţiֽ⁠y׃"],[1,10,"נָאו֤וּ לְחָיַ֨יִ⁠ךְ֙ בַּ⁠תֹּרִ֔ים צַוָּארֵ֖⁠ךְ בַּ⁠חֲרוּזִֽים׃","náʼw֤ẇ lĕẖáya֨yi⁠kĕ֙ bȧ⁠ţò̇ri֔ym ẕawá̇ʼré֖⁠kĕ bȧ⁠ẖàrẇziֽym׃"],[1,11,"תּוֹרֵ֤י זָהָב֙ נַעֲשֶׂה־לָּ֔⁠ךְ עִ֖ם נְקֻדּ֥וֹת הַ⁠כָּֽסֶף׃","ţ̇wòré֤y záháb֙ naʻàşêh-lá̇֔⁠kĕ ʻi֖m nĕquḋ֥wòţ ha⁠káֽ̇sep׃"],[1,12,"עַד־שֶׁ֤⁠הַ⁠מֶּ֨לֶךְ֙ בִּ⁠מְסִבּ֔⁠וֹ נִרְדִּ֖⁠י נָתַ֥ן רֵיחֽ⁠וֹ׃","ʻad-şě֤⁠ha⁠mė֨lekĕ֙ bi̇⁠mĕsiḃ֔⁠wò nirĕdi֖̇⁠y náţa֥n réyẖֽ⁠wò׃"],[1,13,"צְר֨וֹר הַ⁠מֹּ֤ר ׀ דּוֹדִ⁠י֙ לִ֔⁠י בֵּ֥ין שָׁדַ֖⁠י יָלִֽין׃","ẕĕr֨wòr ha⁠mò֤̇r ׀ ḋwòdi⁠y֙ li֔⁠y bé֥̇yn şá̌da֖⁠y yáliֽyn׃"],[1,14,"אֶשְׁכֹּ֨ל הַ⁠כֹּ֤פֶר ׀ דּוֹדִ⁠י֙ לִ֔⁠י בְּ⁠כַרְמֵ֖י עֵ֥ין גֶּֽדִי׃ס","ʼeşĕ̌kò̇֨l ha⁠kò֤̇per ׀ ḋwòdi⁠y֙ li֔⁠y bĕ̇⁠karĕmé֖y ʻé֥yn gėֽdiy׃s"],[1,15,"הִנָּ֤⁠ךְ יָפָה֙ רַעְיָתִ֔⁠י הִנָּ֥⁠ךְ יָפָ֖ה עֵינַ֥יִ⁠ךְ יוֹנִֽים׃","hiná֤̇⁠kĕ yápáh֙ raʻĕyáţi֔⁠y hiná֥̇⁠kĕ yápá֖h ʻéyna֥yi⁠kĕ ywòniֽym׃"],[1,16,"הִנְּ⁠ךָ֨ יָפֶ֤ה דוֹדִ⁠י֙ אַ֣ף נָעִ֔ים אַף־עַרְשֵׂ֖⁠נוּ רַעֲנָנָֽה׃","hinĕ̇⁠ká֨ yápe֤h dwòdi⁠y֙ ʼa֣p náʻi֔ym ʼap-ʻarĕşé֖̂⁠nẇ raʻànánáֽh׃"],[1,17,"קֹר֤וֹת בָּתֵּ֨י⁠נוּ֙ אֲרָזִ֔ים רחיט⁠נו בְּרוֹתִֽים׃","qòr֤wòţ bá̇ţé̇֨y⁠nẇ֙ ʼàrázi֔ym rẖyt⁠nw bĕ̇rwòţiֽym׃"],[2,1,"אֲנִי֙ חֲבַצֶּ֣לֶת הַ⁠שָּׁר֔וֹן שֽׁוֹשַׁנַּ֖ת הָ⁠עֲמָקִֽים׃","ʼàniy֙ ẖàbaẕė֣leţ ha⁠şá̇̌r֔wòn şֽ̌wòşǎnȧ֖ţ há⁠ʻàmáqiֽym׃"],[2,2,"כְּ⁠שֽׁוֹשַׁנָּה֙ בֵּ֣ין הַ⁠חוֹחִ֔ים כֵּ֥ן רַעְיָתִ֖⁠י בֵּ֥ין הַ⁠בָּנֽוֹת׃","kĕ̇⁠şֽ̌wòşǎná̇h֙ bé֣̇yn ha⁠ẖwòẖi֔ym ké֥̇n raʻĕyáţi֖⁠y bé֥̇yn ha⁠bá̇nֽwòţ׃"],[2,3,"כְּ⁠תַפּ֨וּחַ֙ בַּ⁠עֲצֵ֣י הַ⁠יַּ֔עַר כֵּ֥ן דּוֹדִ֖⁠י בֵּ֣ין הַ⁠בָּנִ֑ים בְּ⁠צִלּ⁠וֹ֙ חִמַּ֣דְתִּי וְ⁠יָשַׁ֔בְתִּי וּ⁠פִרְי֖⁠וֹ מָת֥וֹק לְ⁠חִכִּֽ⁠י׃","kĕ̇⁠ţaṗ֨ẇẖa֙ bȧ⁠ʻàẕé֣y ha⁠yȧ֔ʻar ké֥̇n ḋwòdi֖⁠y bé֣̇yn ha⁠bá̇ni֑ym bĕ̇⁠ẕil̇⁠wò֙ ẖimȧ֣dĕţi̇y wĕ⁠yáşǎ֔bĕţi̇y ẇ⁠pirĕy֖⁠wò máţ֥wòq lĕ⁠ẖikiֽ̇⁠y׃"],[2,4,"הֱבִיאַ֨⁠נִי֙ אֶל־בֵּ֣ית הַ⁠יָּ֔יִן וְ⁠דִגְל֥⁠וֹ עָלַ֖⁠י אַהֲבָֽה׃","hèbiyʼa֨⁠niy֙ ʼel-bé֣̇yţ ha⁠yá̇֔yin wĕ⁠digĕl֥⁠wò ʻála֖⁠y ʼahàbáֽh׃"],[2,5,"סַמְּכ֨וּ⁠נִי֙ בָּֽ⁠אֲשִׁישׁ֔וֹת רַפְּד֖וּ⁠נִי בַּ⁠תַּפּוּחִ֑ים כִּי־חוֹלַ֥ת אַהֲבָ֖ה אָֽנִי׃","samĕ̇k֨ẇ⁠niy֙ báֽ̇⁠ʼàşǐyş̌֔wòţ rapĕ̇d֖ẇ⁠niy bȧ⁠ţȧṗẇẖi֑ym ki̇y-ẖwòla֥ţ ʼahàbá֖h ʼáֽniy׃"],[2,6,"שְׂמֹאל⁠וֹ֙ תַּ֣חַת לְ⁠רֹאשִׁ֔⁠י וִ⁠ימִינ֖⁠וֹ תְּחַבְּקֵֽ⁠נִי׃","şĕ̂mòʼl⁠wò֙ ţȧ֣ẖaţ lĕ⁠ròʼşǐ֔⁠y wi⁠ymiyn֖⁠wò ţĕ̇ẖabĕ̇qéֽ⁠niy׃"],[2,7,"הִשְׁבַּ֨עְתִּי אֶתְ⁠כֶ֜ם בְּנ֤וֹת יְרוּשָׁלִַ֨ם֙ בִּ⁠צְבָא֔וֹת א֖וֹ בְּ⁠אַיְל֣וֹת הַ⁠שָּׂדֶ֑ה אִם־תָּעִ֧ירוּ ׀ וְֽ⁠אִם־תְּעֽוֹרְר֛וּ אֶת־הָ⁠אַהֲבָ֖ה עַ֥ד שֶׁ⁠תֶּחְפָּֽץ׃ס","hişĕ̌bȧ֨ʻĕţi̇y ʼeţĕ⁠ke֜m bĕ̇n֤wòţ yĕrẇşá̌lia֨m֙ bi̇⁠ẕĕbáʼ֔wòţ ʼ֖wò bĕ̇⁠ʼayĕl֣wòţ ha⁠şá̇̂de֑h ʼim-ţá̇ʻi֧yrẇ ׀ wĕֽ⁠ʼim-ţĕ̇ʻֽwòrĕr֛ẇ ʼeţ-há⁠ʼahàbá֖h ʻa֥d şě⁠ţėẖĕpáֽ̇ẕ׃s"],[2,8,"ק֣וֹל דּוֹדִ֔⁠י הִנֵּה־זֶ֖ה בָּ֑א מְדַלֵּג֙ עַל־הֶ֣⁠הָרִ֔ים מְקַפֵּ֖ץ עַל־הַ⁠גְּבָעֽוֹת׃","q֣wòl ḋwòdi֔⁠y hiné̇h-ze֖h bá֑̇ʼ mĕdalé̇g֙ ʻal-he֣⁠hári֔ym mĕqapé֖̇ẕ ʻal-ha⁠gĕ̇báʻֽwòţ׃"],[2,9,"דּוֹמֶ֤ה דוֹדִ⁠י֙ לִ⁠צְבִ֔י א֖וֹ לְ⁠עֹ֣פֶר הָֽ⁠אַיָּלִ֑ים הִנֵּה־זֶ֤ה עוֹמֵד֙ אַחַ֣ר כָּתְלֵ֔⁠נוּ מַשְׁגִּ֨יחַ֙ מִן־הַֽ⁠חֲלֹּנ֔וֹת מֵצִ֖יץ מִן־הַֽ⁠חֲרַכִּֽים׃","ḋwòme֤h dwòdi⁠y֙ li⁠ẕĕbi֔y ʼ֖wò lĕ⁠ʻò֣per háֽ⁠ʼayá̇li֑ym hiné̇h-ze֤h ʻwòméd֙ ʼaẖa֣r ká̇ţĕlé֔⁠nẇ maşĕ̌gi̇֨yẖa֙ min-haֽ⁠ẖàlò̇n֔wòţ méẕi֖yẕ min-hֽa⁠ẖàrakiֽ̇ym׃"],[2,10,"עָנָ֥ה דוֹדִ֖⁠י וְ⁠אָ֣מַר לִ֑⁠י ק֥וּמִי לָ֛⁠ךְ רַעְיָתִ֥⁠י יָפָתִ֖⁠י וּ⁠לְכִי־לָֽ⁠ךְ׃","ʻáná֥h dwòdi֖⁠y wĕ⁠ʼá֣mar li֑⁠y q֥ẇmiy lá֛⁠kĕ raʻĕyáţi֥⁠y yápáţi֖⁠y ẇ⁠lĕkiy-láֽ⁠kĕ׃"],[2,11,"כִּֽי־הִנֵּ֥ה ה⁠סתו עָבָ֑ר הַ⁠גֶּ֕שֶׁם חָלַ֖ף הָלַ֥ךְ לֽ⁠וֹ׃","kiֽ̇y-hiné֥̇h h⁠sţw ʻábá֑r ha⁠gė֕şěm ẖála֖p hála֥kĕ lֽ⁠wò׃"],[2,12,"הַ⁠נִּצָּנִים֙ נִרְא֣וּ בָ⁠אָ֔רֶץ עֵ֥ת הַ⁠זָּמִ֖יר הִגִּ֑יעַ וְ⁠ק֥וֹל הַ⁠תּ֖וֹר נִשְׁמַ֥ע בְּ⁠אַרְצֵֽ⁠נוּ׃","ha⁠ni̇ẕá̇niym֙ nirĕʼ֣ẇ bá⁠ʼá֔reẕ ʻé֥ţ ha⁠zá̇mi֖yr higi֑̇yʻa wĕ⁠q֥wòl ha⁠ţ֖̇wòr nişĕ̌ma֥ʻ bĕ̇⁠ʼarĕẕéֽ⁠nẇ׃"],[2,13,"הַ⁠תְּאֵנָה֙ חָֽנְטָ֣ה פַגֶּ֔י⁠הָ וְ⁠הַ⁠גְּפָנִ֥ים ׀ סְמָדַ֖ר נָ֣תְנוּ רֵ֑יחַ ק֥וּמִי לכי רַעְיָתִ֥⁠י יָפָתִ֖⁠י וּ⁠לְכִי־לָֽ⁠ךְ׃ס","ha⁠ţĕ̇ʼénáh֙ ẖáֽnĕtá֣h pagė֔y⁠há wĕ⁠ha⁠gĕ̇páni֥ym ׀ sĕmáda֖r ná֣ţĕnẇ ré֑yẖa q֥ẇmiy lky raʻĕyáţi֥⁠y yápáţi֖⁠y ẇ⁠lĕkiy-láֽ⁠kĕ׃s"],[2,14,"יוֹנָתִ֞⁠י בְּ⁠חַגְוֵ֣י הַ⁠סֶּ֗לַע בְּ⁠סֵ֨תֶר֙ הַ⁠מַּדְרֵגָ֔ה הַרְאִ֨י⁠נִי֙ אֶתּ־מַרְאַ֔יִ⁠ךְ הַשְׁמִיעִ֖י⁠נִי אֶת־קוֹלֵ֑⁠ךְ כִּי־קוֹלֵ֥⁠ךְ עָרֵ֖ב וּ⁠מַרְאֵ֥י⁠ךְ נָאוֶֽה׃ס","ywònáţi֞⁠y bĕ̇⁠ẖagĕwé֣y ha⁠sė֗laʻ bĕ̇⁠sé֨ţer֙ ha⁠mȧdĕrégá֔h harĕʼi֨y⁠niy֙ ʼeţ̇-marĕʼa֔yi⁠kĕ haşĕ̌miyʻi֖y⁠niy ʼeţ-qwòlé֑⁠kĕ ki̇y-qwòlé֥⁠kĕ ʻáré֖b ẇ⁠marĕʼé֥y⁠kĕ náʼweֽh׃s"],[2,15,"אֶֽחֱזוּ־לָ֨⁠נוּ֙ שֽׁוּעָלִ֔ים שֽׁוּעָלִ֥ים קְטַנִּ֖ים מְחַבְּלִ֣ים כְּרָמִ֑ים וּ⁠כְרָמֵ֖י⁠נוּ סְמָדַֽר׃","ʼeֽẖèzẇ-lá֨⁠nẇ֙ şֽ̌ẇʻáli֔ym şֽ̌ẇʻáli֥ym qĕtani֖̇ym mĕẖabĕ̇li֣ym kĕ̇rámi֑ym ẇ⁠kĕrámé֖y⁠nẇ sĕmádaֽr׃"],[2,16,"דּוֹדִ֥⁠י לִ⁠י֙ וַ⁠אֲנִ֣י ל֔⁠וֹ הָ⁠רֹעֶ֖ה בַּ⁠שּׁוֹשַׁנִּֽים׃","ḋwòdi֥⁠y li⁠y֙ wa⁠ʼàni֣y l֔⁠wò há⁠ròʻe֖h bȧ⁠ş̇̌wòşǎniֽ̇ym׃"],[2,17,"עַ֤ד שֶׁ⁠יָּפ֨וּחַ֙ הַ⁠יּ֔וֹם וְ⁠נָ֖סוּ הַ⁠צְּלָלִ֑ים סֹב֩ דְּמֵה־לְ⁠ךָ֨ דוֹדִ֜⁠י לִ⁠צְבִ֗י א֛וֹ לְ⁠עֹ֥פֶר הָ⁠אַיָּלִ֖ים עַל־הָ֥רֵי בָֽתֶר׃ס","ʻa֤d şě⁠yá̇p֨ẇẖa֙ ha⁠ẏ֔wòm wĕ⁠ná֖sẇ ha⁠ẕĕ̇láli֑ym sòb֩ dĕ̇méh-lĕ⁠ká֨ dwòdi֜⁠y li⁠ẕĕbi֗y ʼ֛wò lĕ⁠ʻò֥per há⁠ʼayá̇li֖ym ʻal-há֥réy báֽţer׃s"],[3,1,"עַל־מִשְׁכָּבִ⁠י֙ בַּ⁠לֵּיל֔וֹת בִּקַּ֕שְׁתִּי אֵ֥ת שֶׁ⁠אָהֲבָ֖ה נַפְשִׁ֑⁠י בִּקַּשְׁתִּ֖י⁠ו וְ⁠לֹ֥א מְצָאתִֽי⁠ו׃","ʻal-mişĕ̌ká̇bi⁠y֙ bȧ⁠lé̇yl֔wòţ bi̇qȧ֕şĕ̌ţi̇y ʼé֥ţ şě⁠ʼáhàbá֖h napĕşǐ֑⁠y bi̇qȧşĕ̌ţi֖̇y⁠w wĕ⁠lò֥ʼ mĕẕáʼţiֽy⁠w׃"],[3,2,"אָק֨וּמָה נָּ֜א וַ⁠אֲסוֹבְבָ֣ה בָ⁠עִ֗יר בַּ⁠שְּׁוָקִים֙ וּ⁠בָ֣⁠רְחֹב֔וֹת אֲבַקְשָׁ֕ה אֵ֥ת שֶׁ⁠אָהֲבָ֖ה נַפְשִׁ֑⁠י בִּקַּשְׁתִּ֖י⁠ו וְ⁠לֹ֥א מְצָאתִֽי⁠ו׃","ʼáq֨ẇmáh ná̇֜ʼ wa⁠ʼàswòbĕbá֣h bá⁠ʻi֗yr bȧ⁠şĕ̇̌wáqiym֙ ẇ⁠bá֣⁠rĕẖòb֔wòţ ʼàbaqĕşá̌֕h ʼé֥ţ şě⁠ʼáhàbá֖h napĕşǐ֑⁠y bi̇qȧşĕ̌ţi֖̇y⁠w wĕ⁠lò֥ʼ mĕẕáʼţiֽy⁠w׃"],[3,3,"מְצָא֨וּ⁠נִי֙ הַ⁠שֹּׁ֣מְרִ֔ים הַ⁠סֹּבְבִ֖ים בָּ⁠עִ֑יר אֵ֛ת שֶׁ⁠אָהֲבָ֥ה נַפְשִׁ֖⁠י רְאִיתֶֽם׃","mĕẕáʼ֨ẇ⁠niy֙ ha⁠şò֣̇̌mĕri֔ym ha⁠sò̇bĕbi֖ym bá̇⁠ʻi֑yr ʼé֛ţ şě⁠ʼáhàbá֥h napĕşǐ֖⁠y rĕʼiyţeֽm׃"],[3,4,"כִּ⁠מְעַט֙ שֶׁ⁠עָבַ֣רְתִּי מֵ⁠הֶ֔ם עַ֣ד שֶֽׁ⁠מָּצָ֔אתִי אֵ֥ת שֶׁ⁠אָהֲבָ֖ה נַפְשִׁ֑⁠י אֲחַזְתִּי⁠ו֙ וְ⁠לֹ֣א אַרְפֶּ֔⁠נּוּ עַד־שֶׁ֤⁠הֲבֵיאתִי⁠ו֙ אֶל־בֵּ֣ית אִמִּ֔⁠י וְ⁠אֶל־חֶ֖דֶר הוֹרָתִֽ⁠י׃","ki̇⁠mĕʻat֙ şě⁠ʻába֣rĕţi̇y mé⁠he֔m ʻa֣d şěֽ⁠má̇ẕá֔ʼţiy ʼé֥ţ şě⁠ʼáhàbá֖h napĕşǐ֑⁠y ʼàẖazĕţi̇y⁠w֙ wĕ⁠lò֣ʼ ʼarĕpė֔⁠ṅẇ ʻad-şě֤⁠hàbéyʼţiy⁠w֙ ʼel-bé֣̇yţ ʼimi̇֔⁠y wĕ⁠ʼel-ẖe֖der hwòráţiֽ⁠y׃"],[3,5,"הִשְׁבַּ֨עְתִּי אֶתְ⁠כֶ֜ם בְּנ֤וֹת יְרוּשָׁלִַ֨ם֙ בִּ⁠צְבָא֔וֹת א֖וֹ בְּ⁠אַיְל֣וֹת הַ⁠שָּׂדֶ֑ה אִם־תָּעִ֧ירוּ ׀ וְֽ⁠אִם־תְּעֽוֹרְר֛וּ אֶת־הָ⁠אַהֲבָ֖ה עַ֥ד שֶׁ⁠תֶּחְפָּֽץ׃ס","hişĕ̌bȧ֨ʻĕţi̇y ʼeţĕ⁠ke֜m bĕ̇n֤wòţ yĕrẇşá̌lia֨m֙ bi̇⁠ẕĕbáʼ֔wòţ ʼ֖wò bĕ̇⁠ʼayĕl֣wòţ ha⁠şá̇̂de֑h ʼim-ţá̇ʻi֧yrẇ ׀ wĕֽ⁠ʼim-ţĕ̇ʻֽwòrĕr֛ẇ ʼeţ-há⁠ʼahàbá֖h ʻa֥d şě⁠ţėẖĕpáֽ̇ẕ׃s"],[3,6,"מִ֣י זֹ֗את עֹלָה֙ מִן־הַ⁠מִּדְבָּ֔ר כְּ⁠תִֽימֲר֖וֹת עָשָׁ֑ן מְקֻטֶּ֤רֶת מוֹר֙ וּ⁠לְבוֹנָ֔ה מִ⁠כֹּ֖ל אַבְקַ֥ת רוֹכֵֽל׃","mi֣y zò֗ʼţ ʻòláh֙ min-ha⁠mi̇dĕbá̇֔r kĕ̇⁠ţiֽymàr֖wòţ ʻáşá֑̌n mĕqutė֤reţ mwòr֙ ẇ⁠lĕbwòná֔h mi⁠kò֖̇l ʼabĕqa֥ţ rwòkéֽl׃"],[3,7,"הִנֵּ֗ה מִטָּת⁠וֹ֙ שֶׁ⁠לִּ⁠שְׁלֹמֹ֔ה שִׁשִּׁ֥ים גִּבֹּרִ֖ים סָבִ֣יב לָ֑⁠הּ מִ⁠גִּבֹּרֵ֖י יִשְׂרָאֵֽל׃","hiné̇֗h mitá̇ţ⁠wò֙ şě⁠li̇⁠şĕ̌lòmò֔h şǐşi֥̇̌ym gi̇bò̇ri֖ym sábi֣yb lá֑⁠ḣ mi⁠gi̇bò̇ré֖y yişĕ̂ráʼéֽl׃"],[3,8,"כֻּלָּ⁠ם֙ אֲחֻ֣זֵי חֶ֔רֶב מְלֻמְּדֵ֖י מִלְחָמָ֑ה אִ֤ישׁ חַרְבּ⁠וֹ֙ עַל־יְרֵכ֔⁠וֹ מִ⁠פַּ֖חַד בַּ⁠לֵּילּֽוֹת׃ס","ku̇lá̇⁠m֙ ʼàẖu֣zéy ẖe֔reb mĕlumĕ̇dé֖y milĕẖámá֑h ʼi֤yş̌ ẖarĕḃ⁠wò֙ ʻal-yĕrék֔⁠wò mi⁠pȧ֖ẖad bȧ⁠lé̇ylֽ̇wòţ׃s"],[3,9,"אַפִּרְי֗וֹן עָ֤שָׂה ל⁠וֹ֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה מֵ⁠עֲצֵ֖י הַ⁠לְּבָנֽוֹן׃","ʼapi̇rĕy֗wòn ʻá֤şá̂h l⁠wò֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h mé⁠ʻàẕé֖y ha⁠lĕ̇bánֽwòn׃"],[3,10,"עַמּוּדָי⁠ו֙ עָ֣שָׂה כֶ֔סֶף רְפִידָת֣⁠וֹ זָהָ֔ב מֶרְכָּב֖⁠וֹ אַרְגָּמָ֑ן תּוֹכ⁠וֹ֙ רָצ֣וּף אַהֲבָ֔ה מִ⁠בְּנ֖וֹת יְרוּשָׁלִָֽם׃","ʻaṁẇdáy⁠w֙ ʻá֣şá̂h ke֔sep rĕpiydáţ֣⁠wò záhá֔b merĕká̇b֖⁠wò ʼarĕgá̇má֑n ţ̇wòk⁠wò֙ ráẕ֣ẇp ʼahàbá֔h mi⁠bĕ̇n֖wòţ yĕrẇşá̌liáֽm׃"],[3,11,"צְאֶ֧ינָה ׀ וּֽ⁠רְאֶ֛ינָה בְּנ֥וֹת צִיּ֖וֹן בַּ⁠מֶּ֣לֶךְ שְׁלֹמֹ֑ה בָּ⁠עֲטָרָ֗ה שֶׁ⁠עִטְּרָה־לּ֤⁠וֹ אִמּ⁠וֹ֙ בְּ⁠י֣וֹם חֲתֻנָּת֔⁠וֹ וּ⁠בְ⁠י֖וֹם שִׂמְחַ֥ת לִבּֽ⁠וֹ׃ס","ẕĕʼe֧ynáh ׀ ẇֽ⁠rĕʼe֛ynáh bĕ̇n֥wòţ ẕiẏ֖wòn bȧ⁠mė֣lekĕ şĕ̌lòmò֑h bá̇⁠ʻàtárá֗h şě⁠ʻitĕ̇ráh-l֤̇⁠wò ʼiṁ⁠wò֙ bĕ̇⁠y֣wòm ẖàţuná̇ţ֔⁠wò ẇ⁠bĕ⁠y֖wòm şîmĕẖa֥ţ liḃֽ⁠wò׃s"],[4,1,"הִנָּ֨⁠ךְ יָפָ֤ה רַעְיָתִ⁠י֙ הִנָּ֣⁠ךְ יָפָ֔ה עֵינַ֣יִ⁠ךְ יוֹנִ֔ים מִ⁠בַּ֖עַד לְ⁠צַמָּתֵ֑⁠ךְ שַׂעְרֵ⁠ךְ֙ כְּ⁠עֵ֣דֶר הָֽ⁠עִזִּ֔ים שֶׁ⁠גָּלְשׁ֖וּ מֵ⁠הַ֥ר גִּלְעָֽד׃","hiná̇֨⁠kĕ yápá֤h raʻĕyáţi⁠y֙ hiná֣̇⁠kĕ yápá֔h ʻéyna֣yi⁠kĕ ywòni֔ym mi⁠bȧ֖ʻad lĕ⁠ẕamá̇ţé֑⁠kĕ şâʻĕré⁠kĕ֙ kĕ̇⁠ʻé֣der háֽ⁠ʻizi̇֔ym şě⁠gá̇lĕş֖̌ẇ mé⁠ha֥r gi̇lĕʻáֽd׃"],[4,2,"שִׁנַּ֨יִ⁠ךְ֙ כְּ⁠עֵ֣דֶר הַ⁠קְּצוּב֔וֹת שֶׁ⁠עָל֖וּ מִן־הָ⁠רַחְצָ֑ה שֶׁ⁠כֻּלָּ⁠ם֙ מַתְאִימ֔וֹת וְ⁠שַׁכֻּלָ֖ה אֵ֥ין בָּ⁠הֶֽם׃","şǐnȧ֨yi⁠kĕ֙ kĕ̇⁠ʻé֣der ha⁠qĕ̇ẕẇb֔wòţ şě⁠ʻál֖ẇ min-há⁠raẖĕẕá֑h şě⁠ku̇lá̇⁠m֙ maţĕʼiym֔wòţ wĕ⁠şǎku̇lá֖h ʼé֥yn bá̇⁠heֽm׃"],[4,3,"כְּ⁠ח֤וּט הַ⁠שָּׁנִי֙ שִׂפְתֹתַ֔יִ⁠ךְ וּ⁠מִדְבָּרֵ֖י⁠ךְ נָאוֶ֑ה כְּ⁠פֶ֤לַח הָֽ⁠רִמּוֹן֙ רַקָּתֵ֔⁠ךְ מִ⁠בַּ֖עַד לְ⁠צַמָּתֵֽ⁠ךְ׃","kĕ̇⁠ẖ֤ẇt ha⁠şá̇̌niy֙ şîpĕţòţa֔yi⁠kĕ ẇ⁠midĕbá̇ré֖y⁠kĕ náʼwe֑h kĕ̇⁠pe֤laẖ háֽ⁠riṁwòn֙ raqá̇ţé֔⁠kĕ mi⁠bȧ֖ʻad lĕ⁠ẕamá̇ţéֽ⁠kĕ׃"],[4,4,"כְּ⁠מִגְדַּ֤ל דָּוִיד֙ צַוָּארֵ֔⁠ךְ בָּנ֖וּי לְ⁠תַלְפִּיּ֑וֹת אֶ֤לֶף הַ⁠מָּגֵן֙ תָּל֣וּי עָלָ֔י⁠ו כֹּ֖ל שִׁלְטֵ֥י הַ⁠גִּבּוֹרִֽים׃","kĕ̇⁠migĕdȧ֤l dá̇wiyd֙ ẕawá̇ʼré֔⁠kĕ bá̇n֖ẇy lĕ⁠ţalĕpi̇ẏ֑wòţ ʼe֤lep ha⁠má̇gén֙ ţá̇l֣ẇy ʻálá֔y⁠w kò֖̇l şǐlĕté֥y ha⁠gi̇ḃwòriֽym׃"],[4,5,"שְׁנֵ֥י שָׁדַ֛יִ⁠ךְ כִּ⁠שְׁנֵ֥י עֳפָרִ֖ים תְּאוֹמֵ֣י צְבִיָּ֑ה הָ⁠רוֹעִ֖ים בַּ⁠שּׁוֹשַׁנִּֽים׃","şĕ̌né֥y şá̌da֛yi⁠kĕ ki̇⁠şĕ̌né֥y ʻopári֖ym ţĕ̇ʼwòmé֣y ẕĕbiyá֑̇h há⁠rwòʻi֖ym bȧ⁠ş̇̌wòşǎniֽ̇ym׃"],[4,6,"עַ֤ד שֶׁ⁠יָּפ֨וּחַ֙ הַ⁠יּ֔וֹם וְ⁠נָ֖סוּ הַ⁠צְּלָלִ֑ים אֵ֤לֶךְ לִ⁠י֙ אֶל־הַ֣ר הַ⁠מּ֔וֹר וְ⁠אֶל־גִּבְעַ֖ת הַ⁠לְּבוֹנָֽה׃","ʻa֤d şě⁠yá̇p֨ẇẖa֙ ha⁠ẏ֔wòm wĕ⁠ná֖sẇ ha⁠ẕĕ̇láli֑ym ʼé֤lekĕ li⁠y֙ ʼel-ha֣r ha⁠ṁ֔wòr wĕ⁠ʼel-gi̇bĕʻa֖ţ ha⁠lĕ̇bwònáֽh׃"],[4,7,"כֻּלָּ֤⁠ךְ יָפָה֙ רַעְיָתִ֔⁠י וּ⁠מ֖וּם אֵ֥ין בָּֽ⁠ךְ׃ס","ku̇lá֤̇⁠kĕ yápáh֙ raʻĕyáţi֔⁠y ẇ⁠m֖ẇm ʼé֥yn báֽ̇⁠kĕ׃s"],[4,8,"אִתִּ֤⁠י מִ⁠לְּבָנוֹן֙ כַּלָּ֔ה אִתִּ֖⁠י מִ⁠לְּבָנ֣וֹן תָּב֑וֹאִי תָּשׁ֣וּרִי ׀ מֵ⁠רֹ֣אשׁ אֲמָנָ֗ה מֵ⁠רֹ֤אשׁ שְׂנִיר֙ וְ⁠חֶרְמ֔וֹן מִ⁠מְּעֹנ֣וֹת אֲרָי֔וֹת מֵֽ⁠הַרְרֵ֖י נְמֵרִֽים׃","ʼiţi֤̇⁠y mi⁠lĕ̇bánwòn֙ kȧlá̇֔h ʼiţi֖̇⁠y mi⁠lĕ̇bán֣wòn ţá̇b֑wòʼiy ţá̇ş֣̌ẇriy ׀ mé⁠rò֣ʼş̌ ʼàmáná֗h mé⁠rò֤ʼş̌ şĕ̂niyr֙ wĕ⁠ẖerĕm֔wòn mi⁠mĕ̇ʻòn֣wòţ ʼàráy֔wòţ méֽ⁠harĕré֖y nĕmériֽym׃"],[4,9,"לִבַּבְתִּ֖⁠נִי אֲחֹתִ֣⁠י כַלָּ֑ה לִבַּבְתִּ֨י⁠נִי֙ ב⁠אחד מֵ⁠עֵינַ֔יִ⁠ךְ בְּ⁠אַחַ֥ד עֲנָ֖ק מִ⁠צַּוְּרֹנָֽיִ⁠ךְ׃","libȧbĕţi֖̇⁠niy ʼàẖòţi֣⁠y kalá֑̇h libȧbĕţi̇֨y⁠niy֙ b⁠ʼẖd mé⁠ʻéyna֔yi⁠kĕ bĕ̇⁠ʼaẖa֥d ʻàná֖q mi⁠ẕȧwĕ̇rònáֽyi⁠kĕ׃"],[4,10,"מַה־יָּפ֥וּ דֹדַ֖יִ⁠ךְ אֲחֹתִ֣⁠י כַלָּ֑ה מַה־טֹּ֤בוּ דֹדַ֨יִ⁠ךְ֙ מִ⁠יַּ֔יִן וְ⁠רֵ֥יחַ שְׁמָנַ֖יִ⁠ךְ מִ⁠כָּל־בְּשָׂמִֽים׃","mah-yá̇p֥ẇ dòda֖yi⁠kĕ ʼàẖòţi֣⁠y kalá֑̇h mah-tò֤̇bẇ dòda֨yi⁠kĕ֙ mi⁠yȧ֔yin wĕ⁠ré֥yẖa şĕ̌mána֖yi⁠kĕ mi⁠ká̇l-bĕ̇şá̂miֽym׃"],[4,11,"נֹ֛פֶת תִּטֹּ֥פְנָה שִׂפְתוֹתַ֖יִ⁠ךְ כַּלָּ֑ה דְּבַ֤שׁ וְ⁠חָלָב֙ תַּ֣חַת לְשׁוֹנֵ֔⁠ךְ וְ⁠רֵ֥יחַ שַׂלְמֹתַ֖יִ⁠ךְ כְּ⁠רֵ֥יחַ לְבָנֽוֹן׃ס","nò֛peţ ţi̇tò֥̇pĕnáh şîpĕţwòţa֖yi⁠kĕ kȧlá֑̇h dĕ̇ba֤ş̌ wĕ⁠ẖáláb֙ ţȧ֣ẖaţ lĕş̌wòné֔⁠kĕ wĕ⁠ré֥yẖa şâlĕmòţa֖yi⁠kĕ kĕ̇⁠ré֥yẖa lĕbánֽwòn׃s"],[4,12,"גַּ֥ן ׀ נָע֖וּל אֲחֹתִ֣⁠י כַלָּ֑ה גַּ֥ל נָע֖וּל מַעְיָ֥ן חָתֽוּם׃","gȧ֥n ׀ náʻ֖ẇl ʼàẖòţi֣⁠y kalá֑̇h gȧ֥l náʻ֖ẇl maʻĕyá֥n ẖáţֽẇm׃"],[4,13,"שְׁלָחַ֨יִ⁠ךְ֙ פַּרְדֵּ֣ס רִמּוֹנִ֔ים עִ֖ם פְּרִ֣י מְגָדִ֑ים כְּפָרִ֖ים עִם־נְרָדִֽים׃","şĕ̌láẖa֨yi⁠kĕ֙ pȧrĕdé֣̇s riṁwòni֔ym ʻi֖m pĕ̇ri֣y mĕgádi֑ym kĕ̇pári֖ym ʻim-nĕrádiֽym׃"],[4,14,"נֵ֣רְדְּ ׀ וְ⁠כַרְכֹּ֗ם קָנֶה֙ וְ⁠קִנָּמ֔וֹן עִ֖ם כָּל־עֲצֵ֣י לְבוֹנָ֑ה מֹ֚ר וַ⁠אֲהָל֔וֹת עִ֖ם כָּל־רָאשֵׁ֥י בְשָׂמִֽים׃","né֣rĕdĕ̇ ׀ wĕ⁠karĕkò̇֗m qáneh֙ wĕ⁠qiná̇m֔wòn ʻi֖m ká̇l-ʻàẕé֣y lĕbwòná֑h mò֚r wa⁠ʼàhál֔wòţ ʻi֖m ká̇l-ráʼşé֥̌y bĕşá̂miֽym׃"],[4,15,"מַעְיַ֣ן גַּנִּ֔ים בְּאֵ֖ר מַ֣יִם חַיִּ֑ים וְ⁠נֹזְלִ֖ים מִן־לְבָנֽוֹן׃","maʻĕya֣n gȧni̇֔ym bĕ̇ʼé֖r ma֣yim ẖayi֑̇ym wĕ⁠nòzĕli֖ym min-lĕbánֽwòn׃"],[4,16,"ע֤וּרִי צָפוֹן֙ וּ⁠ב֣וֹאִי תֵימָ֔ן הָפִ֥יחִי גַנִּ֖⁠י יִזְּל֣וּ בְשָׂמָ֑י⁠ו יָבֹ֤א דוֹדִ⁠י֙ לְ⁠גַנּ֔⁠וֹ וְ⁠יֹאכַ֖ל פְּרִ֥י מְגָדָֽי⁠ו׃","ʻ֤ẇriy ẕápwòn֙ ẇ⁠b֣wòʼiy ţéymá֔n hápi֥yẖiy gani֖̇⁠y yizĕ̇l֣ẇ bĕşá̂má֑y⁠w yábò֤ʼ dwòdi⁠y֙ lĕ⁠gaṅ֔⁠wò wĕ⁠yòʼka֖l pĕ̇ri֥y mĕgádáֽy⁠w׃"],[5,1,"בָּ֣אתִי לְ⁠גַנִּ⁠י֮ אֲחֹתִ֣⁠י כַלָּה֒ אָרִ֤יתִי מוֹרִ⁠י֙ עִם־בְּשָׂמִ֔⁠י אָכַ֤לְתִּי יַעְרִ⁠י֙ עִם־דִּבְשִׁ֔⁠י שָׁתִ֥יתִי יֵינִ֖⁠י עִם־חֲלָבִ֑⁠י אִכְל֣וּ רֵעִ֔ים שְׁת֥וּ וְ⁠שִׁכְר֖וּ דּוֹדִֽים׃ס","bá֣̇ʼţiy lĕ⁠gani̇⁠y֮ ʼàẖòţi֣⁠y kalá̇h֒ ʼári֤yţiy mwòri⁠y֙ ʻim-bĕ̇şá̂mi֔⁠y ʼáka֤lĕţi̇y yaʻĕri⁠y֙ ʻim-di̇bĕşǐ֔⁠y şá̌ţi֥yţiy yéyni֖⁠y ʻim-ẖàlábi֑⁠y ʼikĕl֣ẇ réʻi֔ym şĕ̌ţ֥ẇ wĕ⁠şǐkĕr֖ẇ ḋwòdiֽym׃s"],[5,2,"אֲנִ֥י יְשֵׁנָ֖ה וְ⁠לִבִּ֣⁠י עֵ֑ר ק֣וֹל ׀ דּוֹדִ֣⁠י דוֹפֵ֗ק פִּתְחִי־לִ֞⁠י אֲחֹתִ֤⁠י רַעְיָתִ⁠י֙ יוֹנָתִ֣⁠י תַמָּתִ֔⁠י שֶׁ⁠רֹּאשִׁ⁠י֙ נִמְלָא־טָ֔ל קְוֻּצּוֹתַ֖⁠י רְסִ֥יסֵי לָֽיְלָה׃","ʼàni֥y yĕşé̌ná֖h wĕ⁠libi֣̇⁠y ʻé֑r q֣wòl ׀ ḋwòdi֣⁠y dwòpé֗q pi̇ţĕẖiy-li֞⁠y ʼàẖòţi֤⁠y raʻĕyáţi⁠y֙ ywònáţi֣⁠y ţamá̇ţi֔⁠y şě⁠rò̇ʼşǐ⁠y֙ nimĕláʼ-tá֔l qĕwu̇ẕ̇wòţa֖⁠y rĕsi֥yséy láֽyĕláh׃"],[5,3,"פָּשַׁ֨טְתִּי֙ אֶת־כֻּתָּנְתִּ֔⁠י אֵיכָ֖כָה אֶלְבָּשֶׁ֑⁠נָּה רָחַ֥צְתִּי אֶת־רַגְלַ֖⁠י אֵיכָ֥כָה אֲטַנְּפֵֽ⁠ם׃","pá̇şǎ֨tĕţi̇y֙ ʼeţ-ku̇ţá̇nĕţi̇֔⁠y ʼéyká֖káh ʼelĕbá̇şě֑⁠ná̇h ráẖa֥ẕĕţi̇y ʼeţ-ragĕla֖⁠y ʼéyká֥káh ʼàtanĕ̇péֽ⁠m׃"],[5,4,"דּוֹדִ֗⁠י שָׁלַ֤ח יָד⁠וֹ֙ מִן־הַ⁠חֹ֔ר וּ⁠מֵעַ֖⁠י הָמ֥וּ עָלָֽי⁠ו׃","ḋwòdi֗⁠y şá̌la֤ẖ yád⁠wò֙ min-ha⁠ẖò֔r ẇ⁠méʻa֖⁠y hám֥ẇ ʻáláֽy⁠w׃"],[5,5,"קַ֥מְתִּֽי אֲנִ֖י לִ⁠פְתֹּ֣חַ לְ⁠דוֹדִ֑⁠י וְ⁠יָדַ֣⁠י נָֽטְפוּ־מ֗וֹר וְ⁠אֶצְבְּעֹתַ⁠י֙ מ֣וֹר עֹבֵ֔ר עַ֖ל כַּפּ֥וֹת הַ⁠מַּנְעֽוּל׃","qa֥mĕţiֽ̇y ʼàni֖y li⁠pĕţò֣̇ẖa lĕ⁠dwòdi֑⁠y wĕ⁠yáda֣⁠y náֽtĕpẇ-m֗wòr wĕ⁠ʼeẕĕbĕ̇ʻòţa⁠y֙ m֣wòr ʻòbé֔r ʻa֖l kȧṗ֥wòţ ha⁠mȧnĕʻֽẇl׃"],[5,6,"פָּתַ֤חְתִּֽי אֲנִי֙ לְ⁠דוֹדִ֔⁠י וְ⁠דוֹדִ֖⁠י חָמַ֣ק עָבָ֑ר נַפְשִׁ⁠י֙ יָֽצְאָ֣ה בְ⁠דַבְּר֔⁠וֹ בִּקַּשְׁתִּ֨י⁠הוּ֙ וְ⁠לֹ֣א מְצָאתִ֔י⁠הוּ קְרָאתִ֖י⁠ו וְ⁠לֹ֥א עָנָֽ⁠נִי׃","pá̇ţa֤ẖĕţiֽ̇y ʼàniy֙ lĕ⁠dwòdi֔⁠y wĕ⁠dwòdi֖⁠y ẖáma֣q ʻábá֑r napĕşǐ⁠y֙ yáֽẕĕʼá֣h bĕ⁠dabĕ̇r֔⁠wò bi̇qȧşĕ̌ţi̇֨y⁠hẇ֙ wĕ⁠lò֣ʼ mĕẕáʼţi֔y⁠hẇ qĕráʼţi֖y⁠w wĕ⁠lò֥ʼ ʻánáֽ⁠niy׃"],[5,7,"מְצָאֻ֧⁠נִי הַ⁠שֹּׁמְרִ֛ים הַ⁠סֹּבְבִ֥ים בָּ⁠עִ֖יר הִכּ֣וּ⁠נִי פְצָע֑וּ⁠נִי נָשְׂא֤וּ אֶת־רְדִידִ⁠י֙ מֵֽ⁠עָלַ֔⁠י שֹׁמְרֵ֖י הַ⁠חֹמֽוֹת׃","mĕẕáʼu֧⁠niy ha⁠şò̇̌mĕri֛ym ha⁠sò̇bĕbi֥ym bá̇⁠ʻi֖yr hik֣̇ẇ⁠niy pĕẕáʻ֑ẇ⁠niy náşĕ̂ʼ֤ẇ ʼeţ-rĕdiydi⁠y֙ méֽ⁠ʻála֔⁠y şò̌mĕré֖y ha⁠ẖòmֽwòţ׃"],[5,8,"הִשְׁבַּ֥עְתִּי אֶתְ⁠כֶ֖ם בְּנ֣וֹת יְרוּשָׁלִָ֑ם אִֽם־תִּמְצְאוּ֙ אֶת־דּוֹדִ֔⁠י מַה־תַּגִּ֣ידוּ ל֔⁠וֹ שֶׁ⁠חוֹלַ֥ת אַהֲבָ֖ה אָֽנִי׃","hişĕ̌bȧ֥ʻĕţi̇y ʼeţĕ⁠ke֖m bĕ̇n֣wòţ yĕrẇşá̌liá֑m ʼiֽm-ţi̇mĕẕĕʼẇ֙ ʼeţ-ḋwòdi֔⁠y mah-ţȧgi֣̇ydẇ l֔⁠wò şě⁠ẖwòla֥ţ ʼahàbá֖h ʼáֽniy׃"],[5,9,"מַה־דּוֹדֵ֣⁠ךְ מִ⁠דּ֔וֹד הַ⁠יָּפָ֖ה בַּ⁠נָּשִׁ֑ים מַה־דּוֹדֵ֣⁠ךְ מִ⁠דּ֔וֹד שֶׁ⁠כָּ֖כָה הִשְׁבַּעְתָּֽ⁠נוּ׃","mah-ḋwòdé֣⁠kĕ mi⁠ḋ֔wòd ha⁠yá̇pá֖h bȧ⁠ná̇şǐ֑ym mah-ḋwòdé֣⁠kĕ mi⁠ḋ֔wòd şě⁠ká֖̇káh hişĕ̌bȧʻĕţáֽ̇⁠nẇ׃"],[5,10,"דּוֹדִ֥⁠י צַח֙ וְ⁠אָד֔וֹם דָּג֖וּל מֵ⁠רְבָבָֽה׃","ḋwòdi֥⁠y ẕaẖ֙ wĕ⁠ʼád֔wòm dá̇g֖ẇl mé⁠rĕbábáֽh׃"],[5,11,"רֹאשׁ֖⁠וֹ כֶּ֣תֶם פָּ֑ז קְוּצּוֹתָי⁠ו֙ תַּלְתַּלִּ֔ים שְׁחֹר֖וֹת כָּ⁠עוֹרֵֽב׃","ròʼş֖̌⁠wò kė֣ţem pá֑̇z qĕẇẕ̇wòţáy⁠w֙ ţȧlĕţȧli̇֔ym şĕ̌ẖòr֖wòţ ká̇⁠ʻwòréֽb׃"],[5,12,"עֵינָ֕י⁠ו כְּ⁠יוֹנִ֖ים עַל־אֲפִ֣יקֵי מָ֑יִם רֹֽחֲצוֹת֙ בֶּֽ⁠חָלָ֔ב יֹשְׁב֖וֹת עַל־מִלֵּֽאת׃","ʻéyná֕y⁠w kĕ̇⁠ywòni֖ym ʻal-ʼàpi֣yqéy má֑yim ròֽẖàẕwòţ֙ bėֽ⁠ẖálá֔b yòşĕ̌b֖wòţ ʻal-miléֽ̇ʼţ׃"],[5,13,"לְחָיָ⁠ו֙ כַּ⁠עֲרוּגַ֣ת הַ⁠בֹּ֔שֶׂם מִגְדְּל֖וֹת מֶרְקָחִ֑ים שִׂפְתוֹתָי⁠ו֙ שֽׁוֹשַׁנִּ֔ים נֹטְפ֖וֹת מ֥וֹר עֹבֵֽר׃","lĕẖáyá⁠w֙ kȧ⁠ʻàrẇga֣ţ ha⁠bò̇֔şêm migĕdĕ̇l֖wòţ merĕqáẖi֑ym şîpĕţwòţáy⁠w֙ şֽ̌wòşǎni̇֔ym nòtĕp֖wòţ m֥wòr ʻòbéֽr׃"],[5,14,"יָדָי⁠ו֙ גְּלִילֵ֣י זָהָ֔ב מְמֻלָּאִ֖ים בַּ⁠תַּרְשִׁ֑ישׁ מֵעָי⁠ו֙ עֶ֣שֶׁת שֵׁ֔ן מְעֻלֶּ֖פֶת סַפִּירִֽים׃","yádáy⁠w֙ gĕ̇liylé֣y záhá֔b mĕmulá̇ʼi֖ym bȧ⁠ţȧrĕşǐ֑yş̌ méʻáy⁠w֙ ʻe֣şěţ şé̌֔n mĕʻulė֖peţ sapi̇yriֽym׃"],[5,15,"שׁוֹקָי⁠ו֙ עַמּ֣וּדֵי שֵׁ֔שׁ מְיֻסָּדִ֖ים עַל־אַדְנֵי־פָ֑ז מַרְאֵ֨⁠הוּ֙ כַּ⁠לְּבָנ֔וֹן בָּח֖וּר כָּ⁠אֲרָזִֽים׃","ş̌wòqáy⁠w֙ ʻaṁ֣ẇdéy şé̌֔ş̌ mĕyusá̇di֖ym ʻal-ʼadĕnéy-pá֑z marĕʼé֨⁠hẇ֙ kȧ⁠lĕ̇bán֔wòn bá̇ẖ֖ẇr ká̇⁠ʼàráziֽym׃"],[5,16,"חִכּ⁠וֹ֙ מַֽמְתַקִּ֔ים וְ⁠כֻלּ֖⁠וֹ מַחֲּמַדִּ֑ים זֶ֤ה דוֹדִ⁠י֙ וְ⁠זֶ֣ה רֵעִ֔⁠י בְּנ֖וֹת יְרוּשָׁלִָֽם׃","ẖik̇⁠wò֙ maֽmĕţaqi̇֔ym wĕ⁠kul֖̇⁠wò maẖà̇madi֑̇ym ze֤h dwòdi⁠y֙ wĕ⁠ze֣h réʻi֔⁠y bĕ̇n֖wòţ yĕrẇşá̌liáֽm׃"],[6,1,"אָ֚נָה הָלַ֣ךְ דּוֹדֵ֔⁠ךְ הַ⁠יָּפָ֖ה בַּ⁠נָּשִׁ֑ים אָ֚נָה פָּנָ֣ה דוֹדֵ֔⁠ךְ וּ⁠נְבַקְשֶׁ֖⁠נּוּ עִמָּֽ⁠ךְ׃","ʼá֚náh hála֣kĕ ḋwòdé֔⁠kĕ ha⁠yá̇pá֖h bȧ⁠ná̇şǐ֑ym ʼá֚náh pá̇ná֣h dwòdé֔⁠kĕ ẇ⁠nĕbaqĕşě֖⁠ṅẇ ʻimáֽ̇⁠kĕ׃"],[6,2,"דּוֹדִ⁠י֙ יָרַ֣ד לְ⁠גַנּ֔⁠וֹ לַ⁠עֲרוּג֖וֹת הַ⁠בֹּ֑שֶׂם לִ⁠רְעוֹת֙ בַּ⁠גַּנִּ֔ים וְ⁠לִ⁠לְקֹ֖ט שֽׁוֹשַׁנִּֽים׃","ḋwòdi⁠y֙ yára֣d lĕ⁠gaṅ֔⁠wò la⁠ʻàrẇg֖wòţ ha⁠bò֑̇şêm li⁠rĕʻwòţ֙ bȧ⁠gȧni̇֔ym wĕ⁠li⁠lĕqò֖t şֽ̌wòşǎniֽ̇ym׃"],[6,3,"אֲנִ֤י לְ⁠דוֹדִ⁠י֙ וְ⁠דוֹדִ֣⁠י לִ֔⁠י הָ⁠רֹעֶ֖ה בַּ⁠שׁוֹשַׁנִּֽים׃ס","ʼàni֤y lĕ⁠dwòdi⁠y֙ wĕ⁠dwòdi֣⁠y li֔⁠y há⁠ròʻe֖h bȧ⁠ş̌wòşǎniֽ̇ym׃s"],[6,4,"יָפָ֨ה אַ֤תְּ רַעְיָתִ⁠י֙ כְּ⁠תִרְצָ֔ה נָאוָ֖ה כִּ⁠ירוּשָׁלִָ֑ם אֲיֻמָּ֖ה כַּ⁠נִּדְגָּלֽוֹת׃","yápá֨h ʼa֤ţĕ̇ raʻĕyáţi⁠y֙ kĕ̇⁠ţirĕẕá֔h náʼwá֖h ki̇⁠yrẇşá̌liá֑m ʼàyumá֖̇h kȧ⁠ni̇dĕgá̇lֽwòţ׃"],[6,5,"הָסֵ֤בִּי עֵינַ֨יִ⁠ךְ֙ מִ⁠נֶּגְדִּ֔⁠י שֶׁ֥⁠הֵ֖ם הִרְהִיבֻ֑⁠נִי שַׂעְרֵ⁠ךְ֙ כְּ⁠עֵ֣דֶר הָֽ⁠עִזִּ֔ים שֶׁ⁠גָּלְשׁ֖וּ מִן־הַ⁠גִּלְעָֽד׃","hásé֤bi̇y ʻéyna֨yi⁠kĕ֙ mi⁠nėgĕdi̇֔⁠y şě֥⁠hé֖m hirĕhiybu֑⁠niy şâʻĕré⁠kĕ֙ kĕ̇⁠ʻé֣der háֽ⁠ʻizi̇֔ym şě⁠gá̇lĕş֖̌ẇ min-ha⁠gi̇lĕʻáֽd׃"],[6,6,"שִׁנַּ֨יִ⁠ךְ֙ כְּ⁠עֵ֣דֶר הָֽ⁠רְחֵלִ֔ים שֶׁ⁠עָל֖וּ מִן־הָ⁠רַחְצָ֑ה שֶׁ⁠כֻּלָּ⁠ם֙ מַתְאִימ֔וֹת וְ⁠שַׁכֻּלָ֖ה אֵ֥ין בָּ⁠הֶֽם׃","şǐnȧ֨yi⁠kĕ֙ kĕ̇⁠ʻé֣der hֽá⁠rĕẖéli֔ym şě⁠ʻál֖ẇ min-há⁠raẖĕẕá֑h şě⁠ku̇lá̇⁠m֙ maţĕʼiym֔wòţ wĕ⁠şǎku̇lá֖h ʼé֥yn bá̇⁠heֽm׃"],[6,7,"כְּ⁠פֶ֤לַח הָ⁠רִמּוֹן֙ רַקָּתֵ֔⁠ךְ מִ⁠בַּ֖עַד לְ⁠צַמָּתֵֽ⁠ךְ׃","kĕ̇⁠pe֤laẖ há⁠riṁwòn֙ raqá̇ţé֔⁠kĕ mi⁠bȧ֖ʻad lĕ⁠ẕamá̇ţéֽ⁠kĕ׃"],[6,8,"שִׁשִּׁ֥ים הֵ֨מָּה֙ מְּלָכ֔וֹת וּ⁠שְׁמֹנִ֖ים פִּֽילַגְשִׁ֑ים וַ⁠עֲלָמ֖וֹת אֵ֥ין מִסְפָּֽר׃","şǐşi֥̇̌ym hé֨má̇h֙ mĕ̇lák֔wòţ ẇ⁠şĕ̌mòni֖ym piֽ̇ylagĕşǐ֑ym wa⁠ʻàlám֖wòţ ʼé֥yn misĕpáֽ̇r׃"],[6,9,"אַחַ֥ת הִיא֙ יוֹנָתִ֣⁠י תַמָּתִ֔⁠י אַחַ֥ת הִיא֙ לְ⁠אִמָּ֔⁠הּ בָּרָ֥ה הִ֖יא לְ⁠יֽוֹלַדְתָּ֑⁠הּ רָא֤וּ⁠הָ בָנוֹת֙ וַֽ⁠יְאַשְּׁר֔וּ⁠הָ מְלָכ֥וֹת וּ⁠פִֽילַגְשִׁ֖ים וַֽ⁠יְהַלְלֽוּ⁠הָ׃ס","ʼaẖa֥ţ hiyʼ֙ ywònáţi֣⁠y ţamá̇ţi֔⁠y ʼaẖa֥ţ hiyʼ֙ lĕ⁠ʼimá̇֔⁠ḣ bá̇rá֥h hi֖yʼ lĕ⁠yֽwòladĕţá֑̇⁠ḣ ráʼ֤ẇ⁠há bánwòţ֙ waֽ⁠yĕʼaşĕ̇̌r֔ẇ⁠há mĕlák֥wòţ ẇ⁠piֽylagĕşǐ֖ym waֽ⁠yĕhalĕlֽẇ⁠há׃s"],[6,10,"מִי־זֹ֥את הַ⁠נִּשְׁקָפָ֖ה כְּמוֹ־שָׁ֑חַר יָפָ֣ה כַ⁠לְּבָנָ֗ה בָּרָה֙ כַּֽ⁠חַמָּ֔ה אֲיֻמָּ֖ה כַּ⁠נִּדְגָּלֽוֹת׃ס","miy-zò֥ʼţ ha⁠ni̇şĕ̌qápá֖h kĕ̇mwò-şá֑̌ẖar yápá֣h ka⁠lĕ̇báná֗h bá̇ráh֙ kȧֽ⁠ẖamá̇֔h ʼàyumá֖̇h kȧ⁠ni̇dĕgá̇lֽwòţ׃s"],[6,11,"אֶל־גִּנַּ֤ת אֱגוֹז֙ יָרַ֔דְתִּי לִ⁠רְא֖וֹת בְּ⁠אִבֵּ֣י הַ⁠נָּ֑חַל לִ⁠רְאוֹת֙ הֲ⁠פָֽרְחָ֣ה הַ⁠גֶּ֔פֶן הֵנֵ֖צוּ הָ⁠רִמֹּנִֽים׃","ʼel-gi̇nȧ֤ţ ʼègwòz֙ yára֔dĕţi̇y li⁠rĕʼ֖wòţ bĕ̇⁠ʼibé֣̇y ha⁠ná֑̇ẖal li⁠rĕʼwòţ֙ hà⁠páֽrĕẖá֣h ha⁠gė֔pen héné֖ẕẇ há⁠rimò̇niֽym׃"],[6,12,"לֹ֣א יָדַ֔עְתִּי נַפְשִׁ֣⁠י שָׂמַ֔תְ⁠נִי מַרְכְּב֖וֹת עַמִּ⁠י־נָדִֽיב׃","lò֣ʼ yáda֔ʻĕţi̇y napĕşǐ֣⁠y şá̂ma֔ţĕ⁠niy marĕkĕ̇b֖wòţ ʻami̇⁠y-nádiֽyb׃"],[6,13,"שׁ֤וּבִי שׁ֨וּבִי֙ הַ⁠שּׁ֣וּלַמִּ֔ית שׁ֥וּבִי שׁ֖וּבִי וְ⁠נֶחֱזֶה־בָּ֑⁠ךְ מַֽה־תֶּחֱזוּ֙ בַּ⁠שּׁ֣וּלַמִּ֔ית כִּ⁠מְחֹלַ֖ת הַֽ⁠מַּחֲנָֽיִם׃","ş֤̌ẇbiy ş̌֨ẇbiy֙ ha⁠ş֣̇̌ẇlami̇֔yţ ş֥̌ẇbiy ş֖̌ẇbiy wĕ⁠neẖèzeh-bá֑̇⁠kĕ maֽh-ţėẖèzẇ֙ bȧ⁠ş֣̇̌ẇlami̇֔yţ ki̇⁠mĕẖòla֖ţ haֽ⁠mȧẖànáֽyim׃"],[7,1,"מַה־יָּפ֧וּ פְעָמַ֛יִ⁠ךְ בַּ⁠נְּעָלִ֖ים בַּת־נָדִ֑יב חַמּוּקֵ֣י יְרֵכַ֔יִ⁠ךְ כְּמ֣וֹ חֲלָאִ֔ים מַעֲשֵׂ֖ה יְדֵ֥י אָמָּֽן׃","mah-yá̇p֧ẇ pĕʻáma֛yi⁠kĕ bȧ⁠nĕ̇ʻáli֖ym bȧţ-nádi֑yb ẖaṁẇqé֣y yĕréka֔yi⁠kĕ kĕ̇m֣wò ẖàláʼi֔ym maʻàşé֖̂h yĕdé֥y ʼámáֽ̇n׃"],[7,2,"שָׁרְרֵ⁠ךְ֙ אַגַּ֣ן הַ⁠סַּ֔הַר אַל־יֶחְסַ֖ר הַ⁠מָּ֑זֶג בִּטְנֵ⁠ךְ֙ עֲרֵמַ֣ת חִטִּ֔ים סוּגָ֖ה בַּ⁠שּׁוֹשַׁנִּֽים׃","şá̌rĕré⁠kĕ֙ ʼagȧ֣n ha⁠sȧ֔har ʼal-yeẖĕsa֖r ha⁠má֑̇zeg bi̇tĕné⁠kĕ֙ ʻàréma֣ţ ẖiti̇֔ym sẇgá֖h bȧ⁠ş̇̌wòşǎniֽ̇ym׃"],[7,3,"שְׁנֵ֥י שָׁדַ֛יִ⁠ךְ כִּ⁠שְׁנֵ֥י עֳפָרִ֖ים תָּאֳמֵ֥י צְבִיָּֽה׃","şĕ̌né֥y şá̌da֛yi⁠kĕ ki̇⁠şĕ̌né֥y ʻopári֖ym ţá̇ʼomé֥y ẕĕbiyáֽ̇h׃"],[7,4,"צַוָּארֵ֖⁠ךְ כְּ⁠מִגְדַּ֣ל הַ⁠שֵּׁ֑ן עֵינַ֜יִ⁠ךְ בְּרֵכ֣וֹת בְּ⁠חֶשְׁבּ֗וֹן עַל־שַׁ֨עַר֙ בַּת־רַבִּ֔ים אַפֵּ⁠ךְ֙ כְּ⁠מִגְדַּ֣ל הַ⁠לְּבָנ֔וֹן צוֹפֶ֖ה פְּנֵ֥י דַמָּֽשֶׂק׃","ẕawá̇ʼré֖⁠kĕ kĕ̇⁠migĕdȧ֣l ha⁠şé֑̇̌n ʻéyna֜yi⁠kĕ bĕ̇rék֣wòţ bĕ̇⁠ẖeşĕ̌ḃ֗wòn ʻal-şǎ֨ʻar֙ bȧţ-rabi̇֔ym ʼapé̇⁠kĕ֙ kĕ̇⁠migĕdȧ֣l ha⁠lĕ̇bán֔wòn ẕwòpe֖h pĕ̇né֥y damáֽ̇şêq׃"],[7,5,"רֹאשֵׁ֤⁠ךְ עָלַ֨יִ⁠ךְ֙ כַּ⁠כַּרְמֶ֔ל וְ⁠דַלַּ֥ת רֹאשֵׁ֖⁠ךְ כָּ⁠אַרְגָּמָ֑ן מֶ֖לֶךְ אָס֥וּר בָּ⁠רְהָטִֽים׃","ròʼşé֤̌⁠kĕ ʻála֨yi⁠kĕ֙ kȧ⁠kȧrĕme֔l wĕ⁠dalȧ֥ţ ròʼşé֖̌⁠kĕ ká̇⁠ʼarĕgá̇má֑n me֖lekĕ ʼás֥ẇr bá̇⁠rĕhátiֽym׃"],[7,6,"מַה־יָּפִית֙ וּ⁠מַה־נָּעַ֔מְתְּ אַהֲבָ֖ה בַּ⁠תַּֽעֲנוּגִֽים׃","mah-yá̇piyţ֙ ẇ⁠mah-ná̇ʻa֔mĕţĕ̇ ʼahàbá֖h bȧ⁠ţȧֽʻànẇgiֽym׃"],[7,7,"זֹ֤את קֽוֹמָתֵ⁠ךְ֙ דָּֽמְתָ֣ה לְ⁠תָמָ֔ר וְ⁠שָׁדַ֖יִ⁠ךְ לְ⁠אַשְׁכֹּלֽוֹת׃","zò֤ʼţ qֽwòmáţé⁠kĕ֙ dáֽ̇mĕţá֣h lĕ⁠ţámá֔r wĕ⁠şá̌da֖yi⁠kĕ lĕ⁠ʼaşĕ̌kò̇lֽwòţ׃"],[7,8,"אָמַ֨רְתִּי֙ אֶעֱלֶ֣ה בְ⁠תָמָ֔ר אֹֽחֲזָ֖ה בְּ⁠סַנְסִנָּ֑י⁠ו וְ⁠יִֽהְיוּ־נָ֤א שָׁדַ֨יִ⁠ךְ֙ כְּ⁠אֶשְׁכְּל֣וֹת הַ⁠גֶּ֔פֶן וְ⁠רֵ֥יחַ אַפֵּ֖⁠ךְ כַּ⁠תַּפּוּחִֽים׃","ʼáma֨rĕţi̇y֙ ʼeʻèle֣h bĕ⁠ţámá֔r ʼòֽẖàzá֖h bĕ̇⁠sanĕsiná֑̇y⁠w wĕ⁠yiֽhĕyẇ-ná֤ʼ şá̌da֨yi⁠kĕ֙ kĕ̇⁠ʼeşĕ̌kĕ̇l֣wòţ ha⁠gė֔pen wĕ⁠ré֥yẖa ʼapé֖̇⁠kĕ kȧ⁠ţȧṗẇẖiֽym׃"],[7,9,"וְ⁠חִכֵּ֕⁠ךְ כְּ⁠יֵ֥ין הַ⁠טּ֛וֹב הוֹלֵ֥ךְ לְ⁠דוֹדִ֖⁠י לְ⁠מֵישָׁרִ֑ים דּוֹבֵ֖ב שִׂפְתֵ֥י יְשֵׁנִֽים׃","wĕ⁠ẖiké̇֕⁠kĕ kĕ̇⁠yé֥yn ha⁠ṫ֛wòb hwòlé֥kĕ lĕ⁠dwòdi֖⁠y lĕ⁠méyşá̌ri֑ym ḋwòbé֖b şîpĕţé֥y yĕşé̌niֽym׃"],[7,10,"אֲנִ֣י לְ⁠דוֹדִ֔⁠י וְ⁠עָלַ֖⁠י תְּשׁוּקָתֽ⁠וֹ׃ס","ʼàni֣y lĕ⁠dwòdi֔⁠y wĕ⁠ʻála֖⁠y ţĕ̇ş̌ẇqáţֽ⁠wò׃s"],[7,11,"לְכָ֤⁠ה דוֹדִ⁠י֙ נֵצֵ֣א הַ⁠שָּׂדֶ֔ה נָלִ֖ינָה בַּ⁠כְּפָרִֽים׃","lĕká֤⁠h dwòdi⁠y֙ néẕé֣ʼ ha⁠şá̇̂de֔h náli֖ynáh bȧ⁠kĕ̇páriֽym׃"],[7,12,"נַשְׁכִּ֨ימָה֙ לַ⁠כְּרָמִ֔ים נִרְאֶ֞ה אִם פָּֽרְחָ֤ה הַ⁠גֶּ֨פֶן֙ פִּתַּ֣ח הַ⁠סְּמָדַ֔ר הֵנֵ֖צוּ הָ⁠רִמּוֹנִ֑ים שָׁ֛ם אֶתֵּ֥ן אֶת־דֹּדַ֖⁠י לָֽ⁠ךְ׃","naşĕ̌ki̇֨ymáh֙ la⁠kĕ̇rámi֔ym nirĕʼe֞h ʼim páֽ̇rĕẖá֤h ha⁠gė֨pen֙ pi̇ţȧ֣ẖ ha⁠sĕ̇máda֔r héné֖ẕẇ há⁠riṁwòni֑ym şá֛̌m ʼeţé֥̇n ʼeţ-dò̇da֖⁠y láֽ⁠kĕ׃"],[7,13,"הַֽ⁠דּוּדָאִ֣ים נָֽתְנוּ־רֵ֗יחַ וְ⁠עַל־פְּתָחֵ֨י⁠נוּ֙ כָּל־מְגָדִ֔ים חֲדָשִׁ֖ים גַּם־יְשָׁנִ֑ים דּוֹדִ֖⁠י צָפַ֥נְתִּי לָֽ⁠ךְ׃","haֽ⁠ḋẇdáʼi֣ym náֽţĕnẇ-ré֗yẖa wĕ⁠ʻal-pĕ̇ţáẖé֨y⁠nẇ֙ ká̇l-mĕgádi֔ym ẖàdáşǐ֖ym gȧm-yĕşá̌ni֑ym ḋwòdi֖⁠y ẕápa֥nĕţi̇y láֽ⁠kĕ׃"],[8,1,"מִ֤י יִתֶּנְ⁠ךָ֙ כְּ⁠אָ֣ח לִ֔⁠י יוֹנֵ֖ק שְׁדֵ֣י אִמִּ֑⁠י אֶֽמְצָאֲ⁠ךָ֤ בַ⁠חוּץ֙ אֶשָׁ֣קְ⁠ךָ֔ גַּ֖ם לֹא־יָב֥וּזוּ לִֽ⁠י׃","mi֤y yiţėnĕ⁠ká֙ kĕ̇⁠ʼá֣ẖ li֔⁠y ywòné֖q şĕ̌dé֣y ʼimi֑̇⁠y ʼeֽmĕẕáʼà⁠ká֤ ba⁠ẖẇẕ֙ ʼeşá֣̌qĕ⁠ká֔ gȧ֖m lòʼ-yáb֥ẇzẇ liֽ⁠y׃"],[8,2,"אֶנְהָֽגֲ⁠ךָ֗ אֲבִֽיאֲ⁠ךָ֛ אֶל־בֵּ֥ית אִמִּ֖⁠י תְּלַמְּדֵ֑⁠נִי אַשְׁקְ⁠ךָ֙ מִ⁠יַּ֣יִן הָ⁠רֶ֔קַח מֵ⁠עֲסִ֖יס רִמֹּנִֽ⁠י׃","ʼenĕháֽgà⁠ká֗ ʼàbiֽyʼà⁠ká֛ ʼel-bé֥̇yţ ʼimi֖̇⁠y ţĕ̇lamĕ̇dé֑⁠niy ʼaşĕ̌qĕ⁠ká֙ mi⁠yȧ֣yin há⁠re֔qaẖ mé⁠ʻàsi֖ys rimò̇niֽ⁠y׃"],[8,3,"שְׂמֹאל⁠וֹ֙ תַּ֣חַת רֹאשִׁ֔⁠י וִֽ⁠ימִינ֖⁠וֹ תְּחַבְּקֵֽ⁠נִי׃","şĕ̂mòʼl⁠wò֙ ţȧ֣ẖaţ ròʼşǐ֔⁠y wiֽ⁠ymiyn֖⁠wò ţĕ̇ẖabĕ̇qéֽ⁠niy׃"],[8,4,"הִשְׁבַּ֥עְתִּי אֶתְ⁠כֶ֖ם בְּנ֣וֹת יְרוּשָׁלִָ֑ם מַה־תָּעִ֧ירוּ ׀ וּֽ⁠מַה־תְּעֹֽרְר֛וּ אֶת־הָ⁠אַהֲבָ֖ה עַ֥ד שֶׁ⁠תֶּחְפָּֽץ׃ס","hişĕ̌bȧ֥ʻĕţi̇y ʼeţĕ⁠ke֖m bĕ̇n֣wòţ yĕrẇşá̌liá֑m mah-ţá̇ʻi֧yrẇ ׀ ẇֽ⁠mah-ţĕ̇ʻòֽrĕr֛ẇ ʼeţ-há⁠ʼahàbá֖h ʻa֥d şě⁠ţėẖĕpáֽ̇ẕ׃s"],[8,5,"מִ֣י זֹ֗את עֹלָה֙ מִן־הַ⁠מִּדְבָּ֔ר מִתְרַפֶּ֖קֶת עַל־דּוֹדָ֑⁠הּ תַּ֤חַת הַ⁠תַּפּ֨וּחַ֙ עֽוֹרַרְתִּ֔י⁠ךָ שָׁ֚מָּ⁠ה חִבְּלַ֣תְ⁠ךָ אִמֶּ֔⁠ךָ שָׁ֖מָּ⁠ה חִבְּלָ֥ה יְלָדַֽתְ⁠ךָ׃","mi֣y zò֗ʼţ ʻòláh֙ min-ha⁠mi̇dĕbá̇֔r miţĕrapė֖qeţ ʻal-ḋwòdá֑⁠ḣ ţȧ֤ẖaţ ha⁠ţȧṗ֨ẇẖa֙ ʻֽwòrarĕţi̇֔y⁠ká şá֚̌má̇⁠h ẖibĕ̇la֣ţĕ⁠ká ʼimė֔⁠ká şá֖̌má̇⁠h ẖibĕ̇lá֥h yĕládaֽţĕ⁠ká׃"],[8,6,"שִׂימֵ֨⁠נִי כַֽ⁠חוֹתָ֜ם עַל־לִבֶּ֗⁠ךָ כַּֽ⁠חוֹתָם֙ עַל־זְרוֹעֶ֔⁠ךָ כִּֽי־עַזָּ֤ה כַ⁠מָּ֨וֶת֙ אַהֲבָ֔ה קָשָׁ֥ה כִ⁠שְׁא֖וֹל קִנְאָ֑ה רְשָׁפֶ֕י⁠הָ רִשְׁפֵּ֕י אֵ֖שׁ שַׁלְהֶ֥בֶתְ יָֽה׃","şîymé֨⁠niy kaֽ⁠ẖwòţá֜m ʻal-libė֗⁠ká kȧֽ⁠ẖwòţám֙ ʻal-zĕrwòʻe֔⁠ká kiֽ̇y-ʻazá֤̇h ka⁠má̇֨weţ֙ ʼahàbá֔h qáşá֥̌h ki⁠şĕ̌ʼ֖wòl qinĕʼá֑h rĕşá̌pe֕y⁠há rişĕ̌pé̇֕y ʼé֖ş̌ şǎlĕhe֥beţĕ yáֽh׃"],[8,7,"מַ֣יִם רַבִּ֗ים לֹ֤א יֽוּכְלוּ֙ לְ⁠כַבּ֣וֹת אֶת־הָֽ⁠אַהֲבָ֔ה וּ⁠נְהָר֖וֹת לֹ֣א יִשְׁטְפ֑וּ⁠הָ אִם־יִתֵּ֨ן אִ֜ישׁ אֶת־כָּל־ה֤וֹן בֵּית⁠וֹ֙ בָּ⁠אַהֲבָ֔ה בּ֖וֹז יָב֥וּזוּ לֽ⁠וֹ׃ס","ma֣yim rabi̇֗ym lò֤ʼ yֽẇkĕlẇ֙ lĕ⁠kaḃ֣wòţ ʼeţ-háֽ⁠ʼahàbá֔h ẇ⁠nĕhár֖wòţ lò֣ʼ yişĕ̌tĕp֑ẇ⁠há ʼim-yiţé̇֨n ʼi֜yş̌ ʼeţ-ká̇l-h֤wòn bé̇yţ⁠wò֙ bá̇⁠ʼahàbá֔h ḃ֖wòz yáb֥ẇzẇ lֽ⁠wò׃s"],[8,8,"אָח֥וֹת לָ֨⁠נוּ֙ קְטַנָּ֔ה וְ⁠שָׁדַ֖יִם אֵ֣ין לָ֑⁠הּ מַֽה־נַּעֲשֶׂה֙ לַ⁠אֲחֹתֵ֔⁠נוּ בַּ⁠יּ֖וֹם שֶׁ⁠יְּדֻבַּר־בָּֽ⁠הּ׃","ʼáẖ֥wòţ lá֨⁠nẇ֙ qĕtaná̇֔h wĕ⁠şá̌da֖yim ʼé֣yn lá֑⁠ḣ maֽh-nȧʻàşêh֙ la⁠ʼàẖòţé֔⁠nẇ bȧ⁠ẏ֖wòm şě⁠yĕ̇dubȧr-báֽ̇⁠ḣ׃"],[8,9,"אִם־חוֹמָ֣ה הִ֔יא נִבְנֶ֥ה עָלֶ֖י⁠הָ טִ֣ירַת כָּ֑סֶף וְ⁠אִם־דֶּ֣לֶת הִ֔יא נָצ֥וּר עָלֶ֖י⁠הָ ל֥וּחַ אָֽרֶז׃","ʼim-ẖwòmá֣h hi֔yʼ nibĕne֥h ʻále֖y⁠há ti֣yraţ ká֑̇sep wĕ⁠ʼim-dė֣leţ hi֔yʼ náẕ֥ẇr ʻále֖y⁠há l֥ẇẖa ʼáֽrez׃"],[8,10,"אֲנִ֣י חוֹמָ֔ה וְ⁠שָׁדַ֖⁠י כַּ⁠מִּגְדָּל֑וֹת אָ֛ז הָיִ֥יתִי בְ⁠עֵינָ֖י⁠ו כְּ⁠מוֹצְאֵ֥ת שָׁלֽוֹם׃פ","ʼàni֣y ẖwòmá֔h wĕ⁠şá̌da֖⁠y kȧ⁠mi̇gĕdá̇l֑wòţ ʼá֛z háyi֥yţiy bĕ⁠ʻéyná֖y⁠w kĕ̇⁠mwòẕĕʼé֥ţ şá̌lֽwòm׃p"],[8,11,"כֶּ֣רֶם הָיָ֤ה לִ⁠שְׁלֹמֹה֙ בְּ⁠בַ֣עַל הָמ֔וֹן נָתַ֥ן אֶת־הַ⁠כֶּ֖רֶם לַ⁠נֹּטְרִ֑ים אִ֛ישׁ יָבִ֥א בְּ⁠פִרְי֖⁠וֹ אֶ֥לֶף כָּֽסֶף׃","kė֣rem háyá֤h li⁠şĕ̌lòmòh֙ bĕ̇⁠ba֣ʻal hám֔wòn náţa֥n ʼeţ-ha⁠kė֖rem la⁠nò̇tĕri֑ym ʼi֛yş̌ yábi֥ʼ bĕ̇⁠pirĕy֖⁠wò ʼe֥lep káֽ̇sep׃"],[8,12,"כָּרְמִ֥⁠י שֶׁ⁠לִּ֖⁠י לְ⁠פָנָ֑⁠י הָ⁠אֶ֤לֶף לְ⁠ךָ֙ שְׁלֹמֹ֔ה וּ⁠מָאתַ֖יִם לְ⁠נֹטְרִ֥ים אֶת־פִּרְיֽ⁠וֹ׃","ká̇rĕmi֥⁠y şě⁠li֖̇⁠y lĕ⁠páná֑⁠y há⁠ʼe֤lep lĕ⁠ká֙ şĕ̌lòmò֔h ẇ⁠máʼţa֖yim lĕ⁠nòtĕri֥ym ʼeţ-pi̇rĕyֽ⁠wò׃"],[8,13,"הַ⁠יוֹשֶׁ֣בֶת בַּ⁠גַּנִּ֗ים חֲבֵרִ֛ים מַקְשִׁיבִ֥ים לְ⁠קוֹלֵ֖⁠ךְ הַשְׁמִיעִֽי⁠נִי׃","ha⁠ywòşě֣beţ bȧ⁠gȧni̇֗ym ẖàbéri֛ym maqĕşǐybi֥ym lĕ⁠qwòlé֖⁠kĕ haşĕ̌miyʻiֽy⁠niy׃"],[8,14,"בְּרַ֣ח ׀ דּוֹדִ֗⁠י וּֽ⁠דְמֵה־לְ⁠ךָ֤ לִ⁠צְבִי֙ א֚וֹ לְ⁠עֹ֣פֶר הָֽ⁠אַיָּלִ֔ים עַ֖ל הָרֵ֥י בְשָׂמִֽים׃","bĕ̇ra֣ẖ ׀ ḋwòdi֗⁠y ẇֽ⁠dĕméh-lĕ⁠ká֤ li⁠ẕĕbiy֙ ʼ֚wò lĕ⁠ʻò֣per háֽ⁠ʼayá̇li֔ym ʻa֖l háré֥y bĕşá̂miֽym׃"]],"fra-lsg1910":[[1,1,"Cantique des cantiques, de Salomon.","Cantique des cantiques, de Salomon."],[1,2,"Qu'il me baise des baisers de sa bouche! Car ton amour vaut mieux que le vin,","Qu'il me baise des baisers de sa bouche! Car ton amour vaut mieux que le vin,"],[1,3,"Tes parfums ont une odeur suave; Ton nom est un parfum qui se répand; C'est pourquoi les jeunes filles t'aiment.","Tes parfums ont une odeur suave; Ton nom est un parfum qui se répand; C'est pourquoi les jeunes filles t'aiment."],[1,4,"Entraîne-moi après toi! Nous courrons! Le roi m'introduit dans ses appartements... Nous nous égaierons, nous nous réjouirons à cause de toi; Nous célébrerons ton amour plus que le vin. C'est avec raison que l'on t'aime.","Entraîne-moi après toi! Nous courrons! Le roi m'introduit dans ses appartements... Nous nous égaierons, nous nous réjouirons à cause de toi; Nous célébrerons ton amour plus que le vin. C'est avec raison que l'on t'aime."],[1,5,"Je suis noire, mais je suis belle, filles de Jérusalem, Comme les tentes de Kédar, comme les pavillons de Salomon.","Je suis noire, mais je suis belle, filles de Jérusalem, Comme les tentes de Kédar, comme les pavillons de Salomon."],[1,6,"Ne prenez pas garde à mon teint noir: C'est le soleil qui m'a brûlée. Les fils de ma mère se sont irrités contre moi, Ils m'ont faite gardienne des vignes. Ma vigne, à moi, je ne l'ai pas gardée.","Ne prenez pas garde à mon teint noir: C'est le soleil qui m'a brûlée. Les fils de ma mère se sont irrités contre moi, Ils m'ont faite gardienne des vignes. Ma vigne, à moi, je ne l'ai pas gardée."],[1,7,"Dis-moi, ô toi que mon coeur aime, Où tu fais paître tes brebis, Où tu les fais reposer à midi; Car pourquoi serais-je comme une égarée Près des troupeaux de tes compagnons? -","Dis-moi, ô toi que mon coeur aime, Où tu fais paître tes brebis, Où tu les fais reposer à midi; Car pourquoi serais-je comme une égarée Près des troupeaux de tes compagnons? -"],[1,8,"Si tu ne le sais pas, ô la plus belle des femmes, Sors sur les traces des brebis, Et fais paître tes chevreaux Près des demeures des bergers. -","Si tu ne le sais pas, ô la plus belle des femmes, Sors sur les traces des brebis, Et fais paître tes chevreaux Près des demeures des bergers. -"],[1,9,"À ma jument qu'on attelle aux chars de Pharaon Je te compare, ô mon amie.","À ma jument qu'on attelle aux chars de Pharaon Je te compare, ô mon amie."],[1,10,"Tes joues sont belles au milieu des colliers, Ton cou est beau au milieu des rangées de perles.","Tes joues sont belles au milieu des colliers, Ton cou est beau au milieu des rangées de perles."],[1,11,"Nous te ferons des colliers d'or, Avec des points d'argent. -","Nous te ferons des colliers d'or, Avec des points d'argent. -"],[1,12,"Tandis que le roi est dans son entourage, Mon nard exhale son parfum.","Tandis que le roi est dans son entourage, Mon nard exhale son parfum."],[1,13,"Mon bien-aimé est pour moi un bouquet de myrrhe, Qui repose entre mes seins.","Mon bien-aimé est pour moi un bouquet de myrrhe, Qui repose entre mes seins."],[1,14,"Mon bien-aimé est pour moi une grappe de troëne Des vignes d'En-Guédi. -","Mon bien-aimé est pour moi une grappe de troëne Des vignes d'En-Guédi. -"],[1,15,"Que tu es belle, mon amie, que tu es belle! Tes yeux sont des colombes. -","Que tu es belle, mon amie, que tu es belle! Tes yeux sont des colombes. -"],[1,16,"Que tu es beau, mon bien-aimé, que tu es aimable! Notre lit, c'est la verdure. -","Que tu es beau, mon bien-aimé, que tu es aimable! Notre lit, c'est la verdure. -"],[1,17,"Les solives de nos maisons sont des cèdres, Nos lambris sont des cyprès. -","Les solives de nos maisons sont des cèdres, Nos lambris sont des cyprès. -"],[2,1,"Je suis un narcisse de Saron, Un lis des vallées. -","Je suis un narcisse de Saron, Un lis des vallées. -"],[2,2,"Comme un lis au milieu des épines, Telle est mon amie parmi les jeunes filles. -","Comme un lis au milieu des épines, Telle est mon amie parmi les jeunes filles. -"],[2,3,"Comme un pommier au milieu des arbres de la forêt, Tel est mon bien-aimé parmi les jeunes hommes. J'ai désiré m'asseoir à son ombre, Et son fruit est doux à mon palais.","Comme un pommier au milieu des arbres de la forêt, Tel est mon bien-aimé parmi les jeunes hommes. J'ai désiré m'asseoir à son ombre, Et son fruit est doux à mon palais."],[2,4,"Il m'a fait entrer dans la maison du vin; Et la bannière qu'il déploie sur moi, c'est l'amour.","Il m'a fait entrer dans la maison du vin; Et la bannière qu'il déploie sur moi, c'est l'amour."],[2,5,"Soutenez-moi avec des gâteaux de raisins, Fortifiez-moi avec des pommes; Car je suis malade d'amour.","Soutenez-moi avec des gâteaux de raisins, Fortifiez-moi avec des pommes; Car je suis malade d'amour."],[2,6,"Que sa main gauche soit sous ma tête, Et que sa droite m'embrasse! -","Que sa main gauche soit sous ma tête, Et que sa droite m'embrasse! -"],[2,7,"Je vous en conjure, filles de Jérusalem, Par les gazelles et les biches des champs, Ne réveillez pas, ne réveillez pas l'amour, Avant qu'elle le veuille. -","Je vous en conjure, filles de Jérusalem, Par les gazelles et les biches des champs, Ne réveillez pas, ne réveillez pas l'amour, Avant qu'elle le veuille. -"],[2,8,"C'est la voix de mon bien-aimé! Le voici, il vient, Sautant sur les montagnes, Bondissant sur les collines.","C'est la voix de mon bien-aimé! Le voici, il vient, Sautant sur les montagnes, Bondissant sur les collines."],[2,9,"Mon bien-aimé est semblable à la gazelle Ou au faon des biches. Le voici, il est derrière notre mur, Il regarde par la fenêtre, Il regarde par le treillis.","Mon bien-aimé est semblable à la gazelle Ou au faon des biches. Le voici, il est derrière notre mur, Il regarde par la fenêtre, Il regarde par le treillis."],[2,10,"Mon bien-aimé parle et me dit: Lève-toi, mon amie, ma belle, et viens!","Mon bien-aimé parle et me dit: Lève-toi, mon amie, ma belle, et viens!"],[2,11,"Car voici, l'hiver est passé; La pluie a cessé, elle s'en est allée.","Car voici, l'hiver est passé; La pluie a cessé, elle s'en est allée."],[2,12,"Les fleurs paraissent sur la terre, Le temps de chanter est arrivé, Et la voix de la tourterelle se fait entendre dans nos campagnes.","Les fleurs paraissent sur la terre, Le temps de chanter est arrivé, Et la voix de la tourterelle se fait entendre dans nos campagnes."],[2,13,"Le figuier embaume ses fruits, Et les vignes en fleur exhalent leur parfum. Lève-toi, mon amie, ma belle, et viens!","Le figuier embaume ses fruits, Et les vignes en fleur exhalent leur parfum. Lève-toi, mon amie, ma belle, et viens!"],[2,14,"Ma colombe, qui te tiens dans les fentes du rocher, Qui te caches dans les parois escarpées, Fais-moi voir ta figure, Fais-moi entendre ta voix; Car ta voix est douce, et ta figure est agréable.","Ma colombe, qui te tiens dans les fentes du rocher, Qui te caches dans les parois escarpées, Fais-moi voir ta figure, Fais-moi entendre ta voix; Car ta voix est douce, et ta figure est agréable."],[2,15,"Prenez-nous les renards, Les petits renards qui ravagent les vignes; Car nos vignes sont en fleur.","Prenez-nous les renards, Les petits renards qui ravagent les vignes; Car nos vignes sont en fleur."],[2,16,"Mon bien-aimé est à moi, et je suis à lui; Il fait paître son troupeau parmi les lis.","Mon bien-aimé est à moi, et je suis à lui; Il fait paître son troupeau parmi les lis."],[2,17,"Avant que le jour se rafraîchisse, Et que les ombres fuient, Reviens!... sois semblable, mon bien-aimé, À la gazelle ou au faon des biches, Sur les montagnes qui nous séparent.","Avant que le jour se rafraîchisse, Et que les ombres fuient, Reviens!... sois semblable, mon bien-aimé, À la gazelle ou au faon des biches, Sur les montagnes qui nous séparent."],[3,1,"Sur ma couche, pendant les nuits, J'ai cherché celui que mon coeur aime; Je l'ai cherché, et je ne l'ai point trouvé...","Sur ma couche, pendant les nuits, J'ai cherché celui que mon coeur aime; Je l'ai cherché, et je ne l'ai point trouvé..."],[3,2,"Je me lèverai, et je ferai le tour de la ville, Dans les rues et sur les places; Je chercherai celui que mon coeur aime... Je l'ai cherché, et je ne l'ai point trouvé.","Je me lèverai, et je ferai le tour de la ville, Dans les rues et sur les places; Je chercherai celui que mon coeur aime... Je l'ai cherché, et je ne l'ai point trouvé."],[3,3,"Les gardes qui font la ronde dans la ville m'ont rencontrée: Avez-vous vu celui que mon coeur aime?","Les gardes qui font la ronde dans la ville m'ont rencontrée: Avez-vous vu celui que mon coeur aime?"],[3,4,"À peine les avais-je passés, Que j'ai trouvé celui que mon coeur aime; Je l'ai saisi, et je ne l'ai point lâché Jusqu'à ce que je l'aie amené dans la maison de ma mère, Dans la chambre de celle qui m'a conçue. -","À peine les avais-je passés, Que j'ai trouvé celui que mon coeur aime; Je l'ai saisi, et je ne l'ai point lâché Jusqu'à ce que je l'aie amené dans la maison de ma mère, Dans la chambre de celle qui m'a conçue. -"],[3,5,"Je vous en conjure, filles de Jérusalem, Par les gazelles et les biches des champs, Ne réveillez pas, ne réveillez pas l'amour, Avant qu'elle le veuille. -","Je vous en conjure, filles de Jérusalem, Par les gazelles et les biches des champs, Ne réveillez pas, ne réveillez pas l'amour, Avant qu'elle le veuille. -"],[3,6,"Qui est celle qui monte du désert, Comme des colonnes de fumée, Au milieu des vapeurs de myrrhe et d'encens Et de tous les aromates des marchands? -","Qui est celle qui monte du désert, Comme des colonnes de fumée, Au milieu des vapeurs de myrrhe et d'encens Et de tous les aromates des marchands? -"],[3,7,"Voici la litière de Salomon, Et autour d'elle soixante vaillants hommes, Des plus vaillants d'Israël.","Voici la litière de Salomon, Et autour d'elle soixante vaillants hommes, Des plus vaillants d'Israël."],[3,8,"Tous sont armés de l'épée, Sont exercés au combat; Chacun porte l'épée sur sa hanche, En vue des alarmes nocturnes.","Tous sont armés de l'épée, Sont exercés au combat; Chacun porte l'épée sur sa hanche, En vue des alarmes nocturnes."],[3,9,"Le roi Salomon s'est fait une litière De bois du Liban.","Le roi Salomon s'est fait une litière De bois du Liban."],[3,10,"Il en a fait les colonnes d'argent, Le dossier d'or, Le siège de pourpre; Au milieu est une broderie, oeuvre d'amour Des filles de Jérusalem.","Il en a fait les colonnes d'argent, Le dossier d'or, Le siège de pourpre; Au milieu est une broderie, oeuvre d'amour Des filles de Jérusalem."],[3,11,"Sortez, filles de Sion, regardez Le roi Salomon, Avec la couronne dont sa mère l'a couronné Le jour de ses fiançailles, Le jour de la joie de son coeur. -","Sortez, filles de Sion, regardez Le roi Salomon, Avec la couronne dont sa mère l'a couronné Le jour de ses fiançailles, Le jour de la joie de son coeur. -"],[4,1,"Que tu es belle, mon amie, que tu es belle! Tes yeux sont des colombes, Derrière ton voile. Tes cheveux sont comme un troupeau de chèvres, Suspendues aux flancs de la montagne de Galaad.","Que tu es belle, mon amie, que tu es belle! Tes yeux sont des colombes, Derrière ton voile. Tes cheveux sont comme un troupeau de chèvres, Suspendues aux flancs de la montagne de Galaad."],[4,2,"Tes dents sont comme un troupeau de brebis tondues, Qui remontent de l'abreuvoir; Toutes portent des jumeaux, Aucune d'elles n'est stérile.","Tes dents sont comme un troupeau de brebis tondues, Qui remontent de l'abreuvoir; Toutes portent des jumeaux, Aucune d'elles n'est stérile."],[4,3,"Tes lèvres sont comme un fil cramoisi, Et ta bouche est charmante; Ta joue est comme une moitié de grenade, Derrière ton voile.","Tes lèvres sont comme un fil cramoisi, Et ta bouche est charmante; Ta joue est comme une moitié de grenade, Derrière ton voile."],[4,4,"Ton cou est comme la tour de David, Bâtie pour être un arsenal; Mille boucliers y sont suspendus, Tous les boucliers des héros.","Ton cou est comme la tour de David, Bâtie pour être un arsenal; Mille boucliers y sont suspendus, Tous les boucliers des héros."],[4,5,"Tes deux seins sont comme deux faons, Comme les jumeaux d'une gazelle, Qui paissent au milieu des lis.","Tes deux seins sont comme deux faons, Comme les jumeaux d'une gazelle, Qui paissent au milieu des lis."],[4,6,"Avant que le jour se rafraîchisse, Et que les ombres fuient, J'irai à la montagne de la myrrhe Et à la colline de l'encens.","Avant que le jour se rafraîchisse, Et que les ombres fuient, J'irai à la montagne de la myrrhe Et à la colline de l'encens."],[4,7,"Tu es toute belle, mon amie, Et il n'y a point en toi de défaut.","Tu es toute belle, mon amie, Et il n'y a point en toi de défaut."],[4,8,"Viens avec moi du Liban, ma fiancée, Viens avec moi du Liban! Regarde du sommet de l'Amana, Du sommet du Senir et de l'Hermon, Des tanières des lions, Des montagnes des léopards.","Viens avec moi du Liban, ma fiancée, Viens avec moi du Liban! Regarde du sommet de l'Amana, Du sommet du Senir et de l'Hermon, Des tanières des lions, Des montagnes des léopards."],[4,9,"Tu me ravis le coeur, ma soeur, ma fiancée, Tu me ravis le coeur par l'un de tes regards, Par l'un des colliers de ton cou.","Tu me ravis le coeur, ma soeur, ma fiancée, Tu me ravis le coeur par l'un de tes regards, Par l'un des colliers de ton cou."],[4,10,"Que de charmes dans ton amour, ma soeur, ma fiancée! Comme ton amour vaut mieux que le vin, Et combien tes parfums sont plus suaves que tous les aromates!","Que de charmes dans ton amour, ma soeur, ma fiancée! Comme ton amour vaut mieux que le vin, Et combien tes parfums sont plus suaves que tous les aromates!"],[4,11,"Tes lèvres distillent le miel, ma fiancée; Il y a sous ta langue du miel et du lait, Et l'odeur de tes vêtements est comme l'odeur du Liban.","Tes lèvres distillent le miel, ma fiancée; Il y a sous ta langue du miel et du lait, Et l'odeur de tes vêtements est comme l'odeur du Liban."],[4,12,"Tu es un jardin fermé, ma soeur, ma fiancée, Une source fermée, une fontaine scellée.","Tu es un jardin fermé, ma soeur, ma fiancée, Une source fermée, une fontaine scellée."],[4,13,"Tes jets forment un jardin, où sont des grenadiers, Avec les fruits les plus excellents, Les troënes avec le nard;","Tes jets forment un jardin, où sont des grenadiers, Avec les fruits les plus excellents, Les troënes avec le nard;"],[4,14,"Le nard et le safran, le roseau aromatique et le cinnamome, Avec tous les arbres qui donnent l'encens; La myrrhe et l'aloès, Avec tous les principaux aromates;","Le nard et le safran, le roseau aromatique et le cinnamome, Avec tous les arbres qui donnent l'encens; La myrrhe et l'aloès, Avec tous les principaux aromates;"],[4,15,"Une fontaine des jardins, Une source d'eaux vives, Des ruisseaux du Liban.","Une fontaine des jardins, Une source d'eaux vives, Des ruisseaux du Liban."],[4,16,"Lève-toi, aquilon! viens, autan! Soufflez sur mon jardin, et que les parfums s'en exhalent! -Que mon bien-aimé entre dans son jardin, Et qu'il mange de ses fruits excellents! -","Lève-toi, aquilon! viens, autan! Soufflez sur mon jardin, et que les parfums s'en exhalent! -Que mon bien-aimé entre dans son jardin, Et qu'il mange de ses fruits excellents! -"],[5,1,"J'entre dans mon jardin, ma soeur, ma fiancée; Je cueille ma myrrhe avec mes aromates, Je mange mon rayon de miel avec mon miel, Je bois mon vin avec mon lait... -Mangez, amis, buvez, enivrez-vous d'amour! -","J'entre dans mon jardin, ma soeur, ma fiancée; Je cueille ma myrrhe avec mes aromates, Je mange mon rayon de miel avec mon miel, Je bois mon vin avec mon lait... -Mangez, amis, buvez, enivrez-vous d'amour! -"],[5,2,"J'étais endormie, mais mon coeur veillait... C'est la voix de mon bien-aimé, qui frappe: -Ouvre-moi, ma soeur, mon amie, Ma colombe, ma parfaite! Car ma tête est couverte de rosée, Mes boucles sont pleines des gouttes de la nuit. -","J'étais endormie, mais mon coeur veillait... C'est la voix de mon bien-aimé, qui frappe: -Ouvre-moi, ma soeur, mon amie, Ma colombe, ma parfaite! Car ma tête est couverte de rosée, Mes boucles sont pleines des gouttes de la nuit. -"],[5,3,"J'ai ôté ma tunique; comment la remettrais-je? J'ai lavé mes pieds; comment les salirais-je?","J'ai ôté ma tunique; comment la remettrais-je? J'ai lavé mes pieds; comment les salirais-je?"],[5,4,"Mon bien-aimé a passé la main par la fenêtre, Et mes entrailles se sont émues pour lui.","Mon bien-aimé a passé la main par la fenêtre, Et mes entrailles se sont émues pour lui."],[5,5,"Je me suis levée pour ouvrir à mon bien-aimé; Et de mes mains a dégoutté la myrrhe, De mes doigts, la myrrhe répandue Sur la poignée du verrou.","Je me suis levée pour ouvrir à mon bien-aimé; Et de mes mains a dégoutté la myrrhe, De mes doigts, la myrrhe répandue Sur la poignée du verrou."],[5,6,"J'ai ouvert à mon bien-aimé; Mais mon bien-aimé s'en était allé, il avait disparu. J'étais hors de moi, quand il me parlait. Je l'ai cherché, et je ne l'ai point trouvé; Je l'ai appelé, et il ne m'a point répondu.","J'ai ouvert à mon bien-aimé; Mais mon bien-aimé s'en était allé, il avait disparu. J'étais hors de moi, quand il me parlait. Je l'ai cherché, et je ne l'ai point trouvé; Je l'ai appelé, et il ne m'a point répondu."],[5,7,"Les gardes qui font la ronde dans la ville m'ont rencontrée; Ils m'ont frappée, ils m'ont blessée; Ils m'ont enlevé mon voile, les gardes des murs.","Les gardes qui font la ronde dans la ville m'ont rencontrée; Ils m'ont frappée, ils m'ont blessée; Ils m'ont enlevé mon voile, les gardes des murs."],[5,8,"Je vous en conjure, filles de Jérusalem, Si vous trouvez mon bien-aimé, Que lui direz-vous?... Que je suis malade d'amour. -","Je vous en conjure, filles de Jérusalem, Si vous trouvez mon bien-aimé, Que lui direz-vous?... Que je suis malade d'amour. -"],[5,9,"Qu'a ton bien-aimé de plus qu'un autre, O la plus belle des femmes? Qu'a ton bien-aimé de plus qu'un autre, Pour que tu nous conjures ainsi? -","Qu'a ton bien-aimé de plus qu'un autre, O la plus belle des femmes? Qu'a ton bien-aimé de plus qu'un autre, Pour que tu nous conjures ainsi? -"],[5,10,"Mon bien-aimé est blanc et vermeil; Il se distingue entre dix mille.","Mon bien-aimé est blanc et vermeil; Il se distingue entre dix mille."],[5,11,"Sa tête est de l'or pur; Ses boucles sont flottantes, Noires comme le corbeau.","Sa tête est de l'or pur; Ses boucles sont flottantes, Noires comme le corbeau."],[5,12,"Ses yeux sont comme des colombes au bord des ruisseaux, Se baignant dans le lait, Reposant au sein de l'abondance.","Ses yeux sont comme des colombes au bord des ruisseaux, Se baignant dans le lait, Reposant au sein de l'abondance."],[5,13,"Ses joues sont comme un parterre d'aromates, Une couche de plantes odorantes; Ses lèvres sont des lis, D'où découle la myrrhe.","Ses joues sont comme un parterre d'aromates, Une couche de plantes odorantes; Ses lèvres sont des lis, D'où découle la myrrhe."],[5,14,"Ses mains sont des anneaux d'or, Garnis de chrysolithes; Son corps est de l'ivoire poli, Couvert de saphirs;","Ses mains sont des anneaux d'or, Garnis de chrysolithes; Son corps est de l'ivoire poli, Couvert de saphirs;"],[5,15,"Ses jambes sont des colonnes de marbre blanc, Posées sur des bases d'or pur. Son aspect est comme le Liban, Distingué comme les cèdres.","Ses jambes sont des colonnes de marbre blanc, Posées sur des bases d'or pur. Son aspect est comme le Liban, Distingué comme les cèdres."],[5,16,"Son palais n'est que douceur, Et toute sa personne est pleine de charme. Tel est mon bien-aimé, tel est mon ami, Filles de Jérusalem! -","Son palais n'est que douceur, Et toute sa personne est pleine de charme. Tel est mon bien-aimé, tel est mon ami, Filles de Jérusalem! -"],[6,1,"Où est allé ton bien-aimé, O la plus belle des femmes? De quel côté ton bien-aimé s'est-il dirigé? Nous le chercherons avec toi.","Où est allé ton bien-aimé, O la plus belle des femmes? De quel côté ton bien-aimé s'est-il dirigé? Nous le chercherons avec toi."],[6,2,"Mon bien-aimé est descendu à son jardin, Au parterre d'aromates, Pour faire paître son troupeau dans les jardins, Et pour cueillir des lis.","Mon bien-aimé est descendu à son jardin, Au parterre d'aromates, Pour faire paître son troupeau dans les jardins, Et pour cueillir des lis."],[6,3,"Je suis à mon bien-aimé, et mon bien-aimé est à moi; Il fait paître son troupeau parmi les lis. -","Je suis à mon bien-aimé, et mon bien-aimé est à moi; Il fait paître son troupeau parmi les lis. -"],[6,4,"Tu es belle, mon amie, comme Thirtsa, Agréable comme Jérusalem, Mais terrible comme des troupes sous leurs bannières.","Tu es belle, mon amie, comme Thirtsa, Agréable comme Jérusalem, Mais terrible comme des troupes sous leurs bannières."],[6,5,"Détourne de moi tes yeux, car ils me troublent. Tes cheveux sont comme un troupeau de chèvres, Suspendues aux flancs de Galaad.","Détourne de moi tes yeux, car ils me troublent. Tes cheveux sont comme un troupeau de chèvres, Suspendues aux flancs de Galaad."],[6,6,"Tes dents sont comme un troupeau de brebis, Qui remontent de l'abreuvoir; Toutes portent des jumeaux, Aucune d'elles n'est stérile.","Tes dents sont comme un troupeau de brebis, Qui remontent de l'abreuvoir; Toutes portent des jumeaux, Aucune d'elles n'est stérile."],[6,7,"Ta joue est comme une moitié de grenade, Derrière ton voile...","Ta joue est comme une moitié de grenade, Derrière ton voile..."],[6,8,"Il y a soixante reines, quatre-vingts concubines, Et des jeunes filles sans nombre.","Il y a soixante reines, quatre-vingts concubines, Et des jeunes filles sans nombre."],[6,9,"Une seule est ma colombe, ma parfaite; Elle est l'unique de sa mère, La préférée de celle qui lui donna le jour. Les jeunes filles la voient, et la disent heureuse; Les reines et les concubines aussi, et elles la louent. -","Une seule est ma colombe, ma parfaite; Elle est l'unique de sa mère, La préférée de celle qui lui donna le jour. Les jeunes filles la voient, et la disent heureuse; Les reines et les concubines aussi, et elles la louent. -"],[6,10,"Qui est celle qui apparaît comme l'aurore, Belle comme la lune, pure comme le soleil, Mais terrible comme des troupes sous leurs bannières? -","Qui est celle qui apparaît comme l'aurore, Belle comme la lune, pure comme le soleil, Mais terrible comme des troupes sous leurs bannières? -"],[6,11,"Je suis descendue au jardin des noyers, Pour voir la verdure de la vallée, Pour voir si la vigne pousse, Si les grenadiers fleurissent.","Je suis descendue au jardin des noyers, Pour voir la verdure de la vallée, Pour voir si la vigne pousse, Si les grenadiers fleurissent."],[6,12,"Je ne sais, mais mon désir m'a rendue semblable Aux chars de mon noble peuple. -","Je ne sais, mais mon désir m'a rendue semblable Aux chars de mon noble peuple. -"],[6,13,"Reviens, reviens, Sulamithe! Reviens, reviens, afin que nous te regardions. -Qu'avez-vous à regarder la Sulamithe Comme une danse de deux choeurs?","Reviens, reviens, Sulamithe! Reviens, reviens, afin que nous te regardions. -Qu'avez-vous à regarder la Sulamithe Comme une danse de deux choeurs?"],[7,1,"Que tes pieds sont beaux dans ta chaussure, fille de prince! Les contours de ta hanche sont comme des colliers, Oeuvre des mains d'un artiste.","Que tes pieds sont beaux dans ta chaussure, fille de prince! Les contours de ta hanche sont comme des colliers, Oeuvre des mains d'un artiste."],[7,2,"Ton sein est une coupe arrondie, Où le vin parfumé ne manque pas; Ton corps est un tas de froment, Entouré de lis.","Ton sein est une coupe arrondie, Où le vin parfumé ne manque pas; Ton corps est un tas de froment, Entouré de lis."],[7,3,"Tes deux seins sont comme deux faons, Comme les jumeaux d'une gazelle.","Tes deux seins sont comme deux faons, Comme les jumeaux d'une gazelle."],[7,4,"Ton cou est comme une tour d'ivoire; Tes yeux sont comme les étangs de Hesbon, Près de la porte de Bath-Rabbim; Ton nez est comme la tour du Liban, Qui regarde du côté de Damas.","Ton cou est comme une tour d'ivoire; Tes yeux sont comme les étangs de Hesbon, Près de la porte de Bath-Rabbim; Ton nez est comme la tour du Liban, Qui regarde du côté de Damas."],[7,5,"Ta tête est élevée comme le Carmel, Et les cheveux de ta tête sont comme la pourpre; Un roi est enchaîné par des boucles!...","Ta tête est élevée comme le Carmel, Et les cheveux de ta tête sont comme la pourpre; Un roi est enchaîné par des boucles!..."],[7,6,"Que tu es belle, que tu es agréable, O mon amour, au milieu des délices!","Que tu es belle, que tu es agréable, O mon amour, au milieu des délices!"],[7,7,"Ta taille ressemble au palmier, Et tes seins à des grappes.","Ta taille ressemble au palmier, Et tes seins à des grappes."],[7,8,"Je me dis: Je monterai sur le palmier, J'en saisirai les rameaux! Que tes seins soient comme les grappes de la vigne, Le parfum de ton souffle comme celui des pommes,","Je me dis: Je monterai sur le palmier, J'en saisirai les rameaux! Que tes seins soient comme les grappes de la vigne, Le parfum de ton souffle comme celui des pommes,"],[7,9,"Et ta bouche comme un vin excellent,... -Qui coule aisément pour mon bien-aimé, Et glisse sur les lèvres de ceux qui s'endorment!","Et ta bouche comme un vin excellent,... -Qui coule aisément pour mon bien-aimé, Et glisse sur les lèvres de ceux qui s'endorment!"],[7,10,"Je suis à mon bien-aimé, Et ses désirs se portent vers moi.","Je suis à mon bien-aimé, Et ses désirs se portent vers moi."],[7,11,"Viens, mon bien-aimé, sortons dans les champs, Demeurons dans les villages!","Viens, mon bien-aimé, sortons dans les champs, Demeurons dans les villages!"],[7,12,"Dès le matin nous irons aux vignes, Nous verrons si la vigne pousse, si la fleur s'ouvre, Si les grenadiers fleurissent. Là je te donnerai mon amour.","Dès le matin nous irons aux vignes, Nous verrons si la vigne pousse, si la fleur s'ouvre, Si les grenadiers fleurissent. Là je te donnerai mon amour."],[7,13,"Les mandragores répandent leur parfum, Et nous avons à nos portes tous les meilleurs fruits, Nouveaux et anciens: Mon bien-aimé, je les ai gardés pour toi.","Les mandragores répandent leur parfum, Et nous avons à nos portes tous les meilleurs fruits, Nouveaux et anciens: Mon bien-aimé, je les ai gardés pour toi."],[8,1,"Oh! Que n'es-tu mon frère, Allaité des mamelles de ma mère! Je te rencontrerais dehors, je t'embrasserais, Et l'on ne me mépriserait pas.","Oh! Que n'es-tu mon frère, Allaité des mamelles de ma mère! Je te rencontrerais dehors, je t'embrasserais, Et l'on ne me mépriserait pas."],[8,2,"Je veux te conduire, t'amener à la maison de ma mère; Tu me donneras tes instructions, Et je te ferai boire du vin parfumé, Du moût de mes grenades.","Je veux te conduire, t'amener à la maison de ma mère; Tu me donneras tes instructions, Et je te ferai boire du vin parfumé, Du moût de mes grenades."],[8,3,"Que sa main gauche soit sous ma tête, Et que sa droite m'embrasse! -","Que sa main gauche soit sous ma tête, Et que sa droite m'embrasse! -"],[8,4,"Je vous en conjure, filles de Jérusalem, Ne réveillez pas, ne réveillez pas l'amour, Avant qu'elle le veuille. -","Je vous en conjure, filles de Jérusalem, Ne réveillez pas, ne réveillez pas l'amour, Avant qu'elle le veuille. -"],[8,5,"Qui est celle qui monte du désert, Appuyée sur son bien-aimé? -Je t'ai réveillée sous le pommier; Là ta mère t'a enfantée, C'est là qu'elle t'a enfantée, qu'elle t'a donné le jour. -","Qui est celle qui monte du désert, Appuyée sur son bien-aimé? -Je t'ai réveillée sous le pommier; Là ta mère t'a enfantée, C'est là qu'elle t'a enfantée, qu'elle t'a donné le jour. -"],[8,6,"Mets-moi comme un sceau sur ton coeur, Comme un sceau sur ton bras; Car l'amour est fort comme la mort, La jalousie est inflexible comme le séjour des morts; Ses ardeurs sont des ardeurs de feu, Une flamme de l'Éternel.","Mets-moi comme un sceau sur ton coeur, Comme un sceau sur ton bras; Car l'amour est fort comme la mort, La jalousie est inflexible comme le séjour des morts; Ses ardeurs sont des ardeurs de feu, Une flamme de l'Éternel."],[8,7,"Les grandes eaux ne peuvent éteindre l'amour, Et les fleuves ne le submergeraient pas; Quand un homme offrirait tous les biens de sa maison contre l'amour, Il ne s'attirerait que le mépris.","Les grandes eaux ne peuvent éteindre l'amour, Et les fleuves ne le submergeraient pas; Quand un homme offrirait tous les biens de sa maison contre l'amour, Il ne s'attirerait que le mépris."],[8,8,"Nous avons une petite soeur, Qui n'a point encore de mamelles; Que ferons-nous de notre soeur, Le jour où on la recherchera?","Nous avons une petite soeur, Qui n'a point encore de mamelles; Que ferons-nous de notre soeur, Le jour où on la recherchera?"],[8,9,"Si elle est un mur, Nous bâtirons sur elle des créneaux d'argent; Si elle est une porte, Nous la fermerons avec une planche de cèdre. -","Si elle est un mur, Nous bâtirons sur elle des créneaux d'argent; Si elle est une porte, Nous la fermerons avec une planche de cèdre. -"],[8,10,"Je suis un mur, Et mes seins sont comme des tours; J'ai été à ses yeux comme celle qui trouve la paix.","Je suis un mur, Et mes seins sont comme des tours; J'ai été à ses yeux comme celle qui trouve la paix."],[8,11,"Salomon avait une vigne à Baal-Hamon; Il remit la vigne à des gardiens; Chacun apportait pour son fruit mille sicles d'argent.","Salomon avait une vigne à Baal-Hamon; Il remit la vigne à des gardiens; Chacun apportait pour son fruit mille sicles d'argent."],[8,12,"Ma vigne, qui est à moi, je la garde. À toi, Salomon, les mille sicles, Et deux cents à ceux qui gardent le fruit! -","Ma vigne, qui est à moi, je la garde. À toi, Salomon, les mille sicles, Et deux cents à ceux qui gardent le fruit! -"],[8,13,"Habitante des jardins! Des amis prêtent l'oreille à ta voix. Daigne me la faire entendre! -","Habitante des jardins! Des amis prêtent l'oreille à ta voix. Daigne me la faire entendre! -"],[8,14,"Fuis, mon bien-aimé! Sois semblable à la gazelle ou au faon des biches, Sur les montagnes des aromates!","Fuis, mon bien-aimé! Sois semblable à la gazelle ou au faon des biches, Sur les montagnes des aromates!"]],"spa-rv1909":[[1,1,"CANCIÓNde canciones, la cuales de Salomón.","CANCIÓNde canciones, la cuales de Salomón."],[1,2,"¡Oh si él me besaracon ósculos de su boca! porque mejoressontus amoresque el vino.","¡Oh si él me besaracon ósculos de su boca! porque mejoressontus amoresque el vino."],[1,3,"Porel olorde tus suavesungüentos, (ungüentoderramadoes tu nombre,) poresolas doncellaste amaron.","Porel olorde tus suavesungüentos, (ungüentoderramadoes tu nombre,) poresolas doncellaste amaron."],[1,4,"Llévameen posde ti, correremos. Metiómeel reyen sus cámaras: nos gozaremosy alegraremosen ti; acordarémonosde tus amoresmás que del vino: los rectoste aman.","Llévameen posde ti, correremos. Metiómeel reyen sus cámaras: nos gozaremosy alegraremosen ti; acordarémonosde tus amoresmás que del vino: los rectoste aman."],[1,5,"Morenasoy, oh hijasde Jerusalem, mas codiciable; como las cabañas de Cedar, como las tiendasde Salomón.","Morenasoy, oh hijasde Jerusalem, mas codiciable; como las cabañas de Cedar, como las tiendasde Salomón."],[1,6,"Nomiréisen que soy morena, porque el solmemiró. Los hijosde mimadrese airaroncontra mí, hiciéronmeguardade viñas; ymiviña, que era mía, noguardé.","Nomiréisen que soy morena, porque el solmemiró. Los hijosde mimadrese airaroncontra mí, hiciéronmeguardade viñas; ymiviña, que era mía, noguardé."],[1,7,"Hazme saber, ó tú á quien amami alma, dónderepastas, dóndehaces tener majadaal medio día: porque, ¿por quéhabía yo de estarcomo vagueandotras los rebañosde tus compañeros?","Hazme saber, ó tú á quien amami alma, dónderepastas, dóndehaces tener majadaal medio día: porque, ¿por quéhabía yo de estarcomo vagueandotras los rebañosde tus compañeros?"],[1,8,"Si tú nolo sabes, oh hermosaentre las mujeres, sal, yéndote por las huellasdel rebaño, y apacientatuscabritasjunto álas cabañasde los pastores.","Si tú nolo sabes, oh hermosaentre las mujeres, sal, yéndote por las huellasdel rebaño, y apacientatuscabritasjunto álas cabañasde los pastores."],[1,9,"A yeguade los carrosde Faraónte he comparado, amigamía.","A yeguade los carrosde Faraónte he comparado, amigamía."],[1,10,"Hermosasson tus mejillasentre los pendientes, tu cuelloentre los collares.","Hermosasson tus mejillasentre los pendientes, tu cuelloentre los collares."],[1,11,"Zarcillosde orote haremos, con clavos de plata.","Zarcillosde orote haremos, con clavos de plata."],[1,12,"Mientrasque el reyestaba en su reclinatorio, mi nardodiósu olor.","Mientrasque el reyestaba en su reclinatorio, mi nardodiósu olor."],[1,13,"Mi amadoes para mí un manojitode mirra, que reposaentremis pechos.","Mi amadoes para mí un manojitode mirra, que reposaentremis pechos."],[1,14,"Racimode copheren las viñasde Engadies para mí mi amado.","Racimode copheren las viñasde Engadies para mí mi amado."],[1,15,"He aquíque tú eres hermosa, amigamía; he aquíque eres bella: tus ojosde paloma.","He aquíque tú eres hermosa, amigamía; he aquíque eres bella: tus ojosde paloma."],[1,16,"He aquíque tú eres hermoso, amadomío, y suave: nuestrolechotambién florido.","He aquíque tú eres hermoso, amadomío, y suave: nuestrolechotambién florido."],[1,17,"Las vigasde nuestracasason de cedro, yde cipréslos artesonados.","Las vigasde nuestracasason de cedro, yde cipréslos artesonados."],[2,1,"YOsoy la rosade Sarón, y el liriode los valles.","YOsoy la rosade Sarón, y el liriode los valles."],[2,2,"Como el lirioentrelas espinas, asíes mi amiga entrelas doncellas.","Como el lirioentrelas espinas, asíes mi amiga entrelas doncellas."],[2,3,"Como el manzanoentre los árbolessilvestres, asíes mi amadoentrelos mancebos: bajo la sombradel deseadome senté, y su frutofué dulceá mi paladar.","Como el manzanoentre los árbolessilvestres, asíes mi amadoentrelos mancebos: bajo la sombradel deseadome senté, y su frutofué dulceá mi paladar."],[2,4,"Llevómeála cámaradel vino, y su banderasobremí fué amor.","Llevómeála cámaradel vino, y su banderasobremí fué amor."],[2,5,"Sustentadmecon frascos, corroboradmecon manzanas; porqueestoy enfermade amor.","Sustentadmecon frascos, corroboradmecon manzanas; porqueestoy enfermade amor."],[2,6,"Su izquierdaestédebajode mi cabeza, y su derechame abrace.","Su izquierdaestédebajode mi cabeza, y su derechame abrace."],[2,7,"Yo os conjuro, oh doncellasde Jerusalem, por las gamas ypor las ciervasdel campo, que nodespertéisni hagáis velaral amor, hasta que quiera.","Yo os conjuro, oh doncellasde Jerusalem, por las gamas ypor las ciervasdel campo, que nodespertéisni hagáis velaral amor, hasta que quiera."],[2,8,"¡La vozde mi amado! He aquí élvienesaltandosobrelos montes, brincandosobrelos collados.","¡La vozde mi amado! He aquí élvienesaltandosobrelos montes, brincandosobrelos collados."],[2,9,"Mi amadoes semejanteal gamo, óal cabrito de los ciervos. Heloaquí, estátrasnuestrapared, mirandoporlas ventanas, mostrándose porlas rejas.","Mi amadoes semejanteal gamo, óal cabrito de los ciervos. Heloaquí, estátrasnuestrapared, mirandoporlas ventanas, mostrándose porlas rejas."],[2,10,"Mi amadohabló, y me dijo: Levántate, oh amigamía, hermosamía, y vente.","Mi amadohabló, y me dijo: Levántate, oh amigamía, hermosamía, y vente."],[2,11,"Porquehe aquíha pasadoel invierno, hase mudado, la lluviase fué;","Porquehe aquíha pasadoel invierno, hase mudado, la lluviase fué;"],[2,12,"Hanse mostradolas floresen la tierra, el tiempode la canciónes venido, y en nuestropaísse ha oídola vozde la tórtola;","Hanse mostradolas floresen la tierra, el tiempode la canciónes venido, y en nuestropaísse ha oídola vozde la tórtola;"],[2,13,"La higueraha echadosus higos, y las videsen ciernedieronolor: levántate, oh amigamía, hermosamía, y vente.","La higueraha echadosus higos, y las videsen ciernedieronolor: levántate, oh amigamía, hermosamía, y vente."],[2,14,"Palomamía, que estás en los agujerosde la peña, en lo escondidode escarpadosparajes, muéstrameturostro, hazme oirtuvoz; porquedulcees la voztuya, y hermosotuaspecto.","Palomamía, que estás en los agujerosde la peña, en lo escondidode escarpadosparajes, muéstrameturostro, hazme oirtuvoz; porquedulcees la voztuya, y hermosotuaspecto."],[2,15,"Cazadnoslas zorras, las zorraspequeñas, que echan á perderlas viñas; pues que nuestrasviñasestán en cierne.","Cazadnoslas zorras, las zorraspequeñas, que echan á perderlas viñas; pues que nuestrasviñasestán en cierne."],[2,16,"Miamadoes mío, y yosuya; él apacientaentre lirios.","Miamadoes mío, y yosuya; él apacientaentre lirios."],[2,17,"Hastaque apunteel día, y huyanlas sombras, tórnate, amadomío; sé semejanteal gamo, óal cabrito de los ciervos, sobrelos montesde Bether.","Hastaque apunteel día, y huyanlas sombras, tórnate, amadomío; sé semejanteal gamo, óal cabrito de los ciervos, sobrelos montesde Bether."],[3,1,"POR las nochesbusquéenmi lechoal que amami alma: busquélo, y nolo hallé.","POR las nochesbusquéenmi lechoal que amami alma: busquélo, y nolo hallé."],[3,2,"Levantarémeahora, y rodearépor la ciudad; por las callesy por las plazasbuscaréal que amami alma: busquélo, y nolo hallé.","Levantarémeahora, y rodearépor la ciudad; por las callesy por las plazasbuscaréal que amami alma: busquélo, y nolo hallé."],[3,3,"Halláronmelos guardasque rondanla ciudad, y díjeles: ¿Habéis vistoal que amami alma?","Halláronmelos guardasque rondanla ciudad, y díjeles: ¿Habéis vistoal que amami alma?"],[3,4,"Pasando de ellosun poco, halléluegoal que mi almaama: trabéde él, y nolo dejé, hastaque lo metíencasade mi madre, y enla cámarade la que me engendró.","Pasando de ellosun poco, halléluegoal que mi almaama: trabéde él, y nolo dejé, hastaque lo metíencasade mi madre, y enla cámarade la que me engendró."],[3,5,"Yo os conjuro, oh doncellasde Jerusalem, por las gamas ypor las ciervasdel campo, que nodespertéisnihagáis velaral amor, hastaque quiera.","Yo os conjuro, oh doncellasde Jerusalem, por las gamas ypor las ciervasdel campo, que nodespertéisnihagáis velaral amor, hastaque quiera."],[3,6,"¿Quiénes éstaque subedeldesiertocomo columnita de humo, sahumadade mirray de incienso, y detodos polvos aromáticos?","¿Quiénes éstaque subedeldesiertocomo columnita de humo, sahumadade mirray de incienso, y detodos polvos aromáticos?"],[3,7,"He aquíes la litera de Salomón: sesentavalientesla rodean, de los fuertesde Israel.","He aquíes la litera de Salomón: sesentavalientesla rodean, de los fuertesde Israel."],[3,8,"Todosellos tienenespadas, diestrosen la guerra; cada unosu espadasobresu muslo, por los temoresde la noche.","Todosellos tienenespadas, diestrosen la guerra; cada unosu espadasobresu muslo, por los temoresde la noche."],[3,9,"El reySalomónse hizouna carrozade maderadel Líbano.","El reySalomónse hizouna carrozade maderadel Líbano."],[3,10,"Sus columnashizode plata, su respaldode oro, su cielo de grana, su interiorenlosado de amor, por las doncellasde Jerusalem.","Sus columnashizode plata, su respaldode oro, su cielo de grana, su interiorenlosado de amor, por las doncellasde Jerusalem."],[3,11,"Salid, oh doncellasde Sión, y vedal reySalomóncon la coronacon que le coronósu madreel díade su desposorio, y el díadel gozode su corazón.","Salid, oh doncellasde Sión, y vedal reySalomóncon la coronacon que le coronósu madreel díade su desposorio, y el díadel gozode su corazón."],[4,1,"HE aquíque tú eres hermosa, amigamía; he aquíque tú eres hermosa; tus ojosentre tus guedejascomode paloma; tus cabellos comomanadade cabras, que se muestrandesde el montede Galaad.","HE aquíque tú eres hermosa, amigamía; he aquíque tú eres hermosa; tus ojosentre tus guedejascomode paloma; tus cabellos comomanadade cabras, que se muestrandesde el montede Galaad."],[4,2,"Tus dientes, como manadasde trasquiladasovejas, que subendellavadero, todascon crías mellizas, y ningunaentre ellas estéril.","Tus dientes, como manadasde trasquiladasovejas, que subendellavadero, todascon crías mellizas, y ningunaentre ellas estéril."],[4,3,"Tus labios, como un hilode grana, y tu hablahermosa; tus sienes, como cachosde granadaá la parte adentro de tus guedejas.","Tus labios, como un hilode grana, y tu hablahermosa; tus sienes, como cachosde granadaá la parte adentro de tus guedejas."],[4,4,"Tu cuello, como la torrede David, edificadapara muestra; milescudosestán colgadosde ella, todosescudosde valientes.","Tu cuello, como la torrede David, edificadapara muestra; milescudosestán colgadosde ella, todosescudosde valientes."],[4,5,"Tus dospechos, como doscabritos mellizosde gama, que son apacentadosentre azucenas.","Tus dospechos, como doscabritos mellizosde gama, que son apacentadosentre azucenas."],[4,6,"Hastaque apunteel díay huyanlas sombras, irémealmontede la mirra, y alcolladodel incienso.","Hastaque apunteel díay huyanlas sombras, irémealmontede la mirra, y alcolladodel incienso."],[4,7,"Todatú eres hermosa, amigamía, y en ti nohay mancha.","Todatú eres hermosa, amigamía, y en ti nohay mancha."],[4,8,"Conmigo del Líbano, oh esposa, conmigo vendel Líbano: miradesdela cumbrede Amana, desde la cumbrede Seniry de Hermón, desde las guaridasde los leones, desde los montesde los tigres.","Conmigo del Líbano, oh esposa, conmigo vendel Líbano: miradesdela cumbrede Amana, desde la cumbrede Seniry de Hermón, desde las guaridasde los leones, desde los montesde los tigres."],[4,9,"Prendiste mi corazón, hermana, esposamía; has preso mi corazóncon unode tus ojos, con unagargantillade tu cuello.","Prendiste mi corazón, hermana, esposamía; has preso mi corazóncon unode tus ojos, con unagargantillade tu cuello."],[4,10,"¡Cuánhermososson tus amores, hermana, esposamía! ¡cuántomejoresque el vinotus amores, y el olorde tus ungüentosque todaslas especiasaromáticas!","¡Cuánhermososson tus amores, hermana, esposamía! ¡cuántomejoresque el vinotus amores, y el olorde tus ungüentosque todaslas especiasaromáticas!"],[4,11,"Comopanalde miel destilantus labios, oh esposa; miely leche haydebajode tu lengua; y el olorde tus vestidoscomoel olordel Líbano.","Comopanalde miel destilantus labios, oh esposa; miely leche haydebajode tu lengua; y el olorde tus vestidoscomoel olordel Líbano."],[4,12,"Huertocerradoeres, mi hermana, esposamía; fuentecerrada, fuentesellada.","Huertocerradoeres, mi hermana, esposamía; fuentecerrada, fuentesellada."],[4,13,"Tus renuevosparaísode granados, confrutossuaves, de cámphoras y nardos,","Tus renuevosparaísode granados, confrutossuaves, de cámphoras y nardos,"],[4,14,"Nardoy azafrán, cañaaromática y canela, contodoslos árbolesde incienso; mirray áloes, contodaslas principalesespecias.","Nardoy azafrán, cañaaromática y canela, contodoslos árbolesde incienso; mirray áloes, contodaslas principalesespecias."],[4,15,"Fuentede huertos, pozode aguasvivas, que correndelLíbano.","Fuentede huertos, pozode aguasvivas, que correndelLíbano."],[4,16,"Levántate, Aquilón, y ven, Austro: sopla mi huerto, despréndansesus aromas. Vengami amadoá su huerto, y comade su dulcefruta.","Levántate, Aquilón, y ven, Austro: sopla mi huerto, despréndansesus aromas. Vengami amadoá su huerto, y comade su dulcefruta."],[5,1,"YO vineá mi huerto, ohhermana, esposamía: cogido he mi mirray mis aromas; he comidomi panaly mi miel, mi vinoy mi lechehe bebido. Comed, amigos; bebed, amados, y embriagaos.","YO vineá mi huerto, ohhermana, esposamía: cogido he mi mirray mis aromas; he comidomi panaly mi miel, mi vinoy mi lechehe bebido. Comed, amigos; bebed, amados, y embriagaos."],[5,2,"Yodormía, pero micorazónvelaba: la vozde miamadoque llamaba: Abreme, hermanamía, amiga mía, palomamía, perfectamía; porque micabezaestá llenade rocío, miscabellosde las gotasde la noche.","Yodormía, pero micorazónvelaba: la vozde miamadoque llamaba: Abreme, hermanamía, amiga mía, palomamía, perfectamía; porque micabezaestá llenade rocío, miscabellosde las gotasde la noche."],[5,3,"Heme desnudadomi ropa; ¿cómola tengo de vestir? He lavadomis pies; ¿cómolos tengo de ensuciar?","Heme desnudadomi ropa; ¿cómola tengo de vestir? He lavadomis pies; ¿cómolos tengo de ensuciar?"],[5,4,"Mi amadometiósu manoporel agujero, y mis entrañasse conmovierondentro demí.","Mi amadometiósu manoporel agujero, y mis entrañasse conmovierondentro demí."],[5,5,"Yome levantépara abrirá miamado, y mismanosgotearonmirra, y misdedosmirraque corríasobrelas aldabas del candado.","Yome levantépara abrirá miamado, y mismanosgotearonmirra, y misdedosmirraque corríasobrelas aldabas del candado."],[5,6,"Abríyoá miamado; mas miamadose había ido, había ya pasado: y tras su hablarsaliómialma: busquélo, y nolo hallé; llamélo, y nomerespondió.","Abríyoá miamado; mas miamadose había ido, había ya pasado: y tras su hablarsaliómialma: busquélo, y nolo hallé; llamélo, y nomerespondió."],[5,7,"Halláronmelos guardasque rondanla ciudad: hiriéronme, llagáronme, quitáronmemi mantode encimalos guardasde los muros.","Halláronmelos guardasque rondanla ciudad: hiriéronme, llagáronme, quitáronmemi mantode encimalos guardasde los muros."],[5,8,"Yo os conjuro, oh doncellasde Jerusalem, sihallareis á miamado, quele hagáis sabercomo de amorestoy enferma.","Yo os conjuro, oh doncellasde Jerusalem, sihallareis á miamado, quele hagáis sabercomo de amorestoy enferma."],[5,9,"¿Quées tu amadomás que otroamado, oh la más hermosade todas las mujeres? ¿quées tu amadomás que otroamado, que asínosconjuras?","¿Quées tu amadomás que otroamado, oh la más hermosade todas las mujeres? ¿quées tu amadomás que otroamado, que asínosconjuras?"],[5,10,"Mi amadoes blancoy rubio, señaladoentre diez mil.","Mi amadoes blancoy rubio, señaladoentre diez mil."],[5,11,"Su cabeza, comoorofinísimo; sus cabelloscrespos, negroscomo el cuervo.","Su cabeza, comoorofinísimo; sus cabelloscrespos, negroscomo el cuervo."],[5,12,"Sus ojos, como palomasjunto álos arroyosde las aguas, que se lavancon leche, yála perfeccióncolocados.","Sus ojos, como palomasjunto álos arroyosde las aguas, que se lavancon leche, yála perfeccióncolocados."],[5,13,"Sus mejillas, como una erade especiasaromáticas, comofragantesflores: sus labios, comoliriosque destilanmirraque trasciende.","Sus mejillas, como una erade especiasaromáticas, comofragantesflores: sus labios, comoliriosque destilanmirraque trasciende."],[5,14,"Sus manos, comoanillosde oroengastadosde jacintos: su vientre, comoclaromarfilcubiertode zafiros.","Sus manos, comoanillosde oroengastadosde jacintos: su vientre, comoclaromarfilcubiertode zafiros."],[5,15,"Sus piernas, comocolumnasde mármolfundadassobrebasasde fino oro: su aspectocomo el Líbano, escogidocomo los cedros.","Sus piernas, comocolumnasde mármolfundadassobrebasasde fino oro: su aspectocomo el Líbano, escogidocomo los cedros."],[5,16,"Su paladar, dulcísimo: y todoél codiciable. Tales mi amado, tales mi amigo, oh doncellasde Jerusalem.","Su paladar, dulcísimo: y todoél codiciable. Tales mi amado, tales mi amigo, oh doncellasde Jerusalem."],[6,1,"¿DÓNDEse ha idotu amado, oh la más hermosade todas las mujeres? ¿Adóndese apartótu amado, y le buscaremoscontigo?","¿DÓNDEse ha idotu amado, oh la más hermosade todas las mujeres? ¿Adóndese apartótu amado, y le buscaremoscontigo?"],[6,2,"Mi amadodescendióá su huerto, á las erasde los aromas, para apacentaren los huertos, y para cogerlos lirios.","Mi amadodescendióá su huerto, á las erasde los aromas, para apacentaren los huertos, y para cogerlos lirios."],[6,3,"Yosoy de miamado, y miamadoes mío: él apacientaentre los lirios.","Yosoy de miamado, y miamadoes mío: él apacientaentre los lirios."],[6,4,"Hermosaeres tú, oh amiga mía, como Tirsa; de desear, como Jerusalem; imponentecomo ejércitos en orden.","Hermosaeres tú, oh amiga mía, como Tirsa; de desear, como Jerusalem; imponentecomo ejércitos en orden."],[6,5,"Apartatus ojosdedelantede mí, porque ellosme vencieron. Tu cabelloes como manadade cabras, que se muestranenGalaad.","Apartatus ojosdedelantede mí, porque ellosme vencieron. Tu cabelloes como manadade cabras, que se muestranenGalaad."],[6,6,"Tus dientes, como manada de ovejasque subendellavadero, todascon crías mellizas, y estérilnohay entre ellas.","Tus dientes, como manada de ovejasque subendellavadero, todascon crías mellizas, y estérilnohay entre ellas."],[6,7,"Como cachosde granadason tus sienes entre tus guedejas.","Como cachosde granadason tus sienes entre tus guedejas."],[6,8,"Sesentason las reinas, y ochentalas concubinas, y las doncellassincuento:","Sesentason las reinas, y ochentalas concubinas, y las doncellassincuento:"],[6,9,"Masuna esla palomamía, la perfecta mía; únicaesá sumadre, escogidaá laque la engendró. Viéronlalas doncellas, y llamáronla bienaventurada; las reinasy las concubinas, y la alabaron.","Masuna esla palomamía, la perfecta mía; únicaesá sumadre, escogidaá laque la engendró. Viéronlalas doncellas, y llamáronla bienaventurada; las reinasy las concubinas, y la alabaron."],[6,10,"¿Quiénes éstaque se muestracomo el alba, hermosacomo la luna, esclarecidacomo el sol, imponentecomo ejércitos en orden?","¿Quiénes éstaque se muestracomo el alba, hermosacomo la luna, esclarecidacomo el sol, imponentecomo ejércitos en orden?"],[6,11,"Alhuertode los nogalesdescendíá verlos frutosdel valle, ypara versi brotabanlas vides, si florecíanlos granados.","Alhuertode los nogalesdescendíá verlos frutosdel valle, ypara versi brotabanlas vides, si florecíanlos granados."],[6,12,"No lo supe: hame mi almahecho comolos carrosde Amminadab.","No lo supe: hame mi almahecho comolos carrosde Amminadab."],[6,13,"Tórnate, tórnate, oh Sulamita; tórnate, tórnate, y te miraremos. ¿Quéveréisen la Sulamita? Como la reuniónde dos campamentos.","Tórnate, tórnate, oh Sulamita; tórnate, tórnate, y te miraremos. ¿Quéveréisen la Sulamita? Como la reuniónde dos campamentos."],[7,1,"¡CUÁNhermososson tus piesen los calzados, oh hijade príncipe! Los contornosde tus muslosson como joyas, obrade manode excelente maestro.","¡CUÁNhermososson tus piesen los calzados, oh hijade príncipe! Los contornosde tus muslosson como joyas, obrade manode excelente maestro."],[7,2,"Tu ombligo, comouna tazaredonda, que nole faltabebida. Tu vientre, comomontónde trigo, cercado de lirios.","Tu ombligo, comouna tazaredonda, que nole faltabebida. Tu vientre, comomontónde trigo, cercado de lirios."],[7,3,"Tus dospechos, como doscabritos mellizosde gama.","Tus dospechos, como doscabritos mellizosde gama."],[7,4,"Tu cuello, como torrede marfil; tus ojos, comolas pesqueras de Hesbónjunto ála puertade Batrabbim; tu nariz, como la torredel Líbano, que mirahaciaDamasco.","Tu cuello, como torrede marfil; tus ojos, comolas pesqueras de Hesbónjunto ála puertade Batrabbim; tu nariz, como la torredel Líbano, que mirahaciaDamasco."],[7,5,"Tu cabezaencimade ti, como el Carmelo; y el cabellode tu cabeza, como la púrpuradel reyligada en los corredores.","Tu cabezaencimade ti, como el Carmelo; y el cabellode tu cabeza, como la púrpuradel reyligada en los corredores."],[7,6,"¡Quéhermosaeres, y cuánsuave, oh amordeleitoso!","¡Quéhermosaeres, y cuánsuave, oh amordeleitoso!"],[7,7,"¡Y tu estaturaes semejanteá la palma, y tus pechosá los racimos!","¡Y tu estaturaes semejanteá la palma, y tus pechosá los racimos!"],[7,8,"Yo dije: Subiréá la palma, asirésus ramos: y tus pechosserán ahora como racimosde vid, y el olorde tu boca comode manzanas;","Yo dije: Subiréá la palma, asirésus ramos: y tus pechosserán ahora como racimosde vid, y el olorde tu boca comode manzanas;"],[7,9,"Y tu paladarcomo el buenvino, que se entraá mi amadosuavemente, y hace hablarlos labiosde los viejos.","Y tu paladarcomo el buenvino, que se entraá mi amadosuavemente, y hace hablarlos labiosde los viejos."],[7,10,"Yosoy de miamado, y conmigotiene su contentamiento.","Yosoy de miamado, y conmigotiene su contentamiento."],[7,11,"Ven, oh amadomío, salgamosal campo, moremos en las aldeas.","Ven, oh amadomío, salgamosal campo, moremos en las aldeas."],[7,12,"Levantémonosde mañana á las viñas; veamossibrotanlas vides, sise abre el cierne, sihan florecidolos granados; allíte darémis amores.","Levantémonosde mañana á las viñas; veamossibrotanlas vides, sise abre el cierne, sihan florecidolos granados; allíte darémis amores."],[7,13,"Las mandrágorashan dadoolor, y ánuestraspuertashay todasuerte de dulcesfrutas, nuevasyañejas, que para ti, oh amado mío, he guardado.","Las mandrágorashan dadoolor, y ánuestraspuertashay todasuerte de dulcesfrutas, nuevasyañejas, que para ti, oh amado mío, he guardado."],[8,1,"¡OHquién te me diese como hermanoque mamólos pechosde mi madre; de modoque te halle yo fuera, yte bese, ynome menosprecien!","¡OHquién te me diese como hermanoque mamólos pechosde mi madre; de modoque te halle yo fuera, yte bese, ynome menosprecien!"],[8,2,"Yo te llevaría, te metiera encasade mi madre: tú me enseñarías, y yo te hiciera bebervinoadobadodel mostode mis granadas.","Yo te llevaría, te metiera encasade mi madre: tú me enseñarías, y yo te hiciera bebervinoadobadodel mostode mis granadas."],[8,3,"Su izquierdaestédebajode mi cabeza, y su derechame abrace.","Su izquierdaestédebajode mi cabeza, y su derechame abrace."],[8,4,"Conjúroos, oh doncellasde Jerusalem, queno despertéis, ni hagáis velaral amor, hastaquequiera.","Conjúroos, oh doncellasde Jerusalem, queno despertéis, ni hagáis velaral amor, hastaquequiera."],[8,5,"¿Quiénes éstaque subedeldesierto, recostadasobresu amado? Debajode un manzanote desperté: allí tuvo tu madredolores, allítuvo doloresla que te parió.","¿Quiénes éstaque subedeldesierto, recostadasobresu amado? Debajode un manzanote desperté: allí tuvo tu madredolores, allítuvo doloresla que te parió."],[8,6,"Ponmecomo un sellosobretu corazón, como una marcasobretu brazo: porquefuerte es como la muerteel amor; durocomo el sepulcroel celo: sus brasas, brasasde fuego, fuerte llama.","Ponmecomo un sellosobretu corazón, como una marcasobretu brazo: porquefuerte es como la muerteel amor; durocomo el sepulcroel celo: sus brasas, brasasde fuego, fuerte llama."],[8,7,"Las muchasaguasnopodrán apagarel amor, nilo ahogaránlos ríos. Sidieseel hombretodala haciendade su casapor este amor, de ciertolo menospreciaran.","Las muchasaguasnopodrán apagarel amor, nilo ahogaránlos ríos. Sidieseel hombretodala haciendade su casapor este amor, de ciertolo menospreciaran."],[8,8,"Tenemos una pequeñahermana, que notiene pechos: ¿quéharemosá nuestrahermanacuandode ella se hablare?","Tenemos una pequeñahermana, que notiene pechos: ¿quéharemosá nuestrahermanacuandode ella se hablare?"],[8,9,"Siellaes muro, edificaremossobreélun palaciode plata: y sifuere puerta, laguarneceremoscon tablasde cedro.","Siellaes muro, edificaremossobreélun palaciode plata: y sifuere puerta, laguarneceremoscon tablasde cedro."],[8,10,"Yosoy muro, y mispechoscomo torres, desdeque fuíen sus ojoscomo la que halla paz.","Yosoy muro, y mispechoscomo torres, desdeque fuíen sus ojoscomo la que halla paz."],[8,11,"Salomóntuvouna viñaen Baal-hamón, la cual entregóá guardas, cada unode los cuales debía traermilmonedasde platapor su fruto.","Salomóntuvouna viñaen Baal-hamón, la cual entregóá guardas, cada unode los cuales debía traermilmonedasde platapor su fruto."],[8,12,"Mi viña, que es mía, está delantede mí: las milserán tuyas, oh Salomón, y doscientas, de los que guardansu fruto.","Mi viña, que es mía, está delantede mí: las milserán tuyas, oh Salomón, y doscientas, de los que guardansu fruto."],[8,13,"Oh tú la que moras en los huertos, los compañerosescuchantu voz: házmela oir.","Oh tú la que moras en los huertos, los compañerosescuchantu voz: házmela oir."],[8,14,"Huye, amadomío; y sé semejanteal gamo, óal cervatillo, sobrelas montañasde los aromas.","Huye, amadomío; y sé semejanteal gamo, óal cervatillo, sobrelas montañasde los aromas."]],"rus-synodal":[[1,1,"Да лобзает он меня лобзанием уст своих! Ибо ласки твои лучше вина.","Da lobzaet on menâ lobzaniem ust svoih! Ibo laski tvoi lučše vina."],[1,2,"От благовония мастей твоих имя твое – как разлитое миро; поэтому девицы любят тебя.","Ot blagovoniâ mastej tvoih imâ tvoe – kak razlitoe miro; poétomu devicy lûbât tebâ."],[1,3,"Влеки меня, мы побежим за тобою; – царь ввел меня в чертоги свои, – будем восхищаться и радоваться тобою, превозносить ласки твои больше, нежели вино; достойно любят тебя!","Vleki menâ, my pobežim za toboû; – carʹ vvel menâ v čertogi svoi, – budem voshiŝatʹsâ i radovatʹsâ toboû, prevoznositʹ laski tvoi bolʹše, neželi vino; dostojno lûbât tebâ!"],[1,4,"– Дщери Иерусалимские! черна я, но красива, как шатры Кидарские, как завесы Соломоновы.","– Dŝeri Ierusalimskie! černa â, no krasiva, kak šatry Kidarskie, kak zavesy Solomonovy."],[1,5,"Не смотрите на меня, что я смугла, ибо солнце опалило меня: сыновья матери моей разгневались на меня, поставили меня стеречь виноградники, – моего собственного виноградника я не стерегла.","Ne smotrite na menâ, čto â smugla, ibo solnce opalilo menâ: synovʹâ materi moej razgnevalisʹ na menâ, postavili menâ sterečʹ vinogradniki, – moego sobstvennogo vinogradnika â ne steregla."],[1,6,"– Скажи мне, ты, которого любит душа моя: где пасешь ты? где отдыхаешь в полдень? к чему мне быть скиталицею возле стад товарищей твоих?","– Skaži mne, ty, kotorogo lûbit duša moâ: gde pasešʹ ty? gde otdyhaešʹ v poldenʹ? k čemu mne bytʹ skitaliceû vozle stad tovariŝej tvoih?"],[1,7,"– Если ты не знаешь этого, прекраснейшая из женщин, то иди себе по следам овец и паси козлят твоих подле шатров пастушеских.","– Esli ty ne znaešʹ étogo, prekrasnejšaâ iz ženŝin, to idi sebe po sledam ovec i pasi kozlât tvoih podle šatrov pastušeskih."],[1,8,"– Кобылице моей в колеснице фараоновой я уподобил тебя, возлюбленная моя.","– Kobylice moej v kolesnice faraonovoj â upodobil tebâ, vozlûblennaâ moâ."],[1,9,"Прекрасны ланиты твои под подвесками, шея твоя в ожерельях;","Prekrasny lanity tvoi pod podveskami, šeâ tvoâ v ožerelʹâh;"],[1,10,"золотые подвески мы сделаем тебе с серебряными блестками.","zolotye podveski my sdelaem tebe s serebrânymi blestkami."],[1,11,"– Доколе царь был за столом своим, нард мой издавал благовоние свое.","– Dokole carʹ byl za stolom svoim, nard moj izdaval blagovonie svoe."],[1,12,"Мирровый пучок – возлюбленный мой у меня, у грудей моих пребывает.","Mirrovyj pučok – vozlûblennyj moj u menâ, u grudej moih prebyvaet."],[1,13,"Как кисть кипера, возлюбленный мой у меня в виноградниках Енгедских.","Kak kistʹ kipera, vozlûblennyj moj u menâ v vinogradnikah Engedskih."],[1,14,"– О, ты прекрасна, возлюбленная моя, ты прекрасна! глаза твои голубиные.","– O, ty prekrasna, vozlûblennaâ moâ, ty prekrasna! glaza tvoi golubinye."],[1,15,"– О, ты прекрасен, возлюбленный мой, и любезен! и ложе у нас – зелень;","– O, ty prekrasen, vozlûblennyj moj, i lûbezen! i lože u nas – zelenʹ;"],[1,16,"кровли домов наших – кедры, потолки наши – кипарисы.","krovli domov naših – kedry, potolki naši – kiparisy."],[2,1,"– Я нарцисс Саронский, лилия долин!","– Â narciss Saronskij, liliâ dolin!"],[2,2,"– Что лилия между тернами, то возлюбленная моя между девицами.","– Čto liliâ meždu ternami, to vozlûblennaâ moâ meždu devicami."],[2,3,"– Что яблоня между лесными деревьями, то возлюбленный мой между юношами. В тени ее люблю я сидеть, и плоды ее сладки для гортани моей.","– Čto âblonâ meždu lesnymi derevʹâmi, to vozlûblennyj moj meždu ûnošami. V teni ee lûblû â sidetʹ, i plody ee sladki dlâ gortani moej."],[2,4,"Он ввел меня в дом пира, и знамя его надо мною – любовь.","On vvel menâ v dom pira, i znamâ ego nado mnoû – lûbovʹ."],[2,5,"Подкрепите меня вином, освежите меня яблоками, ибо я изнемогаю от любви.","Podkrepite menâ vinom, osvežite menâ âblokami, ibo â iznemogaû ot lûbvi."],[2,6,"Левая рука его у меня под головою, а правая обнимает меня.","Levaâ ruka ego u menâ pod golovoû, a pravaâ obnimaet menâ."],[2,7,"Заклинаю вас, дщери Иерусалимские, сернами или полевыми ланями: не будите и не тревожьте возлюбленной, доколе ей угодно.","Zaklinaû vas, dŝeri Ierusalimskie, sernami ili polevymi lanâmi: ne budite i ne trevožʹte vozlûblennoj, dokole ej ugodno."],[2,8,"– Голос возлюбленного моего! вот, он идет, скачет по горам, прыгает по холмам.","– Golos vozlûblennogo moego! vot, on idet, skačet po goram, prygaet po holmam."],[2,9,"Друг мой похож на серну или на молодого оленя. Вот, он стоит у нас за стеною, заглядывает в окно, мелькает сквозь решетку.","Drug moj pohož na sernu ili na molodogo olenâ. Vot, on stoit u nas za stenoû, zaglâdyvaet v okno, melʹkaet skvozʹ rešetku."],[2,10,"Возлюбленный мой начал говорить мне: встань, возлюбленная моя, прекрасная моя, выйди!","Vozlûblennyj moj načal govoritʹ mne: vstanʹ, vozlûblennaâ moâ, prekrasnaâ moâ, vyjdi!"],[2,11,"Вот, зима уже прошла; дождь миновал, перестал;","Vot, zima uže prošla; doždʹ minoval, perestal;"],[2,12,"цветы показались на земле; время пения настало, и голос горлицы слышен в стране нашей;","cvety pokazalisʹ na zemle; vremâ peniâ nastalo, i golos gorlicy slyšen v strane našej;"],[2,13,"смоковницы распустили свои почки, и виноградные лозы, расцветая, издают благовоние. Встань, возлюбленная моя, прекрасная моя, выйди!","smokovnicy raspustili svoi počki, i vinogradnye lozy, rascvetaâ, izdaût blagovonie. Vstanʹ, vozlûblennaâ moâ, prekrasnaâ moâ, vyjdi!"],[2,14,"Голубица моя в ущелье скалы под кровом утеса! покажи мне лицо твое, дай мне услышать голос твой, потому что голос твой сладок и лицо твое приятно.","Golubica moâ v uŝelʹe skaly pod krovom utesa! pokaži mne lico tvoe, daj mne uslyšatʹ golos tvoj, potomu čto golos tvoj sladok i lico tvoe priâtno."],[2,15,"– Ловите нам лисиц, лисенят, которые портят виноградники, а виноградники наши в цвете.","– Lovite nam lisic, lisenât, kotorye portât vinogradniki, a vinogradniki naši v cvete."],[2,16,"– Возлюбленный мой принадлежит мне, а я ему; он пасет между лилиями.","– Vozlûblennyj moj prinadležit mne, a â emu; on paset meždu liliâmi."],[2,17,"Доколе день дышит прохладою, и убегают тени, возвратись, будь подобен серне или молодому оленю на расселинах гор.","Dokole denʹ dyšit prohladoû, i ubegaût teni, vozvratisʹ, budʹ podoben serne ili molodomu olenû na rasselinah gor."],[3,1,"– На ложе моем ночью искала я того, которого любит душа моя, искала его и не нашла его.","– Na lože moem nočʹû iskala â togo, kotorogo lûbit duša moâ, iskala ego i ne našla ego."],[3,2,"Встану же я, пойду по городу, по улицам и площадям, и буду искать того, которого любит душа моя; искала я его и не нашла его.","Vstanu že â, pojdu po gorodu, po ulicam i ploŝadâm, i budu iskatʹ togo, kotorogo lûbit duša moâ; iskala â ego i ne našla ego."],[3,3,"Встретили меня стражи, обходящие город: «не видали ли вы того, которого любит душа моя?»","Vstretili menâ straži, obhodâŝie gorod: «ne vidali li vy togo, kotorogo lûbit duša moâ?»"],[3,4,"Но едва я отошла от них, как нашла того, которого любит душа моя, ухватилась за него, и не отпустила его, доколе не привела его в дом матери моей и во внутренние комнаты родительницы моей.","No edva â otošla ot nih, kak našla togo, kotorogo lûbit duša moâ, uhvatilasʹ za nego, i ne otpustila ego, dokole ne privela ego v dom materi moej i vo vnutrennie komnaty roditelʹnicy moej."],[3,5,"Заклинаю вас, дщери Иерусалимские, сернами или полевыми ланями: не будите и не тревожьте возлюбленной, доколе ей угодно.","Zaklinaû vas, dŝeri Ierusalimskie, sernami ili polevymi lanâmi: ne budite i ne trevožʹte vozlûblennoj, dokole ej ugodno."],[3,6,"– Кто эта, восходящая от пустыни как бы столбы дыма, окуриваемая миррою и фимиамом, всякими порошками мироварника?","– Kto éta, voshodâŝaâ ot pustyni kak by stolby dyma, okurivaemaâ mirroû i fimiamom, vsâkimi poroškami mirovarnika?"],[3,7,"Вот одр его – Соломона: шестьдесят сильных вокруг него, из сильных Израилевых.","Vot odr ego – Solomona: šestʹdesât silʹnyh vokrug nego, iz silʹnyh Izrailevyh."],[3,8,"Все они держат по мечу, опытны в бою; у каждого меч при бедре его ради страха ночного.","Vse oni deržat po meču, opytny v boû; u každogo meč pri bedre ego radi straha nočnogo."],[3,9,"Носильный одр сделал себе царь Соломон из дерев Ливанских;","Nosilʹnyj odr sdelal sebe carʹ Solomon iz derev Livanskih;"],[3,10,"столпцы его сделал из серебра, локотники его из золота, седалище его из пурпуровой ткани; внутренность его убрана с любовью дщерями Иерусалимскими.","stolpcy ego sdelal iz serebra, lokotniki ego iz zolota, sedaliŝe ego iz purpurovoj tkani; vnutrennostʹ ego ubrana s lûbovʹû dŝerâmi Ierusalimskimi."],[3,11,"Пойдите и посмотрите, дщери Сионские, на царя Соломона в венце, которым увенчала его мать его в день бракосочетания его, в день, радостный для сердца его.","Pojdite i posmotrite, dŝeri Sionskie, na carâ Solomona v vence, kotorym uvenčala ego matʹ ego v denʹ brakosočetaniâ ego, v denʹ, radostnyj dlâ serdca ego."],[4,1,"– О, ты прекрасна, возлюбленная моя, ты прекрасна! глаза твои голубиные под кудрями твоими; волосы твои – как стадо коз, сходящих с горы Галаадской;","– O, ty prekrasna, vozlûblennaâ moâ, ty prekrasna! glaza tvoi golubinye pod kudrâmi tvoimi; volosy tvoi – kak stado koz, shodâŝih s gory Galaadskoj;"],[4,2,"зубы твои – как стадо выстриженных овец, выходящих из купальни, из которых у каждой пара ягнят, и бесплодной нет между ними;","zuby tvoi – kak stado vystrižennyh ovec, vyhodâŝih iz kupalʹni, iz kotoryh u každoj para âgnât, i besplodnoj net meždu nimi;"],[4,3,"как лента алая губы твои, и уста твои любезны; как половинки гранатового яблока – ланиты твои под кудрями твоими;","kak lenta alaâ guby tvoi, i usta tvoi lûbezny; kak polovinki granatovogo âbloka – lanity tvoi pod kudrâmi tvoimi;"],[4,4,"шея твоя – как столп Давидов, сооруженный для оружий, тысяча щитов висит на нем – все щиты сильных;","šeâ tvoâ – kak stolp Davidov, sooružennyj dlâ oružij, tysâča ŝitov visit na nem – vse ŝity silʹnyh;"],[4,5,"два сосца твои – как двойни молодой серны, пасущиеся между лилиями.","dva sosca tvoi – kak dvojni molodoj serny, pasuŝiesâ meždu liliâmi."],[4,6,"Доколе день дышит прохладою, и убегают тени, пойду я на гору мирровую и на холм фимиама.","Dokole denʹ dyšit prohladoû, i ubegaût teni, pojdu â na goru mirrovuû i na holm fimiama."],[4,7,"Вся ты прекрасна, возлюбленная моя, и пятна нет на тебе!","Vsâ ty prekrasna, vozlûblennaâ moâ, i pâtna net na tebe!"],[4,8,"Со мною с Ливана, невеста! со мною иди с Ливана! спеши с вершины Аманы, с вершины Сенира и Ермона, от логовищ львиных, от гор барсовых!","So mnoû s Livana, nevesta! so mnoû idi s Livana! speši s veršiny Amany, s veršiny Senira i Ermona, ot logoviŝ lʹvinyh, ot gor barsovyh!"],[4,9,"Пленила ты сердце мое, сестра моя, невеста! пленила ты сердце мое одним взглядом очей твоих, одним ожерельем на шее твоей.","Plenila ty serdce moe, sestra moâ, nevesta! plenila ty serdce moe odnim vzglâdom očej tvoih, odnim ožerelʹem na šee tvoej."],[4,10,"О, как любезны ласки твои, сестра моя, невеста! о, как много ласки твои лучше вина, и благовоние мастей твоих лучше всех ароматов!","O, kak lûbezny laski tvoi, sestra moâ, nevesta! o, kak mnogo laski tvoi lučše vina, i blagovonie mastej tvoih lučše vseh aromatov!"],[4,11,"Сотовый мед каплет из уст твоих, невеста; мед и молоко под языком твоим, и благоухание одежды твоей подобно благоуханию Ливана!","Sotovyj med kaplet iz ust tvoih, nevesta; med i moloko pod âzykom tvoim, i blagouhanie odeždy tvoej podobno blagouhaniû Livana!"],[4,12,"Запертый сад – сестра моя, невеста, заключенный колодезь, запечатанный источник:","Zapertyj sad – sestra moâ, nevesta, zaklûčennyj kolodezʹ, zapečatannyj istočnik:"],[4,13,"рассадники твои – сад с гранатовыми яблоками, с превосходными плодами, киперы с нардами,","rassadniki tvoi – sad s granatovymi âblokami, s prevoshodnymi plodami, kipery s nardami,"],[4,14,"нард и шафран, аир и корица со всякими благовонными деревами, мирра и алой со всякими лучшими ароматами;","nard i šafran, air i korica so vsâkimi blagovonnymi derevami, mirra i aloj so vsâkimi lučšimi aromatami;"],[4,15,"садовый источник – колодезь живых вод и потоки с Ливана.","sadovyj istočnik – kolodezʹ živyh vod i potoki s Livana."],[4,16,"Поднимись, ветер, с севера и принесись с юга, повей на сад мой, – и польются ароматы его! – Пусть придет возлюбленный мой в сад свой и вкушает сладкие плоды его.","Podnimisʹ, veter, s severa i prinesisʹ s ûga, povej na sad moj, – i polʹûtsâ aromaty ego! – Pustʹ pridet vozlûblennyj moj v sad svoj i vkušaet sladkie plody ego."],[5,1,"Пришел я в сад мой, сестра моя, невеста; набрал мирры моей с ароматами моими, поел сотов моих с медом моим, напился вина моего с молоком моим. – Ешьте, друзья, пейте и насыщайтесь, возлюбленные!","Prišel â v sad moj, sestra moâ, nevesta; nabral mirry moej s aromatami moimi, poel sotov moih s medom moim, napilsâ vina moego s molokom moim. – Ešʹte, druzʹâ, pejte i nasyŝajtesʹ, vozlûblennye!"],[5,2,"– Я сплю, а сердце мое бодрствует; вот, голос моего возлюбленного, который стучится: «отвори мне, сестра моя, возлюбленная моя, голубица моя, чистая моя! потому что голова моя вся покрыта росою, кудри мои – ночною влагою».","– Â splû, a serdce moe bodrstvuet; vot, golos moego vozlûblennogo, kotoryj stučitsâ: «otvori mne, sestra moâ, vozlûblennaâ moâ, golubica moâ, čistaâ moâ! potomu čto golova moâ vsâ pokryta rosoû, kudri moi – nočnoû vlagoû»."],[5,3,"Я скинула хитон мой; как же мне опять надевать его? Я вымыла ноги мои; как же мне марать их?","Â skinula hiton moj; kak že mne opâtʹ nadevatʹ ego? Â vymyla nogi moi; kak že mne maratʹ ih?"],[5,4,"Возлюбленный мой протянул руку свою сквозь скважину, и внутренность моя взволновалась от него.","Vozlûblennyj moj protânul ruku svoû skvozʹ skvažinu, i vnutrennostʹ moâ vzvolnovalasʹ ot nego."],[5,5,"Я встала, чтобы отпереть возлюбленному моему, и с рук моих капала мирра, и с перстов моих мирра капала на ручки замка.","Â vstala, čtoby otperetʹ vozlûblennomu moemu, i s ruk moih kapala mirra, i s perstov moih mirra kapala na ručki zamka."],[5,6,"Отперла я возлюбленному моему, а возлюбленный мой повернулся и ушел. Души во мне не стало, когда он говорил; я искала его и не находила его; звала его, и он не отзывался мне.","Otperla â vozlûblennomu moemu, a vozlûblennyj moj povernulsâ i ušel. Duši vo mne ne stalo, kogda on govoril; â iskala ego i ne nahodila ego; zvala ego, i on ne otzyvalsâ mne."],[5,7,"Встретили меня стражи, обходящие город, избили меня, изранили меня; сняли с меня покрывало стерегущие стены.","Vstretili menâ straži, obhodâŝie gorod, izbili menâ, izranili menâ; snâli s menâ pokryvalo stereguŝie steny."],[5,8,"Заклинаю вас, дщери Иерусалимские: если вы встретите возлюбленного моего, что скажете вы ему? что я изнемогаю от любви.","Zaklinaû vas, dŝeri Ierusalimskie: esli vy vstretite vozlûblennogo moego, čto skažete vy emu? čto â iznemogaû ot lûbvi."],[5,9,"– Чем возлюбленный твой лучше других возлюбленных, прекраснейшая из женщин? Чем возлюбленный твой лучше других, что ты так заклинаешь нас?","– Čem vozlûblennyj tvoj lučše drugih vozlûblennyh, prekrasnejšaâ iz ženŝin? Čem vozlûblennyj tvoj lučše drugih, čto ty tak zaklinaešʹ nas?"],[5,10,"– Возлюбленный мой бел и румян, лучше десяти тысяч других:","– Vozlûblennyj moj bel i rumân, lučše desâti tysâč drugih:"],[5,11,"голова его – чистое золото; кудри его волнистые, черные, как ворон;","golova ego – čistoe zoloto; kudri ego volnistye, černye, kak voron;"],[5,12,"глаза его – как голуби при потоках вод, купающиеся в молоке, сидящие в довольстве;","glaza ego – kak golubi pri potokah vod, kupaûŝiesâ v moloke, sidâŝie v dovolʹstve;"],[5,13,"щеки его – цветник ароматный, гряды благовонных растений; губы его – лилии, источают текучую мирру;","ŝeki ego – cvetnik aromatnyj, grâdy blagovonnyh rastenij; guby ego – lilii, istočaût tekučuû mirru;"],[5,14,"руки его – золотые кругляки, усаженные топазами; живот его – как изваяние из слоновой кости, обложенное сапфирами;","ruki ego – zolotye kruglâki, usažennye topazami; život ego – kak izvaânie iz slonovoj kosti, obložennoe sapfirami;"],[5,15,"голени его – мраморные столбы, поставленные на золотых подножиях; вид его подобен Ливану, величествен, как кедры;","goleni ego – mramornye stolby, postavlennye na zolotyh podnožiâh; vid ego podoben Livanu, veličestven, kak kedry;"],[5,16,"уста его – сладость, и весь он – любезность. Вот кто возлюбленный мой, и вот кто друг мой, дщери Иерусалимские!","usta ego – sladostʹ, i vesʹ on – lûbeznostʹ. Vot kto vozlûblennyj moj, i vot kto drug moj, dŝeri Ierusalimskie!"],[6,1,"– Куда пошел возлюбленный твой, прекраснейшая из женщин? куда обратился возлюбленный твой? мы поищем его с тобою.","– Kuda pošel vozlûblennyj tvoj, prekrasnejšaâ iz ženŝin? kuda obratilsâ vozlûblennyj tvoj? my poiŝem ego s toboû."],[6,2,"– Мой возлюбленный пошел в сад свой, в цветники ароматные, чтобы пасти в садах и собирать лилии.","– Moj vozlûblennyj pošel v sad svoj, v cvetniki aromatnye, čtoby pasti v sadah i sobiratʹ lilii."],[6,3,"Я принадлежу возлюбленному моему, а возлюбленный мой – мне; он пасет между лилиями.","Â prinadležu vozlûblennomu moemu, a vozlûblennyj moj – mne; on paset meždu liliâmi."],[6,4,"– Прекрасна ты, возлюбленная моя, как Фирца, любезна, как Иерусалим, грозна, как полки со знаменами.","– Prekrasna ty, vozlûblennaâ moâ, kak Firca, lûbezna, kak Ierusalim, grozna, kak polki so znamenami."],[6,5,"Уклони очи твои от меня, потому что они волнуют меня.","Ukloni oči tvoi ot menâ, potomu čto oni volnuût menâ."],[6,6,"Волосы твои – как стадо коз, сходящих с Галаада; зубы твои – как стадо овец, выходящих из купальни, из которых у каждой пара ягнят, и бесплодной нет между ними;","Volosy tvoi – kak stado koz, shodâŝih s Galaada; zuby tvoi – kak stado ovec, vyhodâŝih iz kupalʹni, iz kotoryh u každoj para âgnât, i besplodnoj net meždu nimi;"],[6,7,"как половинки гранатового яблока – ланиты твои под кудрями твоими.","kak polovinki granatovogo âbloka – lanity tvoi pod kudrâmi tvoimi."],[6,8,"Есть шестьдесят цариц и восемьдесят наложниц и девиц без числа,","Estʹ šestʹdesât caric i vosemʹdesât naložnic i devic bez čisla,"],[6,9,"но единственная – она, голубица моя, чистая моя; единственная она у матери своей, отличенная у родительницы своей. Увидели ее девицы, и – превознесли ее, царицы и наложницы, и – восхвалили ее.","no edinstvennaâ – ona, golubica moâ, čistaâ moâ; edinstvennaâ ona u materi svoej, otličennaâ u roditelʹnicy svoej. Uvideli ee devicy, i – prevoznesli ee, caricy i naložnicy, i – voshvalili ee."],[6,10,"Кто эта, блистающая, как заря, прекрасная, как луна, светлая, как солнце, грозная, как полки со знаменами?","Kto éta, blistaûŝaâ, kak zarâ, prekrasnaâ, kak luna, svetlaâ, kak solnce, groznaâ, kak polki so znamenami?"],[6,11,"– Я сошла в ореховый сад посмотреть на зелень долины, поглядеть, распустилась ли виноградная лоза, расцвели ли гранатовые яблоки?","– Â sošla v orehovyj sad posmotretʹ na zelenʹ doliny, poglâdetʹ, raspustilasʹ li vinogradnaâ loza, rascveli li granatovye âbloki?"],[6,12,"Не знаю, как душа моя влекла меня к колесницам знатных народа моего.","Ne znaû, kak duša moâ vlekla menâ k kolesnicam znatnyh naroda moego."],[7,1,"– «Оглянись, оглянись, Суламита! оглянись, оглянись, – и мы посмотрим на тебя». – Что вам смотреть на Суламиту, как на хоровод Манаимский?","– «Oglânisʹ, oglânisʹ, Sulamita! oglânisʹ, oglânisʹ, – i my posmotrim na tebâ». – Čto vam smotretʹ na Sulamitu, kak na horovod Manaimskij?"],[7,2,"– О, как прекрасны ноги твои в сандалиях, дщерь именитая! Округление бедр твоих, как ожерелье, дело рук искусного художника;","– O, kak prekrasny nogi tvoi v sandaliâh, dŝerʹ imenitaâ! Okruglenie bedr tvoih, kak ožerelʹe, delo ruk iskusnogo hudožnika;"],[7,3,"живот твой – круглая чаша, в которой не истощается ароматное вино; чрево твое – ворох пшеницы, обставленный лилиями;","život tvoj – kruglaâ čaša, v kotoroj ne istoŝaetsâ aromatnoe vino; črevo tvoe – voroh pšenicy, obstavlennyj liliâmi;"],[7,4,"два сосца твои – как два козленка, двойни серны;","dva sosca tvoi – kak dva kozlenka, dvojni serny;"],[7,5,"шея твоя – как столп из слоновой кости; глаза твои – озерки Есевонские, что у ворот Батраббима; нос твой – башня Ливанская, обращенная к Дамаску;","šeâ tvoâ – kak stolp iz slonovoj kosti; glaza tvoi – ozerki Esevonskie, čto u vorot Batrabbima; nos tvoj – bašnâ Livanskaâ, obraŝennaâ k Damasku;"],[7,6,"голова твоя на тебе, как Кармил, и волосы на голове твоей, как пурпур; царь увлечен твоими кудрями.","golova tvoâ na tebe, kak Karmil, i volosy na golove tvoej, kak purpur; carʹ uvlečen tvoimi kudrâmi."],[7,7,"Как ты прекрасна, как привлекательна, возлюбленная, твоею миловидностью!","Kak ty prekrasna, kak privlekatelʹna, vozlûblennaâ, tvoeû milovidnostʹû!"],[7,8,"Этот стан твой похож на пальму, и груди твои – на виноградные кисти.","Étot stan tvoj pohož na palʹmu, i grudi tvoi – na vinogradnye kisti."],[7,9,"Подумал я: влез бы я на пальму, ухватился бы за ветви ее; и груди твои были бы вместо кистей винограда, и запах от ноздрей твоих, как от яблок;","Podumal â: vlez by â na palʹmu, uhvatilsâ by za vetvi ee; i grudi tvoi byli by vmesto kistej vinograda, i zapah ot nozdrej tvoih, kak ot âblok;"],[7,10,"уста твои – как отличное вино. Оно течет прямо к другу моему, услаждает уста утомленных.","usta tvoi – kak otličnoe vino. Ono tečet prâmo k drugu moemu, uslaždaet usta utomlennyh."],[7,11,"– Я принадлежу другу моему, и ко мне обращено желание его.","– Â prinadležu drugu moemu, i ko mne obraŝeno želanie ego."],[7,12,"Приди, возлюбленный мой, выйдем в поле, побудем в селах;","Pridi, vozlûblennyj moj, vyjdem v pole, pobudem v selah;"],[7,13,"поутру пойдем в виноградники, посмотрим, распустилась ли виноградная лоза, раскрылись ли почки, расцвели ли гранатовые яблони; там я окажу ласки мои тебе.","poutru pojdem v vinogradniki, posmotrim, raspustilasʹ li vinogradnaâ loza, raskrylisʹ li počki, rascveli li granatovye âbloni; tam â okažu laski moi tebe."],[7,14,"Мандрагоры уже пустили благовоние, и у дверей наших всякие превосходные плоды, новые и старые: это сберегла я для тебя, мой возлюбленный!","Mandragory uže pustili blagovonie, i u dverej naših vsâkie prevoshodnye plody, novye i starye: éto sberegla â dlâ tebâ, moj vozlûblennyj!"],[8,1,"О, если бы ты был мне брат, сосавший груди матери моей! тогда я, встретив тебя на улице, целовала бы тебя, и меня не осуждали бы.","O, esli by ty byl mne brat, sosavšij grudi materi moej! togda â, vstretiv tebâ na ulice, celovala by tebâ, i menâ ne osuždali by."],[8,2,"Повела бы я тебя, привела бы тебя в дом матери моей. Ты учил бы меня, а я поила бы тебя ароматным вином, соком гранатовых яблок моих.","Povela by â tebâ, privela by tebâ v dom materi moej. Ty učil by menâ, a â poila by tebâ aromatnym vinom, sokom granatovyh âblok moih."],[8,3,"Левая рука его у меня под головою, а правая обнимает меня.","Levaâ ruka ego u menâ pod golovoû, a pravaâ obnimaet menâ."],[8,4,"Заклинаю вас, дщери Иерусалимские, не будите и не тревожьте возлюбленной, доколе ей угодно.","Zaklinaû vas, dŝeri Ierusalimskie, ne budite i ne trevožʹte vozlûblennoj, dokole ej ugodno."],[8,5,"– Кто это восходит от пустыни, опираясь на своего возлюбленного? – Под яблоней разбудила я тебя: там родила тебя мать твоя, там родила тебя родительница твоя.","– Kto éto voshodit ot pustyni, opiraâsʹ na svoego vozlûblennogo? – Pod âblonej razbudila â tebâ: tam rodila tebâ matʹ tvoâ, tam rodila tebâ roditelʹnica tvoâ."],[8,6,"Положи меня, как печать, на сердце твое, как перстень, на руку твою: ибо крепка, как смерть, любовь; люта, как преисподняя, ревность; стрелы ее – стрелы огненные; она пламень весьма сильный.","Položi menâ, kak pečatʹ, na serdce tvoe, kak perstenʹ, na ruku tvoû: ibo krepka, kak smertʹ, lûbovʹ; lûta, kak preispodnââ, revnostʹ; strely ee – strely ognennye; ona plamenʹ vesʹma silʹnyj."],[8,7,"Большие воды не могут потушить любви, и реки не зальют ее. Если бы кто давал все богатство дома своего за любовь, то он был бы отвергнут с презреньем.","Bolʹšie vody ne mogut potušitʹ lûbvi, i reki ne zalʹût ee. Esli by kto daval vse bogatstvo doma svoego za lûbovʹ, to on byl by otvergnut s prezrenʹem."],[8,8,"– Есть у нас сестра, которая еще мала, и сосцов нет у нее; что нам будет делать с сестрою нашею, когда будут свататься за нее?","– Estʹ u nas sestra, kotoraâ eŝe mala, i soscov net u nee; čto nam budet delatʹ s sestroû našeû, kogda budut svatatʹsâ za nee?"],[8,9,"Если бы она была стена, то мы построили бы на ней палаты из серебра; если бы она была дверь, то мы обложили бы ее кедровыми досками.","Esli by ona byla stena, to my postroili by na nej palaty iz serebra; esli by ona byla dverʹ, to my obložili by ee kedrovymi doskami."],[8,10,"– Я стена, и сосцы у меня, как башни; потому я буду в глазах его, как достигшая полноты.","– Â stena, i soscy u menâ, kak bašni; potomu â budu v glazah ego, kak dostigšaâ polnoty."],[8,11,"– Виноградник был у Соломона в Ваал-Гамоне; он отдал этот виноградник сторожам; каждый должен был доставлять за плоды его тысячу сребреников.","– Vinogradnik byl u Solomona v Vaal-Gamone; on otdal étot vinogradnik storožam; každyj dolžen byl dostavlâtʹ za plody ego tysâču srebrenikov."],[8,12,"А мой виноградник у меня при себе. Тысяча пусть тебе, Соломон, а двести – стерегущим плоды его.","A moj vinogradnik u menâ pri sebe. Tysâča pustʹ tebe, Solomon, a dvesti – stereguŝim plody ego."],[8,13,"– Жительница садов! товарищи внимают голосу твоему, дай и мне послушать его.","– Žitelʹnica sadov! tovariŝi vnimaût golosu tvoemu, daj i mne poslušatʹ ego."],[8,14,"– Беги, возлюбленный мой; будь подобен серне или молодому оленю на горах бальзамических!","– Begi, vozlûblennyj moj; budʹ podoben serne ili molodomu olenû na gorah balʹzamičeskih!"]],"cmn-cuv-hant":[[1,1,"所羅門的歌，是歌中的雅歌。","suǒ luó mén de gē， shì gē zhōng de yǎ gē."],[1,2,"願他用口與我親嘴； 因你的愛情比酒更美。","yuàn tā yòng kǒu yǔ wǒ qīn zuǐ； yīn nǐ de ài qíng bǐ jiǔ gèng měi."],[1,3,"你的膏油馨香； 你的名 如同倒出來的 香膏， 所以眾童女都愛你。","nǐ de gāo yóu xīn xiāng； nǐ de míng rú tóng dào chū lái de xiāng gāo， suǒ yǐ zhòng tóng nǚ dōu ài nǐ."],[1,4,"願你吸引我，我們就快跑跟隨你。 王帶我進了內室， 我們必因你歡喜快樂。 我們要稱讚你的愛情， 勝似稱讚 美酒。 他們愛你是理所當然的。","yuàn nǐ xī yǐn wǒ， wǒ men jiù kuài pǎo gēn suí nǐ. wáng dài wǒ jìn le nèi shì， wǒ men bì yīn nǐ huān xǐ kuài lè. wǒ men yào chēng zàn nǐ de ài qíng， shèng sì chēng zàn měi jiǔ. tā men ài nǐ shì lǐ suǒ dāng rán de."],[1,5,"耶路撒冷的眾女子啊， 我雖然黑，卻是秀美， 如同 基達的帳棚， 好像 所羅門的幔子。","yé lù sā lěng de zhòng nǚ zǐ a， wǒ suī rán hēi， què shì xiù měi， rú tóng jī dá de zhàng péng， hǎo xiàng suǒ luó mén de màn zǐ."],[1,6,"不要因日頭把我曬黑了就輕看我。 我同母的弟兄向我發怒， 他們使我看守葡萄園； 我自己的葡萄園卻沒有看守。","bù yào yīn rì tóu bǎ wǒ shài hēi le jiù qīng kàn wǒ. wǒ tóng mǔ de dì xiōng xiàng wǒ fā nù， tā men shǐ wǒ kàn shǒu pú táo yuán； wǒ zì jǐ de pú táo yuán què méi yǒu kàn shǒu."],[1,7,"我心所愛的啊，求你告訴我， 你在何處牧羊？ 晌午在何處使羊歇臥？ 我何必在你同伴的羊群旁邊 好像蒙着臉的人呢？","wǒ xīn suǒ ài de a， qiú nǐ gào sù wǒ， nǐ zài hé chù mù yáng？ shǎng wǔ zài hé chù shǐ yáng xiē wò？ wǒ hé bì zài nǐ tóng bàn de yáng qún páng biān hǎo xiàng méng zhe liǎn de rén ne？"],[1,8,"你這女子中極美麗的， 你若不知道， 只管跟隨羊群的腳蹤去， 把你的山羊羔牧放在牧人帳棚的旁邊。","nǐ zhè nǚ zǐ zhōng jí měi lì de， nǐ ruò bù zhī dào， zhǐ guǎn gēn suí yáng qún de jiǎo zōng qù， bǎ nǐ de shān yáng gāo mù fàng zài mù rén zhàng péng de páng biān."],[1,9,"我的佳偶， 我將你比法老車上套的駿馬。","wǒ de jiā ǒu， wǒ jiāng nǐ bǐ fǎ lǎo chē shàng tào de jùn mǎ."],[1,10,"你的兩腮因髮辮而秀美； 你的頸項因珠串而華麗。","nǐ de liǎng sāi yīn fà biàn ér xiù měi； nǐ de jǐng xiàng yīn zhū chuàn ér huá lì."],[1,11,"我們要為你編上金辮，鑲上銀釘。","wǒ men yào wèi nǐ biān shàng jīn biàn， xiāng shàng yín dīng."],[1,12,"王正坐席的時候， 我的哪噠香膏發出香味。","wáng zhèng zuò xí de shí hòu， wǒ de nǎ dā xiāng gāo fā chū xiāng wèi."],[1,13,"我以我的良人為一袋沒藥， 常在我懷中。","wǒ yǐ wǒ de liáng rén wèi yī dài méi yào， cháng zài wǒ huái zhōng."],[1,14,"我以我的良人為一棵鳳仙花， 在 隱‧基底葡萄園中。","wǒ yǐ wǒ de liáng rén wèi yī kē fèng xiān huā， zài yǐn‧jī dǐ pú táo yuán zhōng."],[1,15,"我的佳偶，你甚美麗！你甚美麗！ 你的眼 好像鴿子眼。","wǒ de jiā ǒu， nǐ shèn měi lì！ nǐ shèn měi lì！ nǐ de yǎn hǎo xiàng gē zǐ yǎn."],[1,16,"我的良人哪，你甚美麗可愛！ 我們以青草為床榻，","wǒ de liáng rén nǎ， nǐ shèn měi lì kě ài！ wǒ men yǐ qīng cǎo wèi chuáng tà，"],[1,17,"以香柏樹為房屋的棟樑， 以松樹為椽子。","yǐ xiāng bǎi shù wèi fáng wū de dòng liáng， yǐ sōng shù wèi chuán zǐ."],[2,1,"我是 沙崙的玫瑰花， 是谷中的百合花。","wǒ shì shā lún de méi guī huā， shì gǔ zhōng de bǎi hé huā."],[2,2,"我的佳偶在女子中， 好像百合花在荊棘內。","wǒ de jiā ǒu zài nǚ zǐ zhōng， hǎo xiàng bǎi hé huā zài jīng jí nèi."],[2,3,"我的良人在男子中， 如同蘋果樹在樹林中。 我歡歡喜喜坐在他的蔭下， 嘗他果子的滋味，覺得甘甜。","wǒ de liáng rén zài nán zǐ zhōng， rú tóng píng guǒ shù zài shù lín zhōng. wǒ huān huān xǐ xǐ zuò zài tā de yīn xià， cháng tā guǒ zǐ de zī wèi， jué dé gān tián."],[2,4,"他帶我入筵宴所， 以愛為旗在我以上。","tā dài wǒ rù yán yàn suǒ， yǐ ài wèi qí zài wǒ yǐ shàng."],[2,5,"求你們給我葡萄乾增補我力， 給我蘋果暢快我心， 因我思愛成病。","qiú nǐ men gěi wǒ pú táo qián zēng bǔ wǒ lì， gěi wǒ píng guǒ chàng kuài wǒ xīn， yīn wǒ sī ài chéng bìng."],[2,6,"他的左手在我頭下； 他的右手將我抱住。","tā de zuǒ shǒu zài wǒ tóu xià； tā de yòu shǒu jiāng wǒ bào zhù."],[2,7,"耶路撒冷的眾女子啊， 我指着羚羊或田野的母鹿囑咐你們： 不要驚動、不要叫醒我所親愛的， 等他自己情願。","yé lù sā lěng de zhòng nǚ zǐ a， wǒ zhǐ zhe líng yáng huò tián yě de mǔ lù zhǔ fù nǐ men： bù yào jīng dòng, bù yào jiào xǐng wǒ suǒ qīn ài de， děng tā zì jǐ qíng yuàn."],[2,8,"聽啊！是我良人的聲音； 看哪！他躥山越嶺而來。","tīng a！ shì wǒ liáng rén de shēng yīn； kàn nǎ！ tā cuān shān yuè lǐng ér lái."],[2,9,"我的良人好像羚羊，或像小鹿。 他站在我們牆壁後， 從窗戶往裏觀看， 從窗欞往裏窺探。","wǒ de liáng rén hǎo xiàng líng yáng， huò xiàng xiǎo lù. tā zhàn zài wǒ men qiáng bì hòu， cóng chuāng hù wǎng lǐ guān kàn， cóng chuāng líng wǎng lǐ kuī tàn."],[2,10,"我良人對我說： 我的佳偶，我的美人， 起來，與我同去！","wǒ liáng rén duì wǒ shuō： wǒ de jiā ǒu， wǒ de měi rén， qǐ lái， yǔ wǒ tóng qù！"],[2,11,"因為冬天已往， 雨水止住過去了。","yīn wèi dōng tiān yǐ wǎng， yǔ shuǐ zhǐ zhù guò qù le."],[2,12,"地上百花開放， 百鳥鳴叫的時候已經來到； 斑鳩的聲音在我們境內也聽見了。","de shàng bǎi huā kāi fàng， bǎi niǎo míng jiào de shí hòu yǐ jīng lái dào； bān jiū de shēng yīn zài wǒ men jìng nèi yě tīng jiàn le."],[2,13,"無花果樹的果子漸漸成熟； 葡萄樹開花放香。 我的佳偶，我的美人， 起來，與我同去！","wú huā guǒ shù de guǒ zǐ jiàn jiàn chéng shú； pú táo shù kāi huā fàng xiāng. wǒ de jiā ǒu， wǒ de měi rén， qǐ lái， yǔ wǒ tóng qù！"],[2,14,"我的鴿子啊，你在磐石穴中， 在陡巖的隱密處。 求你容我得見你的面貌， 得聽你的聲音； 因為你的聲音柔和， 你的面貌秀美。","wǒ de gē zǐ a， nǐ zài pán shí xué zhōng， zài dǒu yán de yǐn mì chù. qiú nǐ róng wǒ dé jiàn nǐ de miàn mào， dé tīng nǐ de shēng yīn； yīn wèi nǐ de shēng yīn róu hé， nǐ de miàn mào xiù měi."],[2,15,"要給我們擒拿狐狸， 就是毀壞葡萄園的小狐狸， 因為我們的葡萄正在開花。","yào gěi wǒ men qín ná hú lí， jiù shì huǐ huài pú táo yuán de xiǎo hú lí， yīn wèi wǒ men de pú táo zhèng zài kāi huā."],[2,16,"良人屬我，我也屬他； 他在百合花中牧放 群羊。","liáng rén shǔ wǒ， wǒ yě shǔ tā； tā zài bǎi hé huā zhōng mù fàng qún yáng."],[2,17,"我的良人哪， 求你等到天起涼風、 日影飛去的時候， 你要轉回，好像羚羊， 或像小鹿在 比特山上。","wǒ de liáng rén nǎ， qiú nǐ děng dào tiān qǐ liáng fēng, rì yǐng fēi qù de shí hòu， nǐ yào zhuǎn huí， hǎo xiàng líng yáng， huò xiàng xiǎo lù zài bǐ tè shān shàng."],[3,1,"我夜間躺臥在床上， 尋找我心所愛的； 我尋找他，卻尋不見。","wǒ yè jiān tǎng wò zài chuáng shàng， xún zhǎo wǒ xīn suǒ ài de； wǒ xún zhǎo tā， què xún bù jiàn."],[3,2,"我說：我要起來，遊行城中， 在街市上，在寬闊處， 尋找我心所愛的。 我尋找他，卻尋不見。","wǒ shuō： wǒ yào qǐ lái， yóu xíng chéng zhōng， zài jiē shì shàng， zài kuān kuò chù， xún zhǎo wǒ xīn suǒ ài de. wǒ xún zhǎo tā， què xún bù jiàn."],[3,3,"城中巡邏看守的人遇見我； 我問他們：你們看見我心所愛的沒有？","chéng zhōng xún luó kàn shǒu de rén yù jiàn wǒ； wǒ wèn tā men： nǐ men kàn jiàn wǒ xīn suǒ ài de méi yǒu？"],[3,4,"我剛離開他們就遇見我心所愛的。 我拉住他，不容他走， 領他入我母家， 到懷我者的內室。","wǒ gāng lí kāi tā men jiù yù jiàn wǒ xīn suǒ ài de. wǒ lā zhù tā， bù róng tā zǒu， lǐng tā rù wǒ mǔ jiā， dào huái wǒ zhě de nèi shì."],[3,5,"耶路撒冷的眾女子啊， 我指着羚羊或田野的母鹿囑咐你們： 不要驚動、不要叫醒我所親愛的， 等他自己情願。","yé lù sā lěng de zhòng nǚ zǐ a， wǒ zhǐ zhe líng yáng huò tián yě de mǔ lù zhǔ fù nǐ men： bù yào jīng dòng, bù yào jiào xǐng wǒ suǒ qīn ài de， děng tā zì jǐ qíng yuàn."],[3,6,"那從曠野上來、形狀如煙柱、 以沒藥和乳香並商人各樣香粉薰的是誰呢？","nà cóng kuàng yě shàng lái, xíng zhuàng rú yān zhù, yǐ méi yào hé rǔ xiāng bìng shāng rén gè yàng xiāng fěn xūn de shì shuí ne？"],[3,7,"看哪，是 所羅門的轎； 四圍有六十個勇士， 都是 以色列中的勇士；","kàn nǎ， shì suǒ luó mén de jiào； sì wéi yǒu liù shí gè yǒng shì， dōu shì yǐ sè liè zhōng de yǒng shì；"],[3,8,"手都持刀，善於爭戰， 腰間佩刀，防備夜間有驚慌。","shǒu dōu chí dāo， shàn yú zhēng zhàn， yāo jiān pèi dāo， fáng bèi yè jiān yǒu jīng huāng."],[3,9,"所羅門王用 黎巴嫩木 為自己製造一乘華轎。","suǒ luó mén wáng yòng lí bā nèn mù wèi zì jǐ zhì zào yī chéng huá jiào."],[3,10,"轎柱是用銀做的， 轎底是用金做的； 坐墊是紫色的， 其中所鋪的乃 耶路撒冷眾女子的愛情。","jiào zhù shì yòng yín zuò de， jiào dǐ shì yòng jīn zuò de； zuò diàn shì zǐ sè de， qí zhōng suǒ pù de nǎi yé lù sā lěng zhòng nǚ zǐ de ài qíng."],[3,11,"錫安的眾女子啊， 你們出去觀看 所羅門王！ 頭戴冠冕，就是在他婚筵的日子、 心中喜樂的時候，他母親給他戴上的。","xī ān de zhòng nǚ zǐ a， nǐ men chū qù guān kàn suǒ luó mén wáng！ tóu dài guān miǎn， jiù shì zài tā hūn yán de rì zǐ, xīn zhōng xǐ lè de shí hòu， tā mǔ qīn gěi tā dài shàng de."],[4,1,"我的佳偶，你甚美麗！你甚美麗！ 你的眼在帕子內 好像鴿子眼。 你的頭髮如同山羊群臥在 基列山旁。","wǒ de jiā ǒu， nǐ shèn měi lì！ nǐ shèn měi lì！ nǐ de yǎn zài pà zǐ nèi hǎo xiàng gē zǐ yǎn. nǐ de tóu fà rú tóng shān yáng qún wò zài jī liè shān páng."],[4,2,"你的牙齒如 新剪毛的一群 母羊， 洗淨上來，個個都有雙生， 沒有一隻喪掉子的。","nǐ de yá chǐ rú xīn jiǎn máo de yī qún mǔ yáng， xǐ jìng shàng lái， gè gè dōu yǒu shuāng shēng， méi yǒu yī zhī sàng diào zǐ de."],[4,3,"你的唇好像一條朱紅線； 你的嘴也秀美。 你的兩太陽在帕子內， 如同一塊石榴。","nǐ de chún hǎo xiàng yī tiáo zhū hóng xiàn； nǐ de zuǐ yě xiù měi. nǐ de liǎng tài yáng zài pà zǐ nèi， rú tóng yī kuài shí liú."],[4,4,"你的頸項好像 大衛建造收藏軍器的高臺， 其上懸掛一千盾牌， 都是勇士的籐牌。","nǐ de jǐng xiàng hǎo xiàng dà wèi jiàn zào shōu cáng jūn qì de gāo tái， qí shàng xuán guà yī qiān dùn pái， dōu shì yǒng shì de téng pái."],[4,5,"你的兩乳好像百合花中吃草的一對小鹿， 就是母鹿雙生的。","nǐ de liǎng rǔ hǎo xiàng bǎi hé huā zhōng chī cǎo de yī duì xiǎo lù， jiù shì mǔ lù shuāng shēng de."],[4,6,"我要往沒藥山和乳香岡去， 直等到天起涼風、 日影飛去的時候 回來。","wǒ yào wǎng méi yào shān hé rǔ xiāng gāng qù， zhí děng dào tiān qǐ liáng fēng, rì yǐng fēi qù de shí hòu huí lái."],[4,7,"我的佳偶，你全然美麗， 毫無瑕疵！","wǒ de jiā ǒu， nǐ quán rán měi lì， háo wú xiá cī！"],[4,8,"我的新婦，求你與我一同離開 黎巴嫩， 與我一同離開 黎巴嫩。 從 亞瑪拿頂， 從 示尼珥與 黑門頂， 從有獅子的洞， 從有豹子的山往下觀看。","wǒ de xīn fù， qiú nǐ yǔ wǒ yī tóng lí kāi lí bā nèn， yǔ wǒ yī tóng lí kāi lí bā nèn. cóng yà mǎ ná dǐng， cóng shì ní ěr yǔ hēi mén dǐng， cóng yǒu shī zǐ de dòng， cóng yǒu bào zǐ de shān wǎng xià guān kàn."],[4,9,"我妹子，我新婦， 你奪了我的心。 你用眼一看， 用你項上的一條 金鍊， 奪了我的心！","wǒ mèi zǐ， wǒ xīn fù， nǐ duó le wǒ de xīn. nǐ yòng yǎn yī kàn， yòng nǐ xiàng shàng de yī tiáo jīn liàn， duó le wǒ de xīn！"],[4,10,"我妹子，我新婦， 你的愛情何其美！ 你的愛情比酒更美！ 你膏油的香氣勝過一切香品！","wǒ mèi zǐ， wǒ xīn fù， nǐ de ài qíng hé qí měi！ nǐ de ài qíng bǐ jiǔ gèng měi！ nǐ gāo yóu de xiāng qì shèng guò yī qiè xiāng pǐn！"],[4,11,"我新婦，你的嘴唇滴蜜， 好像蜂房滴蜜； 你的舌下有蜜，有奶。 你衣服的香氣如 黎巴嫩的香氣。","wǒ xīn fù， nǐ de zuǐ chún dī mì， hǎo xiàng fēng fáng dī mì； nǐ de shé xià yǒu mì， yǒu nǎi. nǐ yī fú de xiāng qì rú lí bā nèn de xiāng qì."],[4,12,"我妹子，我新婦， 乃是關鎖的園， 禁閉的井，封閉的泉源。","wǒ mèi zǐ， wǒ xīn fù， nǎi shì guān suǒ de yuán， jìn bì de jǐng， fēng bì de quán yuán."],[4,13,"你園內所種的結了石榴， 有佳美的果子， 並鳳仙花與哪噠樹。","nǐ yuán nèi suǒ zhǒng de jié le shí liú， yǒu jiā měi de guǒ zǐ， bìng fèng xiān huā yǔ nǎ dā shù."],[4,14,"有哪噠和番紅花， 菖蒲和桂樹， 並各樣乳香木、沒藥、沉香， 與一切上等的果品。","yǒu nǎ dā hé fān hóng huā， chāng pú hé guì shù， bìng gè yàng rǔ xiāng mù, méi yào, chén xiāng， yǔ yī qiè shàng děng de guǒ pǐn."],[4,15,"你是園中的泉，活水的井， 從 黎巴嫩流下來的溪水。","nǐ shì yuán zhōng de quán， huó shuǐ de jǐng， cóng lí bā nèn liú xià lái de xī shuǐ."],[4,16,"北風啊，興起！ 南風啊，吹來！ 吹在我的園內， 使其中的香氣發出來。 願我的良人進入自己園裏， 吃他佳美的果子。","běi fēng a， xìng qǐ！ nán fēng a， chuī lái！ chuī zài wǒ de yuán nèi， shǐ qí zhōng de xiāng qì fā chū lái. yuàn wǒ de liáng rén jìn rù zì jǐ yuán lǐ， chī tā jiā měi de guǒ zǐ."],[5,1,"我妹子，我新婦， 我進了我的園中， 採了我的沒藥和香料， 吃了我的蜜房和蜂蜜， 喝了我的酒和奶。 我的朋友們，請吃！ 我所親愛的，請喝，且多多地喝！","wǒ mèi zǐ， wǒ xīn fù， wǒ jìn le wǒ de yuán zhōng， cǎi le wǒ de méi yào hé xiāng liào， chī le wǒ de mì fáng hé fēng mì， hē le wǒ de jiǔ hé nǎi. wǒ de péng yǒu men， qǐng chī！ wǒ suǒ qīn ài de， qǐng hē， qiě duō duō de hē！"],[5,2,"我身睡臥，我心卻醒。 這是我良人的聲音； 他敲門 說： 我的妹子，我的佳偶， 我的鴿子，我的完全人， 求你給我開門； 因我的頭滿了露水， 我的頭髮被夜露滴濕。","wǒ shēn shuì wò， wǒ xīn què xǐng. zhè shì wǒ liáng rén de shēng yīn； tā qiāo mén shuō： wǒ de mèi zǐ， wǒ de jiā ǒu， wǒ de gē zǐ， wǒ de wán quán rén， qiú nǐ gěi wǒ kāi mén； yīn wǒ de tóu mǎn le lù shuǐ， wǒ de tóu fà bèi yè lù dī shī."],[5,3,"我回答說： 我脫了衣裳，怎能再穿上呢？ 我洗了腳，怎能再玷污呢？","wǒ huí dá shuō： wǒ tuō le yī shang， zěn néng zài chuān shàng ne？ wǒ xǐ le jiǎo， zěn néng zài diàn wū ne？"],[5,4,"我的良人從 門孔裏伸進手來， 我便因他動了心。","wǒ de liáng rén cóng mén kǒng lǐ shēn jìn shǒu lái， wǒ biàn yīn tā dòng le xīn."],[5,5,"我起來，要給我良人開門。 我的兩手滴下沒藥； 我的指頭有沒藥汁滴在門閂上。","wǒ qǐ lái， yào gěi wǒ liáng rén kāi mén. wǒ de liǎng shǒu dī xià méi yào； wǒ de zhǐ tóu yǒu méi yào zhī dī zài mén shuān shàng."],[5,6,"我給我的良人開了門； 我的良人卻已轉身走了。 他說話的時候，我神不守舍； 我尋找他，竟尋不見； 我呼叫他，他卻不回答。","wǒ gěi wǒ de liáng rén kāi le mén； wǒ de liáng rén què yǐ zhuǎn shēn zǒu le. tā shuō huà de shí hòu， wǒ shén bù shǒu shě； wǒ xún zhǎo tā， jìng xún bù jiàn； wǒ hū jiào tā， tā què bù huí dá."],[5,7,"城中巡邏看守的人遇見我， 打了我，傷了我； 看守城牆的人奪去我的披肩。","chéng zhōng xún luó kàn shǒu de rén yù jiàn wǒ， dǎ le wǒ， shāng le wǒ； kàn shǒu chéng qiáng de rén duó qù wǒ de pī jiān."],[5,8,"耶路撒冷的眾女子啊，我囑咐你們： 若遇見我的良人， 要告訴他，我因思愛成病。","yé lù sā lěng de zhòng nǚ zǐ a， wǒ zhǔ fù nǐ men： ruò yù jiàn wǒ de liáng rén， yào gào sù tā， wǒ yīn sī ài chéng bìng."],[5,9,"你這女子中極美麗的， 你的良人比別人的良人有何強處？ 你的良人比別人的良人有何強處， 你就這樣囑咐我們？","nǐ zhè nǚ zǐ zhōng jí měi lì de， nǐ de liáng rén bǐ bié rén de liáng rén yǒu hé qiáng chù？ nǐ de liáng rén bǐ bié rén de liáng rén yǒu hé qiáng chù， nǐ jiù zhè yàng zhǔ fù wǒ men？"],[5,10,"我的良人白而且紅， 超乎萬人之上。","wǒ de liáng rén bái ér qiě hóng， chāo hū wàn rén zhī shàng."],[5,11,"他的頭 像至精的金子； 他的頭髮厚密纍垂，黑如烏鴉。","tā de tóu xiàng zhì jīng de jīn zǐ； tā de tóu fà hòu mì léi chuí， hēi rú wū yā."],[5,12,"他的眼如溪水旁的鴿子 眼， 用奶洗淨，安得合式。","tā de yǎn rú xī shuǐ páng de gē zǐ yǎn， yòng nǎi xǐ jìng， ān dé hé shì."],[5,13,"他的兩腮如香花畦， 如香草臺； 他的嘴唇 像百合花， 且滴下沒藥汁。","tā de liǎng sāi rú xiāng huā qí， rú xiāng cǎo tái； tā de zuǐ chún xiàng bǎi hé huā， qiě dī xià méi yào zhī."],[5,14,"他的兩手 好像金管， 鑲嵌水蒼玉； 他的身體 如同雕刻的象牙， 周圍鑲嵌藍寶石。","tā de liǎng shǒu hǎo xiàng jīn guǎn， xiāng qiàn shuǐ cāng yù； tā de shēn tǐ rú tóng diāo kè de xiàng yá， zhōu wéi xiāng qiàn lán bǎo shí."],[5,15,"他的腿 好像白玉石柱， 安在精金座上； 他的形狀如 黎巴嫩， 且佳美如香柏樹。","tā de tuǐ hǎo xiàng bái yù shí zhù， ān zài jīng jīn zuò shàng； tā de xíng zhuàng rú lí bā nèn， qiě jiā měi rú xiāng bǎi shù."],[5,16,"他的口極其甘甜； 他全然可愛。 耶路撒冷的眾女子啊， 這是我的良人； 這是我的朋友。","tā de kǒu jí qí gān tián； tā quán rán kě ài. yé lù sā lěng de zhòng nǚ zǐ a， zhè shì wǒ de liáng rén； zhè shì wǒ de péng yǒu."],[6,1,"你這女子中極美麗的， 你的良人往何處去了？ 你的良人轉向何處去了， 我們好與你同去尋找他。","nǐ zhè nǚ zǐ zhōng jí měi lì de， nǐ de liáng rén wǎng hé chù qù le？ nǐ de liáng rén zhuǎn xiàng hé chù qù le， wǒ men hǎo yǔ nǐ tóng qù xún zhǎo tā."],[6,2,"我的良人下入自己園中， 到香花畦， 在園內牧放 群羊， 採百合花。","wǒ de liáng rén xià rù zì jǐ yuán zhōng， dào xiāng huā qí， zài yuán nèi mù fàng qún yáng， cǎi bǎi hé huā."],[6,3,"我屬我的良人， 我的良人也屬我； 他在百合花中牧放 群羊。","wǒ shǔ wǒ de liáng rén， wǒ de liáng rén yě shǔ wǒ； tā zài bǎi hé huā zhōng mù fàng qún yáng."],[6,4,"我的佳偶啊，你美麗如 得撒， 秀美如 耶路撒冷， 威武如展開旌旗的軍隊。","wǒ de jiā ǒu a， nǐ měi lì rú dé sā， xiù měi rú yé lù sā lěng， wēi wǔ rú zhǎn kāi jīng qí de jūn duì."],[6,5,"求你掉轉眼目不看我， 因你的眼目使我驚亂。 你的頭髮如同山羊群臥在 基列山旁。","qiú nǐ diào zhuǎn yǎn mù bù kàn wǒ， yīn nǐ de yǎn mù shǐ wǒ jīng luàn. nǐ de tóu fà rú tóng shān yáng qún wò zài jī liè shān páng."],[6,6,"你的牙齒如一群母羊 洗淨上來，個個都有雙生， 沒有一隻喪掉子的。","nǐ de yá chǐ rú yī qún mǔ yáng xǐ jìng shàng lái， gè gè dōu yǒu shuāng shēng， méi yǒu yī zhī sàng diào zǐ de."],[6,7,"你的兩太陽在帕子內， 如同一塊石榴。","nǐ de liǎng tài yáng zài pà zǐ nèi， rú tóng yī kuài shí liú."],[6,8,"有六十王后八十妃嬪， 並有無數的童女。","yǒu liù shí wáng hòu bā shí fēi pín， bìng yǒu wú shù de tóng nǚ."],[6,9,"我的鴿子，我的完全人， 只有這一個是她母親獨生的， 是生養她者所寶愛的。 眾女子見了就稱她有福； 王后妃嬪見了也讚美她。","wǒ de gē zǐ， wǒ de wán quán rén， zhǐ yǒu zhè yī gè shì tā mǔ qīn dú shēng de， shì shēng yǎng tā zhě suǒ bǎo ài de. zhòng nǚ zǐ jiàn le jiù chēng tā yǒu fú； wáng hòu fēi pín jiàn le yě zàn měi tā."],[6,10,"那向外觀看、如晨光發現、 美麗如月亮、皎潔如日頭、 威武如展開旌旗軍隊的是誰呢？","nà xiàng wài guān kàn, rú chén guāng fā xiàn, měi lì rú yuè liàng, jiǎo jié rú rì tóu, wēi wǔ rú zhǎn kāi jīng qí jūn duì de shì shuí ne？"],[6,11,"我下入核桃園， 要看谷中青綠的植物， 要看葡萄發芽沒有， 石榴開花沒有。","wǒ xià rù hé táo yuán， yào kàn gǔ zhōng qīng lǜ de zhí wù， yào kàn pú táo fā yá méi yǒu， shí liú kāi huā méi yǒu."],[6,12,"不知不覺， 我的心將我安置在我尊長的車中。","bù zhī bù jué， wǒ de xīn jiāng wǒ ān zhì zài wǒ zūn zhǎng de chē zhōng."],[6,13,"回來，回來， 書拉密女； 你回來，你回來，使我們得觀看你。 你們為何要觀看 書拉密女， 像觀看 瑪哈念跳舞的呢？","huí lái， huí lái， shū lā mì nǚ； nǐ huí lái， nǐ huí lái， shǐ wǒ men dé guān kàn nǐ. nǐ men wèi hé yào guān kàn shū lā mì nǚ， xiàng guān kàn mǎ hā niàn tiào wǔ de ne？"],[7,1,"王女啊，你的腳在鞋中何其美好！ 你的大腿圓潤，好像美玉， 是巧匠的手做成的。","wáng nǚ a， nǐ de jiǎo zài xié zhōng hé qí měi hǎo！ nǐ de dà tuǐ yuán rùn， hǎo xiàng měi yù， shì qiǎo jiàng de shǒu zuò chéng de."],[7,2,"你的肚臍 如圓杯， 不缺調和的酒； 你的腰如一堆麥子， 周圍有百合花。","nǐ de dù qí rú yuán bēi， bù quē diào hé de jiǔ； nǐ de yāo rú yī duī mài zǐ， zhōu wéi yǒu bǎi hé huā."],[7,3,"你的兩乳好像一對小鹿， 就是母鹿雙生的。","nǐ de liǎng rǔ hǎo xiàng yī duì xiǎo lù， jiù shì mǔ lù shuāng shēng de."],[7,4,"你的頸項如象牙臺； 你的眼目 像 希實本、 巴特‧拉併門旁的水池； 你的鼻子彷彿朝 大馬士革的 黎巴嫩塔。","nǐ de jǐng xiàng rú xiàng yá tái； nǐ de yǎn mù xiàng xī shí běn, bā tè‧lā bìng mén páng de shuǐ chí； nǐ de bí zǐ páng fú cháo dà mǎ shì gé de lí bā nèn tǎ."],[7,5,"你的頭在你身上好像 迦密山； 你頭上的髮是紫黑色； 王的心因這下垂的髮綹繫住了。","nǐ de tóu zài nǐ shēn shàng hǎo xiàng jiā mì shān； nǐ tóu shàng de fà shì zǐ hēi sè； wáng de xīn yīn zhè xià chuí de fà liǔ xì zhù le."],[7,6,"我所愛的，你何其美好！ 何其可悅，使人歡暢喜樂！","wǒ suǒ ài de， nǐ hé qí měi hǎo！ hé qí kě yuè， shǐ rén huān chàng xǐ lè！"],[7,7,"你的身量好像棕樹； 你的兩乳如同其上的果子，纍纍下垂。","nǐ de shēn liàng hǎo xiàng zōng shù； nǐ de liǎng rǔ rú tóng qí shàng de guǒ zǐ， léi léi xià chuí."],[7,8,"我說：我要上這棕樹，抓住枝子。 願你的兩乳好像葡萄纍纍下垂， 你鼻子的氣味香如蘋果；","wǒ shuō： wǒ yào shàng zhè zōng shù， zhuā zhù zhī zǐ. yuàn nǐ de liǎng rǔ hǎo xiàng pú táo léi léi xià chuí， nǐ bí zǐ de qì wèi xiāng rú píng guǒ；"],[7,9,"你的口如上好的酒。 女子說：為我的良人下咽舒暢， 流入睡覺人的嘴中。","nǐ de kǒu rú shàng hǎo de jiǔ. nǚ zǐ shuō： wèi wǒ de liáng rén xià yàn shū chàng， liú rù shuì jué rén de zuǐ zhōng."],[7,10,"我屬我的良人， 他也戀慕我。","wǒ shǔ wǒ de liáng rén， tā yě liàn mù wǒ."],[7,11,"我的良人，來吧！ 你我可以往田間去； 你我可以在村莊住宿。","wǒ de liáng rén， lái ba！ nǐ wǒ kě yǐ wǎng tián jiān qù； nǐ wǒ kě yǐ zài cūn zhuāng zhù sù."],[7,12,"我們早晨起來往葡萄園去， 看看葡萄發芽開花沒有， 石榴放蕊沒有； 我在那裏要將我的愛情給你。","wǒ men zǎo chén qǐ lái wǎng pú táo yuán qù， kàn kàn pú táo fā yá kāi huā méi yǒu， shí liú fàng ruǐ méi yǒu； wǒ zài nà lǐ yào jiāng wǒ de ài qíng gěi nǐ."],[7,13,"風茄放香， 在我們的門內有各樣新陳佳美的果子； 我的良人，這都是我為你存留的。","fēng jiā fàng xiāng， zài wǒ men de mén nèi yǒu gè yàng xīn chén jiā měi de guǒ zǐ； wǒ de liáng rén， zhè dōu shì wǒ wèi nǐ cún liú de."],[8,1,"巴不得你像我的兄弟， 像吃我母親奶的兄弟； 我在外頭遇見你就與你親嘴， 誰也不輕看我。","bā bù dé nǐ xiàng wǒ de xiōng dì， xiàng chī wǒ mǔ qīn nǎi de xiōng dì； wǒ zài wài tóu yù jiàn nǐ jiù yǔ nǐ qīn zuǐ， shuí yě bù qīng kàn wǒ."],[8,2,"我必引導你， 領你進我母親的家； 我可以領受教訓， 也就使你喝石榴汁釀的香酒。","wǒ bì yǐn dǎo nǐ， lǐng nǐ jìn wǒ mǔ qīn de jiā； wǒ kě yǐ lǐng shòu jiào xùn， yě jiù shǐ nǐ hē shí liú zhī niàng de xiāng jiǔ."],[8,3,"他的左手必在我頭下； 他的右手必將我抱住。","tā de zuǒ shǒu bì zài wǒ tóu xià； tā de yòu shǒu bì jiāng wǒ bào zhù."],[8,4,"耶路撒冷的眾女子啊， 我囑咐你們： 不要驚動、不要叫醒我所親愛的， 等他自己情願。","yé lù sā lěng de zhòng nǚ zǐ a， wǒ zhǔ fù nǐ men： bù yào jīng dòng, bù yào jiào xǐng wǒ suǒ qīn ài de， děng tā zì jǐ qíng yuàn."],[8,5,"那靠着良人從曠野上來的是誰呢？ 我在蘋果樹下叫醒你。 你母親在那裏為你劬勞； 生養你的在那裏 為你劬勞。","nà kào zhe liáng rén cóng kuàng yě shàng lái de shì shuí ne？ wǒ zài píng guǒ shù xià jiào xǐng nǐ. nǐ mǔ qīn zài nà lǐ wèi nǐ qú láo； shēng yǎng nǐ de zài nà lǐ wèi nǐ qú láo."],[8,6,"求你將我放在你心上如印記， 帶在你臂上如戳記。 因為愛情如死之堅強， 嫉恨如陰間之殘忍； 所發的電光是火焰的電光， 是耶和華的烈焰。","qiú nǐ jiāng wǒ fàng zài nǐ xīn shàng rú yìn jì， dài zài nǐ bì shàng rú chuō jì. yīn wèi ài qíng rú sǐ zhī jiān qiáng， jí hèn rú yīn jiān zhī cán rěn； suǒ fā de diàn guāng shì huǒ yàn de diàn guāng， shì yé hé huá de liè yàn."],[8,7,"愛情，眾水不能熄滅， 大水也不能淹沒。 若有人拿家中所有的財寶要換愛情， 就全被藐視。","ài qíng， zhòng shuǐ bù néng xī miè， dà shuǐ yě bù néng yān méi. ruò yǒu rén ná jiā zhōng suǒ yǒu de cái bǎo yào huàn ài qíng， jiù quán bèi miǎo shì."],[8,8,"我們有一小妹； 她的兩乳尚未長成， 人來提親的日子， 我們當為她怎樣辦理？","wǒ men yǒu yī xiǎo mèi； tā de liǎng rǔ shàng wèi zhǎng chéng， rén lái tí qīn de rì zǐ， wǒ men dāng wèi tā zěn yàng bàn lǐ？"],[8,9,"她若是牆， 我們要在其上建造銀塔； 她若是門， 我們要用香柏木板圍護她。","tā ruò shì qiáng， wǒ men yào zài qí shàng jiàn zào yín tǎ； tā ruò shì mén， wǒ men yào yòng xiāng bǎi mù bǎn wéi hù tā."],[8,10,"我是牆； 我兩乳像 其上的樓。 那時，我在他眼中像得平安的人。","wǒ shì qiáng； wǒ liǎng rǔ xiàng qí shàng de lóu. nà shí， wǒ zài tā yǎn zhōng xiàng dé píng ān de rén."],[8,11,"所羅門在 巴力‧哈們有一葡萄園； 他將這葡萄園交給看守的人， 為其中的果子必交一千 舍客勒銀子。","suǒ luó mén zài bā lì‧hā men yǒu yī pú táo yuán； tā jiāng zhè pú táo yuán jiāo gěi kàn shǒu de rén， wèi qí zhōng de guǒ zǐ bì jiāo yī qiān shě kè lēi yín zǐ."],[8,12,"我自己的葡萄園在我面前。 所羅門哪，一千 舍客勒歸你， 二百 舍客勒歸看守果子的人。","wǒ zì jǐ de pú táo yuán zài wǒ miàn qián. suǒ luó mén nǎ， yī qiān shě kè lēi guī nǐ， èr bǎi shě kè lēi guī kàn shǒu guǒ zǐ de rén."],[8,13,"你這住在園中的， 同伴都要聽你的聲音， 求你使我也得聽見。","nǐ zhè zhù zài yuán zhōng de， tóng bàn dōu yào tīng nǐ de shēng yīn， qiú nǐ shǐ wǒ yě dé tīng jiàn."],[8,14,"我的良人哪，求你快來！ 如羚羊或小鹿在香草山上。","wǒ de liáng rén nǎ， qiú nǐ kuài lái！ rú líng yáng huò xiǎo lù zài xiāng cǎo shān shàng."]],"arb-vandyck":[[1,1,"نَشِيدُ ٱلْأَنْشَادِ ٱلَّذِي لِسُلَيْمَانَ:","nasẖīdu ٱl̊ạản̊sẖādi ٱlãdẖī lisulaẙmāna:"],[1,2,"لِيُقَبِّلْنِي بِقُبْلَاتِ فَمِهِ، لِأَنَّ حُبَّكَ أَطْيَبُ مِنَ ٱلْخَمْرِ.","līuqabĩl̊nī biqub̊lāti famihi, liạảnã ḥubãka ạảṭ̊yabu mina ٱl̊kẖam̊ri."],[1,3,"لِرَائِحَةِ أَدْهَانِكَ ٱلطَّيِّبَةِ. ٱسْمُكَ دُهْنٌ مُهْرَاقٌ، لِذَلِكَ أَحَبَّتْكَ ٱلْعَذَارَى.","lirāyỉḥaẗi ạảd̊hānika ٱlṭãyĩbaẗi. ٱs̊muka duh̊nuⁿ muh̊rāquⁿ, lidẖalika ạảḥabãt̊ka ٱl̊ʿadẖāray̱."],[1,4,"اُجْذُبْنِي وَرَاءَكَ فَنَجْرِيَ. أَدْخَلَنِي ٱلْمَلِكُ إِلَى حِجَالِهِ. نَبْتَهِجُ وَنَفْرَحُ بِكَ. نَذْكُرُ حُبَّكَ أَكْثَرَ مِنَ ٱلْخَمْرِ. بِٱلْحَقِّ يُحِبُّونَكَ.","ạuj̊dẖub̊nī warāʾaka fanaj̊rīa. ạảd̊kẖalanī ٱl̊maliku ại̹lay̱ ḥijālihi. nab̊tahiju wanaf̊raḥu bika. nadẖ̊kuru ḥubãka ạảk̊tẖara mina ٱl̊kẖam̊ri. biٱl̊ḥaqĩ yuḥibũwnaka."],[1,5,"أَنَا سَوْدَاءُ وَجَمِيلَةٌ يَا بَنَاتِ أُورُشَلِيمَ، كَخِيَامِ قِيدَارَ، كَشُقَقِ سُلَيْمَانَ.","ạảnā saẘdāʾu wajamīlaẗuⁿ yā banāti ạủwrusẖalīma, kakẖīāmi qīdāra, kasẖuqaqi sulaẙmāna."],[1,6,"لَا تَنْظُرْنَ إِلَيَّ لِكَوْنِي سَوْدَاءَ، لِأَنَّ ٱلشَّمْسَ قَدْ لَوَّحَتْنِي. بَنُو أُمِّي غَضِبُوا عَلَيَّ. جَعَلُونِي نَاطُورَةَ ٱلْكُرُومِ. أَمَّا كَرْمِي فَلَمْ أَنْطُرْهُ.","lā tan̊ẓur̊na ại̹layã likaẘnī saẘdāʾa, liạảnã ٱlsẖãm̊sa qad̊ lawãḥat̊nī. banū ạủmĩy gẖaḍibūạ ʿalayã. jaʿalūnī nāṭūraẗa ٱl̊kurūmi. ạảmãạ kar̊mī falam̊ ạản̊ṭur̊hu."],[1,7,"أَخْبِرْنِي يَا مَنْ تُحِبُّهُ نَفْسِي، أَيْنَ تَرْعَى، أَيْنَ تُرْبِضُ عِنْدَ ٱلظَّهِيرَةِ. لِمَاذَا أَنَا أَكُونُ كَمُقَنَّعَةٍ عِنْدَ قُطْعَانِ أَصْحَابِكَ؟","ạảkẖ̊bir̊nī yā man̊ tuḥibũhu naf̊sī, ạảẙna tar̊ʿay̱, ạảẙna tur̊biḍu ʿin̊da ٱlẓãhīraẗi. limādẖā ạảnā ạảkūnu kamuqanãʿaẗiⁿ ʿin̊da quṭ̊ʿāni ạảṣ̊ḥābika?"],[1,8,"إِنْ لَمْ تَعْرِفِي أَيَّتُهَا ٱلْجَمِيلَةُ بَيْنَ ٱلنِّسَاءِ، فَٱخْرُجِي عَلَى آثَارِ ٱلْغَنَمِ، وَٱرْعَيْ جِدَاءَكِ عِنْدَ مَسَاكِنِ ٱلرُّعَاةِ.","ại̹n̊ lam̊ taʿ̊rifī ạảyãtuhā ٱl̊jamīlaẗu baẙna ٱlnĩsāʾi, faٱkẖ̊rujī ʿalay̱ ậtẖāri ٱl̊gẖanami, waٱr̊ʿaẙ jidāʾaki ʿin̊da masākini ٱlrũʿāẗi."],[1,9,"لَقَدْ شَبَّهْتُكِ يَا حَبِيبَتِي بِفَرَسٍ فِي مَرْكَبَاتِ فِرْعَوْنَ.","laqad̊ sẖabãh̊tuki yā ḥabībatī bifarasiⁿ fī mar̊kabāti fir̊ʿaẘna."],[1,10,"مَا أَجْمَلَ خَدَّيْكِ بِسُمُوطٍ، وَعُنُقَكِ بِقَلَائِدَ!","mā ạảj̊mala kẖadãẙki bisumūṭiⁿ, waʿunuqaki biqalāyỉda!"],[1,11,"نَصْنَعُ لَكِ سَلَاسِلَ مِنْ ذَهَبٍ مَعَ جُمَانٍ مِنْ فِضَّةٍ.","naṣ̊naʿu laki salāsila min̊ dẖahabiⁿ maʿa jumāniⁿ min̊ fiḍãẗiⁿ."],[1,12,"مَا دَامَ ٱلْمَلِكُ فِي مَجْلِسِهِ أَفَاحَ نَارِدِينِي رَائِحَتَهُ.","mā dāma ٱl̊maliku fī maj̊lisihi ạảfāḥa nāridīnī rāyỉḥatahu."],[1,13,"صُرَّةُ ٱلْمُرِّ حَبِيبِي لِي. بَيْنَ ثَدْيَيَّ يَبِيتُ.","ṣurãẗu ٱl̊murĩ ḥabībī lī. baẙna tẖad̊yayã yabītu."],[1,14,"طَاقَةُ فَاغِيَةٍ حَبِيبِي لِي فِي كُرُومِ عَيْنِ جَدْيٍ.","ṭāqaẗu fāgẖīaẗiⁿ ḥabībī lī fī kurūmi ʿaẙni jad̊yiⁿ."],[1,15,"هَا أَنْتِ جَمِيلَةٌ يَا حَبِيبَتِي، هَا أَنْتِ جَمِيلَةٌ. عَيْنَاكِ حَمَامَتَانِ.","hā ạản̊ti jamīlaẗuⁿ yā ḥabībatī, hā ạản̊ti jamīlaẗuⁿ. ʿaẙnāki ḥamāmatāni."],[1,16,"هَا أَنْتَ جَمِيلٌ يَا حَبِيبِي وَحُلْوٌ، وَسَرِيرُنَا أَخْضَرُ.","hā ạản̊ta jamīluⁿ yā ḥabībī waḥul̊wuⁿ, wasarīrunā ạảkẖ̊ḍaru."],[1,17,"جَوَائِزُ بَيْتِنَا أَرْزٌ، وَرَوَافِدُنَا سَرْوٌ.","jawāyỉzu baẙtinā ạảr̊zuⁿ, warawāfidunā sar̊wuⁿ."],[2,1,"أَنَا نَرْجِسُ شَارُونَ، سَوْسَنَةُ ٱلْأَوْدِيَةِ.","ạảnā nar̊jisu sẖārūna, saẘsanaẗu ٱl̊ạảẘdīaẗi."],[2,2,"كَٱلسَّوْسَنَةِ بَيْنَ ٱلشَّوْكِ كَذَلِكَ حَبِيبَتِي بَيْنَ ٱلْبَنَاتِ.","kaٱlsãẘsanaẗi baẙna ٱlsẖãẘki kadẖalika ḥabībatī baẙna ٱl̊banāti."],[2,3,"كَٱلتُّفَّاحِ بَيْنَ شَجَرِ ٱلْوَعْرِ كَذَلِكَ حَبِيبِي بَيْنَ ٱلْبَنِينَ. تَحْتَ ظِلِّهِ ٱشْتَهَيْتُ أَنْ أَجْلِسَ، وَثَمَرَتُهُ حُلْوَةٌ لِحَلْقِي.","kaٱltũfãạḥi baẙna sẖajari ٱl̊waʿ̊ri kadẖalika ḥabībī baẙna ٱl̊banīna. taḥ̊ta ẓilĩhi ٱsẖ̊tahaẙtu ạản̊ ạảj̊lisa, watẖamaratuhu ḥul̊waẗuⁿ liḥal̊qī."],[2,4,"أَدْخَلَنِي إِلَى بَيْتِ ٱلْخَمْرِ، وَعَلَمُهُ فَوْقِي مَحَبَّةٌ.","ạảd̊kẖalanī ại̹lay̱ baẙti ٱl̊kẖam̊ri, waʿalamuhu faẘqī maḥabãẗuⁿ."],[2,5,"أَسْنِدُونِي بِأَقْرَاصِ ٱلزَّبِيبِ. أَنْعِشُونِي بِٱلتُّفَّاحِ، فَإِنِّي مَرِيضَةٌ حُبًّا.","ạảs̊nidūnī biạảq̊rāṣi ٱlzãbībi. ạản̊ʿisẖūnī biٱltũfãạḥi, fāi̹nĩy marīḍaẗuⁿ ḥubaⁿ̃ạ."],[2,6,"شِمَالُهُ تَحْتَ رَأْسِي وَيَمِينُهُ تُعَانِقُنِي.","sẖimāluhu taḥ̊ta rā̊̉sī wayamīnuhu tuʿāniqunī."],[2,7,"أُحَلِّفُكُنَّ يَا بَنَاتِ أُورُشَلِيمَ بِٱلظِّبَاءِ وَبِأَيَائِلِ ٱلْحُقُولِ، أَلَّا تُيَقِّظْنَ وَلَا تُنَبِّهْنَ ٱلْحَبِيبَ حَتَّى يَشَاءَ.","ạủḥalĩfukunã yā banāti ạủwrusẖalīma biٱlẓĩbāʾi wabiạảyāyỉli ٱl̊ḥuqūli, ạảlãạ tuyaqĩẓ̊na walā tunabĩh̊na ٱl̊ḥabība ḥatãy̱ yasẖāʾa."],[2,8,"صَوْتُ حَبِيبِي. هُوَذَا آتٍ طَافِرًا عَلَى ٱلْجِبَالِ، قَافِزًا عَلَى ٱلتِّلَالِ.","ṣaẘtu ḥabībī. hūadẖā ậtiⁿ ṭāfiraⁿạ ʿalay̱ ٱl̊jibāli, qāfizaⁿạ ʿalay̱ ٱltĩlāli."],[2,9,"حَبِيبِي هُوَ شَبِيهٌ بِٱلظَّبْيِ أَوْ بِغُفْرِ ٱلْأَيَائِلِ. هُوَذَا وَاقِفٌ وَرَاءَ حَائِطِنَا، يَتَطَلَّعُ مِنَ ٱلْكُوَى، يُوَصْوِصُ مِنَ ٱلشَّبَابِيكِ.","ḥabībī hūa sẖabīhuⁿ biٱlẓãb̊yi ạảẘ bigẖuf̊ri ٱl̊ạảyāyỉli. hūadẖā wāqifuⁿ warāʾa ḥāyỉṭinā, yataṭalãʿu mina ٱl̊kūay̱, yūaṣ̊wiṣu mina ٱlsẖãbābīki."],[2,10,"أَجَابَ حَبِيبِي وَقَالَ لِي: «قُومِي يَا حَبِيبَتِي، يَاجَمِيلَتِي وَتَعَالَيْ.","ạảjāba ḥabībī waqāla lī: «qūmī yā ḥabībatī, yājamīlatī wataʿālaẙ."],[2,11,"لِأَنَّ ٱلشِّتَاءَ قَدْ مَضَى، وَٱلْمَطَرَ مَرَّ وَزَالَ.","liạảnã ٱlsẖĩtāʾa qad̊ maḍay̱, waٱl̊maṭara marã wazāla."],[2,12,"ٱلزُّهُورُ ظَهَرَتْ فِي ٱلْأَرْضِ. بَلَغَ أَوَانُ ٱلْقَضْبِ، وَصَوْتُ ٱلْيَمَامَةِ سُمِعَ فِي أَرْضِنَا.","ٱlzũhūru ẓaharat̊ fī ٱl̊ạảr̊ḍi. balagẖa ạảwānu ٱl̊qaḍ̊bi, waṣaẘtu ٱl̊yamāmaẗi sumiʿa fī ạảr̊ḍinā."],[2,13,"ٱلتِّينَةُ أَخْرَجَتْ فِجَّهَا، وَقُعَالُ ٱلْكُرُومِ تُفِيحُ رَائِحَتَهَا. قُومِي يَا حَبِيبَتِي، يَا جَمِيلَتِي وَتَعَالَيْ.","ٱltĩynaẗu ạảkẖ̊rajat̊ fijãhā, waquʿālu ٱl̊kurūmi tufīḥu rāyỉḥatahā. qūmī yā ḥabībatī, yā jamīlatī wataʿālaẙ."],[2,14,"يَا حَمَامَتِي فِي مَحَاجِئِ ٱلصَّخْرِ، فِي سِتْرِ ٱلْمَعَاقِلِ، أَرِينِي وَجْهَكِ، أَسْمِعِينِي صَوْتَكِ، لِأَنَّ صَوْتَكِ لَطِيفٌ وَوَجْهَكِ جَمِيلٌ.","yā ḥamāmatī fī maḥājīỉ ٱlṣãkẖ̊ri, fī sit̊ri ٱl̊maʿāqili, ạảrīnī waj̊haki, ạảs̊miʿīnī ṣaẘtaki, liạảnã ṣaẘtaki laṭīfuⁿ wawaj̊haki jamīluⁿ."],[2,15,"خُذُوا لَنَا ٱلثَّعَالِبَ، ٱلثَّعَالِبَ ٱلصِّغَارَ ٱلْمُفْسِدَةَ ٱلْكُرُومِ، لِأَنَّ كُرُومَنَا قَدْ أَقْعَلَتْ.","kẖudẖūạ lanā ٱltẖãʿāliba, ٱltẖãʿāliba ٱlṣĩgẖāra ٱl̊muf̊sidaẗa ٱl̊kurūmi, liạảnã kurūmanā qad̊ ạảq̊ʿalat̊."],[2,16,"حَبِيبِي لِي وَأَنَا لَهُ. ٱلرَّاعِي بَيْنَ ٱلسَّوْسَنِ.","ḥabībī lī wāảnā lahu. ٱlrãạʿī baẙna ٱlsãẘsani."],[2,17,"إِلَى أَنْ يَفِيحَ ٱلنَّهَارُ وَتَنْهَزِمَ ٱلظِّلَالُ، ٱرْجِعْ وَأَشْبِهْ يَا حَبِيبِي ٱلظَّبْيَ أَوْ غُفْرَ ٱلْأَيَائِلِ عَلَى ٱلْجِبَالِ ٱلْمُشَعَّبَةِ.","ại̹lay̱ ạản̊ yafīḥa ٱlnãhāru watan̊hazima ٱlẓĩlālu, ٱr̊jiʿ̊ wāảsẖ̊bih̊ yā ḥabībī ٱlẓãb̊ya ạảẘ gẖuf̊ra ٱl̊ạảyāyỉli ʿalay̱ ٱl̊jibāli ٱl̊musẖaʿãbaẗi."],[3,1,"فِي ٱللَّيْلِ عَلَى فِرَاشِي طَلَبْتُ مَنْ تُحِبُّهُ نَفْسِي. طَلَبْتُهُ فَمَا وَجَدْتُهُ.","fī ٱllãẙli ʿalay̱ firāsẖī ṭalab̊tu man̊ tuḥibũhu naf̊sī. ṭalab̊tuhu famā wajad̊tuhu."],[3,2,"إِنِّي أَقُومُ وَأَطُوفُ فِي ٱلْمَدِينَةِ، فِي ٱلْأَسْوَاقِ وَفِي ٱلشَّوَارِعِ، أَطْلُبُ مَنْ تُحِبُّهُ نَفْسِي. طَلَبْتُهُ فَمَا وَجَدْتُهُ.","ại̹nĩy ạảqūmu wāảṭūfu fī ٱl̊madīnaẗi, fī ٱl̊ạảs̊wāqi wafī ٱlsẖãwāriʿi, ạảṭ̊lubu man̊ tuḥibũhu naf̊sī. ṭalab̊tuhu famā wajad̊tuhu."],[3,3,"وَجَدَنِي ٱلْحَرَسُ ٱلطَّائِفُ فِي ٱلْمَدِينَةِ، فَقُلْتُ: «أَرَأَيْتُمْ مَنْ تُحِبُّهُ نَفْسِي؟»","wajadanī ٱl̊ḥarasu ٱlṭãạyỉfu fī ٱl̊madīnaẗi, faqul̊tu: «ạảrāảẙtum̊ man̊ tuḥibũhu naf̊sī?»"],[3,4,"فَمَا جَاوَزْتُهُمْ إِلَّا قَلِيلًا حَتَّى وَجَدْتُ مَنْ تُحِبُّهُ نَفْسِي، فَأَمْسَكْتُهُ وَلَمْ أَرْخِهِ، حَتَّى أَدْخَلْتُهُ بَيْتَ أُمِّي وَحُجْرَةَ مَنْ حَبِلَتْ بِي.","famā jāwaz̊tuhum̊ ại̹lãạ qalīlaⁿạ ḥatãy̱ wajad̊tu man̊ tuḥibũhu naf̊sī, fāảm̊sak̊tuhu walam̊ ạảr̊kẖihi, ḥatãy̱ ạảd̊kẖal̊tuhu baẙta ạủmĩy waḥuj̊raẗa man̊ ḥabilat̊ bī."],[3,5,"أُحَلِّفُكُنَّ يَا بَنَاتِ أُورُشَلِيمَ بِٱلظِّبَاءِ وَبِأَيَائِلِ ٱلْحَقْلِ، أَلَّا تُيَقِّظْنَ وَلَا تُنَبِّهْنَ ٱلْحَبِيبَ حَتَّى يَشَاءَ.","ạủḥalĩfukunã yā banāti ạủwrusẖalīma biٱlẓĩbāʾi wabiạảyāyỉli ٱl̊ḥaq̊li, ạảlãạ tuyaqĩẓ̊na walā tunabĩh̊na ٱl̊ḥabība ḥatãy̱ yasẖāʾa."],[3,6,"مَنْ هَذِهِ ٱلطَّالِعَةُ مِنَ ٱلْبَرِّيَّةِ كَأَعْمِدَةٍ مِنْ دُخَانٍ، مُعَطَّرَةً بِٱلْمُرِّ وَٱللُّبَانِ وَبِكُلِّ أَذِرَّةِ ٱلتَّاجِرِ؟","man̊ hadẖihi ٱlṭãạliʿaẗu mina ٱl̊barĩyãẗi kāảʿ̊midaẗiⁿ min̊ dukẖāniⁿ, muʿaṭãraẗaⁿ biٱl̊murĩ waٱllũbāni wabikulĩ ạảdẖirãẗi ٱltãạjiri?"],[3,7,"هُوَذَا تَخْتُ سُلَيْمَانَ حَوْلَهُ سِتُّونَ جَبَّارًا مِنْ جَبَابِرَةِ إِسْرَائِيلَ.","hūadẖā takẖ̊tu sulaẙmāna ḥaẘlahu sitũwna jabãạraⁿạ min̊ jabābiraẗi ại̹s̊rāyỉyla."],[3,8,"كُلُّهُمْ قَابِضُونَ سُيُوفًا وَمُتَعَلِّمُونَ ٱلْحَرْبَ. كُلُّ رَجُلٍ سَيْفُهُ عَلَى فَخْذِهِ مِنْ هَوْلِ ٱللَّيْلِ.","kulũhum̊ qābiḍūna suyūfaⁿạ wamutaʿalĩmūna ٱl̊ḥar̊ba. kulũ rajuliⁿ saẙfuhu ʿalay̱ fakẖ̊dẖihi min̊ haẘli ٱllãẙli."],[3,9,"اَلْمَلِكُ سُلَيْمَانُ عَمِلَ لِنَفْسِهِ تَخْتًا مِنْ خَشَبِ لُبْنَانَ.","ạal̊maliku sulaẙmānu ʿamila linaf̊sihi takẖ̊taⁿạ min̊ kẖasẖabi lub̊nāna."],[3,10,"عَمِلَ أَعْمِدَتَهُ فِضَّةً، وَرَوَافِدَهُ ذَهَبًا، وَمَقْعَدَهُ أُرْجُوانًا، وَوَسَطَهُ مَرْصُوفًا مَحَبَّةً مِنْ بَنَاتِ أُورُشَلِيمَ.","ʿamila ạảʿ̊midatahu fiḍãẗaⁿ, warawāfidahu dẖahabaⁿạ, wamaq̊ʿadahu ạủr̊jūạnaⁿạ, wawasaṭahu mar̊ṣūfaⁿạ maḥabãẗaⁿ min̊ banāti ạủwrusẖalīma."],[3,11,"اُخْرُجْنَ يَا بَنَاتِ صِهْيَوْنَ، وَٱنْظُرْنَ ٱلْمَلِكَ سُلَيْمَانَ بِٱلتَّاجِ ٱلَّذِي تَوَّجَتْهُ بِهِ أُمُّهُ فِي يَوْمِ عُرْسِهِ، وَفِي يَوْمِ فَرَحِ قَلْبِهِ.","ạukẖ̊ruj̊na yā banāti ṣih̊yaẘna, waٱn̊ẓur̊na ٱl̊malika sulaẙmāna biٱltãạji ٱlãdẖī tawãjat̊hu bihi ạủmũhu fī yaẘmi ʿur̊sihi, wafī yaẘmi faraḥi qal̊bihi."],[4,1,"هَا أَنْتِ جَمِيلَةٌ يَا حَبِيبَتِي، هَا أَنْتِ جَمِيلَةٌ! عَيْنَاكِ حَمَامَتَانِ مِنْ تَحْتِ نَقَابِكِ. شَعْرُكِ كَقَطِيعِ مِعْزٍ رَابِضٍ عَلَى جَبَلِ جِلْعَادَ.","hā ạản̊ti jamīlaẗuⁿ yā ḥabībatī, hā ạản̊ti jamīlaẗuⁿ! ʿaẙnāki ḥamāmatāni min̊ taḥ̊ti naqābiki. sẖaʿ̊ruki kaqaṭīʿi miʿ̊ziⁿ rābiḍiⁿ ʿalay̱ jabali jil̊ʿāda."],[4,2,"أَسْنَانُكِ كَقَطِيعِ ٱلْجَزَائِزِ ٱلصَّادِرَةِ مِنَ ٱلْغَسْلِ، ٱللَّوَاتِي كُلُّ وَاحِدَةٍ مُتْئِمٌ، وَلَيْسَ فِيهِنَّ عَقِيمٌ.","ạảs̊nānuki kaqaṭīʿi ٱl̊jazāyỉzi ٱlṣãạdiraẗi mina ٱl̊gẖas̊li, ٱllãwātī kulũ wāḥidaẗiⁿ mut̊yỉmuⁿ, walaẙsa fīhinã ʿaqīmuⁿ."],[4,3,"شَفَتَاكِ كَسِلْكَةٍ مِنَ ٱلْقِرْمِزِ، وَفَمُكِ حُلْوٌ. خَدُّكِ كَفِلْقَةِ رُمَّانَةٍ تَحْتَ نَقَابِكِ.","sẖafatāki kasil̊kaẗiⁿ mina ٱl̊qir̊mizi, wafamuki ḥul̊wuⁿ. kẖadũki kafil̊qaẗi rumãạnaẗiⁿ taḥ̊ta naqābiki."],[4,4,"عُنُقُكِ كَبُرْجِ دَاوُدَ ٱلْمَبْنِيِّ لِلْأَسْلِحَةِ. أَلْفُ مِجَنٍّ عُلِّقَ عَلَيْهِ، كُلُّهَا أَتْرَاسُ ٱلْجَبَابِرَةِ.","ʿunuquki kabur̊ji dāwuda ٱl̊mab̊nīĩ lil̊ạảs̊liḥaẗi. ạảl̊fu mijaniⁿ̃ ʿulĩqa ʿalaẙhi, kulũhā ạảt̊rāsu ٱl̊jabābiraẗi."],[4,5,"ثَدْيَاكِ كَخِشْفَتَيْ ظَبْيَةٍ، تَوْأَمَيْنِ يَرْعَيَانِ بَيْنَ ٱلسَّوْسَنِ.","tẖad̊yāki kakẖisẖ̊fataẙ ẓab̊yaẗiⁿ, taẘạảmaẙni yar̊ʿayāni baẙna ٱlsãẘsani."],[4,6,"إِلَى أَنْ يَفِيحَ ٱلنَّهَارُ وَتَنْهَزِمَ ٱلظِّلَالُ، أَذْهَبُ إِلَى جَبَلِ ٱلْمُرِّ وَإِلَى تَلِّ ٱللُّبَانِ.","ại̹lay̱ ạản̊ yafīḥa ٱlnãhāru watan̊hazima ٱlẓĩlālu, ạảdẖ̊habu ại̹lay̱ jabali ٱl̊murĩ wāi̹lay̱ talĩ ٱllũbāni."],[4,7,"كُلُّكِ جَمِيلٌ يَا حَبِيبَتِي لَيْسَ فِيكِ عَيْبَةٌ.","kulũki jamīluⁿ yā ḥabībatī laẙsa fīki ʿaẙbaẗuⁿ."],[4,8,"هَلُمِّي مَعِي مِنْ لُبْنَانَ يَا عَرُوسُ، مَعِي مِنْ لُبْنَانَ! ٱنْظُرِي مِنْ رَأْسِ أَمَانَةَ، مِنْ رَأْسِ شَنِيرَ وَحَرْمُونَ، مِنْ خُدُورِ ٱلْأُسُودِ، مِنْ جِبَالِ ٱلنُّمُورِ.","halumĩy maʿī min̊ lub̊nāna yā ʿarūsu, maʿī min̊ lub̊nāna! ٱn̊ẓurī min̊ rā̊̉si ạảmānaẗa, min̊ rā̊̉si sẖanīra waḥar̊mūna, min̊ kẖudūri ٱl̊ạủsūdi, min̊ jibāli ٱlnũmūri."],[4,9,"قَدْ سَبَيْتِ قَلْبِي يَا أُخْتِي ٱلْعَرُوسُ. قَدْ سَبَيْتِ قَلْبِي بِإِحْدَى عَيْنَيْكِ، بِقَلَادَةٍ وَاحِدَةٍ مِنْ عُنُقِكِ.","qad̊ sabaẙti qal̊bī yā ạủkẖ̊tī ٱl̊ʿarūsu. qad̊ sabaẙti qal̊bī biại̹ḥ̊day̱ ʿaẙnaẙki, biqalādaẗiⁿ wāḥidaẗiⁿ min̊ ʿunuqiki."],[4,10,"مَا أَحْسَنَ حُبَّكِ يَا أُخْتِي ٱلْعَرُوسُ! كَمْ مَحَبَّتُكِ أَطْيَبُ مِنَ ٱلْخَمْرِ! وَكَمْ رَائِحَةُ أَدْهَانِكِ أَطْيَبُ مِنْ كُلِّ ٱلْأَطْيَابِ!","mā ạảḥ̊sana ḥubãki yā ạủkẖ̊tī ٱl̊ʿarūsu! kam̊ maḥabãtuki ạảṭ̊yabu mina ٱl̊kẖam̊ri! wakam̊ rāyỉḥaẗu ạảd̊hāniki ạảṭ̊yabu min̊ kulĩ ٱl̊ạảṭ̊yābi!"],[4,11,"شَفَتَاكِ يَا عَرُوسُ تَقْطُرَانِ شَهْدًا. تَحْتَ لِسَانِكِ عَسَلٌ وَلَبَنٌ، وَرَائِحَةُ ثِيَابِكِ كَرَائِحَةِ لُبْنَانَ.","sẖafatāki yā ʿarūsu taq̊ṭurāni sẖah̊daⁿạ. taḥ̊ta lisāniki ʿasaluⁿ walabanuⁿ, warāyỉḥaẗu tẖīābiki karāyỉḥaẗi lub̊nāna."],[4,12,"أُخْتِي ٱلْعَرُوسُ جَنَّةٌ مُغْلَقَةٌ، عَيْنٌ مُقْفَلَةٌ، يَنْبُوعٌ مَخْتُومٌ.","ạủkẖ̊tī ٱl̊ʿarūsu janãẗuⁿ mugẖ̊laqaẗuⁿ, ʿaẙnuⁿ muq̊falaẗuⁿ, yan̊būʿuⁿ makẖ̊tūmuⁿ."],[4,13,"أَغْرَاسُكِ فِرْدَوْسُ رُمَّانٍ مَعَ أَثْمَارٍ نَفِيسَةٍ، فَاغِيَةٍ وَنَارِدِينٍ.","ạảgẖ̊rāsuki fir̊daẘsu rumãạniⁿ maʿa ạảtẖ̊māriⁿ nafīsaẗiⁿ, fāgẖīaẗiⁿ wanāridīniⁿ."],[4,14,"نَارِدِينٍ وَكُرْكُمٍ. قَصَبِ ٱلذَّرِيرَةِ وَقِرْفَةٍ، مَعَ كُلِّ عُودِ ٱللُّبَانِ. مُرٌّ وَعُودٌ مَعَ كُلِّ أَنْفَسِ ٱلْأَطْيَابِ.","nāridīniⁿ wakur̊kumiⁿ. qaṣabi ٱldẖãrīraẗi waqir̊faẗiⁿ, maʿa kulĩ ʿūdi ٱllũbāni. muruⁿ̃ waʿūduⁿ maʿa kulĩ ạản̊fasi ٱl̊ạảṭ̊yābi."],[4,15,"يَنْبُوعُ جَنَّاتٍ، بِئْرُ مِيَاهٍ حَيَّةٍ، وَسُيُولٌ مِنْ لُبْنَانَ.","yan̊būʿu janãạtiⁿ, bī̊̉ru mīāhiⁿ ḥayãẗiⁿ, wasuyūluⁿ min̊ lub̊nāna."],[4,16,"اِسْتَيْقِظِي يَا رِيحَ ٱلشَّمَالِ، وَتَعَالَيْ يَا رِيحَ ٱلْجَنُوبِ! هَبِّي عَلَى جَنَّتِي فَتَقْطُرَ أَطْيَابُهَا. لِيَأْتِ حَبِيبِي إِلَى جَنَّتِهِ وَيَأْكُلْ ثَمَرَهُ ٱلنَّفِيسَ.","ạis̊taẙqiẓī yā rīḥa ٱlsẖãmāli, wataʿālaẙ yā rīḥa ٱl̊janūbi! habĩy ʿalay̱ janãtī fataq̊ṭura ạảṭ̊yābuhā. līā̊̉ti ḥabībī ại̹lay̱ janãtihi wayā̊̉kul̊ tẖamarahu ٱlnãfīsa."],[5,1,"قَدْ دَخَلْتُ جَنَّتِي يَا أُخْتِي ٱلْعَرُوسُ. قَطَفْتُ مُرِّي مَعَ طِيبِي. أَكَلْتُ شَهْدِي مَعَ عَسَلِي. شَرِبْتُ خَمْرِي مَعَ لَبَنِي. كُلُوا أَيُّهَا ٱلْأَصْحَابُ. ٱشْرَبُوا وَٱسْكَرُوا أَيُّهَا ٱلْأَحِبَّاءُ.","qad̊ dakẖal̊tu janãtī yā ạủkẖ̊tī ٱl̊ʿarūsu. qaṭaf̊tu murĩy maʿa ṭībī. ạảkal̊tu sẖah̊dī maʿa ʿasalī. sẖarib̊tu kẖam̊rī maʿa labanī. kulūạ ạảyũhā ٱl̊ạảṣ̊ḥābu. ٱsẖ̊rabūạ waٱs̊karūạ ạảyũhā ٱl̊ạảḥibãạʾu."],[5,2,"أَنَا نَائِمَةٌ وَقَلْبِي مُسْتَيْقِظٌ. صَوْتُ حَبِيبِي قَارِعًا: «اِفْتَحِي لِي يَا أُخْتِي، يَا حَبِيبَتِي، يَاحَمَامَتِي، يَا كَامِلَتِي! لِأَنَّ رَأْسِي ٱمْتَلَأَ مِنَ ٱلطَّلِّ، وَقُصَصِي مِنْ نُدَى ٱللَّيْلِ».","ạảnā nāyỉmaẗuⁿ waqal̊bī mus̊taẙqiẓuⁿ. ṣaẘtu ḥabībī qāriʿaⁿạ: «ạif̊taḥī lī yā ạủkẖ̊tī, yā ḥabībatī, yāḥamāmatī, yā kāmilatī! liạảnã rā̊̉sī ٱm̊talāả mina ٱlṭãlĩ, waquṣaṣī min̊ nuday̱ ٱllãẙli»."],[5,3,"قَدْ خَلَعْتُ ثَوْبِي، فَكَيْفَ أَلْبَسُهُ؟ قَدْ غَسَلْتُ رِجْلَيَّ، فَكَيْفَ أُوَسِّخُهُمَا؟","qad̊ kẖalaʿ̊tu tẖaẘbī, fakaẙfa ạảl̊basuhu? qad̊ gẖasal̊tu rij̊layã, fakaẙfa ạủwasĩkẖuhumā?"],[5,4,"حَبِيبِي مَدَّ يَدَهُ مِنَ ٱلْكَوَّةِ، فَأَنَّتْ عَلَيْهِ أَحْشَائِي.","ḥabībī madã yadahu mina ٱl̊kawãẗi, fāảnãt̊ ʿalaẙhi ạảḥ̊sẖāyỉy."],[5,5,"قُمْتُ لِأَفْتَحَ لِحَبِيبِي وَيَدَايَ تَقْطُرَانِ مُرًّا، وَأَصَابِعِي مُرٌّ قَاطِرٌ عَلَى مَقْبَضِ ٱلْقُفْلِ.","qum̊tu liạảf̊taḥa liḥabībī wayadāya taq̊ṭurāni muraⁿ̃ạ, wāảṣābiʿī muruⁿ̃ qāṭiruⁿ ʿalay̱ maq̊baḍi ٱl̊quf̊li."],[5,6,"فَتَحْتُ لِحَبِيبِي، لَكِنَّ حَبِيبِي تَحَوَّلَ وَعَبَرَ. نَفْسِي خَرَجَتْ عِنْدَمَا أَدْبَرَ. طَلَبْتُهُ فَمَا وَجَدْتُهُ. دَعَوْتُهُ فَمَا أَجَابَنِي.","fataḥ̊tu liḥabībī, lakinã ḥabībī taḥawãla waʿabara. naf̊sī kẖarajat̊ ʿin̊damā ạảd̊bara. ṭalab̊tuhu famā wajad̊tuhu. daʿaẘtuhu famā ạảjābanī."],[5,7,"وَجَدَنِي ٱلْحَرَسُ ٱلطَّائِفُ فِي ٱلْمَدِينَةِ. ضَرَبُونِي. جَرَحُونِي. حَفَظَةُ ٱلْأَسْوَارِ رَفَعُوا إِزَارِي عَنِّي.","wajadanī ٱl̊ḥarasu ٱlṭãạyỉfu fī ٱl̊madīnaẗi. ḍarabūnī. jaraḥūnī. ḥafaẓaẗu ٱl̊ạảs̊wāri rafaʿūạ ại̹zārī ʿanĩy."],[5,8,"أُحَلِّفُكُنَّ يَا بَنَاتِ أُورُشَلِيمَ إِنْ وَجَدْتُنَّ حَبِيبِي أَنْ تُخْبِرْنَهُ بِأَنِّي مَرِيضَةٌ حُبًّا.","ạủḥalĩfukunã yā banāti ạủwrusẖalīma ại̹n̊ wajad̊tunã ḥabībī ạản̊ tukẖ̊bir̊nahu biạảnĩy marīḍaẗuⁿ ḥubaⁿ̃ạ."],[5,9,"مَا حَبِيبُكِ مِنْ حَبِيبٍ أَيَّتُهَا ٱلْجَمِيلَةُ بَيْنَ ٱلنِّسَاءِ! مَا حَبِيبُكِ مِنْ حَبِيبٍ حَتَّى تُحَلِّفِينَا هَكَذَا!","mā ḥabībuki min̊ ḥabībiⁿ ạảyãtuhā ٱl̊jamīlaẗu baẙna ٱlnĩsāʾi! mā ḥabībuki min̊ ḥabībiⁿ ḥatãy̱ tuḥalĩfīnā hakadẖā!"],[5,10,"حَبِيبِي أَبْيَضُ وَأَحْمَرُ. مُعْلَمٌ بَيْنَ رَبْوَةٍ.","ḥabībī ạảb̊yaḍu wāảḥ̊maru. muʿ̊lamuⁿ baẙna rab̊waẗiⁿ."],[5,11,"رَأْسُهُ ذَهَبٌ إِبْرِيزٌ. قُصَصُهُ مُسْتَرْسِلَةٌ حَالِكَةٌ كَٱلْغُرَابِ.","rā̊̉suhu dẖahabuⁿ ại̹b̊rīzuⁿ. quṣaṣuhu mus̊tar̊silaẗuⁿ ḥālikaẗuⁿ kaٱl̊gẖurābi."],[5,12,"عَيْنَاهُ كَٱلْحَمَامِ عَلَى مَجَارِي ٱلْمِيَاهِ، مَغْسُولَتَانِ بِٱللَّبَنِ، جَالِسَتَانِ فِي وَقْبَيْهِمَا.","ʿaẙnāhu kaٱl̊ḥamāmi ʿalay̱ majārī ٱl̊mīāhi, magẖ̊sūlatāni biٱllãbani, jālisatāni fī waq̊baẙhimā."],[5,13,"خَدَّاهُ كَخَمِيلَةِ ٱلطِّيبِ وَأَتْلَامِ رَيَاحِينَ ذَكِيَّةٍ. شَفَتَاهُ سُوْسَنٌ تَقْطُرَانِ مُرًّا مَائِعًا.","kẖadãạhu kakẖamīlaẗi ٱlṭĩybi wāảt̊lāmi rayāḥīna dẖakīãẗiⁿ. sẖafatāhu sū̊sanuⁿ taq̊ṭurāni muraⁿ̃ạ māyỉʿaⁿạ."],[5,14,"يَدَاهُ حَلْقَتَانِ مِنْ ذَهَبٍ، مُرَصَّعَتَانِ بِٱلزَّبَرْجَدِ. بَطْنُهُ عَاجٌ أَبْيَضُ مُغَلَّفٌ بِٱلْيَاقُوتِ ٱلْأَزْرَقِ.","yadāhu ḥal̊qatāni min̊ dẖahabiⁿ, muraṣãʿatāni biٱlzãbar̊jadi. baṭ̊nuhu ʿājuⁿ ạảb̊yaḍu mugẖalãfuⁿ biٱl̊yāqūti ٱl̊ạảz̊raqi."],[5,15,"سَاقَاهُ عَمُودَا رُخَامٍ، مُؤَسَّسَتَانِ عَلَى قَاعِدَتَيْنِ مِنْ إِبْرِيزٍ. طَلْعَتُهُ كَلُبْنَانَ. فَتًى كَٱلْأَرْزِ.","sāqāhu ʿamūdā rukẖāmiⁿ, mūảsãsatāni ʿalay̱ qāʿidataẙni min̊ ại̹b̊rīziⁿ. ṭal̊ʿatuhu kalub̊nāna. fataⁿy̱ kaٱl̊ạảr̊zi."],[5,16,"حَلْقُهُ حَلَاوَةٌ وَكُلُّهُ مُشْتَهَيَاتٌ. هَذَا حَبِيبِي، وَهَذَا خَلِيلِي، يَا بَنَاتِ أُورُشَلِيمَ.","ḥal̊quhu ḥalāwaẗuⁿ wakulũhu musẖ̊tahayātuⁿ. hadẖā ḥabībī, wahadẖā kẖalīlī, yā banāti ạủwrusẖalīma."],[6,1,"أَيْنَ ذَهَبَ حَبِيبُكِ أَيَّتُهَا ٱلْجَمِيلَةُ بَيْنَ ٱلنِّسَاءِ؟ أَيْنَ تَوَجَّهَ حَبِيبُكِ فَنَطْلُبَهُ مَعَكِ؟","ạảẙna dẖahaba ḥabībuki ạảyãtuhā ٱl̊jamīlaẗu baẙna ٱlnĩsāʾi? ạảẙna tawajãha ḥabībuki fanaṭ̊lubahu maʿaki?"],[6,2,"حَبِيبِي نَزَلَ إِلَى جَنَّتِهِ، إِلَى خَمَائِلِ ٱلطِّيبِ، لِيَرْعَى فِي ٱلْجَنَّاتِ، وَيَجْمَعَ ٱلسَّوْسَنَ.","ḥabībī nazala ại̹lay̱ janãtihi, ại̹lay̱ kẖamāyỉli ٱlṭĩybi, līar̊ʿay̱ fī ٱl̊janãạti, wayaj̊maʿa ٱlsãẘsana."],[6,3,"أَنَا لِحَبِيبِي وَحَبِيبِي لِي. ٱلرَّاعِي بَيْنَ ٱلسَّوْسَنِ.","ạảnā liḥabībī waḥabībī lī. ٱlrãạʿī baẙna ٱlsãẘsani."],[6,4,"أَنْتِ جَمِيلَةٌ يَا حَبِيبَتِي كَتِرْصَةَ، حَسَنَةٌ كَأُورُشَلِيمَ، مُرْهِبَةٌ كَجَيْشٍ بِأَلْوِيَةٍ.","ạản̊ti jamīlaẗuⁿ yā ḥabībatī katir̊ṣaẗa, ḥasanaẗuⁿ kāủwrusẖalīma, mur̊hibaẗuⁿ kajaẙsẖiⁿ biạảl̊wīaẗiⁿ."],[6,5,"حَوِّلِي عَنِّي عَيْنَيْكِ فَإِنَّهُمَا قَدْ غَلَبَتَانِي. شَعْرُكِ كَقَطِيعِ ٱلْمَعْزِ ٱلرَّابِضِ فِي جِلْعَادَ.","ḥawĩlī ʿanĩy ʿaẙnaẙki fāi̹nãhumā qad̊ gẖalabatānī. sẖaʿ̊ruki kaqaṭīʿi ٱl̊maʿ̊zi ٱlrãạbiḍi fī jil̊ʿāda."],[6,6,"أَسْنَانُكِ كَقَطِيعِ نِعَاجٍ صَادِرةٍ مِنَ ٱلْغَسْلِ، ٱللَّوَاتِي كُلُّ وَاحِدَةٍ مُتْئِمٌ وَلَيْسَ فِيهَا عَقِيمٌ.","ạảs̊nānuki kaqaṭīʿi niʿājiⁿ ṣādirẗiⁿ mina ٱl̊gẖas̊li, ٱllãwātī kulũ wāḥidaẗiⁿ mut̊yỉmuⁿ walaẙsa fīhā ʿaqīmuⁿ."],[6,7,"كَفِلْقَةِ رُمَّانَةٍ خَدُّكِ تَحْتَ نَقَابِكِ.","kafil̊qaẗi rumãạnaẗiⁿ kẖadũki taḥ̊ta naqābiki."],[6,8,"هُنَّ سِتُّونَ مَلِكَةً وَثَمَانُونَ سُرِّيَّةً وَعَذَارَى بِلَا عَدَدٍ.","hunã sitũwna malikaẗaⁿ watẖamānūna surĩyãẗaⁿ waʿadẖāray̱ bilā ʿadadiⁿ."],[6,9,"وَاحِدَةٌ هِيَ حَمَامَتِي كَامِلَتِي. ٱلْوَحِيدَةُ لِأُمِّهَا هِيَ. عَقِيلَةُ وَالِدَتِهَا هِيَ. رَأَتْهَا ٱلْبَنَاتُ فَطَوَّبْنَهَا. ٱلْمَلِكَاتُ وَٱلسَّرَارِيُّ فَمَدَحْنَهَا.","wāḥidaẗuⁿ hīa ḥamāmatī kāmilatī. ٱl̊waḥīdaẗu liạủmĩhā hīa. ʿaqīlaẗu wālidatihā hīa. rāảt̊hā ٱl̊banātu faṭawãb̊nahā. ٱl̊malikātu waٱlsãrārīũ famadaḥ̊nahā."],[6,10,"مَنْ هِيَ ٱلْمُشْرِفَةُ مِثْلَ ٱلصَّبَاحِ، جَمِيلَةٌ كَٱلْقَمَرِ، طَاهِرَةٌ كَٱلشَّمْسِ، مُرْهِبَةٌ كَجَيْشٍ بِأَلْوِيَةٍ؟","man̊ hīa ٱl̊musẖ̊rifaẗu mitẖ̊la ٱlṣãbāḥi, jamīlaẗuⁿ kaٱl̊qamari, ṭāhiraẗuⁿ kaٱlsẖãm̊si, mur̊hibaẗuⁿ kajaẙsẖiⁿ biạảl̊wīaẗiⁿ?"],[6,11,"نَزَلْتُ إِلَى جَنَّةِ ٱلْجَوْزِ لِأَنْظُرَ إِلَى خُضَرِ ٱلْوَادِي، وَلِأَنْظُرَ: هَلْ أَقْعَلَ ٱلْكَرْمُ؟ هَلْ نَوَّرَ ٱلرُّمَّانُ؟","nazal̊tu ại̹lay̱ janãẗi ٱl̊jaẘzi liạản̊ẓura ại̹lay̱ kẖuḍari ٱl̊wādī, waliạản̊ẓura: hal̊ ạảq̊ʿala ٱl̊kar̊mu? hal̊ nawãra ٱlrũmãạnu?"],[6,12,"فَلَمْ أَشْعُرْ إِلَّا وَقَدْ جَعَلَتْنِي نَفْسِي بَيْنَ مَرْكَبَاتِ قَوْمِ شَرِيفٍ.","falam̊ ạảsẖ̊ʿur̊ ại̹lãạ waqad̊ jaʿalat̊nī naf̊sī baẙna mar̊kabāti qaẘmi sẖarīfiⁿ."],[6,13,"اِرْجِعِي، ٱرْجِعِي يَا شُولَمِّيثُ. ٱرْجِعِي، ٱرْجِعِي فَنَنْظُرَ إِلَيْكِ. مَاذَا تَرَوْنَ فِي شُولَمِّيثَ، مِثْلَ رَقْصِ صَفَّيْنِ؟","ạir̊jiʿī, ٱr̊jiʿī yā sẖūlamĩytẖu. ٱr̊jiʿī, ٱr̊jiʿī fanan̊ẓura ại̹laẙki. mādẖā taraẘna fī sẖūlamĩytẖa, mitẖ̊la raq̊ṣi ṣafãẙni?"],[7,1,"مَا أَجْمَلَ رِجْلَيْكِ بِٱلنَّعْلَيْنِ يَا بِنْتَ ٱلْكَرِيمِ! دَوَائِرُ فَخْذَيْكِ مِثْلُ ٱلْحَلِيِّ، صَنْعَةِ يَدَيْ صَنَّاعٍ.","mā ạảj̊mala rij̊laẙki biٱlnãʿ̊laẙni yā bin̊ta ٱl̊karīmi! dawāyỉru fakẖ̊dẖaẙki mitẖ̊lu ٱl̊ḥalīĩ, ṣan̊ʿaẗi yadaẙ ṣanãạʿiⁿ."],[7,2,"سُرَّتُكِ كَأْسٌ مُدَوَّرَةٌ، لَا يُعْوِزُهَا شَرَابٌ مَمْزُوجٌ. بَطْنُكِ صُبْرَةُ حِنْطَةٍ مُسَيَّجَةٌ بِٱلسَّوْسَنِ.","surãtuki kā̊̉suⁿ mudawãraẗuⁿ, lā yuʿ̊wizuhā sẖarābuⁿ mam̊zūjuⁿ. baṭ̊nuki ṣub̊raẗu ḥin̊ṭaẗiⁿ musayãjaẗuⁿ biٱlsãẘsani."],[7,3,"ثَدْيَاكِ كَخَشْفَتَيْنِ، تَوْأَمَيْ ظَبْيَةٍ.","tẖad̊yāki kakẖasẖ̊fataẙni, taẘạảmaẙ ẓab̊yaẗiⁿ."],[7,4,"عُنُقُكِ كَبُرْجٍ مِنْ عَاجٍ. عَيْنَاكِ كَٱلْبِرَكِ فِي حَشْبُونَ عِنْدَ بَابِ بَثِّ رَبِّيمَ. أَنْفُكِ كَبُرْجِ لُبْنَانَ ٱلنَّاظِرِ تُجَاهَ دِمَشْقَ.","ʿunuquki kabur̊jiⁿ min̊ ʿājiⁿ. ʿaẙnāki kaٱl̊biraki fī ḥasẖ̊būna ʿin̊da bābi batẖĩ rabĩyma. ạản̊fuki kabur̊ji lub̊nāna ٱlnãạẓiri tujāha dimasẖ̊qa."],[7,5,"رَأْسُكِ عَلَيْكِ مِثْلُ ٱلْكَرْمَلِ، وَشَعْرُ رَأْسِكِ كَأُرْجُوَانٍ. مَلِكٌ قَدْ أُسِرَ بِٱلْخُصَلِ.","rā̊̉suki ʿalaẙki mitẖ̊lu ٱl̊kar̊mali, wasẖaʿ̊ru rā̊̉siki kāủr̊jūāniⁿ. malikuⁿ qad̊ ạủsira biٱl̊kẖuṣali."],[7,6,"مَا أَجْمَلَكِ وَمَا أَحْلَاكِ أَيَّتُهَا ٱلْحَبِيبَةُ بِٱللَّذَّاتِ!","mā ạảj̊malaki wamā ạảḥ̊lāki ạảyãtuhā ٱl̊ḥabībaẗu biٱllãdẖãạti!"],[7,7,"قَامَتُكِ هَذِهِ شَبِيهَةٌ بِٱلنَّخْلَةِ، وَثَدْيَاكِ بِٱلْعَنَاقِيدِ.","qāmatuki hadẖihi sẖabīhaẗuⁿ biٱlnãkẖ̊laẗi, watẖad̊yāki biٱl̊ʿanāqīdi."],[7,8,"قُلْتُ: «إِنِّي أَصْعَدُ إِلَى ٱلنَّخْلَةِ وَأُمْسِكُ بِعُذُوقِهَا». وَتَكُونُ ثَدْيَاكِ كَعَنَاقِيدِ ٱلْكَرْمِ، وَرَائِحَةُ أَنْفِكِ كَٱلتُّفَّاحِ،","qul̊tu: «ại̹nĩy ạảṣ̊ʿadu ại̹lay̱ ٱlnãkẖ̊laẗi wāủm̊siku biʿudẖūqihā». watakūnu tẖad̊yāki kaʿanāqīdi ٱl̊kar̊mi, warāyỉḥaẗu ạản̊fiki kaٱltũfãạḥi,"],[7,9,"وَحَنَكُكِ كَأَجْوَدِ ٱلْخَمْرِ. لِحَبِيبِي ٱلسَّائِغَةُ ٱلْمُرَقْرِقَةُ ٱلسَّائِحَةُ عَلَى شِفَاهِ ٱلنَّائِمِينَ.","waḥanakuki kāảj̊wadi ٱl̊kẖam̊ri. liḥabībī ٱlsãạyỉgẖaẗu ٱl̊muraq̊riqaẗu ٱlsãạyỉḥaẗu ʿalay̱ sẖifāhi ٱlnãạyỉmīna."],[7,10,"أَنَا لِحَبِيبِي، وَإِلَيَّ ٱشْتِيَاقُهُ.","ạảnā liḥabībī, wāi̹layã ٱsẖ̊tīāquhu."],[7,11,"تَعَالَ يَاحَبِيبِي لِنَخْرُجْ إِلَى ٱلْحَقْلِ، وَلْنَبِتْ فِي ٱلْقُرَى.","taʿāla yāḥabībī linakẖ̊ruj̊ ại̹lay̱ ٱl̊ḥaq̊li, wal̊nabit̊ fī ٱl̊quray̱."],[7,12,"لِنُبَكِّرَنَّ إِلَى ٱلْكُرُومِ، لِنَنْظُرَ: هَلْ أَزْهَرَ ٱلْكَرْمُ؟ هَلْ تَفَتَّحَ ٱلْقُعَالُ؟ هَلْ نَوَّرَ ٱلرُّمَّانُ؟ هُنَالِكَ أُعْطِيكَ حُبِّي.","linubakĩranã ại̹lay̱ ٱl̊kurūmi, linan̊ẓura: hal̊ ạảz̊hara ٱl̊kar̊mu? hal̊ tafatãḥa ٱl̊quʿālu? hal̊ nawãra ٱlrũmãạnu? hunālika ạủʿ̊ṭīka ḥubĩy."],[7,13,"اَللُّفَّاحُ يَفُوحُ رَائِحَةً، وَعِنْدَ أَبْوَابِنَا كُلُّ ٱلنَّفَائِسِ مِنْ جَدِيدَةٍ وَقَدِيمَةٍ، ذَخَرْتُهَا لَكَ يَاحَبِيبِي.","ạallũfãạḥu yafūḥu rāyỉḥaẗaⁿ, waʿin̊da ạảb̊wābinā kulũ ٱlnãfāyỉsi min̊ jadīdaẗiⁿ waqadīmaẗiⁿ, dẖakẖar̊tuhā laka yāḥabībī."],[8,1,"لَيْتَكَ كَأَخٍ لِي ٱلرَّاضِعِ ثَدْيَيْ أُمِّي، فَأَجِدَكَ فِي ٱلْخَارِجِ وَأُقَبِّلَكَ وَلَا يُخْزُونَنِي.","laẙtaka kāảkẖiⁿ lī ٱlrãạḍiʿi tẖad̊yaẙ ạủmĩy, fāảjidaka fī ٱl̊kẖāriji wāủqabĩlaka walā yukẖ̊zūnanī."],[8,2,"وَأَقُودُكَ وَأَدْخُلُ بِكَ بَيْتَ أُمِّي، وَهِيَ تُعَلِّمُنِي، فَأَسْقِيكَ مِنَ ٱلْخَمْرِ ٱلْمَمْزُوجَةِ مِنْ سُلَافِ رُمَّانِي.","wāảqūduka wāảd̊kẖulu bika baẙta ạủmĩy, wahīa tuʿalĩmunī, fāảs̊qīka mina ٱl̊kẖam̊ri ٱl̊mam̊zūjaẗi min̊ sulāfi rumãạnī."],[8,3,"شِمَالُهُ تَحْتَ رَأْسِي، وَيَمِينُهُ تُعَانِقُنِي.","sẖimāluhu taḥ̊ta rā̊̉sī, wayamīnuhu tuʿāniqunī."],[8,4,"أُحَلِّفُكُنَّ يَا بَنَاتِ أُورُشَلِيمَ أَلَّا تُيَقِّظْنَ وَلَا تُنَبِّهْنَ ٱلْحَبِيبَ حَتَّى يَشَاءَ.","ạủḥalĩfukunã yā banāti ạủwrusẖalīma ạảlãạ tuyaqĩẓ̊na walā tunabĩh̊na ٱl̊ḥabība ḥatãy̱ yasẖāʾa."],[8,5,"مَنْ هَذِهِ ٱلطَّالِعَةُ مِنَ ٱلْبَرِّيَّةِ مُسْتَنِدَةً عَلَى حَبِيبِهَا؟ تَحْتَ شَجَرَةِ ٱلتُّفَّاحِ شَوَّقْتُكَ، هُنَاكَ خَطَبَتْ لَكَ أُمُّكَ، هُنَاكَ خَطَبَتْ لَكَ وَالِدَتُكَ.","man̊ hadẖihi ٱlṭãạliʿaẗu mina ٱl̊barĩyãẗi mus̊tanidaẗaⁿ ʿalay̱ ḥabībihā? taḥ̊ta sẖajaraẗi ٱltũfãạḥi sẖawãq̊tuka, hunāka kẖaṭabat̊ laka ạủmũka, hunāka kẖaṭabat̊ laka wālidatuka."],[8,6,"اِجْعَلْنِي كَخَاتِمٍ عَلَى قَلْبِكَ، كَخَاتِمٍ عَلَى سَاعِدِكَ. لِأَنَّ ٱلْمَحَبَّةَ قَوِيَّةٌ كَٱلْمَوْتِ. ٱلْغَيْرَةُ قَاسِيَةٌ كَٱلْهَاوِيَةِ. لَهِيبُهَا لَهِيبُ نَارِ لَظَى ٱلرَّبِّ.","ạij̊ʿal̊nī kakẖātimiⁿ ʿalay̱ qal̊bika, kakẖātimiⁿ ʿalay̱ sāʿidika. liạảnã ٱl̊maḥabãẗa qawīãẗuⁿ kaٱl̊maẘti. ٱl̊gẖaẙraẗu qāsīaẗuⁿ kaٱl̊hāwīaẗi. lahībuhā lahību nāri laẓay̱ ٱlrãbĩ."],[8,7,"مِيَاهٌ كَثِيرَةٌ لَا تَسْتَطِيعُ أَنْ تُطْفِئَ ٱلْمَحَبَّةَ، وَٱلسُّيُولُ لَا تَغْمُرُهَا. إِنْ أَعْطَى ٱلْإِنْسَانُ كُلَّ ثَرْوَةِ بَيْتِهِ بَدَلَ ٱلْمَحَبَّةِ، تُحْتَقَرُ ٱحْتِقَارًا.","mīāhuⁿ katẖīraẗuⁿ lā tas̊taṭīʿu ạản̊ tuṭ̊fīả ٱl̊maḥabãẗa, waٱlsũyūlu lā tagẖ̊muruhā. ại̹n̊ ạảʿ̊ṭay̱ ٱl̊ại̹n̊sānu kulã tẖar̊waẗi baẙtihi badala ٱl̊maḥabãẗi, tuḥ̊taqaru ٱḥ̊tiqāraⁿạ."],[8,8,"لَنَا أُخْتٌ صَغِيرَةٌ لَيْسَ لَهَا ثَدْيَانِ. فَمَاذَا نَصْنَعُ لِأُخْتِنَا فِي يَوْمٍ تُخْطَبُ؟","lanā ạủkẖ̊tuⁿ ṣagẖīraẗuⁿ laẙsa lahā tẖad̊yāni. famādẖā naṣ̊naʿu liạủkẖ̊tinā fī yaẘmiⁿ tukẖ̊ṭabu?"],[8,9,"إِنْ تَكُنْ سُورًا فَنَبْنِي عَلَيْهَا بُرْجَ فِضَّةٍ. وَإِنْ تَكُنْ بَابًا فَنَحْصُرُهَا بِأَلْوَاحِ أَرْزٍ.","ại̹n̊ takun̊ sūraⁿạ fanab̊nī ʿalaẙhā bur̊ja fiḍãẗiⁿ. wāi̹n̊ takun̊ bābaⁿạ fanaḥ̊ṣuruhā biạảl̊wāḥi ạảr̊ziⁿ."],[8,10,"أَنَا سُورٌ وَثَدْيَايَ كَبُرْجَيْنِ. حِينَئِذٍ كُنْتُ فِي عَيْنَيْهِ كَوَاجِدَةٍ سَلَامَةً.","ạảnā sūruⁿ watẖad̊yāya kabur̊jaẙni. ḥīnayỉdẖiⁿ kun̊tu fī ʿaẙnaẙhi kawājidaẗiⁿ salāmaẗaⁿ."],[8,11,"كَانَ لِسُلَيْمَانَ كَرْمٌ فِي بَعْلَ هَامُونَ. دَفَعَ ٱلْكَرْمَ إِلَى نَوَاطِيرَ، كُلُّ وَاحِدٍ يُؤَدِّي عَنْ ثَمَرِهِ أَلْفًا مِنَ ٱلْفِضَّةِ.","kāna lisulaẙmāna kar̊muⁿ fī baʿ̊la hāmūna. dafaʿa ٱl̊kar̊ma ại̹lay̱ nawāṭīra, kulũ wāḥidiⁿ yūảdĩy ʿan̊ tẖamarihi ạảl̊faⁿạ mina ٱl̊fiḍãẗi."],[8,12,"كَرْمِي ٱلَّذِي لِي هُوَ أَمَامِي. ٱلْأَلْفُ لَكَ يَا سُلَيْمَانُ، وَمِئَتَانِ لِنَوَاطِيرِ ٱلثَّمَرِ.","kar̊mī ٱlãdẖī lī hūa ạảmāmī. ٱl̊ạảl̊fu laka yā sulaẙmānu, wamīảtāni linawāṭīri ٱltẖãmari."],[8,13,"أَيَّتُهَا ٱلْجَالِسَةُ فِي ٱلْجَنَّاتِ، ٱلْأَصْحَابُ يَسْمَعُونَ صَوْتَكِ، فَأَسْمِعِينِي.","ạảyãtuhā ٱl̊jālisaẗu fī ٱl̊janãạti, ٱl̊ạảṣ̊ḥābu yas̊maʿūna ṣaẘtaki, fāảs̊miʿīnī."],[8,14,"اُهْرُبْ يَا حَبِيبِي، وَكُنْ كَٱلظَّبْيِ أَوْ كَغُفْرِ ٱلْأَيَائِلِ عَلَى جِبَالِ ٱلْأَطْيَابِ.","ạuh̊rub̊ yā ḥabībī, wakun̊ kaٱlẓãb̊yi ạảẘ kagẖuf̊ri ٱl̊ạảyāyỉli ʿalay̱ jibāli ٱl̊ạảṭ̊yābi."]],"bis-obbr":[[1,1,"Nem blong sing ya, Sing we i Gud Moa, i Winim ol Narafala Sing,we King Solomon i wokem.","Nem blong sing ya, Sing we i Gud Moa, i Winim ol Narafala Sing,we King Solomon i wokem."],[1,2,"Nao woman i talem se, “Daling. Mi wantem blong yu stap kisim mi we yu kisim mi. Yu yu laekem mi tumas. Ol fasin ya we yu stap mekem long mi, i swit moa i winim waen.","Nao woman i talem se, “Daling. Mi wantem blong yu stap kisim mi we yu kisim mi. Yu yu laekem mi tumas. Ol fasin ya we yu stap mekem long mi, i swit moa i winim waen."],[1,3,"Senta ya we yu stap putum long bodi blong yu, mi mi laekem smel blong hem tumas. Mo nem blong yu tu i mekem mi mi tingbaot senta ya. Samting ya nao i mekem ol gel oli laekem yu tumas.","Senta ya we yu stap putum long bodi blong yu, mi mi laekem smel blong hem tumas. Mo nem blong yu tu i mekem mi mi tingbaot senta ya. Samting ya nao i mekem ol gel oli laekem yu tumas."],[1,4,"Yu yu king blong mi, plis yu tekem mi, yumitu resis i go. Yu tekem mi mi go stap long rum blong yu. Bambae yumitu harem gud, yumitu glad, from we yumitufala i laeklaekem yumitu moa, i winim we yumitu stap harem gud long waen. I stret nomo we ol gel ya oli stap laekem yu tumas.”","Yu yu king blong mi, plis yu tekem mi, yumitu resis i go. Yu tekem mi mi go stap long rum blong yu. Bambae yumitu harem gud, yumitu glad, from we yumitufala i laeklaekem yumitu moa, i winim we yumitu stap harem gud long waen. I stret nomo we ol gel ya oli stap laekem yu tumas.”"],[1,5,"Mo hem i talem long ol narafala woman se, “Ol woman Jerusalem,* mi mi blak, be mi naes we mi naes. Mi mi blak olsem ol haos tapolen long draeples ya Kedara, be mi naes olsem ol gudfala kaliko ya blong flasem haos blong king.","Mo hem i talem long ol narafala woman se, “Ol woman Jerusalem,* mi mi blak, be mi naes we mi naes. Mi mi blak olsem ol haos tapolen long draeples ya Kedara, be mi naes olsem ol gudfala kaliko ya blong flasem haos blong king."],[1,6,"Kala blong mi i narafala, be plis yufala i no lukluk nogud long mi from. Ol brata blong mi oli kros long mi, oli mekem mi mi stap wok long plantesen blong grep,* nao san i bonem mi i jenisim kala blong mi, from we mi no gat taem // blong lukaot gud long bodi blong mi.”","Kala blong mi i narafala, be plis yufala i no lukluk nogud long mi from. Ol brata blong mi oli kros long mi, oli mekem mi mi stap wok long plantesen blong grep,* nao san i bonem mi i jenisim kala blong mi, from we mi no gat taem // blong lukaot gud long bodi blong mi.”"],[1,7,"Nao hem i talem long man ya se, “Daling, plis yu talemaot long mi ples we bambae yu tekem ol sipsip blong yu i go long hem blong oli kakae. ?Long medel dei, taem san i strong, weples nao bambae ol sipsip ya oli go spel long hem? I no stret blong mi stap go olbaot blong lukaot yu long ol ples we ol narafala man oli stap lukaot long ol sipsip blong olgeta long hem.”","Nao hem i talem long man ya se, “Daling, plis yu talemaot long mi ples we bambae yu tekem ol sipsip blong yu i go long hem blong oli kakae. ?Long medel dei, taem san i strong, weples nao bambae ol sipsip ya oli go spel long hem? I no stret blong mi stap go olbaot blong lukaot yu long ol ples we ol narafala man oli stap lukaot long ol sipsip blong olgeta long hem.”"],[1,8,"Nao man ya i talem long hem se, “Daling, yu yu naes moa, yu winim ol narafala woman. Sipos yu no save weples ol sipsip ya oli stap, yu folem trak blong olgeta, yu tekem ol nani blong yu oli kam kakae klosap long ol haos tapolen blong ol man blong lukaot long sipsip blong mi.","Nao man ya i talem long hem se, “Daling, yu yu naes moa, yu winim ol narafala woman. Sipos yu no save weples ol sipsip ya oli stap, yu folem trak blong olgeta, yu tekem ol nani blong yu oli kam kakae klosap long ol haos tapolen blong ol man blong lukaot long sipsip blong mi."],[1,9,"“Daling, yu stap mekem we ol man oli wantem yu tumas, olsem we woman hos i save mekem ol man hos we oli stap pulum kat blong faet // blong king blong Ijip oli no save stap kwaet.","“Daling, yu stap mekem we ol man oli wantem yu tumas, olsem we woman hos i save mekem ol man hos we oli stap pulum kat blong faet // blong king blong Ijip oli no save stap kwaet."],[1,10,"Hea blong yu we i hang i kamdaon long fes blong yu i naes tumas, mo i hanghang, i kamdaon long nek blong yu olsem ol jen blong ol flas ston.","Hea blong yu we i hang i kamdaon long fes blong yu i naes tumas, mo i hanghang, i kamdaon long nek blong yu olsem ol jen blong ol flas ston."],[1,11,"Bambae mifala i wokem wan jen blong yu long gol, mo bambae mifala i flasem long ol bidbid we mifala i wokem long silva.”","Bambae mifala i wokem wan jen blong yu long gol, mo bambae mifala i flasem long ol bidbid we mifala i wokem long silva.”"],[1,12,"Nao woman ya i talem se, “King blong mi, yu stap ledaon long bed ya blong yu, mo gudfala smel blong senta blong mi i kavremapgud ples ya.","Nao woman ya i talem se, “King blong mi, yu stap ledaon long bed ya blong yu, mo gudfala smel blong senta blong mi i kavremapgud ples ya."],[1,13,"Man blong mi, mi mi laekem yu tumas. Taem yu yu slip long tufala titi blong mi, mi harem olsem we mi putum gudfala senta ya mir* long ples ya.","Man blong mi, mi mi laekem yu tumas. Taem yu yu slip long tufala titi blong mi, mi harem olsem we mi putum gudfala senta ya mir* long ples ya."],[1,14,"Daling, mi harem yu yu olsem bandel flaoa ya hena* we i beswan, we oli stap gru long ol plantesen long ples ya Enkedi.”","Daling, mi harem yu yu olsem bandel flaoa ya hena* we i beswan, we oli stap gru long ol plantesen long ples ya Enkedi.”"],[1,15,"Nao man ya i talem se, “Daling, yu naes we yu naes. Taem mi luk long ae blong yu mi save we yu yu laekem mi tumas.”","Nao man ya i talem se, “Daling, yu naes we yu naes. Taem mi luk long ae blong yu mi save we yu yu laekem mi tumas.”"],[1,16,"Nao woman ya i talem se, “Daling, mi mi laekem yu moa i winim olgeta narafala man. Yu yu naes we yu naes, yu stap mekem mi mi harem gud tumas. Bambae yumitufala i go slip long gras ya we i grin gud,","Nao woman ya i talem se, “Daling, mi mi laekem yu moa i winim olgeta narafala man. Yu yu naes we yu naes, yu stap mekem mi mi harem gud tumas. Bambae yumitufala i go slip long gras ya we i grin gud,"],[1,17,"aninit long ol sida* mo ol paentri.* Ol sida ya bambae oli olsem haos blong yumitu, mo ol paentri ya bambae oli olsem siling blong hem.","aninit long ol sida* mo ol paentri.* Ol sida ya bambae oli olsem haos blong yumitu, mo ol paentri ya bambae oli olsem siling blong hem."],[2,1,"Mi ya mi olsem waelflaoa ya nomo we i stap gru long ples ya Saron. Mi olsem narafala waelflaoa ya nomo, we i stap gru long levelples long medel blong ol hil.”","Mi ya mi olsem waelflaoa ya nomo we i stap gru long ples ya Saron. Mi olsem narafala waelflaoa ya nomo, we i stap gru long levelples long medel blong ol hil.”"],[2,2,"Nao man ya i talem se, “Daling, taem yu stap wetem ol narafala woman, yu yu olsem wan gudfala waelflaoa we i stap gru long medel blong rop we i gat nil.”","Nao man ya i talem se, “Daling, taem yu stap wetem ol narafala woman, yu yu olsem wan gudfala waelflaoa we i stap gru long medel blong rop we i gat nil.”"],[2,3,"Nao woman ya i talem se, “Man blong mi, mi mi laekem yu tumas, i winim olgeta narafala man. Taem yu stap wetem ol narafala man, yu yu olsem gudfala tri ya apol* we i stap long medel blong ol narafala tri long bus. Mi mi laekem tumas blong sidaon long sed blong tri ya, mo taem mi kakae frut blong hem, mi harem i swit we i swit.","Nao woman ya i talem se, “Man blong mi, mi mi laekem yu tumas, i winim olgeta narafala man. Taem yu stap wetem ol narafala man, yu yu olsem gudfala tri ya apol* we i stap long medel blong ol narafala tri long bus. Mi mi laekem tumas blong sidaon long sed blong tri ya, mo taem mi kakae frut blong hem, mi harem i swit we i swit."],[2,4,"Yu yu tekem mi mi go long haos ya we yu stap mekem lafet long hem, mo yu stap soemaot i klia we yu laekem mi tumas.","Yu yu tekem mi mi go long haos ya we yu stap mekem lafet long hem, mo yu stap soemaot i klia we yu laekem mi tumas."],[2,5,"Yu putum lef han blong yu aninit long hed blong mi, mo yu stap holeholem mi long raet han blong yu. Oltaem mi wantem yu tumas, nao mi kam slak olgeta from. Plis yu givim drae grep long mi, blong mi kakae, mi strong bakegen, mo yu givim apol long mi, blong mi kakae, mi harem gud.”","Yu putum lef han blong yu aninit long hed blong mi, mo yu stap holeholem mi long raet han blong yu. Oltaem mi wantem yu tumas, nao mi kam slak olgeta from. Plis yu givim drae grep long mi, blong mi kakae, mi strong bakegen, mo yu givim apol long mi, blong mi kakae, mi harem gud.”",6],[2,7,"Nao man ya i talem long ol woman ya se, “Ol woman Jerusalem, plis yufala i mekem wan strong promes long mi long nem blong anamol ya dia* mo gudfala anamol ya gasel,* se bambae yufala i no save spolem mitufala taem mitufala i stap wanples.”","Nao man ya i talem long ol woman ya se, “Ol woman Jerusalem, plis yufala i mekem wan strong promes long mi long nem blong anamol ya dia* mo gudfala anamol ya gasel,* se bambae yufala i no save spolem mitufala taem mitufala i stap wanples.”"],[2,8,"Nao woman i talem se, “Mi stap harem voes blong man blong mi. Hem i stap resis antap long ol hil i stap kam, hem i stap krosem ol hil, blong spid i kam long mi.","Nao woman i talem se, “Mi stap harem voes blong man blong mi. Hem i stap resis antap long ol hil i stap kam, hem i stap krosem ol hil, blong spid i kam long mi."],[2,9,"Hem i save ron kwik tumas olsem gudfala anamol ya gasel.* Hem i save spid olsem wan smol man dia. Hem i stap stanap afsaed long wol blong haos, i stap lukluk i kamtru long windo, i stap lukluk i kam insaed.","Hem i save ron kwik tumas olsem gudfala anamol ya gasel.* Hem i save spid olsem wan smol man dia. Hem i stap stanap afsaed long wol blong haos, i stap lukluk i kamtru long windo, i stap lukluk i kam insaed."],[2,10,"Hem i stap toktok wetem mi.” Nao man ya i talem se, “!Ale, daling yu girap! Yu yu naes we yu naes, yu kam afsaed, yumitufala i go.","Hem i stap toktok wetem mi.” Nao man ya i talem se, “!Ale, daling yu girap! Yu yu naes we yu naes, yu kam afsaed, yumitufala i go."],[2,11,"Koltaem i finis nao. Rentaem i finis finis.","Koltaem i finis nao. Rentaem i finis finis."],[2,12,"Naoia, long bus, ol waelflaoa oli stap kamkamaot. Naoia i taem blong ol pijin oli stap singsingaot, mo long bus, mi harem ol sotleg* oli stap krae.","Naoia, long bus, ol waelflaoa oli stap kamkamaot. Naoia i taem blong ol pijin oli stap singsingaot, mo long bus, mi harem ol sotleg* oli stap krae."],[2,13,"Naoia ol figtri* oli stap karem kakae, mo ol rop ya grep* oli stap karem flaoa we i mekem ples i smel gud tumas. !Daling yu girap! Yu yu naes we yu naes, yu kam afsaed, yumitufala i go.","Naoia ol figtri* oli stap karem kakae, mo ol rop ya grep* oli stap karem flaoa we i mekem ples i smel gud tumas. !Daling yu girap! Yu yu naes we yu naes, yu kam afsaed, yumitufala i go."],[2,14,"Yu yu stap haed olsem wan sotleg we i fraet, i stap haed long hol blong ston. Plis, mi wantem harem voes blong yu, we i gud we i gud. Mo mi wantem luk fes blong yu, we i naes we i naes.”","Yu yu stap haed olsem wan sotleg we i fraet, i stap haed long hol blong ston. Plis, mi wantem harem voes blong yu, we i gud we i gud. Mo mi wantem luk fes blong yu, we i naes we i naes.”"],[2,15,"Nao man ya i talem long ol woman ya se, “Plis yufala i go ronem ol wael dog ya, yufala i holem olgeta. I nogud oli spolem plantesen blong mitufala. Ol grep long plantesen ya oli karem flaoa finis.”","Nao man ya i talem long ol woman ya se, “Plis yufala i go ronem ol wael dog ya, yufala i holem olgeta. I nogud oli spolem plantesen blong mitufala. Ol grep long plantesen ya oli karem flaoa finis.”"],[2,16,"Nao woman ya i talem se, “Daling, mi mi laekem yu tumas. Yu yu blong mi, mo mi mi blong yu. Yu yu stap lidim ol sipsip blong yu, oli pas long ples blong waelflaoa blong oli tekem kakae,","Nao woman ya i talem se, “Daling, mi mi laekem yu tumas. Yu yu blong mi, mo mi mi blong yu. Yu yu stap lidim ol sipsip blong yu, oli pas long ples blong waelflaoa blong oli tekem kakae,"],[2,17,"mo oli stap long ples ya gogo kasem we kol win blong moning i blu i kam mo tudak i lus, delaet i kamtru. Daling, plis yu kambak kwik olsem anamol ya gasel, yu spid olsem smol man dia blong hil blong ples ya Beta.","mo oli stap long ples ya gogo kasem we kol win blong moning i blu i kam mo tudak i lus, delaet i kamtru. Daling, plis yu kambak kwik olsem anamol ya gasel, yu spid olsem smol man dia blong hil blong ples ya Beta."],[3,1,"Daling, long naet, taem mi stap slip long bed blong mi, oltaem mi stap drim long yu, se mi stap lukaot yu be mi no save faenem yu.","Daling, long naet, taem mi stap slip long bed blong mi, oltaem mi stap drim long yu, se mi stap lukaot yu be mi no save faenem yu."],[3,2,"Mi luk se mi stap go long olgeta ples long taon ya. Mi stap pas long ol big rod, mo long ol smosmol rod, mi stap lukaot yu. Mi lukaot, mi lukaot, mi lukaot, be mi no save faenem yu.","Mi luk se mi stap go long olgeta ples long taon ya. Mi stap pas long ol big rod, mo long ol smosmol rod, mi stap lukaot yu. Mi lukaot, mi lukaot, mi lukaot, be mi no save faenem yu."],[3,3,"Ol polis we oli stap wokbaot blong gad long taon ya, oli luk mi, nao mi askem long olgeta se, ‘Mi mi stap lukaot man blong mi. ?Yufala i no luk hem?’","Ol polis we oli stap wokbaot blong gad long taon ya, oli luk mi, nao mi askem long olgeta se, ‘Mi mi stap lukaot man blong mi. ?Yufala i no luk hem?’"],[3,4,"Be taem mi livim olgeta, wantaem nomo mi faenem yu. Nao mi holem yu, we mi no save lego yu nating, gogo mi tekem yu yu go long haos blong mama blong mi, long rum ya we mi mi bon long hem.”","Be taem mi livim olgeta, wantaem nomo mi faenem yu. Nao mi holem yu, we mi no save lego yu nating, gogo mi tekem yu yu go long haos blong mama blong mi, long rum ya we mi mi bon long hem.”"],[3,5,"Nao man ya i talem long ol woman ya bakegen se, “Ol woman Jerusalem,* plis yufala i mekem wan strong promes long mi long nem blong anamol ya dia* mo gudfala anamol ya gasel,* se bambae yufala i no save spolem mitufala taem mitufala i stap wanples.”","Nao man ya i talem long ol woman ya bakegen se, “Ol woman Jerusalem,* plis yufala i mekem wan strong promes long mi long nem blong anamol ya dia* mo gudfala anamol ya gasel,* se bambae yufala i no save spolem mitufala taem mitufala i stap wanples.”"],[3,6,"Nao woman i talem se, “?Wanem samting ya we i aot long draeples longwe, we i stap stanap stret olsem smok blong faea? Smel blong hem i gud tumas, i olsem smel blong insens* mo mir,* we ol treda oli stap salem.","Nao woman i talem se, “?Wanem samting ya we i aot long draeples longwe, we i stap stanap stret olsem smok blong faea? Smel blong hem i gud tumas, i olsem smel blong insens* mo mir,* we ol treda oli stap salem."],[3,7,"!A, King Solomon ya! Hem i stap sidaon long jea blong hem, mo ol man blong hem oli stap karem hem i kam. I gat sikisti man we oli nambawan soldia blong Isrel,* oli stap gad long hem.","!A, King Solomon ya! Hem i stap sidaon long jea blong hem, mo ol man blong hem oli stap karem hem i kam. I gat sikisti man we oli nambawan soldia blong Isrel,* oli stap gad long hem."],[3,8,"Olgeta ya evriwan oli waes gud blong faet long naef blong faet. Olgeta oli go long faet plante taem, mo oli save faet gud tumas. Olgeta evriwan oli hangemrere naef blong faet, blong oli save blokem ol man we oli wantem kam faet long olgeta long naet.","Olgeta ya evriwan oli waes gud blong faet long naef blong faet. Olgeta oli go long faet plante taem, mo oli save faet gud tumas. Olgeta evriwan oli hangemrere naef blong faet, blong oli save blokem ol man we oli wantem kam faet long olgeta long naet."],[3,9,"Ol man oli stap karem king ya long spesel jea blong hem we oli wokem long timba we i beswan.","Ol man oli stap karem king ya long spesel jea blong hem we oli wokem long timba we i beswan."],[3,10,"Ol leg blong jea ya, ol man we oli wokem oli blokem olgeta long silva blong flasemgud olgeta. Mo kaliko we oli putum antap long hem, oli flasem long gol. Mo ol pilo blong jea ya oli blokem long kaliko, we kala blong hem i pepol, we ol woman Jerusalem* oli bin wokem, from we oli laekem king ya tumas.","Ol leg blong jea ya, ol man we oli wokem oli blokem olgeta long silva blong flasemgud olgeta. Mo kaliko we oli putum antap long hem, oli flasem long gol. Mo ol pilo blong jea ya oli blokem long kaliko, we kala blong hem i pepol, we ol woman Jerusalem* oli bin wokem, from we oli laekem king ya tumas."],[3,11,"Ol woman Jerusalem, yufala i kam luk hem. Hem i stap werem hat ya blong king we mama blong hem i bin putum long hed blong hem bifo, long dei ya we hem i mared, we hem i stap harem i gud tumas.”","Ol woman Jerusalem, yufala i kam luk hem. Hem i stap werem hat ya blong king we mama blong hem i bin putum long hed blong hem bifo, long dei ya we hem i mared, we hem i stap harem i gud tumas.”"],[4,1,"Nao man ya i talem se, “Daling, yu yu naes we yu naes. Nating we kaliko i blokem fes blong yu, be mi save makem long ae blong yu se yu yu laekem mi tumas. Hea blong yu i stap muvmuv olbaot, olsem ol nani ya we oli stap jamjam, oli stap kamdaon long hil long Gilead.","Nao man ya i talem se, “Daling, yu yu naes we yu naes. Nating we kaliko i blokem fes blong yu, be mi save makem long ae blong yu se yu yu laekem mi tumas. Hea blong yu i stap muvmuv olbaot, olsem ol nani ya we oli stap jamjam, oli stap kamdaon long hil long Gilead."],[4,2,"Ol tut blong yu oli waet gud olsem sipsip we man i jes katemaot hea blong hem, nao i wasem bodi blong hem i waet gud. I no gat wan long ol tut blong yu i foldaon, olgeta evriwan oli sem mak nomo, mo oli stret gud.","Ol tut blong yu oli waet gud olsem sipsip we man i jes katemaot hea blong hem, nao i wasem bodi blong hem i waet gud. I no gat wan long ol tut blong yu i foldaon, olgeta evriwan oli sem mak nomo, mo oli stret gud."],[4,3,"Maot blong yu i olsem riben we i red, mo taem yu toktok, i naes we i naes. Nating we kaliko i blokem fes blong yu, be kala blong hem i stap saenaot i kasem mi.","Maot blong yu i olsem riben we i red, mo taem yu toktok, i naes we i naes. Nating we kaliko i blokem fes blong yu, be kala blong hem i stap saenaot i kasem mi."],[4,4,"Nek blong yu i naes tumas, i raon mo i smut olsem wajhaos* blong papa blong mi, mo ol bidbid long nek blong yu oli olsem wan taosen sil* blong ol strong man blong faet we oli hangem raon long wajhaos ya // blong flasem.","Nek blong yu i naes tumas, i raon mo i smut olsem wajhaos* blong papa blong mi, mo ol bidbid long nek blong yu oli olsem wan taosen sil* blong ol strong man blong faet we oli hangem raon long wajhaos ya // blong flasem."],[4,5,"Tufala titi blong yu i naes tumas, tufala i naes olsem tu anamol ya gasel.* Tufala i olsem tu anamol ya dia* we tufala i twin, we tufala i stap kakae gras long ples blong waelflaoa.","Tufala titi blong yu i naes tumas, tufala i naes olsem tu anamol ya gasel.* Tufala i olsem tu anamol ya dia* we tufala i twin, we tufala i stap kakae gras long ples blong waelflaoa."],[4,6,"Bambae mi go stap long hil ya we i gat fulap senta ya mir long hem, mo long hil ya we i olsem hip blong senta ya frangkinsens,* gogo kasem we kol win blong moning i blu i kam, mo tudak i lus, delaet i kamtru.","Bambae mi go stap long hil ya we i gat fulap senta ya mir long hem, mo long hil ya we i olsem hip blong senta ya frangkinsens,* gogo kasem we kol win blong moning i blu i kam, mo tudak i lus, delaet i kamtru."],[4,7,"Daling, yu yu naes tumas. Bodi blong yu i nambawan, i no gat wan mak nating i spolem hem.","Daling, yu yu naes tumas. Bodi blong yu i nambawan, i no gat wan mak nating i spolem hem."],[4,8,"“Yu yu woman blong mi, yu kam wetem mi. Bambae yumitufala i aot long ol hil ya long Lebanon. Bambae yumitufala i aot long kantri ya, yumitu go. Bae yumitu aot long top blong hil ya Amana yumitu godaon. Bae yumitu aot long hil ya Seniri we narafala nem blong hem Hemon, we i ples blong laeon mo leped.*","“Yu yu woman blong mi, yu kam wetem mi. Bambae yumitufala i aot long ol hil ya long Lebanon. Bambae yumitufala i aot long kantri ya, yumitu go. Bae yumitu aot long top blong hil ya Amana yumitu godaon. Bae yumitu aot long hil ya Seniri we narafala nem blong hem Hemon, we i ples blong laeon mo leped.*"],[4,9,"Daling, yu yu woman blong mi. Long fasin ya we yu lukluk i kam long mi, mo long jen ya we yu hangem long nek blong yu, wantaem nomo, yu brekemgud hat blong mi.","Daling, yu yu woman blong mi. Long fasin ya we yu lukluk i kam long mi, mo long jen ya we yu hangem long nek blong yu, wantaem nomo, yu brekemgud hat blong mi."],[4,10,"Yu yu woman blong mi. Ol fasin ya we yu stap mekem long mi we yumitu i stap wanples, oli stap mekem mi mi glad oltaem nomo. Ol fasin ya blong yu i gud moa, i winim waen, mo senta we yu yu putum, smel blong hem i gud moa, i winim olgeta lif we oli gat gudfala smel.","Yu yu woman blong mi. Ol fasin ya we yu stap mekem long mi we yumitu i stap wanples, oli stap mekem mi mi glad oltaem nomo. Ol fasin ya blong yu i gud moa, i winim waen, mo senta we yu yu putum, smel blong hem i gud moa, i winim olgeta lif we oli gat gudfala smel."],[4,11,"Daling, maot blong yu i swit olsem hani,* mo tang blong yu i swit olsem melek wetem hani. Smel blong klos blong yu i gud tumas, i olsem smel blong senta ya we i kam long Lebanon.","Daling, maot blong yu i swit olsem hani,* mo tang blong yu i swit olsem melek wetem hani. Smel blong klos blong yu i gud tumas, i olsem smel blong senta ya we i kam long Lebanon."],[4,12,"“Daling, yu yu woman blong mi. Yu yu olsem wan gudfala ples blong spel we i blong mi, mi wan. Yu yu olsem wan smol ples blong spel blong mi, we stonwol i goraon long hem. Yu yu olsem wan springwota we mi wan nomo mi save dring long hem.","“Daling, yu yu woman blong mi. Yu yu olsem wan gudfala ples blong spel we i blong mi, mi wan. Yu yu olsem wan smol ples blong spel blong mi, we stonwol i goraon long hem. Yu yu olsem wan springwota we mi wan nomo mi save dring long hem."],[4,13,"Long ples ya, ol tri oli stap gru gud tumas. Oli stap gru olsem plantesen blong grenadin* we i stap karem ol nambawan frut. Long ples ya, i gat ol gudgudfala samting oli stap gru long hem.","Long ples ya, ol tri oli stap gru gud tumas. Oli stap gru olsem plantesen blong grenadin* we i stap karem ol nambawan frut. Long ples ya, i gat ol gudgudfala samting oli stap gru long hem."],[4,14,"I gat hena* mo nad* mo safron* mo kalamas* mo sinamon.* Mo i gat olkaen insens i stap long hem. Mir* mo alos* tu i gru long ples ya, wetem ol narafala samting blong wokem senta we smel blong olgeta i gud tumas.","I gat hena* mo nad* mo safron* mo kalamas* mo sinamon.* Mo i gat olkaen insens i stap long hem. Mir* mo alos* tu i gru long ples ya, wetem ol narafala samting blong wokem senta we smel blong olgeta i gud tumas."],[4,15,"Oltaem, ol springwota oli stap wasem ples ya, mo ol wota oli stap ron i kam long hem, wetem ol smosmol wota we oli kamaot long ol hil long kantri ya Lebanon.”","Oltaem, ol springwota oli stap wasem ples ya, mo ol wota oli stap ron i kam long hem, wetem ol smosmol wota we oli kamaot long ol hil long kantri ya Lebanon.”"],[4,16,"Nao woman ya i talem se, “Not win, yu girap. Saot win, yu blu i kam long mi. Yutufala i mekem we ples ya i fulap long gudfala smel. Yutufala i mekem we daling blong mi i kam long gudfala ples ya blong spel blong hem, blong i kakae ol nambawan frut blong ples ya.”","Nao woman ya i talem se, “Not win, yu girap. Saot win, yu blu i kam long mi. Yutufala i mekem we ples ya i fulap long gudfala smel. Yutufala i mekem we daling blong mi i kam long gudfala ples ya blong spel blong hem, blong i kakae ol nambawan frut blong ples ya.”"],[5,1,"Nao man ya i talem se, “Daling, yu yu woman blong mi. Mi mi kam insaed finis long gudfala ples ya blong mi. Naoia mi stap tekem mir mo ol lif we i gat gudfala smel. Naoia mi stap kakae hani mo bed blong hem, mo mi stap dring waen mo melek.” Nao ol woman ya oli talem se, “Tufala, yutufala i gohed, yutufala i kakae, yutufala i dring, gogo yutufala i drong // long fasin ya we yutufala i stap mekem.”","Nao man ya i talem se, “Daling, yu yu woman blong mi. Mi mi kam insaed finis long gudfala ples ya blong mi. Naoia mi stap tekem mir mo ol lif we i gat gudfala smel. Naoia mi stap kakae hani mo bed blong hem, mo mi stap dring waen mo melek.” Nao ol woman ya oli talem se, “Tufala, yutufala i gohed, yutufala i kakae, yutufala i dring, gogo yutufala i drong // long fasin ya we yutufala i stap mekem.”"],[5,2,"Nao woman i talem se, “Mi mi stap slip, be mi stap tingbaot man ya blong mi, nao mi drim, mi luk se hem i stap kilkilim doa blong mi, mo i stap singaot i kam. Hem i talem long mi se, ‘Daling, yu yu woman blong mi. Maeswitat, yu yu naes we yu naes. Plis yu letem mi mi kam insaed. Hed blong mi i wetwet long wota blong naet mo hea blong mi i wetwet gud from.’","Nao woman i talem se, “Mi mi stap slip, be mi stap tingbaot man ya blong mi, nao mi drim, mi luk se hem i stap kilkilim doa blong mi, mo i stap singaot i kam. Hem i talem long mi se, ‘Daling, yu yu woman blong mi. Maeswitat, yu yu naes we yu naes. Plis yu letem mi mi kam insaed. Hed blong mi i wetwet long wota blong naet mo hea blong mi i wetwet gud from.’"],[5,3,"Be mi mi talem long hem se, ‘Mi mi tekemaot klos blong mi finis blong mi slip, mi no save putum bakegen. Mi wasem leg blong mi finis, mi no wantem mekem i doti bakegen.’","Be mi mi talem long hem se, ‘Mi mi tekemaot klos blong mi finis blong mi slip, mi no save putum bakegen. Mi wasem leg blong mi finis, mi no wantem mekem i doti bakegen.’"],[5,4,"“Nao daling blong mi i pusum han blong hem i kamtru long hol blong doa, mo mi mi harem gud tumas long hem.","“Nao daling blong mi i pusum han blong hem i kamtru long hol blong doa, mo mi mi harem gud tumas long hem."],[5,5,"Nao mi girap blong letem hem i kam insaed. Taem mi holem handel blong doa ya, han blong mi i wetwet gud long mir,* mo ol fingga blong mi oli fulap gud long wota blong mir.","Nao mi girap blong letem hem i kam insaed. Taem mi holem handel blong doa ya, han blong mi i wetwet gud long mir,* mo ol fingga blong mi oli fulap gud long wota blong mir."],[5,6,"Mi openem doa blong hem i kam insaed, be hem i go finis. Mi wantem tumas blong harem voes blong hem. Mi lukaot hem, be mi no faenem hem. Mi traem singaot hem, be hem i no ansa.","Mi openem doa blong hem i kam insaed, be hem i go finis. Mi wantem tumas blong harem voes blong hem. Mi lukaot hem, be mi no faenem hem. Mi traem singaot hem, be hem i no ansa."],[5,7,"“Ol polis we oli stap wokbaot long taon ya mo we oli stap gad long bigfala stonwol blong hem, oli kilim mi, oli mekem mi mi karekil, mo oli pulumaot kot blong mi.","“Ol polis we oli stap wokbaot long taon ya mo we oli stap gad long bigfala stonwol blong hem, oli kilim mi, oli mekem mi mi karekil, mo oli pulumaot kot blong mi."],[5,8,"Ol woman Jerusalem,* plis yufala i mekem wan promes long mi, se sipos yufala i faenem man blong mi, bambae yufala i talemaot long hem we mi mi stap wantem hem tumas, gogo mi kam slak from.”","Ol woman Jerusalem,* plis yufala i mekem wan promes long mi, se sipos yufala i faenem man blong mi, bambae yufala i talemaot long hem we mi mi stap wantem hem tumas, gogo mi kam slak from.”"],[5,9,"Nao ol woman ya oli talem long hem se, “Yu yu naes moa i winim ol narafala woman, be man blong yu i no naes moa winim ol narafala man, hem i sem mak nomo long olgeta. ?From wanem mifala i mas mekem promes olsem long yu?”","Nao ol woman ya oli talem long hem se, “Yu yu naes moa i winim ol narafala woman, be man blong yu i no naes moa winim ol narafala man, hem i sem mak nomo long olgeta. ?From wanem mifala i mas mekem promes olsem long yu?”"],[5,10,"Nao hem i talem long olgeta se, “Man blong mi, hem i strong, mo i naes we i naes. Long ten taosen man, hem nomo i naes olsem.","Nao hem i talem long olgeta se, “Man blong mi, hem i strong, mo i naes we i naes. Long ten taosen man, hem nomo i naes olsem."],[5,11,"Fes blong hem i braon mo i smut. Mo hea blong hem i blak we i blak mo i sofsof gud.","Fes blong hem i braon mo i smut. Mo hea blong hem i blak we i blak mo i sofsof gud."],[5,12,"Ae blong hem i naes we i naes, olsem sotleg* we oltaem i stap klosap long reva. Ae blong hem i klin gud, mo i saen olsem flas ston long ring.","Ae blong hem i naes we i naes, olsem sotleg* we oltaem i stap klosap long reva. Ae blong hem i klin gud, mo i saen olsem flas ston long ring."],[5,13,"Fes blong hem i naes tumas, i olsem garen we i fulap gud long ol plan we lif blong olgeta i gat gudfala tes. Mo maot blong hem i red gud, olsem gudfala flaoa ya lili, mo i wetwet gud long senta ya mir.","Fes blong hem i naes tumas, i olsem garen we i fulap gud long ol plan we lif blong olgeta i gat gudfala tes. Mo maot blong hem i red gud, olsem gudfala flaoa ya lili, mo i wetwet gud long senta ya mir."],[5,14,"Han blong hem i strong mo i naes, mo hem i stap putum ol ring we oli flasem long gudfala ston. Bodi blong hem i saen olsem tut blong elefen we oli ravem i saen gud, mo oli flasem long ol flas ston ya safaea.*","Han blong hem i strong mo i naes, mo hem i stap putum ol ring we oli flasem long gudfala ston. Bodi blong hem i saen olsem tut blong elefen we oli ravem i saen gud, mo oli flasem long ol flas ston ya safaea.*"],[5,15,"Leg blong hem i olsem tufala pos we oli wokem long gudfala ston ya alabasta,* we stamba blong tufala oli wokem long gol. Taem mi luk hem, mi stap tingbaot ol bigbigfala hil ya long Lebanon, wetem ol sida* blong ples ya we oli longlongfala.","Leg blong hem i olsem tufala pos we oli wokem long gudfala ston ya alabasta,* we stamba blong tufala oli wokem long gol. Taem mi luk hem, mi stap tingbaot ol bigbigfala hil ya long Lebanon, wetem ol sida* blong ples ya we oli longlongfala."],[5,16,"Maot blong hem i swit tumas blong kisim, mo evri haf blong bodi blong hem, mi mi laekem tumas. “Ol woman Jerusalem, tru, man ya blong mi, hem i stret olsem we mi mi talem.”","Maot blong hem i swit tumas blong kisim, mo evri haf blong bodi blong hem, mi mi laekem tumas. “Ol woman Jerusalem, tru, man ya blong mi, hem i stret olsem we mi mi talem.”"],[6,1,"Nao ol woman ya oli talem long hem se, “?Yu yu naes moa, yu winim ol narafala woman, be man blong yu i stap wea? Yu traem talemaot long mifala weples hem i go, blong mifala i save halpem yu blong faenem hem.”","Nao ol woman ya oli talem long hem se, “?Yu yu naes moa, yu winim ol narafala woman, be man blong yu i stap wea? Yu traem talemaot long mifala weples hem i go, blong mifala i save halpem yu blong faenem hem.”"],[6,2,"Nao woman ya i talem se, “Hem i go spel long gudfala ples blong hem, we ol tri ya balsam* oli stap gru long hem. Hem i stap harem gud long ples ya, mo i stap tekem ol flaoa blong lili.","Nao woman ya i talem se, “Hem i go spel long gudfala ples blong hem, we ol tri ya balsam* oli stap gru long hem. Hem i stap harem gud long ples ya, mo i stap tekem ol flaoa blong lili."],[6,3,"Man ya, hem i blong mi, mo mi mi blong hem. Hem i stap lidim ol sipsip blong hem, oli pas long ples blong waelflaoa blong oli tekem kakae.”","Man ya, hem i blong mi, mo mi mi blong hem. Hem i stap lidim ol sipsip blong hem, oli pas long ples blong waelflaoa blong oli tekem kakae.”"],[6,4,"Nao man i talem se, “Daling, yu yu naes we yu naes. Taem mi luk yu, mi harem gud tumas, olsem we mi stap luk taon ya Tijaha. Taem mi lukluk i kam long yu, mi glad tumas, olsem we mi stap luk gudfala taon ya Jerusalem.* Taem mi luk yu, mi sek gud, olsem we mi sek long ol soldia we oli leftemap flaeg, oli maj i go long faet.","Nao man i talem se, “Daling, yu yu naes we yu naes. Taem mi luk yu, mi harem gud tumas, olsem we mi stap luk taon ya Tijaha. Taem mi lukluk i kam long yu, mi glad tumas, olsem we mi stap luk gudfala taon ya Jerusalem.* Taem mi luk yu, mi sek gud, olsem we mi sek long ol soldia we oli leftemap flaeg, oli maj i go long faet."],[6,5,"Plis yu tanem fes blong yu, yu no lukluk mi. Ae blong yu i stap spolemgud tingting blong mi. Hea blong yu i stap muvmuv olbaot, olsem ol nani we oli stap jamjam, oli stap kamdaon long hil long Gilead.","Plis yu tanem fes blong yu, yu no lukluk mi. Ae blong yu i stap spolemgud tingting blong mi. Hea blong yu i stap muvmuv olbaot, olsem ol nani we oli stap jamjam, oli stap kamdaon long hil long Gilead."],[6,6,"Ol tut blong yu oli waet gud olsem sipsip we man i jes katemaot hea blong hem, nao i wasem bodi blong hem i waet gud. I no gat wan long ol tut blong yu i foldaon, olgeta evriwan oli sem mak nomo, mo oli stret gud.","Ol tut blong yu oli waet gud olsem sipsip we man i jes katemaot hea blong hem, nao i wasem bodi blong hem i waet gud. I no gat wan long ol tut blong yu i foldaon, olgeta evriwan oli sem mak nomo, mo oli stret gud."],[6,7,"Nating we kaliko i blokem fes blong yu, be kala blong hem i stap saenaot i kasem mi.","Nating we kaliko i blokem fes blong yu, be kala blong hem i stap saenaot i kasem mi."],[6,8,"Mi mi king, mo mi gat sikisti woman blong mi, we oli kwin, mo eiti narafala woman blong mi, mo ol yang gel we oli plante we plante, we man i no save kaontem olgeta, be nating.","Mi mi king, mo mi gat sikisti woman blong mi, we oli kwin, mo eiti narafala woman blong mi, mo ol yang gel we oli plante we plante, we man i no save kaontem olgeta, be nating."],[6,9,"Yu yu olsem flaoa we i naes we i naes, mo mi mi laekem yu tumas. Yu yu wan dota nomo we mama blong yu i gat, mo hem i lavem yu moa, i winim ol narafala pikinini blong hem. Olgeta yang gel oli stap lukluk i kam long yu, mo oli stap presem yu. Ol kwin ya blong mi mo ol narafala woman ya blong mi, oli stap sing blong leftemap nem blong yu.","Yu yu olsem flaoa we i naes we i naes, mo mi mi laekem yu tumas. Yu yu wan dota nomo we mama blong yu i gat, mo hem i lavem yu moa, i winim ol narafala pikinini blong hem. Olgeta yang gel oli stap lukluk i kam long yu, mo oli stap presem yu. Ol kwin ya blong mi mo ol narafala woman ya blong mi, oli stap sing blong leftemap nem blong yu."],[6,10,"Olgeta oli talem se, ‘?Hu woman ya we taem i lukluk i kam, mifala i luk olsem we delaet i kamtru? Hem i naes we i naes, mo fes blong hem i saen we i saen, olsem san mo mun.’","Olgeta oli talem se, ‘?Hu woman ya we taem i lukluk i kam, mifala i luk olsem we delaet i kamtru? Hem i naes we i naes, mo fes blong hem i saen we i saen, olsem san mo mun.’"],[6,11,"Mi mi kamdaon mi stap finis long plantesen blong tri ya amon.* Mi kam blong luk ol yang tri long levelples long medel blong tufala hil ya. Mi kamdaon blong luk ol niufala lif blong grep,* mo ol gudfala flaoa blong grenadin.*","Mi mi kamdaon mi stap finis long plantesen blong tri ya amon.* Mi kam blong luk ol yang tri long levelples long medel blong tufala hil ya. Mi kamdaon blong luk ol niufala lif blong grep,* mo ol gudfala flaoa blong grenadin.*"],[6,12,"Naoia tingting blong mi i no moa save stap kwaet. Mi mi olsem man blong faet we i gat kat blong faet blong hem, we oltaem nomo i wantem tumas blong go long faet. Oltaem nomo, mi mi wantem tumas blong yumitufala i stap wanples.”","Naoia tingting blong mi i no moa save stap kwaet. Mi mi olsem man blong faet we i gat kat blong faet blong hem, we oltaem nomo i wantem tumas blong go long faet. Oltaem nomo, mi mi wantem tumas blong yumitufala i stap wanples.”"],[6,13,"Nao ol woman ya oli talem se, “!Woman Sulam, yu kambak! !Plis yu kambak! !Mifala i wantem lukluk yu we yu danis!” Nao woman ya i talem long olgeta se, “?From wanem yufala i wantem lukluk mi olsem? ?From wanem yufala i wantem mekem mi mi danis, mi kam olsem man blong wokem konset long fes blong ol man?”","Nao ol woman ya oli talem se, “!Woman Sulam, yu kambak! !Plis yu kambak! !Mifala i wantem lukluk yu we yu danis!” Nao woman ya i talem long olgeta se, “?From wanem yufala i wantem lukluk mi olsem? ?From wanem yufala i wantem mekem mi mi danis, mi kam olsem man blong wokem konset long fes blong ol man?”"],[7,1,"Nao man ya i talem se, “!Daling, yu yu naes we yu naes! Taem yu putum sandel, tufala leg blong yu i naes tumas. Mo leg blong yu antap, tufala i saes gud, olsem we man we i gat gudhan i wokem tufala.","Nao man ya i talem se, “!Daling, yu yu naes we yu naes! Taem yu putum sandel, tufala leg blong yu i naes tumas. Mo leg blong yu antap, tufala i saes gud, olsem we man we i gat gudhan i wokem tufala."],[7,2,"I gat wan dis i stap we neva i emti samtaem, oltaem i fulap gud long waen we i beswan. Mo i gat bandel wit* i stap, we ol flaoa ya lili oli stap raon long hem blong flasem.","I gat wan dis i stap we neva i emti samtaem, oltaem i fulap gud long waen we i beswan. Mo i gat bandel wit* i stap, we ol flaoa ya lili oli stap raon long hem blong flasem."],[7,3,"Tufala titi blong yu i naes tumas. Tufala i olsem tu anamol ya dia* we tufala i twin, tufala i naes olsem tu anamol ya gasel.*","Tufala titi blong yu i naes tumas. Tufala i olsem tu anamol ya dia* we tufala i twin, tufala i naes olsem tu anamol ya gasel.*"],[7,4,"Nek blong yu i naes tumas, mo i smut olsem wajhaos* we oli flasem long tut blong elefen. Ae blong yu i saen olsem wota long wel, klosap long doa* blong bigfala stonwol long taon ya Hesbon. Nus blong yu i naes we i naes. Taem mi luk, mi stap tingbaot gudfala wajhaos ya long Lebanon, we i stap lukluk i kam long Damaskes.","Nek blong yu i naes tumas, mo i smut olsem wajhaos* we oli flasem long tut blong elefen. Ae blong yu i saen olsem wota long wel, klosap long doa* blong bigfala stonwol long taon ya Hesbon. Nus blong yu i naes we i naes. Taem mi luk, mi stap tingbaot gudfala wajhaos ya long Lebanon, we i stap lukluk i kam long Damaskes."],[7,5,"Hed blong yu i no save hang, oltaem i stap stanap stret nomo. Taem mi luk, mi stap tingbaot bigfala hil ya Kamel. Mo hea blong yu i naes tumas. Taem yu tantanem wetem ol flas samting, hem i stap saen olsem silik we i saen gud. Nating we mi mi king, be i save mekem mi mi stap kwaet, olsem man we i stap long kalabus.","Hed blong yu i no save hang, oltaem i stap stanap stret nomo. Taem mi luk, mi stap tingbaot bigfala hil ya Kamel. Mo hea blong yu i naes tumas. Taem yu tantanem wetem ol flas samting, hem i stap saen olsem silik we i saen gud. Nating we mi mi king, be i save mekem mi mi stap kwaet, olsem man we i stap long kalabus."],[7,6,"“Yu yu naes we yu naes. Ol fasin ya we yu stap mekem long mi we yumitu stap wanples oli stap mekem mi mi harem gud tumas.","“Yu yu naes we yu naes. Ol fasin ya we yu stap mekem long mi we yumitu stap wanples oli stap mekem mi mi harem gud tumas."],[7,7,"Yu yu olsem wan naes pamtri* we i longfala, mo tufala titi blong yu i olsem tu gudfala bandel frut ya det.*","Yu yu olsem wan naes pamtri* we i longfala, mo tufala titi blong yu i olsem tu gudfala bandel frut ya det.*"],[7,8,"Bambae mi klaem long pamtri ya, mi tekem frut blong hem. Long mi, tufala titi blong yu i naes olsem tu bandel frut ya grep we i swit. Mo maot blong yu, mi harem smel blong hem i gud tumas olsem apol,*","Bambae mi klaem long pamtri ya, mi tekem frut blong hem. Long mi, tufala titi blong yu i naes olsem tu bandel frut ya grep we i swit. Mo maot blong yu, mi harem smel blong hem i gud tumas olsem apol,*"],[7,9,"mo kis blong yu i swit, i olsem waen we i beswan olgeta.” Nao woman ya i talem se, “Ale, daling, mi wantem waen ya i ron i go stret long yu, i wasem maot blong yu mo tut blong yu.","mo kis blong yu i swit, i olsem waen we i beswan olgeta.” Nao woman ya i talem se, “Ale, daling, mi wantem waen ya i ron i go stret long yu, i wasem maot blong yu mo tut blong yu."],[7,10,"Mi mi woman blong yu, mo yu yu wantem mi tumas.","Mi mi woman blong yu, mo yu yu wantem mi tumas."],[7,11,"Yu kam, yumitu ronwe long taon ya. Long naet, bambae yumitufala i go stap long wan vilej longwe.","Yu kam, yumitu ronwe long taon ya. Long naet, bambae yumitufala i go stap long wan vilej longwe."],[7,12,"Nao bambae yumitufala i girap long eli moning, yumitu go luk ol rop ya grep, se oli stat gru finis no no yet. Bambae yumitu go luk ol grep ya wetem ol grenadin se oli karem flaoa finis no no yet. Long ples ya nao, bambae mi soemaot long yu we mi mi laekem yu tumas.","Nao bambae yumitufala i girap long eli moning, yumitu go luk ol rop ya grep, se oli stat gru finis no no yet. Bambae yumitu go luk ol grep ya wetem ol grenadin se oli karem flaoa finis no no yet. Long ples ya nao, bambae mi soemaot long yu we mi mi laekem yu tumas."],[7,13,"Bambae yu save harem gudfala smel blong ol frut ya mandrek* mo blong ol gudgudfala frut ya tu we oli stap klosap long doa blong yumitu. Daling, ol gudgudfala fasin ya we yumitufala i save harem gud long hem, ol olfala fasin wetem ol niuwan, mi mi stap holemtaet olgeta // se oli blong yu nomo.","Bambae yu save harem gudfala smel blong ol frut ya mandrek* mo blong ol gudgudfala frut ya tu we oli stap klosap long doa blong yumitu. Daling, ol gudgudfala fasin ya we yumitufala i save harem gud long hem, ol olfala fasin wetem ol niuwan, mi mi stap holemtaet olgeta // se oli blong yu nomo."],[8,1,"“Sipos mama blong mi i bin bonem yu mo i bin givim titi long yu, nao yu yu stret brata blong mi, hemia bambae i moa gud. Sipos i olsem, taem mi mi mitim yu long taon, bambae mi save kis long yu, mo mi save toktok wetem yu we ol man // bambae oli no save tingting nogud from.","“Sipos mama blong mi i bin bonem yu mo i bin givim titi long yu, nao yu yu stret brata blong mi, hemia bambae i moa gud. Sipos i olsem, taem mi mi mitim yu long taon, bambae mi save kis long yu, mo mi save toktok wetem yu we ol man // bambae oli no save tingting nogud from."],[8,2,"Sipos i olsem, bambae mi save tekem yu yumitu go long haos blong mama blong yumi, nao long ples ya, bambae yu save tijim mi blong soemaot we mi mi laekem yu tumas. Bambae mi givim waen long yu we i miks wetem ol lif we i gat gudfala tes, mo bambae mi givim wota blong grenadin* long yu blong yu dring.","Sipos i olsem, bambae mi save tekem yu yumitu go long haos blong mama blong yumi, nao long ples ya, bambae yu save tijim mi blong soemaot we mi mi laekem yu tumas. Bambae mi givim waen long yu we i miks wetem ol lif we i gat gudfala tes, mo bambae mi givim wota blong grenadin* long yu blong yu dring."],[8,3,"“Bambae yu save putum lef han blong yu aninit long hed blong mi, mo yu save holeholem mi long raet han blong yu.","“Bambae yu save putum lef han blong yu aninit long hed blong mi, mo yu save holeholem mi long raet han blong yu."],[8,4,"“Ol woman Jerusalem, plis yufala i mekem wan strong promes long mi, se bambae yufala i no save spolem mitufala taem mitufala i stap wanples.”","“Ol woman Jerusalem, plis yufala i mekem wan strong promes long mi, se bambae yufala i no save spolem mitufala taem mitufala i stap wanples.”"],[8,5,"Nao ol woman ya oli talem se, “?Hu woman ya longwe long draeples i stap wokbaot i kam, we hem wetem man blong hem tufala i stap holeholem han blong tufala?” Nao woman ya i talem se, “Daling. Mi mi wekemap yu aninit long apol,* long ples ya we yu yu bon long hem.","Nao ol woman ya oli talem se, “?Hu woman ya longwe long draeples i stap wokbaot i kam, we hem wetem man blong hem tufala i stap holeholem han blong tufala?” Nao woman ya i talem se, “Daling. Mi mi wekemap yu aninit long apol,* long ples ya we yu yu bon long hem."],[8,6,"Plis, yu no tingbaot ol narafala woman, yu holem mi nomo mi stap long tingting blong yu. Bambae yu no tekem narafala woman i kam stap wanples wetem yu, yu letem mi nomo mi kam stap wetem yu. Fasin ya we yumitufala i laeklaekem yumitufala, hem i gat paoa, man i no save blokem, olsem we ded i gat paoa, man i no save blokem. Fasin ya we yumitufala i stap wantem yumitufala tumas, hem i strong tumas blong blokem, olsem we Hom* blong ol Dedman i strong tumas, man i no save ronwe long hem. Fasin ya i stap kamaot olsem faea we i laet bigwan, mo i stap bon strong tumas olsem faea we i red we i red.","Plis, yu no tingbaot ol narafala woman, yu holem mi nomo mi stap long tingting blong yu. Bambae yu no tekem narafala woman i kam stap wanples wetem yu, yu letem mi nomo mi kam stap wetem yu. Fasin ya we yumitufala i laeklaekem yumitufala, hem i gat paoa, man i no save blokem, olsem we ded i gat paoa, man i no save blokem. Fasin ya we yumitufala i stap wantem yumitufala tumas, hem i strong tumas blong blokem, olsem we Hom* blong ol Dedman i strong tumas, man i no save ronwe long hem. Fasin ya i stap kamaot olsem faea we i laet bigwan, mo i stap bon strong tumas olsem faea we i red we i red."],[8,7,"Hem i olsem wan bigfala faea we wota i no save kilim, we i no gat wan wota we i ron bigwan we i naf blong draonem. Be fasin ya, man i no save pem. Sipos wan man i traem blong pem, nating we hem i rere blong givim olgeta gudgudfala samting we hem i gat, be ol woman bambae oli stap laf nogud nomo long hem.”","Hem i olsem wan bigfala faea we wota i no save kilim, we i no gat wan wota we i ron bigwan we i naf blong draonem. Be fasin ya, man i no save pem. Sipos wan man i traem blong pem, nating we hem i rere blong givim olgeta gudgudfala samting we hem i gat, be ol woman bambae oli stap laf nogud nomo long hem.”"],[8,8,"Nao ol brata blong woman ya oli talem se, “Mifala i gat wan sista blong mifala we hem i yangfala, we titi blong hem i no gat yet. ?Sipos wan yang man i kam, i stap mekem fren wetem hem, bambae mifala i mekem olsem wanem long gel ya?","Nao ol brata blong woman ya oli talem se, “Mifala i gat wan sista blong mifala we hem i yangfala, we titi blong hem i no gat yet. ?Sipos wan yang man i kam, i stap mekem fren wetem hem, bambae mifala i mekem olsem wanem long gel ya?"],[8,9,"Sipos hem i strong olsem wan stonwol, bambae mifala i bildim wan wajhaos* long silva, blong mekem stonwol ya i strong moa. Be sipos hem i olsem wan doa, bambae mifala i blokemgud hem long ol plang we oli wokem long wud ya sida.*”","Sipos hem i strong olsem wan stonwol, bambae mifala i bildim wan wajhaos* long silva, blong mekem stonwol ya i strong moa. Be sipos hem i olsem wan doa, bambae mifala i blokemgud hem long ol plang we oli wokem long wud ya sida.*”"],[8,10,"Nao woman ya i talem se, “Mi mi wan stonwol ya, mo tufala titi blong mi i olsem tufala wajhaos blong hem. Man blong mi i save we hem nomo i stap mekem mi mi harem gud, mi stap long pis.”","Nao woman ya i talem se, “Mi mi wan stonwol ya, mo tufala titi blong mi i olsem tufala wajhaos blong hem. Man blong mi i save we hem nomo i stap mekem mi mi harem gud, mi stap long pis.”"],[8,11,"Nao man ya i talem se, “Mi mi king, mi gat wan plantesen grep* blong mi we i stap long ples ya Balamon, mo i gat ol fama we oli stap rentem plantesen ya long mi. Olgeta ya wanwan oli stap pem ren long mi long faef handred taosen vatu.*","Nao man ya i talem se, “Mi mi king, mi gat wan plantesen grep* blong mi we i stap long ples ya Balamon, mo i gat ol fama we oli stap rentem plantesen ya long mi. Olgeta ya wanwan oli stap pem ren long mi long faef handred taosen vatu.*"],[8,12,"Mi mi glad tumas long ol vatu ya blong hem, mo ol fama ya tu, olgeta wanwan oli glad long ol profit blong olgeta we wan handred taosen vatu long wan, be mi gat wan narafala plantesen we i blong mi, mi wan nomo.","Mi mi glad tumas long ol vatu ya blong hem, mo ol fama ya tu, olgeta wanwan oli glad long ol profit blong olgeta we wan handred taosen vatu long wan, be mi gat wan narafala plantesen we i blong mi, mi wan nomo."],[8,13,"“Daling, yu yu stap long gudfala ples ya blong spel, plis mi wantem harem voes blong yu. Ol fren blong mi oli stap wet blong harem yu yu toktok.”","“Daling, yu yu stap long gudfala ples ya blong spel, plis mi wantem harem voes blong yu. Ol fren blong mi oli stap wet blong harem yu yu toktok.”"],[8,14,"Nao woman ya i talem se, “Daling, plis yu kam kwik long mi olsem anamol ya gasel,* yu spid olsem wan smol man dia* blong hil we i aot long ples blong ol lif ya we i gat gudfala smel, i stap kam.”","Nao woman ya i talem se, “Daling, plis yu kam kwik long mi olsem anamol ya gasel,* yu spid olsem wan smol man dia* blong hil we i aot long ples blong ol lif ya we i gat gudfala smel, i stap kam.”"]],"hbo-wlc":[[1,1,"שִׁ֥יר הַשִּׁירִ֖ים אֲשֶׁ֥ר לִשְׁלֹמֹֽה׃","şǐ֥yr haşi̇̌yri֖ym ʼàşě֥r lişĕ̌lòmòֽh׃"],[1,2,"יִשָּׁקֵ֙נִי֙ מִנְּשִׁיק֣וֹת פִּ֔יהוּ כִּֽי־טוֹבִ֥ים דֹּדֶ֖יךָ מִיָּֽיִן׃","yişá̇̌qé֙niy֙ minĕ̇şǐyq֣wòţ pi̇֔yhẇ kiֽ̇y-twòbi֥ym dò̇de֖yká miyáֽ̇yin׃"],[1,3,"לְרֵ֙יחַ֙ שְׁמָנֶ֣יךָ טוֹבִ֔ים שֶׁ֖מֶן תּוּרַ֣ק שְׁמֶ֑ךָ עַל־כֵּ֖ן עֲלָמ֥וֹת אֲהֵבֽוּךָ׃","lĕré֙yẖa֙ şĕ̌máne֣yká twòbi֔ym şě֖men ţ̇ẇra֣q şĕ̌me֑ká ʻal-ké֖̇n ʻàlám֥wòţ ʼàhébֽẇká׃"],[1,4,"מָשְׁכֵ֖נִי אַחֲרֶ֣יךָ נָּר֑וּצָה הֱבִיאַ֨נִי הַמֶּ֜לֶךְ חֲדָרָ֗יו נָגִ֤ילָה וְנִשְׂמְחָה֙ בָּ֔ךְ נַזְכִּ֤ירָה דֹדֶ֙יךָ֙ מִיַּ֔יִן מֵישָׁרִ֖ים אֲהֵבֽוּךָ׃ ס","máşĕ̌ké֖niy ʼaẖàre֣yká ná̇r֑ẇẕáh hèbiyʼa֨niy hamė֜lekĕ ẖàdárá֗yw nági֤yláh wĕnişĕ̂mĕẖáh֙ bá̇֔kĕ nazĕki֤̇yráh dòde֙yká֙ miyȧ֔yin méyşá̌ri֖ym ʼàhébֽẇká׃ s"],[1,5,"שְׁחוֹרָ֤ה אֲנִי֙ וְֽנָאוָ֔ה בְּנ֖וֹת יְרוּשָׁלִָ֑ם כְּאָהֳלֵ֣י קֵדָ֔ר כִּירִיע֖וֹת שְׁלֹמֹֽה׃","şĕ̌ẖwòrá֤h ʼàniy֙ wĕֽnáʼwá֔h bĕ̇n֖wòţ yĕrẇşá̌liá֑m kĕ̇ʼáholé֣y qédá֔r ki̇yriyʻ֖wòţ şĕ̌lòmòֽh׃"],[1,6,"אַל־תִּרְא֙וּנִי֙ שֶׁאֲנִ֣י שְׁחַרְחֹ֔רֶת שֶׁשֱּׁזָפַ֖תְנִי הַשָּׁ֑מֶשׁ בְּנֵ֧י אִמִּ֣י נִֽחֲרוּ־בִ֗י שָׂמֻ֙נִי֙ נֹטֵרָ֣ה אֶת־הַכְּרָמִ֔ים כַּרְמִ֥י שֶׁלִּ֖י לֹ֥א נָטָֽרְתִּי׃","ʼal-ţi̇rĕʼ֙ẇniy֙ şěʼàni֣y şĕ̌ẖarĕẖò֔reţ şěşè̇̌zápa֖ţĕniy haşá֑̇̌meş̌ bĕ̇né֧y ʼimi֣̇y niֽẖàrẇ-bi֗y şá̂mu֙niy֙ nòtérá֣h ʼeţ-hakĕ̇rámi֔ym kȧrĕmi֥y şěli֖̇y lò֥ʼ nátáֽrĕţi̇y׃"],[1,7,"הַגִּ֣ידָה לִּ֗י שֶׁ֤אָהֲבָה֙ נַפְשִׁ֔י אֵיכָ֣ה תִרְעֶ֔ה אֵיכָ֖ה תַּרְבִּ֣יץ בַּֽצָּהֳרָ֑יִם שַׁלָּמָ֤ה אֶֽהְיֶה֙ כְּעֹ֣טְיָ֔ה עַ֖ל עֶדְרֵ֥י חֲבֵרֶֽיךָ׃","hagi֣̇ydáh li̇֗y şě֤ʼáhàbáh֙ napĕşǐ֔y ʼéyká֣h ţirĕʻe֔h ʼéyká֖h ţȧrĕbi֣̇yẕ bȧֽẕá̇horá֑yim şǎlá̇má֤h ʼeֽhĕyeh֙ kĕ̇ʻò֣tĕyá֔h ʻa֖l ʻedĕré֥y ẖàbéreֽyká׃"],[1,8,"אִם־לֹ֤א תֵדְעִי֙ לָ֔ךְ הַיָּפָ֖ה בַּנָּשִׁ֑ים צְֽאִי־לָ֞ךְ בְּעִקְבֵ֣י הַצֹּ֗אן וּרְעִי֙ אֶת־גְּדִיֹּתַ֔יִךְ עַ֖ל מִשְׁכְּנ֥וֹת הָרֹעִֽים׃ ס","ʼim-lò֤ʼ ţédĕʻiy֙ lá֔kĕ hayá̇pá֖h bȧná̇şǐ֑ym ẕĕֽʼiy-lá֞kĕ bĕ̇ʻiqĕbé֣y haẕò̇֗ʼn ẇrĕʻiy֙ ʼeţ-gĕ̇diyò̇ţa֔yikĕ ʻa֖l mişĕ̌kĕ̇n֥wòţ háròʻiֽym׃ s"],[1,9,"לְסֻסָתִי֙ בְּרִכְבֵ֣י פַרְעֹ֔ה דִּמִּיתִ֖יךְ רַעְיָתִֽי׃","lĕsusáţiy֙ bĕ̇rikĕbé֣y parĕʻò֔h di̇mi̇yţi֖ykĕ raʻĕyáţiֽy׃"],[1,10,"נָאו֤וּ לְחָיַ֙יִךְ֙ בַּתֹּרִ֔ים צַוָּארֵ֖ךְ בַּחֲרוּזִֽים׃","náʼw֤ẇ lĕẖáya֙yikĕ֙ bȧţò̇ri֔ym ẕawá̇ʼré֖kĕ bȧẖàrẇziֽym׃"],[1,11,"תּוֹרֵ֤י זָהָב֙ נַעֲשֶׂה־לָּ֔ךְ עִ֖ם נְקֻדּ֥וֹת הַכָּֽסֶף׃","ţ̇wòré֤y záháb֙ naʻàşêh-lá̇֔kĕ ʻi֖m nĕquḋ֥wòţ hakáֽ̇sep׃"],[1,12,"עַד־שֶׁ֤הַמֶּ֙לֶךְ֙ בִּמְסִבּ֔וֹ נִרְדִּ֖י נָתַ֥ן רֵיחֽוֹ׃","ʻad-şě֤hamė֙lekĕ֙ bi̇mĕsiḃ֔wò nirĕdi֖̇y náţa֥n réyẖֽwò׃"],[1,13,"צְר֨וֹר הַמֹּ֤ר ׀ דּוֹדִי֙ לִ֔י בֵּ֥ין שָׁדַ֖י יָלִֽין׃","ẕĕr֨wòr hamò֤̇r ׀ ḋwòdiy֙ li֔y bé֥̇yn şá̌da֖y yáliֽyn׃"],[1,14,"אֶשְׁכֹּ֨ל הַכֹּ֤פֶר ׀ דּוֹדִי֙ לִ֔י בְּכַרְמֵ֖י עֵ֥ין גֶּֽדִי׃ ס","ʼeşĕ̌kò̇֨l hakò֤̇per ׀ ḋwòdiy֙ li֔y bĕ̇karĕmé֖y ʻé֥yn gėֽdiy׃ s"],[1,15,"הִנָּ֤ךְ יָפָה֙ רַעְיָתִ֔י הִנָּ֥ךְ יָפָ֖ה עֵינַ֥יִךְ יוֹנִֽים׃","hiná֤̇kĕ yápáh֙ raʻĕyáţi֔y hiná֥̇kĕ yápá֖h ʻéyna֥yikĕ ywòniֽym׃"],[1,16,"הִנְּךָ֨ יָפֶ֤ה דוֹדִי֙ אַ֣ף נָעִ֔ים אַף־עַרְשֵׂ֖נוּ רַעֲנָנָֽה׃","hinĕ̇ká֨ yápe֤h dwòdiy֙ ʼa֣p náʻi֔ym ʼap-ʻarĕşé֖̂nẇ raʻànánáֽh׃"],[1,17,"קֹר֤וֹת בָּתֵּ֙ינוּ֙ אֲרָזִ֔ים רחיטנו בְּרוֹתִֽים׃","qòr֤wòţ bá̇ţé̇֙ynẇ֙ ʼàrázi֔ym rẖytnw bĕ̇rwòţiֽym׃"],[2,1,"אֲנִי֙ חֲבַצֶּ֣לֶת הַשָּׁר֔וֹן שֽׁוֹשַׁנַּ֖ת הָעֲמָקִֽים׃","ʼàniy֙ ẖàbaẕė֣leţ haşá̇̌r֔wòn şֽ̌wòşǎnȧ֖ţ háʻàmáqiֽym׃"],[2,2,"כְּשֽׁוֹשַׁנָּה֙ בֵּ֣ין הַחוֹחִ֔ים כֵּ֥ן רַעְיָתִ֖י בֵּ֥ין הַבָּנֽוֹת׃","kĕ̇şֽ̌wòşǎná̇h֙ bé֣̇yn haẖwòẖi֔ym ké֥̇n raʻĕyáţi֖y bé֥̇yn habá̇nֽwòţ׃"],[2,3,"כְּתַפּ֙וּחַ֙ בַּעֲצֵ֣י הַיַּ֔עַר כֵּ֥ן דּוֹדִ֖י בֵּ֣ין הַבָּנִ֑ים בְּצִלּוֹ֙ חִמַּ֣דְתִּי וְיָשַׁ֔בְתִּי וּפִרְי֖וֹ מָת֥וֹק לְחִכִּֽי׃","kĕ̇ţaṗ֙ẇẖa֙ bȧʻàẕé֣y hayȧ֔ʻar ké֥̇n ḋwòdi֖y bé֣̇yn habá̇ni֑ym bĕ̇ẕil̇wò֙ ẖimȧ֣dĕţi̇y wĕyáşǎ֔bĕţi̇y ẇpirĕy֖wò máţ֥wòq lĕẖikiֽ̇y׃"],[2,4,"הֱבִיאַ֙נִי֙ אֶל־בֵּ֣ית הַיָּ֔יִן וְדִגְל֥וֹ עָלַ֖י אַהֲבָֽה׃","hèbiyʼa֙niy֙ ʼel-bé֣̇yţ hayá̇֔yin wĕdigĕl֥wò ʻála֖y ʼahàbáֽh׃"],[2,5,"סַמְּכ֙וּנִי֙ בָּֽאֲשִׁישׁ֔וֹת רַפְּד֖וּנִי בַּתַּפּוּחִ֑ים כִּי־חוֹלַ֥ת אַהֲבָ֖ה אָֽנִי׃","samĕ̇k֙ẇniy֙ báֽ̇ʼàşǐyş̌֔wòţ rapĕ̇d֖ẇniy bȧţȧṗẇẖi֑ym ki̇y-ẖwòla֥ţ ʼahàbá֖h ʼáֽniy׃"],[2,6,"שְׂמֹאלוֹ֙ תַּ֣חַת לְרֹאשִׁ֔י וִימִינ֖וֹ תְּחַבְּקֵֽנִי׃","şĕ̂mòʼlwò֙ ţȧ֣ẖaţ lĕròʼşǐ֔y wiymiyn֖wò ţĕ̇ẖabĕ̇qéֽniy׃"],[2,7,"הִשְׁבַּ֨עְתִּי אֶתְכֶ֜ם בְּנ֤וֹת יְרוּשָׁלִַ֙ם֙ בִּצְבָא֔וֹת א֖וֹ בְּאַיְל֣וֹת הַשָּׂדֶ֑ה אִם־תָּעִ֧ירוּ ׀ וְֽאִם־תְּעֽוֹרְר֛וּ אֶת־הָאַהֲבָ֖ה עַ֥ד שֶׁתֶּחְפָּֽץ׃ ס","hişĕ̌bȧ֨ʻĕţi̇y ʼeţĕke֜m bĕ̇n֤wòţ yĕrẇşá̌lia֙m֙ bi̇ẕĕbáʼ֔wòţ ʼ֖wò bĕ̇ʼayĕl֣wòţ haşá̇̂de֑h ʼim-ţá̇ʻi֧yrẇ ׀ wĕֽʼim-ţĕ̇ʻֽwòrĕr֛ẇ ʼeţ-háʼahàbá֖h ʻa֥d şěţėẖĕpáֽ̇ẕ׃ s"],[2,8,"ק֣וֹל דּוֹדִ֔י הִנֵּה־זֶ֖ה בָּ֑א מְדַלֵּג֙ עַל־הֶ֣הָרִ֔ים מְקַפֵּ֖ץ עַל־הַגְּבָעֽוֹת׃","q֣wòl ḋwòdi֔y hiné̇h-ze֖h bá֑̇ʼ mĕdalé̇g֙ ʻal-he֣hári֔ym mĕqapé֖̇ẕ ʻal-hagĕ̇báʻֽwòţ׃"],[2,9,"דּוֹמֶ֤ה דוֹדִי֙ לִצְבִ֔י א֖וֹ לְעֹ֣פֶר הָֽאַיָּלִ֑ים הִנֵּה־זֶ֤ה עוֹמֵד֙ אַחַ֣ר כָּתְלֵ֔נוּ מַשְׁגִּ֙יחַ֙ מִן־הַֽחֲלֹּנ֔וֹת מֵצִ֖יץ מִן־הַֽחֲרַכִּֽים׃","ḋwòme֤h dwòdiy֙ liẕĕbi֔y ʼ֖wò lĕʻò֣per háֽʼayá̇li֑ym hiné̇h-ze֤h ʻwòméd֙ ʼaẖa֣r ká̇ţĕlé֔nẇ maşĕ̌gi̇֙yẖa֙ min-haֽẖàlò̇n֔wòţ méẕi֖yẕ min-hֽaẖàrakiֽ̇ym׃"],[2,10,"עָנָ֥ה דוֹדִ֖י וְאָ֣מַר לִ֑י ק֥וּמִי לָ֛ךְ רַעְיָתִ֥י יָפָתִ֖י וּלְכִי־לָֽךְ׃","ʻáná֥h dwòdi֖y wĕʼá֣mar li֑y q֥ẇmiy lá֛kĕ raʻĕyáţi֥y yápáţi֖y ẇlĕkiy-láֽkĕ׃"],[2,11,"כִּֽי־הִנֵּ֥ה הסתו עָבָ֑ר הַגֶּ֕שֶׁם חָלַ֖ף הָלַ֥ךְ לֽוֹ׃","kiֽ̇y-hiné֥̇h hsţw ʻábá֑r hagė֕şěm ẖála֖p hála֥kĕ lֽwò׃"],[2,12,"הַנִּצָּנִים֙ נִרְא֣וּ בָאָ֔רֶץ עֵ֥ת הַזָּמִ֖יר הִגִּ֑יעַ וְק֥וֹל הַתּ֖וֹר נִשְׁמַ֥ע בְּאַרְצֵֽנוּ׃","hani̇ẕá̇niym֙ nirĕʼ֣ẇ báʼá֔reẕ ʻé֥ţ hazá̇mi֖yr higi֑̇yʻa wĕq֥wòl haţ֖̇wòr nişĕ̌ma֥ʻ bĕ̇ʼarĕẕéֽnẇ׃"],[2,13,"הַתְּאֵנָה֙ חָֽנְטָ֣ה פַגֶּ֔יהָ וְהַגְּפָנִ֥ים ׀ סְמָדַ֖ר נָ֣תְנוּ רֵ֑יחַ ק֥וּמִי לכי רַעְיָתִ֥י יָפָתִ֖י וּלְכִי־לָֽךְ׃ ס","haţĕ̇ʼénáh֙ ẖáֽnĕtá֣h pagė֔yhá wĕhagĕ̇páni֥ym ׀ sĕmáda֖r ná֣ţĕnẇ ré֑yẖa q֥ẇmiy lky raʻĕyáţi֥y yápáţi֖y ẇlĕkiy-láֽkĕ׃ s"],[2,14,"יוֹנָתִ֞י בְּחַגְוֵ֣י הַסֶּ֗לַע בְּסֵ֙תֶר֙ הַמַּדְרֵגָ֔ה הַרְאִ֙ינִי֙ אֶתּ־מַרְאַ֔יִךְ הַשְׁמִיעִ֖ינִי אֶת־קוֹלֵ֑ךְ כִּי־קוֹלֵ֥ךְ עָרֵ֖ב וּמַרְאֵ֥יךְ נָאוֶֽה׃ ס","ywònáţi֞y bĕ̇ẖagĕwé֣y hasė֗laʻ bĕ̇sé֙ţer֙ hamȧdĕrégá֔h harĕʼi֙yniy֙ ʼeţ̇-marĕʼa֔yikĕ haşĕ̌miyʻi֖yniy ʼeţ-qwòlé֑kĕ ki̇y-qwòlé֥kĕ ʻáré֖b ẇmarĕʼé֥ykĕ náʼweֽh׃ s"],[2,15,"אֶֽחֱזוּ־לָ֙נוּ֙ שֽׁוּעָלִ֔ים שֽׁוּעָלִ֥ים קְטַנִּ֖ים מְחַבְּלִ֣ים כְּרָמִ֑ים וּכְרָמֵ֖ינוּ סְמָדַֽר׃","ʼeֽẖèzẇ-lá֙nẇ֙ şֽ̌ẇʻáli֔ym şֽ̌ẇʻáli֥ym qĕtani֖̇ym mĕẖabĕ̇li֣ym kĕ̇rámi֑ym ẇkĕrámé֖ynẇ sĕmádaֽr׃"],[2,16,"דּוֹדִ֥י לִי֙ וַאֲנִ֣י ל֔וֹ הָרֹעֶ֖ה בַּשּׁוֹשַׁנִּֽים׃","ḋwòdi֥y liy֙ waʼàni֣y l֔wò háròʻe֖h bȧş̇̌wòşǎniֽ̇ym׃"],[2,17,"עַ֤ד שֶׁיָּפ֙וּחַ֙ הַיּ֔וֹם וְנָ֖סוּ הַצְּלָלִ֑ים סֹב֩ דְּמֵה־לְךָ֨ דוֹדִ֜י לִצְבִ֗י א֛וֹ לְעֹ֥פֶר הָאַיָּלִ֖ים עַל־הָ֥רֵי בָֽתֶר׃ ס","ʻa֤d şěyá̇p֙ẇẖa֙ haẏ֔wòm wĕná֖sẇ haẕĕ̇láli֑ym sòb֩ dĕ̇méh-lĕká֨ dwòdi֜y liẕĕbi֗y ʼ֛wò lĕʻò֥per háʼayá̇li֖ym ʻal-há֥réy báֽţer׃ s"],[3,1,"עַל־מִשְׁכָּבִי֙ בַּלֵּיל֔וֹת בִּקַּ֕שְׁתִּי אֵ֥ת שֶׁאָהֲבָ֖ה נַפְשִׁ֑י בִּקַּשְׁתִּ֖יו וְלֹ֥א מְצָאתִֽיו׃","ʻal-mişĕ̌ká̇biy֙ bȧlé̇yl֔wòţ bi̇qȧ֕şĕ̌ţi̇y ʼé֥ţ şěʼáhàbá֖h napĕşǐ֑y bi̇qȧşĕ̌ţi֖̇yw wĕlò֥ʼ mĕẕáʼţiֽyw׃"],[3,2,"אָק֨וּמָה נָּ֜א וַאֲסוֹבְבָ֣ה בָעִ֗יר בַּשְּׁוָקִים֙ וּבָ֣רְחֹב֔וֹת אֲבַקְשָׁ֕ה אֵ֥ת שֶׁאָהֲבָ֖ה נַפְשִׁ֑י בִּקַּשְׁתִּ֖יו וְלֹ֥א מְצָאתִֽיו׃","ʼáq֨ẇmáh ná̇֜ʼ waʼàswòbĕbá֣h báʻi֗yr bȧşĕ̇̌wáqiym֙ ẇbá֣rĕẖòb֔wòţ ʼàbaqĕşá̌֕h ʼé֥ţ şěʼáhàbá֖h napĕşǐ֑y bi̇qȧşĕ̌ţi֖̇yw wĕlò֥ʼ mĕẕáʼţiֽyw׃"],[3,3,"מְצָא֙וּנִי֙ הַשֹּׁ֣מְרִ֔ים הַסֹּבְבִ֖ים בָּעִ֑יר אֵ֛ת שֶׁאָהֲבָ֥ה נַפְשִׁ֖י רְאִיתֶֽם׃","mĕẕáʼ֙ẇniy֙ haşò֣̇̌mĕri֔ym hasò̇bĕbi֖ym bá̇ʻi֑yr ʼé֛ţ şěʼáhàbá֥h napĕşǐ֖y rĕʼiyţeֽm׃"],[3,4,"כִּמְעַט֙ שֶׁעָבַ֣רְתִּי מֵהֶ֔ם עַ֣ד שֶֽׁמָּצָ֔אתִי אֵ֥ת שֶׁאָהֲבָ֖ה נַפְשִׁ֑י אֲחַזְתִּיו֙ וְלֹ֣א אַרְפֶּ֔נּוּ עַד־שֶׁ֤הֲבֵיאתִיו֙ אֶל־בֵּ֣ית אִמִּ֔י וְאֶל־חֶ֖דֶר הוֹרָתִֽי׃","ki̇mĕʻat֙ şěʻába֣rĕţi̇y méhe֔m ʻa֣d şěֽmá̇ẕá֔ʼţiy ʼé֥ţ şěʼáhàbá֖h napĕşǐ֑y ʼàẖazĕţi̇yw֙ wĕlò֣ʼ ʼarĕpė֔ṅẇ ʻad-şě֤hàbéyʼţiyw֙ ʼel-bé֣̇yţ ʼimi̇֔y wĕʼel-ẖe֖der hwòráţiֽy׃"],[3,5,"הִשְׁבַּ֨עְתִּי אֶתְכֶ֜ם בְּנ֤וֹת יְרוּשָׁלִַ֙ם֙ בִּצְבָא֔וֹת א֖וֹ בְּאַיְל֣וֹת הַשָּׂדֶ֑ה אִם־תָּעִ֧ירוּ ׀ וְֽאִם־תְּעֽוֹרְר֛וּ אֶת־הָאַהֲבָ֖ה עַ֥ד שֶׁתֶּחְפָּֽץ׃ ס","hişĕ̌bȧ֨ʻĕţi̇y ʼeţĕke֜m bĕ̇n֤wòţ yĕrẇşá̌lia֙m֙ bi̇ẕĕbáʼ֔wòţ ʼ֖wò bĕ̇ʼayĕl֣wòţ haşá̇̂de֑h ʼim-ţá̇ʻi֧yrẇ ׀ wĕֽʼim-ţĕ̇ʻֽwòrĕr֛ẇ ʼeţ-háʼahàbá֖h ʻa֥d şěţėẖĕpáֽ̇ẕ׃ s"],[3,6,"מִ֣י זֹ֗את עֹלָה֙ מִן־הַמִּדְבָּ֔ר כְּתִֽימֲר֖וֹת עָשָׁ֑ן מְקֻטֶּ֤רֶת מוֹר֙ וּלְבוֹנָ֔ה מִכֹּ֖ל אַבְקַ֥ת רוֹכֵֽל׃","mi֣y zò֗ʼţ ʻòláh֙ min-hami̇dĕbá̇֔r kĕ̇ţiֽymàr֖wòţ ʻáşá֑̌n mĕqutė֤reţ mwòr֙ ẇlĕbwòná֔h mikò֖̇l ʼabĕqa֥ţ rwòkéֽl׃"],[3,7,"הִנֵּ֗ה מִטָּתוֹ֙ שֶׁלִּשְׁלֹמֹ֔ה שִׁשִּׁ֥ים גִּבֹּרִ֖ים סָבִ֣יב לָ֑הּ מִגִּבֹּרֵ֖י יִשְׂרָאֵֽל׃","hiné̇֗h mitá̇ţwò֙ şěli̇şĕ̌lòmò֔h şǐşi֥̇̌ym gi̇bò̇ri֖ym sábi֣yb lá֑ḣ migi̇bò̇ré֖y yişĕ̂ráʼéֽl׃"],[3,8,"כֻּלָּם֙ אֲחֻ֣זֵי חֶ֔רֶב מְלֻמְּדֵ֖י מִלְחָמָ֑ה אִ֤ישׁ חַרְבּוֹ֙ עַל־יְרֵכ֔וֹ מִפַּ֖חַד בַּלֵּילּֽוֹת׃ ס","ku̇lá̇m֙ ʼàẖu֣zéy ẖe֔reb mĕlumĕ̇dé֖y milĕẖámá֑h ʼi֤yş̌ ẖarĕḃwò֙ ʻal-yĕrék֔wò mipȧ֖ẖad bȧlé̇ylֽ̇wòţ׃ s"],[3,9,"אַפִּרְי֗וֹן עָ֤שָׂה לוֹ֙ הַמֶּ֣לֶךְ שְׁלֹמֹ֔ה מֵעֲצֵ֖י הַלְּבָנֽוֹן׃","ʼapi̇rĕy֗wòn ʻá֤şá̂h lwò֙ hamė֣lekĕ şĕ̌lòmò֔h méʻàẕé֖y halĕ̇bánֽwòn׃"],[3,10,"עַמּוּדָיו֙ עָ֣שָׂה כֶ֔סֶף רְפִידָת֣וֹ זָהָ֔ב מֶרְכָּב֖וֹ אַרְגָּמָ֑ן תּוֹכוֹ֙ רָצ֣וּף אַהֲבָ֔ה מִבְּנ֖וֹת יְרוּשָׁלִָֽם׃","ʻaṁẇdáyw֙ ʻá֣şá̂h ke֔sep rĕpiydáţ֣wò záhá֔b merĕká̇b֖wò ʼarĕgá̇má֑n ţ̇wòkwò֙ ráẕ֣ẇp ʼahàbá֔h mibĕ̇n֖wòţ yĕrẇşá̌liáֽm׃"],[3,11,"צְאֶ֧ינָה ׀ וּֽרְאֶ֛ינָה בְּנ֥וֹת צִיּ֖וֹן בַּמֶּ֣לֶךְ שְׁלֹמֹ֑ה בָּעֲטָרָ֗ה שֶׁעִטְּרָה־לּ֤וֹ אִמּוֹ֙ בְּי֣וֹם חֲתֻנָּת֔וֹ וּבְי֖וֹם שִׂמְחַ֥ת לִבּֽוֹ׃ ס","ẕĕʼe֧ynáh ׀ ẇֽrĕʼe֛ynáh bĕ̇n֥wòţ ẕiẏ֖wòn bȧmė֣lekĕ şĕ̌lòmò֑h bá̇ʻàtárá֗h şěʻitĕ̇ráh-l֤̇wò ʼiṁwò֙ bĕ̇y֣wòm ẖàţuná̇ţ֔wò ẇbĕy֖wòm şîmĕẖa֥ţ liḃֽwò׃ s"],[4,1,"הִנָּ֨ךְ יָפָ֤ה רַעְיָתִי֙ הִנָּ֣ךְ יָפָ֔ה עֵינַ֣יִךְ יוֹנִ֔ים מִבַּ֖עַד לְצַמָּתֵ֑ךְ שַׂעְרֵךְ֙ כְּעֵ֣דֶר הָֽעִזִּ֔ים שֶׁגָּלְשׁ֖וּ מֵהַ֥ר גִּלְעָֽד׃","hiná̇֨kĕ yápá֤h raʻĕyáţiy֙ hiná֣̇kĕ yápá֔h ʻéyna֣yikĕ ywòni֔ym mibȧ֖ʻad lĕẕamá̇ţé֑kĕ şâʻĕrékĕ֙ kĕ̇ʻé֣der háֽʻizi̇֔ym şěgá̇lĕş֖̌ẇ méha֥r gi̇lĕʻáֽd׃"],[4,2,"שִׁנַּ֙יִךְ֙ כְּעֵ֣דֶר הַקְּצוּב֔וֹת שֶׁעָל֖וּ מִן־הָרַחְצָ֑ה שֶׁכֻּלָּם֙ מַתְאִימ֔וֹת וְשַׁכֻּלָ֖ה אֵ֥ין בָּהֶֽם׃","şǐnȧ֙yikĕ֙ kĕ̇ʻé֣der haqĕ̇ẕẇb֔wòţ şěʻál֖ẇ min-háraẖĕẕá֑h şěku̇lá̇m֙ maţĕʼiym֔wòţ wĕşǎku̇lá֖h ʼé֥yn bá̇heֽm׃"],[4,3,"כְּח֤וּט הַשָּׁנִי֙ שִׂפְתֹתַ֔יִךְ וּמִדְבָּרֵ֖יךְ נָאוֶ֑ה כְּפֶ֤לַח הָֽרִמּוֹן֙ רַקָּתֵ֔ךְ מִבַּ֖עַד לְצַמָּתֵֽךְ׃","kĕ̇ẖ֤ẇt haşá̇̌niy֙ şîpĕţòţa֔yikĕ ẇmidĕbá̇ré֖ykĕ náʼwe֑h kĕ̇pe֤laẖ háֽriṁwòn֙ raqá̇ţé֔kĕ mibȧ֖ʻad lĕẕamá̇ţéֽkĕ׃"],[4,4,"כְּמִגְדַּ֤ל דָּוִיד֙ צַוָּארֵ֔ךְ בָּנ֖וּי לְתַלְפִּיּ֑וֹת אֶ֤לֶף הַמָּגֵן֙ תָּל֣וּי עָלָ֔יו כֹּ֖ל שִׁלְטֵ֥י הַגִּבּוֹרִֽים׃","kĕ̇migĕdȧ֤l dá̇wiyd֙ ẕawá̇ʼré֔kĕ bá̇n֖ẇy lĕţalĕpi̇ẏ֑wòţ ʼe֤lep hamá̇gén֙ ţá̇l֣ẇy ʻálá֔yw kò֖̇l şǐlĕté֥y hagi̇ḃwòriֽym׃"],[4,5,"שְׁנֵ֥י שָׁדַ֛יִךְ כִּשְׁנֵ֥י עֳפָרִ֖ים תְּאוֹמֵ֣י צְבִיָּ֑ה הָרוֹעִ֖ים בַּשּׁוֹשַׁנִּֽים׃","şĕ̌né֥y şá̌da֛yikĕ ki̇şĕ̌né֥y ʻopári֖ym ţĕ̇ʼwòmé֣y ẕĕbiyá֑̇h hárwòʻi֖ym bȧş̇̌wòşǎniֽ̇ym׃"],[4,6,"עַ֤ד שֶׁיָּפ֙וּחַ֙ הַיּ֔וֹם וְנָ֖סוּ הַצְּלָלִ֑ים אֵ֤לֶךְ לִי֙ אֶל־הַ֣ר הַמּ֔וֹר וְאֶל־גִּבְעַ֖ת הַלְּבוֹנָֽה׃","ʻa֤d şěyá̇p֙ẇẖa֙ haẏ֔wòm wĕná֖sẇ haẕĕ̇láli֑ym ʼé֤lekĕ liy֙ ʼel-ha֣r haṁ֔wòr wĕʼel-gi̇bĕʻa֖ţ halĕ̇bwònáֽh׃"],[4,7,"כֻּלָּ֤ךְ יָפָה֙ רַעְיָתִ֔י וּמ֖וּם אֵ֥ין בָּֽךְ׃ ס","ku̇lá֤̇kĕ yápáh֙ raʻĕyáţi֔y ẇm֖ẇm ʼé֥yn báֽ̇kĕ׃ s"],[4,8,"אִתִּ֤י מִלְּבָנוֹן֙ כַּלָּ֔ה אִתִּ֖י מִלְּבָנ֣וֹן תָּב֑וֹאִי תָּשׁ֣וּרִי ׀ מֵרֹ֣אשׁ אֲמָנָ֗ה מֵרֹ֤אשׁ שְׂנִיר֙ וְחֶרְמ֔וֹן מִמְּעֹנ֣וֹת אֲרָי֔וֹת מֵֽהַרְרֵ֖י נְמֵרִֽים׃","ʼiţi֤̇y milĕ̇bánwòn֙ kȧlá̇֔h ʼiţi֖̇y milĕ̇bán֣wòn ţá̇b֑wòʼiy ţá̇ş֣̌ẇriy ׀ mérò֣ʼş̌ ʼàmáná֗h mérò֤ʼş̌ şĕ̂niyr֙ wĕẖerĕm֔wòn mimĕ̇ʻòn֣wòţ ʼàráy֔wòţ méֽharĕré֖y nĕmériֽym׃"],[4,9,"לִבַּבְתִּ֖נִי אֲחֹתִ֣י כַלָּ֑ה לִבַּבְתִּ֙ינִי֙ באחד מֵעֵינַ֔יִךְ בְּאַחַ֥ד עֲנָ֖ק מִצַּוְּרֹנָֽיִךְ׃","libȧbĕţi֖̇niy ʼàẖòţi֣y kalá֑̇h libȧbĕţi̇֙yniy֙ bʼẖd méʻéyna֔yikĕ bĕ̇ʼaẖa֥d ʻàná֖q miẕȧwĕ̇rònáֽyikĕ׃"],[4,10,"מַה־יָּפ֥וּ דֹדַ֖יִךְ אֲחֹתִ֣י כַלָּ֑ה מַה־טֹּ֤בוּ דֹדַ֙יִךְ֙ מִיַּ֔יִן וְרֵ֥יחַ שְׁמָנַ֖יִךְ מִכָּל־בְּשָׂמִֽים׃","mah-yá̇p֥ẇ dòda֖yikĕ ʼàẖòţi֣y kalá֑̇h mah-tò֤̇bẇ dòda֙yikĕ֙ miyȧ֔yin wĕré֥yẖa şĕ̌mána֖yikĕ miká̇l-bĕ̇şá̂miֽym׃"],[4,11,"נֹ֛פֶת תִּטֹּ֥פְנָה שִׂפְתוֹתַ֖יִךְ כַּלָּ֑ה דְּבַ֤שׁ וְחָלָב֙ תַּ֣חַת לְשׁוֹנֵ֔ךְ וְרֵ֥יחַ שַׂלְמֹתַ֖יִךְ כְּרֵ֥יחַ לְבָנֽוֹן׃ ס","nò֛peţ ţi̇tò֥̇pĕnáh şîpĕţwòţa֖yikĕ kȧlá֑̇h dĕ̇ba֤ş̌ wĕẖáláb֙ ţȧ֣ẖaţ lĕş̌wòné֔kĕ wĕré֥yẖa şâlĕmòţa֖yikĕ kĕ̇ré֥yẖa lĕbánֽwòn׃ s"],[4,12,"גַּ֥ן ׀ נָע֖וּל אֲחֹתִ֣י כַלָּ֑ה גַּ֥ל נָע֖וּל מַעְיָ֥ן חָתֽוּם׃","gȧ֥n ׀ náʻ֖ẇl ʼàẖòţi֣y kalá֑̇h gȧ֥l náʻ֖ẇl maʻĕyá֥n ẖáţֽẇm׃"],[4,13,"שְׁלָחַ֙יִךְ֙ פַּרְדֵּ֣ס רִמּוֹנִ֔ים עִ֖ם פְּרִ֣י מְגָדִ֑ים כְּפָרִ֖ים עִם־נְרָדִֽים׃","şĕ̌láẖa֙yikĕ֙ pȧrĕdé֣̇s riṁwòni֔ym ʻi֖m pĕ̇ri֣y mĕgádi֑ym kĕ̇pári֖ym ʻim-nĕrádiֽym׃"],[4,14,"נֵ֣רְדְּ ׀ וְכַרְכֹּ֗ם קָנֶה֙ וְקִנָּמ֔וֹן עִ֖ם כָּל־עֲצֵ֣י לְבוֹנָ֑ה מֹ֚ר וַאֲהָל֔וֹת עִ֖ם כָּל־רָאשֵׁ֥י בְשָׂמִֽים׃","né֣rĕdĕ̇ ׀ wĕkarĕkò̇֗m qáneh֙ wĕqiná̇m֔wòn ʻi֖m ká̇l-ʻàẕé֣y lĕbwòná֑h mò֚r waʼàhál֔wòţ ʻi֖m ká̇l-ráʼşé֥̌y bĕşá̂miֽym׃"],[4,15,"מַעְיַ֣ן גַּנִּ֔ים בְּאֵ֖ר מַ֣יִם חַיִּ֑ים וְנֹזְלִ֖ים מִן־לְבָנֽוֹן׃","maʻĕya֣n gȧni̇֔ym bĕ̇ʼé֖r ma֣yim ẖayi֑̇ym wĕnòzĕli֖ym min-lĕbánֽwòn׃"],[4,16,"ע֤וּרִי צָפוֹן֙ וּב֣וֹאִי תֵימָ֔ן הָפִ֥יחִי גַנִּ֖י יִזְּל֣וּ בְשָׂמָ֑יו יָבֹ֤א דוֹדִי֙ לְגַנּ֔וֹ וְיֹאכַ֖ל פְּרִ֥י מְגָדָֽיו׃","ʻ֤ẇriy ẕápwòn֙ ẇb֣wòʼiy ţéymá֔n hápi֥yẖiy gani֖̇y yizĕ̇l֣ẇ bĕşá̂má֑yw yábò֤ʼ dwòdiy֙ lĕgaṅ֔wò wĕyòʼka֖l pĕ̇ri֥y mĕgádáֽyw׃"],[5,1,"בָּ֣אתִי לְגַנִּי֮ אֲחֹתִ֣י כַלָּה֒ אָרִ֤יתִי מוֹרִי֙ עִם־בְּשָׂמִ֔י אָכַ֤לְתִּי יַעְרִי֙ עִם־דִּבְשִׁ֔י שָׁתִ֥יתִי יֵינִ֖י עִם־חֲלָבִ֑י אִכְל֣וּ רֵעִ֔ים שְׁת֥וּ וְשִׁכְר֖וּ דּוֹדִֽים׃ ס","bá֣̇ʼţiy lĕgani̇y֮ ʼàẖòţi֣y kalá̇h֒ ʼári֤yţiy mwòriy֙ ʻim-bĕ̇şá̂mi֔y ʼáka֤lĕţi̇y yaʻĕriy֙ ʻim-di̇bĕşǐ֔y şá̌ţi֥yţiy yéyni֖y ʻim-ẖàlábi֑y ʼikĕl֣ẇ réʻi֔ym şĕ̌ţ֥ẇ wĕşǐkĕr֖ẇ ḋwòdiֽym׃ s"],[5,2,"אֲנִ֥י יְשֵׁנָ֖ה וְלִבִּ֣י עֵ֑ר ק֣וֹל ׀ דּוֹדִ֣י דוֹפֵ֗ק פִּתְחִי־לִ֞י אֲחֹתִ֤י רַעְיָתִי֙ יוֹנָתִ֣י תַמָּתִ֔י שֶׁרֹּאשִׁי֙ נִמְלָא־טָ֔ל קְוֻּצּוֹתַ֖י רְסִ֥יסֵי לָֽיְלָה׃","ʼàni֥y yĕşé̌ná֖h wĕlibi֣̇y ʻé֑r q֣wòl ׀ ḋwòdi֣y dwòpé֗q pi̇ţĕẖiy-li֞y ʼàẖòţi֤y raʻĕyáţiy֙ ywònáţi֣y ţamá̇ţi֔y şěrò̇ʼşǐy֙ nimĕláʼ-tá֔l qĕwu̇ẕ̇wòţa֖y rĕsi֥yséy láֽyĕláh׃"],[5,3,"פָּשַׁ֙טְתִּי֙ אֶת־כֻּתָּנְתִּ֔י אֵיכָ֖כָה אֶלְבָּשֶׁ֑נָּה רָחַ֥צְתִּי אֶת־רַגְלַ֖י אֵיכָ֥כָה אֲטַנְּפֵֽם׃","pá̇şǎ֙tĕţi̇y֙ ʼeţ-ku̇ţá̇nĕţi̇֔y ʼéyká֖káh ʼelĕbá̇şě֑ná̇h ráẖa֥ẕĕţi̇y ʼeţ-ragĕla֖y ʼéyká֥káh ʼàtanĕ̇péֽm׃"],[5,4,"דּוֹדִ֗י שָׁלַ֤ח יָדוֹ֙ מִן־הַחֹ֔ר וּמֵעַ֖י הָמ֥וּ עָלָֽיו׃","ḋwòdi֗y şá̌la֤ẖ yádwò֙ min-haẖò֔r ẇméʻa֖y hám֥ẇ ʻáláֽyw׃"],[5,5,"קַ֥מְתִּֽי אֲנִ֖י לִפְתֹּ֣חַ לְדוֹדִ֑י וְיָדַ֣י נָֽטְפוּ־מ֗וֹר וְאֶצְבְּעֹתַי֙ מ֣וֹר עֹבֵ֔ר עַ֖ל כַּפּ֥וֹת הַמַּנְעֽוּל׃","qa֥mĕţiֽ̇y ʼàni֖y lipĕţò֣̇ẖa lĕdwòdi֑y wĕyáda֣y náֽtĕpẇ-m֗wòr wĕʼeẕĕbĕ̇ʻòţay֙ m֣wòr ʻòbé֔r ʻa֖l kȧṗ֥wòţ hamȧnĕʻֽẇl׃"],[5,6,"פָּתַ֤חְתִּֽי אֲנִי֙ לְדוֹדִ֔י וְדוֹדִ֖י חָמַ֣ק עָבָ֑ר נַפְשִׁי֙ יָֽצְאָ֣ה בְדַבְּר֔וֹ בִּקַּשְׁתִּ֙יהוּ֙ וְלֹ֣א מְצָאתִ֔יהוּ קְרָאתִ֖יו וְלֹ֥א עָנָֽנִי׃","pá̇ţa֤ẖĕţiֽ̇y ʼàniy֙ lĕdwòdi֔y wĕdwòdi֖y ẖáma֣q ʻábá֑r napĕşǐy֙ yáֽẕĕʼá֣h bĕdabĕ̇r֔wò bi̇qȧşĕ̌ţi̇֙yhẇ֙ wĕlò֣ʼ mĕẕáʼţi֔yhẇ qĕráʼţi֖yw wĕlò֥ʼ ʻánáֽniy׃"],[5,7,"מְצָאֻ֧נִי הַשֹּׁמְרִ֛ים הַסֹּבְבִ֥ים בָּעִ֖יר הִכּ֣וּנִי פְצָע֑וּנִי נָשְׂא֤וּ אֶת־רְדִידִי֙ מֵֽעָלַ֔י שֹׁמְרֵ֖י הַחֹמֽוֹת׃","mĕẕáʼu֧niy haşò̇̌mĕri֛ym hasò̇bĕbi֥ym bá̇ʻi֖yr hik֣̇ẇniy pĕẕáʻ֑ẇniy náşĕ̂ʼ֤ẇ ʼeţ-rĕdiydiy֙ méֽʻála֔y şò̌mĕré֖y haẖòmֽwòţ׃"],[5,8,"הִשְׁבַּ֥עְתִּי אֶתְכֶ֖ם בְּנ֣וֹת יְרוּשָׁלִָ֑ם אִֽם־תִּמְצְאוּ֙ אֶת־דּוֹדִ֔י מַה־תַּגִּ֣ידוּ ל֔וֹ שֶׁחוֹלַ֥ת אַהֲבָ֖ה אָֽנִי׃","hişĕ̌bȧ֥ʻĕţi̇y ʼeţĕke֖m bĕ̇n֣wòţ yĕrẇşá̌liá֑m ʼiֽm-ţi̇mĕẕĕʼẇ֙ ʼeţ-ḋwòdi֔y mah-ţȧgi֣̇ydẇ l֔wò şěẖwòla֥ţ ʼahàbá֖h ʼáֽniy׃"],[5,9,"מַה־דּוֹדֵ֣ךְ מִדּ֔וֹד הַיָּפָ֖ה בַּנָּשִׁ֑ים מַה־דּוֹדֵ֣ךְ מִדּ֔וֹד שֶׁכָּ֖כָה הִשְׁבַּעְתָּֽנוּ׃","mah-ḋwòdé֣kĕ miḋ֔wòd hayá̇pá֖h bȧná̇şǐ֑ym mah-ḋwòdé֣kĕ miḋ֔wòd şěká֖̇káh hişĕ̌bȧʻĕţáֽ̇nẇ׃"],[5,10,"דּוֹדִ֥י צַח֙ וְאָד֔וֹם דָּג֖וּל מֵרְבָבָֽה׃","ḋwòdi֥y ẕaẖ֙ wĕʼád֔wòm dá̇g֖ẇl mérĕbábáֽh׃"],[5,11,"רֹאשׁ֖וֹ כֶּ֣תֶם פָּ֑ז קְוּצּוֹתָיו֙ תַּלְתַּלִּ֔ים שְׁחֹר֖וֹת כָּעוֹרֵֽב׃","ròʼş֖̌wò kė֣ţem pá֑̇z qĕẇẕ̇wòţáyw֙ ţȧlĕţȧli̇֔ym şĕ̌ẖòr֖wòţ ká̇ʻwòréֽb׃"],[5,12,"עֵינָ֕יו כְּיוֹנִ֖ים עַל־אֲפִ֣יקֵי מָ֑יִם רֹֽחֲצוֹת֙ בֶּֽחָלָ֔ב יֹשְׁב֖וֹת עַל־מִלֵּֽאת׃","ʻéyná֕yw kĕ̇ywòni֖ym ʻal-ʼàpi֣yqéy má֑yim ròֽẖàẕwòţ֙ bėֽẖálá֔b yòşĕ̌b֖wòţ ʻal-miléֽ̇ʼţ׃"],[5,13,"לְחָיָו֙ כַּעֲרוּגַ֣ת הַבֹּ֔שֶׂם מִגְדְּל֖וֹת מֶרְקָחִ֑ים שִׂפְתוֹתָיו֙ שֽׁוֹשַׁנִּ֔ים נֹטְפ֖וֹת מ֥וֹר עֹבֵֽר׃","lĕẖáyáw֙ kȧʻàrẇga֣ţ habò̇֔şêm migĕdĕ̇l֖wòţ merĕqáẖi֑ym şîpĕţwòţáyw֙ şֽ̌wòşǎni̇֔ym nòtĕp֖wòţ m֥wòr ʻòbéֽr׃"],[5,14,"יָדָיו֙ גְּלִילֵ֣י זָהָ֔ב מְמֻלָּאִ֖ים בַּתַּרְשִׁ֑ישׁ מֵעָיו֙ עֶ֣שֶׁת שֵׁ֔ן מְעֻלֶּ֖פֶת סַפִּירִֽים׃","yádáyw֙ gĕ̇liylé֣y záhá֔b mĕmulá̇ʼi֖ym bȧţȧrĕşǐ֑yş̌ méʻáyw֙ ʻe֣şěţ şé̌֔n mĕʻulė֖peţ sapi̇yriֽym׃"],[5,15,"שׁוֹקָיו֙ עַמּ֣וּדֵי שֵׁ֔שׁ מְיֻסָּדִ֖ים עַל־אַדְנֵי־פָ֑ז מַרְאֵ֙הוּ֙ כַּלְּבָנ֔וֹן בָּח֖וּר כָּאֲרָזִֽים׃","ş̌wòqáyw֙ ʻaṁ֣ẇdéy şé̌֔ş̌ mĕyusá̇di֖ym ʻal-ʼadĕnéy-pá֑z marĕʼé֙hẇ֙ kȧlĕ̇bán֔wòn bá̇ẖ֖ẇr ká̇ʼàráziֽym׃"],[5,16,"חִכּוֹ֙ מַֽמְתַקִּ֔ים וְכֻלּ֖וֹ מַחֲּמַדִּ֑ים זֶ֤ה דוֹדִי֙ וְזֶ֣ה רֵעִ֔י בְּנ֖וֹת יְרוּשָׁלִָֽם׃","ẖik̇wò֙ maֽmĕţaqi̇֔ym wĕkul֖̇wò maẖà̇madi֑̇ym ze֤h dwòdiy֙ wĕze֣h réʻi֔y bĕ̇n֖wòţ yĕrẇşá̌liáֽm׃"],[6,1,"אָ֚נָה הָלַ֣ךְ דּוֹדֵ֔ךְ הַיָּפָ֖ה בַּנָּשִׁ֑ים אָ֚נָה פָּנָ֣ה דוֹדֵ֔ךְ וּנְבַקְשֶׁ֖נּוּ עִמָּֽךְ׃","ʼá֚náh hála֣kĕ ḋwòdé֔kĕ hayá̇pá֖h bȧná̇şǐ֑ym ʼá֚náh pá̇ná֣h dwòdé֔kĕ ẇnĕbaqĕşě֖ṅẇ ʻimáֽ̇kĕ׃"],[6,2,"דּוֹדִי֙ יָרַ֣ד לְגַנּ֔וֹ לַעֲרוּג֖וֹת הַבֹּ֑שֶׂם לִרְעוֹת֙ בַּגַּנִּ֔ים וְלִלְקֹ֖ט שֽׁוֹשַׁנִּֽים׃","ḋwòdiy֙ yára֣d lĕgaṅ֔wò laʻàrẇg֖wòţ habò֑̇şêm lirĕʻwòţ֙ bȧgȧni̇֔ym wĕlilĕqò֖t şֽ̌wòşǎniֽ̇ym׃"],[6,3,"אֲנִ֤י לְדוֹדִי֙ וְדוֹדִ֣י לִ֔י הָרֹעֶ֖ה בַּשׁוֹשַׁנִּֽים׃ ס","ʼàni֤y lĕdwòdiy֙ wĕdwòdi֣y li֔y háròʻe֖h bȧş̌wòşǎniֽ̇ym׃ s"],[6,4,"יָפָ֨ה אַ֤תְּ רַעְיָתִי֙ כְּתִרְצָ֔ה נָאוָ֖ה כִּירוּשָׁלִָ֑ם אֲיֻמָּ֖ה כַּנִּדְגָּלֽוֹת׃","yápá֨h ʼa֤ţĕ̇ raʻĕyáţiy֙ kĕ̇ţirĕẕá֔h náʼwá֖h ki̇yrẇşá̌liá֑m ʼàyumá֖̇h kȧni̇dĕgá̇lֽwòţ׃"],[6,5,"הָסֵ֤בִּי עֵינַ֙יִךְ֙ מִנֶּגְדִּ֔י שֶׁ֥הֵ֖ם הִרְהִיבֻ֑נִי שַׂעְרֵךְ֙ כְּעֵ֣דֶר הָֽעִזִּ֔ים שֶׁגָּלְשׁ֖וּ מִן־הַגִּלְעָֽד ׃","hásé֤bi̇y ʻéyna֙yikĕ֙ minėgĕdi̇֔y şě֥hé֖m hirĕhiybu֑niy şâʻĕrékĕ֙ kĕ̇ʻé֣der háֽʻizi̇֔ym şěgá̇lĕş֖̌ẇ min-hagi̇lĕʻáֽd ׃"],[6,6,"שִׁנַּ֙יִךְ֙ כְּעֵ֣דֶר הָֽרְחֵלִ֔ים שֶׁעָל֖וּ מִן־הָרַחְצָ֑ה שֶׁכֻּלָּם֙ מַתְאִימ֔וֹת וְשַׁכֻּלָ֖ה אֵ֥ין בָּהֶֽם׃","şǐnȧ֙yikĕ֙ kĕ̇ʻé֣der hֽárĕẖéli֔ym şěʻál֖ẇ min-háraẖĕẕá֑h şěku̇lá̇m֙ maţĕʼiym֔wòţ wĕşǎku̇lá֖h ʼé֥yn bá̇heֽm׃"],[6,7,"כְּפֶ֤לַח הָרִמּוֹן֙ רַקָּתֵ֔ךְ מִבַּ֖עַד לְצַמָּתֵֽךְ׃","kĕ̇pe֤laẖ háriṁwòn֙ raqá̇ţé֔kĕ mibȧ֖ʻad lĕẕamá̇ţéֽkĕ׃"],[6,8,"שִׁשִּׁ֥ים הֵ֙מָּה֙ מְּלָכ֔וֹת וּשְׁמֹנִ֖ים פִּֽילַגְשִׁ֑ים וַעֲלָמ֖וֹת אֵ֥ין מִסְפָּֽר׃","şǐşi֥̇̌ym hé֙má̇h֙ mĕ̇lák֔wòţ ẇşĕ̌mòni֖ym piֽ̇ylagĕşǐ֑ym waʻàlám֖wòţ ʼé֥yn misĕpáֽ̇r׃"],[6,9,"אַחַ֥ת הִיא֙ יוֹנָתִ֣י תַמָּתִ֔י אַחַ֥ת הִיא֙ לְאִמָּ֔הּ בָּרָ֥ה הִ֖יא לְיֽוֹלַדְתָּ֑הּ רָא֤וּהָ בָנוֹת֙ וַֽיְאַשְּׁר֔וּהָ מְלָכ֥וֹת וּפִֽילַגְשִׁ֖ים וַֽיְהַלְלֽוּהָ׃ ס","ʼaẖa֥ţ hiyʼ֙ ywònáţi֣y ţamá̇ţi֔y ʼaẖa֥ţ hiyʼ֙ lĕʼimá̇֔ḣ bá̇rá֥h hi֖yʼ lĕyֽwòladĕţá֑̇ḣ ráʼ֤ẇhá bánwòţ֙ waֽyĕʼaşĕ̇̌r֔ẇhá mĕlák֥wòţ ẇpiֽylagĕşǐ֖ym waֽyĕhalĕlֽẇhá׃ s"],[6,10,"מִי־זֹ֥את הַנִּשְׁקָפָ֖ה כְּמוֹ־שָׁ֑חַר יָפָ֣ה כַלְּבָנָ֗ה בָּרָה֙ כַּֽחַמָּ֔ה אֲיֻמָּ֖ה כַּנִּדְגָּלֽוֹת׃ ס","miy-zò֥ʼţ hani̇şĕ̌qápá֖h kĕ̇mwò-şá֑̌ẖar yápá֣h kalĕ̇báná֗h bá̇ráh֙ kȧֽẖamá̇֔h ʼàyumá֖̇h kȧni̇dĕgá̇lֽwòţ׃ s"],[6,11,"אֶל־גִּנַּ֤ת אֱגוֹז֙ יָרַ֔דְתִּי לִרְא֖וֹת בְּאִבֵּ֣י הַנָּ֑חַל לִרְאוֹת֙ הֲפָֽרְחָ֣ה הַגֶּ֔פֶן הֵנֵ֖צוּ הָרִמֹּנִֽים׃","ʼel-gi̇nȧ֤ţ ʼègwòz֙ yára֔dĕţi̇y lirĕʼ֖wòţ bĕ̇ʼibé֣̇y haná֑̇ẖal lirĕʼwòţ֙ hàpáֽrĕẖá֣h hagė֔pen héné֖ẕẇ hárimò̇niֽym׃"],[6,12,"לֹ֣א יָדַ֔עְתִּי נַפְשִׁ֣י שָׂמַ֔תְנִי מַרְכְּב֖וֹת עַמִּי־נָדִֽיב׃","lò֣ʼ yáda֔ʻĕţi̇y napĕşǐ֣y şá̂ma֔ţĕniy marĕkĕ̇b֖wòţ ʻami̇y-nádiֽyb׃"],[7,1,"שׁ֤וּבִי שׁ֙וּבִי֙ הַשּׁ֣וּלַמִּ֔ית שׁ֥וּבִי שׁ֖וּבִי וְנֶחֱזֶה־בָּ֑ךְ מַֽה־תֶּחֱזוּ֙ בַּשּׁ֣וּלַמִּ֔ית כִּמְחֹלַ֖ת הַֽמַּחֲנָֽיִם׃","ş֤̌ẇbiy ş̌֙ẇbiy֙ haş֣̇̌ẇlami̇֔yţ ş֥̌ẇbiy ş֖̌ẇbiy wĕneẖèzeh-bá֑̇kĕ maֽh-ţėẖèzẇ֙ bȧş֣̇̌ẇlami̇֔yţ ki̇mĕẖòla֖ţ haֽmȧẖànáֽyim׃"],[7,2,"מַה־יָּפ֧וּ פְעָמַ֛יִךְ בַּנְּעָלִ֖ים בַּת־נָדִ֑יב חַמּוּקֵ֣י יְרֵכַ֔יִךְ כְּמ֣וֹ חֲלָאִ֔ים מַעֲשֵׂ֖ה יְדֵ֥י אָמָּֽן׃","mah-yá̇p֧ẇ pĕʻáma֛yikĕ bȧnĕ̇ʻáli֖ym bȧţ-nádi֑yb ẖaṁẇqé֣y yĕréka֔yikĕ kĕ̇m֣wò ẖàláʼi֔ym maʻàşé֖̂h yĕdé֥y ʼámáֽ̇n׃"],[7,3,"שָׁרְרֵךְ֙ אַגַּ֣ן הַסַּ֔הַר אַל־יֶחְסַ֖ר הַמָּ֑זֶג בִּטְנֵךְ֙ עֲרֵמַ֣ת חִטִּ֔ים סוּגָ֖ה בַּשּׁוֹשַׁנִּֽים׃","şá̌rĕrékĕ֙ ʼagȧ֣n hasȧ֔har ʼal-yeẖĕsa֖r hamá֑̇zeg bi̇tĕnékĕ֙ ʻàréma֣ţ ẖiti̇֔ym sẇgá֖h bȧş̇̌wòşǎniֽ̇ym׃"],[7,4,"שְׁנֵ֥י שָׁדַ֛יִךְ כִּשְׁנֵ֥י עֳפָרִ֖ים תָּאֳמֵ֥י צְבִיָּֽה׃","şĕ̌né֥y şá̌da֛yikĕ ki̇şĕ̌né֥y ʻopári֖ym ţá̇ʼomé֥y ẕĕbiyáֽ̇h׃"],[7,5,"צַוָּארֵ֖ךְ כְּמִגְדַּ֣ל הַשֵּׁ֑ן עֵינַ֜יִךְ בְּרֵכ֣וֹת בְּחֶשְׁבּ֗וֹן עַל־שַׁ֙עַר֙ בַּת־רַבִּ֔ים אַפֵּךְ֙ כְּמִגְדַּ֣ל הַלְּבָנ֔וֹן צוֹפֶ֖ה פְּנֵ֥י דַמָּֽשֶׂק׃","ẕawá̇ʼré֖kĕ kĕ̇migĕdȧ֣l haşé֑̇̌n ʻéyna֜yikĕ bĕ̇rék֣wòţ bĕ̇ẖeşĕ̌ḃ֗wòn ʻal-şǎ֙ʻar֙ bȧţ-rabi̇֔ym ʼapé̇kĕ֙ kĕ̇migĕdȧ֣l halĕ̇bán֔wòn ẕwòpe֖h pĕ̇né֥y damáֽ̇şêq׃"],[7,6,"רֹאשֵׁ֤ךְ עָלַ֙יִךְ֙ כַּכַּרְמֶ֔ל וְדַלַּ֥ת רֹאשֵׁ֖ךְ כָּאַרְגָּמָ֑ן מֶ֖לֶךְ אָס֥וּר בָּרְהָטִֽים׃","ròʼşé֤̌kĕ ʻála֙yikĕ֙ kȧkȧrĕme֔l wĕdalȧ֥ţ ròʼşé֖̌kĕ ká̇ʼarĕgá̇má֑n me֖lekĕ ʼás֥ẇr bá̇rĕhátiֽym׃"],[7,7,"מַה־יָּפִית֙ וּמַה־נָּעַ֔מְתְּ אַהֲבָ֖ה בַּתַּֽעֲנוּגִֽים׃","mah-yá̇piyţ֙ ẇmah-ná̇ʻa֔mĕţĕ̇ ʼahàbá֖h bȧţȧֽʻànẇgiֽym׃"],[7,8,"זֹ֤את קֽוֹמָתֵךְ֙ דָּֽמְתָ֣ה לְתָמָ֔ר וְשָׁדַ֖יִךְ לְאַשְׁכֹּלֽוֹת׃","zò֤ʼţ qֽwòmáţékĕ֙ dáֽ̇mĕţá֣h lĕţámá֔r wĕşá̌da֖yikĕ lĕʼaşĕ̌kò̇lֽwòţ׃"],[7,9,"אָמַ֙רְתִּי֙ אֶעֱלֶ֣ה בְתָמָ֔ר אֹֽחֲזָ֖ה בְּסַנְסִנָּ֑יו וְיִֽהְיוּ־נָ֤א שָׁדַ֙יִךְ֙ כְּאֶשְׁכְּל֣וֹת הַגֶּ֔פֶן וְרֵ֥יחַ אַפֵּ֖ךְ כַּתַּפּוּחִֽים׃","ʼáma֙rĕţi̇y֙ ʼeʻèle֣h bĕţámá֔r ʼòֽẖàzá֖h bĕ̇sanĕsiná֑̇yw wĕyiֽhĕyẇ-ná֤ʼ şá̌da֙yikĕ֙ kĕ̇ʼeşĕ̌kĕ̇l֣wòţ hagė֔pen wĕré֥yẖa ʼapé֖̇kĕ kȧţȧṗẇẖiֽym׃"],[7,10,"וְחִכֵּ֕ךְ כְּיֵ֥ין הַטּ֛וֹב הוֹלֵ֥ךְ לְדוֹדִ֖י לְמֵישָׁרִ֑ים דּוֹבֵ֖ב שִׂפְתֵ֥י יְשֵׁנִֽים׃","wĕẖiké̇֕kĕ kĕ̇yé֥yn haṫ֛wòb hwòlé֥kĕ lĕdwòdi֖y lĕméyşá̌ri֑ym ḋwòbé֖b şîpĕţé֥y yĕşé̌niֽym׃"],[7,11,"אֲנִ֣י לְדוֹדִ֔י וְעָלַ֖י תְּשׁוּקָתֽוֹ׃ ס","ʼàni֣y lĕdwòdi֔y wĕʻála֖y ţĕ̇ş̌ẇqáţֽwò׃ s"],[7,12,"לְכָ֤ה דוֹדִי֙ נֵצֵ֣א הַשָּׂדֶ֔ה נָלִ֖ינָה בַּכְּפָרִֽים׃","lĕká֤h dwòdiy֙ néẕé֣ʼ haşá̇̂de֔h náli֖ynáh bȧkĕ̇páriֽym׃"],[7,13,"נַשְׁכִּ֙ימָה֙ לַכְּרָמִ֔ים נִרְאֶ֞ה אִם פָּֽרְחָ֤ה הַגֶּ֙פֶן֙ פִּתַּ֣ח הַסְּמָדַ֔ר הֵנֵ֖צוּ הָרִמּוֹנִ֑ים שָׁ֛ם אֶתֵּ֥ן אֶת־דֹּדַ֖י לָֽךְ׃","naşĕ̌ki̇֙ymáh֙ lakĕ̇rámi֔ym nirĕʼe֞h ʼim páֽ̇rĕẖá֤h hagė֙pen֙ pi̇ţȧ֣ẖ hasĕ̇máda֔r héné֖ẕẇ háriṁwòni֑ym şá֛̌m ʼeţé֥̇n ʼeţ-dò̇da֖y láֽkĕ׃"],[7,14,"הַֽדּוּדָאִ֣ים נָֽתְנוּ־רֵ֗יחַ וְעַל־פְּתָחֵ֙ינוּ֙ כָּל־מְגָדִ֔ים חֲדָשִׁ֖ים גַּם־יְשָׁנִ֑ים דּוֹדִ֖י צָפַ֥נְתִּי לָֽךְ׃","haֽḋẇdáʼi֣ym náֽţĕnẇ-ré֗yẖa wĕʻal-pĕ̇ţáẖé֙ynẇ֙ ká̇l-mĕgádi֔ym ẖàdáşǐ֖ym gȧm-yĕşá̌ni֑ym ḋwòdi֖y ẕápa֥nĕţi̇y láֽkĕ׃"],[8,1,"מִ֤י יִתֶּנְךָ֙ כְּאָ֣ח לִ֔י יוֹנֵ֖ק שְׁדֵ֣י אִמִּ֑י אֶֽמְצָאֲךָ֤ בַחוּץ֙ אֶשָׁ֣קְךָ֔ גַּ֖ם לֹא־יָב֥וּזוּ לִֽי׃","mi֤y yiţėnĕká֙ kĕ̇ʼá֣ẖ li֔y ywòné֖q şĕ̌dé֣y ʼimi֑̇y ʼeֽmĕẕáʼàká֤ baẖẇẕ֙ ʼeşá֣̌qĕká֔ gȧ֖m lòʼ-yáb֥ẇzẇ liֽy׃"],[8,2,"אֶנְהָֽגֲךָ֗ אֲבִֽיאֲךָ֛ אֶל־בֵּ֥ית אִמִּ֖י תְּלַמְּדֵ֑נִי אַשְׁקְךָ֙ מִיַּ֣יִן הָרֶ֔קַח מֵעֲסִ֖יס רִמֹּנִֽי׃","ʼenĕháֽgàká֗ ʼàbiֽyʼàká֛ ʼel-bé֥̇yţ ʼimi֖̇y ţĕ̇lamĕ̇dé֑niy ʼaşĕ̌qĕká֙ miyȧ֣yin háre֔qaẖ méʻàsi֖ys rimò̇niֽy׃"],[8,3,"שְׂמֹאלוֹ֙ תַּ֣חַת רֹאשִׁ֔י וִֽימִינ֖וֹ תְּחַבְּקֵֽנִי׃","şĕ̂mòʼlwò֙ ţȧ֣ẖaţ ròʼşǐ֔y wiֽymiyn֖wò ţĕ̇ẖabĕ̇qéֽniy׃"],[8,4,"הִשְׁבַּ֥עְתִּי אֶתְכֶ֖ם בְּנ֣וֹת יְרוּשָׁלִָ֑ם מַה־תָּעִ֧ירוּ ׀ וּֽמַה־תְּעֹֽרְר֛וּ אֶת־הָאַהֲבָ֖ה עַ֥ד שֶׁתֶּחְפָּֽץ׃ ס","hişĕ̌bȧ֥ʻĕţi̇y ʼeţĕke֖m bĕ̇n֣wòţ yĕrẇşá̌liá֑m mah-ţá̇ʻi֧yrẇ ׀ ẇֽmah-ţĕ̇ʻòֽrĕr֛ẇ ʼeţ-háʼahàbá֖h ʻa֥d şěţėẖĕpáֽ̇ẕ׃ s"],[8,5,"מִ֣י זֹ֗את עֹלָה֙ מִן־הַמִּדְבָּ֔ר מִתְרַפֶּ֖קֶת עַל־דּוֹדָ֑הּ תַּ֤חַת הַתַּפּ֙וּחַ֙ עֽוֹרַרְתִּ֔יךָ שָׁ֚מָּה חִבְּלַ֣תְךָ אִמֶּ֔ךָ שָׁ֖מָּה חִבְּלָ֥ה יְלָדַֽתְךָ׃","mi֣y zò֗ʼţ ʻòláh֙ min-hami̇dĕbá̇֔r miţĕrapė֖qeţ ʻal-ḋwòdá֑ḣ ţȧ֤ẖaţ haţȧṗ֙ẇẖa֙ ʻֽwòrarĕţi̇֔yká şá֚̌má̇h ẖibĕ̇la֣ţĕká ʼimė֔ká şá֖̌má̇h ẖibĕ̇lá֥h yĕládaֽţĕká׃"],[8,6,"שִׂימֵ֨נִי כַֽחוֹתָ֜ם עַל־לִבֶּ֗ךָ כַּֽחוֹתָם֙ עַל־זְרוֹעֶ֔ךָ כִּֽי־עַזָּ֤ה כַמָּ֙וֶת֙ אַהֲבָ֔ה קָשָׁ֥ה כִשְׁא֖וֹל קִנְאָ֑ה רְשָׁפֶ֕יהָ רִשְׁפֵּ֕י אֵ֖שׁ שַׁלְהֶ֥בֶתְיָֽה׃","şîymé֨niy kaֽẖwòţá֜m ʻal-libė֗ká kȧֽẖwòţám֙ ʻal-zĕrwòʻe֔ká kiֽ̇y-ʻazá֤̇h kamá̇֙weţ֙ ʼahàbá֔h qáşá֥̌h kişĕ̌ʼ֖wòl qinĕʼá֑h rĕşá̌pe֕yhá rişĕ̌pé̇֕y ʼé֖ş̌ şǎlĕhe֥beţĕyáֽh׃"],[8,7,"מַ֣יִם רַבִּ֗ים לֹ֤א יֽוּכְלוּ֙ לְכַבּ֣וֹת אֶת־הָֽאַהֲבָ֔ה וּנְהָר֖וֹת לֹ֣א יִשְׁטְפ֑וּהָ אִם־יִתֵּ֨ן אִ֜ישׁ אֶת־כָּל־ה֤וֹן בֵּיתוֹ֙ בָּאַהֲבָ֔ה בּ֖וֹז יָב֥וּזוּ לֽוֹ׃ ס","ma֣yim rabi̇֗ym lò֤ʼ yֽẇkĕlẇ֙ lĕkaḃ֣wòţ ʼeţ-háֽʼahàbá֔h ẇnĕhár֖wòţ lò֣ʼ yişĕ̌tĕp֑ẇhá ʼim-yiţé̇֨n ʼi֜yş̌ ʼeţ-ká̇l-h֤wòn bé̇yţwò֙ bá̇ʼahàbá֔h ḃ֖wòz yáb֥ẇzẇ lֽwò׃ s"],[8,8,"אָח֥וֹת לָ֙נוּ֙ קְטַנָּ֔ה וְשָׁדַ֖יִם אֵ֣ין לָ֑הּ מַֽה־נַּעֲשֶׂה֙ לַאֲחֹתֵ֔נוּ בַּיּ֖וֹם שֶׁיְּדֻבַּר־בָּֽהּ׃","ʼáẖ֥wòţ lá֙nẇ֙ qĕtaná̇֔h wĕşá̌da֖yim ʼé֣yn lá֑ḣ maֽh-nȧʻàşêh֙ laʼàẖòţé֔nẇ bȧẏ֖wòm şěyĕ̇dubȧr-báֽ̇ḣ׃"],[8,9,"אִם־חוֹמָ֣ה הִ֔יא נִבְנֶ֥ה עָלֶ֖יהָ טִ֣ירַת כָּ֑סֶף וְאִם־דֶּ֣לֶת הִ֔יא נָצ֥וּר עָלֶ֖יהָ ל֥וּחַ אָֽרֶז׃","ʼim-ẖwòmá֣h hi֔yʼ nibĕne֥h ʻále֖yhá ti֣yraţ ká֑̇sep wĕʼim-dė֣leţ hi֔yʼ náẕ֥ẇr ʻále֖yhá l֥ẇẖa ʼáֽrez׃"],[8,10,"אֲנִ֣י חוֹמָ֔ה וְשָׁדַ֖י כַּמִּגְדָּל֑וֹת אָ֛ז הָיִ֥יתִי בְעֵינָ֖יו כְּמוֹצְאֵ֥ת שָׁלֽוֹם׃ פ","ʼàni֣y ẖwòmá֔h wĕşá̌da֖y kȧmi̇gĕdá̇l֑wòţ ʼá֛z háyi֥yţiy bĕʻéyná֖yw kĕ̇mwòẕĕʼé֥ţ şá̌lֽwòm׃ p"],[8,11,"כֶּ֣רֶם הָיָ֤ה לִשְׁלֹמֹה֙ בְּבַ֣עַל הָמ֔וֹן נָתַ֥ן אֶת־הַכֶּ֖רֶם לַנֹּטְרִ֑ים אִ֛ישׁ יָבִ֥א בְּפִרְי֖וֹ אֶ֥לֶף כָּֽסֶף׃","kė֣rem háyá֤h lişĕ̌lòmòh֙ bĕ̇ba֣ʻal hám֔wòn náţa֥n ʼeţ-hakė֖rem lanò̇tĕri֑ym ʼi֛yş̌ yábi֥ʼ bĕ̇pirĕy֖wò ʼe֥lep káֽ̇sep׃"],[8,12,"כָּרְמִ֥י שֶׁלִּ֖י לְפָנָ֑י הָאֶ֤לֶף לְךָ֙ שְׁלֹמֹ֔ה וּמָאתַ֖יִם לְנֹטְרִ֥ים אֶת־פִּרְיֽוֹ׃","ká̇rĕmi֥y şěli֖̇y lĕpáná֑y háʼe֤lep lĕká֙ şĕ̌lòmò֔h ẇmáʼţa֖yim lĕnòtĕri֥ym ʼeţ-pi̇rĕyֽwò׃"],[8,13,"הַיוֹשֶׁ֣בֶת בַּגַּנִּ֗ים חֲבֵרִ֛ים מַקְשִׁיבִ֥ים לְקוֹלֵ֖ךְ הַשְׁמִיעִֽינִי׃","haywòşě֣beţ bȧgȧni̇֗ym ẖàbéri֛ym maqĕşǐybi֥ym lĕqwòlé֖kĕ haşĕ̌miyʻiֽyniy׃"],[8,14,"בְּרַ֣ח ׀ דּוֹדִ֗י וּֽדְמֵה־לְךָ֤ לִצְבִי֙ א֚וֹ לְעֹ֣פֶר הָֽאַיָּלִ֔ים עַ֖ל הָרֵ֥י בְשָׂמִֽים׃","bĕ̇ra֣ẖ ׀ ḋwòdi֗y ẇֽdĕméh-lĕká֤ liẕĕbiy֙ ʼ֚wò lĕʻò֣per háֽʼayá̇li֔ym ʻa֖l háré֥y bĕşá̂miֽym׃"]],"fra-giguet-lxx":[[1,1,"Cantique des cantiques, qui est de Salomon. Qu’il me baise des baisers de sa bouche; car tes mamelles sont meilleures que le vin.","Cantique des cantiques, qui est de Salomon. Qu’il me baise des baisers de sa bouche; car tes mamelles sont meilleures que le vin."],[1,2,"Et la senteur de tes parfums l’emporte sur tous les aromates; ton nom est l’essence de parfum: voilà pourquoi les jeunes filles t’aiment.","Et la senteur de tes parfums l’emporte sur tous les aromates; ton nom est l’essence de parfum: voilà pourquoi les jeunes filles t’aiment."],[1,3,"Elles t’attirent, et à ta suite nous courons aux senteurs de tes parfums. Le roi m’a introduite dans sa chambre secrète; nous tressaillirons, nous nous réjouirons en toi; nous aimerons tes mamelles plus que le vin; la droiture te chérit.","Elles t’attirent, et à ta suite nous courons aux senteurs de tes parfums. Le roi m’a introduite dans sa chambre secrète; nous tressaillirons, nous nous réjouirons en toi; nous aimerons tes mamelles plus que le vin; la droiture te chérit."],[1,4,"Filles de Jérusalem, je suis noire, et je suis belle, comme les tentes de Cédar, comme les tentures de Salomon.","Filles de Jérusalem, je suis noire, et je suis belle, comme les tentes de Cédar, comme les tentures de Salomon."],[1,5,"Ne me dédaignez pas, parce que je suis noire; c’est que le soleil a altéré ma couleur. Les fils de ma mère se sont levés contre moi; ils m’avaient fait la gardienne des vignes, et ma propre vigne, je ne l’ai point gardée.","Ne me dédaignez pas, parce que je suis noire; c’est que le soleil a altéré ma couleur. Les fils de ma mère se sont levés contre moi; ils m’avaient fait la gardienne des vignes, et ma propre vigne, je ne l’ai point gardée."],[1,6,"O toi que mon âme a aimé, indique-moi où tu pais ton troupeau, où tu reposes à midi, de peur que peut-être je ne m’égare à la suite des troupeaux de tes compagnons.","O toi que mon âme a aimé, indique-moi où tu pais ton troupeau, où tu reposes à midi, de peur que peut-être je ne m’égare à la suite des troupeaux de tes compagnons."],[1,7,"O toi, la plus belle des femmes, si tu ne te connais toi-même, suis les traces de mes troupeaux, et pais tes chevreaux près des tentes de mes pasteurs.","O toi, la plus belle des femmes, si tu ne te connais toi-même, suis les traces de mes troupeaux, et pais tes chevreaux près des tentes de mes pasteurs."],[1,8,"Ma bien-aimée, je t’ai comparée à mes cavales attelées aux chars de Pharaon.","Ma bien-aimée, je t’ai comparée à mes cavales attelées aux chars de Pharaon."],[1,9,"Tes joues, elles sont belles comme la colombe, et ton cou, comme un collier.","Tes joues, elles sont belles comme la colombe, et ton cou, comme un collier."],[1,10,"Nous te ferons des ornements d’or émaillés d’argent.","Nous te ferons des ornements d’or émaillés d’argent."],[1,11,"Aussi longtemps que le roi a été à table, mon nard a répandu son parfum.","Aussi longtemps que le roi a été à table, mon nard a répandu son parfum."],[1,12,"Mon frère bien-aimé est pour moi un bouquet de myrrhe; il reposera entre mes mamelles.","Mon frère bien-aimé est pour moi un bouquet de myrrhe; il reposera entre mes mamelles."],[1,13,"Mon frère bien-aimé est pour moi une grappe en fleur dans la vigne d’Engaddi.","Mon frère bien-aimé est pour moi une grappe en fleur dans la vigne d’Engaddi."],[1,14,"Que tu es belle, ô ma bien-aimée, que tu es belle! Tes yeux sont ceux d’une colombe.","Que tu es belle, ô ma bien-aimée, que tu es belle! Tes yeux sont ceux d’une colombe."],[1,15,"Et toi, que tu es beau, mon frère bien-aimé! que tu es charmant à l’ombre de notre couche!","Et toi, que tu es beau, mon frère bien-aimé! que tu es charmant à l’ombre de notre couche!"],[1,16,"Les solives de vos demeures sont de cèdre, et ses lambris de cyprès.","Les solives de vos demeures sont de cèdre, et ses lambris de cyprès."],[2,1,"Je suis la fleur des champs et le lis des vallées.","Je suis la fleur des champs et le lis des vallées."],[2,2,"Comme le lis des vallées au milieu des épines, est ainsi ma bien-aimée au milieu des jeunes filles.","Comme le lis des vallées au milieu des épines, est ainsi ma bien-aimée au milieu des jeunes filles."],[2,3,"Comme le pommier parmi les arbres de la forêt, ainsi est mon frère bien-aimé parmi les jeunes hommes. J’ai désiré son ombre, et je m’y suis assise, et son fruit est doux à mon palais.","Comme le pommier parmi les arbres de la forêt, ainsi est mon frère bien-aimé parmi les jeunes hommes. J’ai désiré son ombre, et je m’y suis assise, et son fruit est doux à mon palais."],[2,4,"Introduisez-moi dans le cellier au vin; faites-y venir ma bien-aimée.","Introduisez-moi dans le cellier au vin; faites-y venir ma bien-aimée."],[2,5,"Soutenez-moi avec des parfums; entourez-moi de fruits, car je suis blessée d’amour.","Soutenez-moi avec des parfums; entourez-moi de fruits, car je suis blessée d’amour."],[2,6,"Sa main gauche sera sous ma tête, et de sa droite il m’embrassera.","Sa main gauche sera sous ma tête, et de sa droite il m’embrassera."],[2,7,"Filles de Jérusalem, je vous adjure, par les puissances et les vertus de la campagne, n’éveillez pas, ne réveillez pas ma bien-aimée, qu’elle-même ne le désire.","Filles de Jérusalem, je vous adjure, par les puissances et les vertus de la campagne, n’éveillez pas, ne réveillez pas ma bien-aimée, qu’elle-même ne le désire."],[2,8,"C’est la voix de mon bien-aimé; le voilà qui vient en bondissant sur les monts, en franchissant les collines.","C’est la voix de mon bien-aimé; le voilà qui vient en bondissant sur les monts, en franchissant les collines."],[2,9,"Mon frère bien-aimé ressemble au chevreuil ou au jeune faon sur les montagnes de Béthel. Le voilà derrière notre mur; il se penche par la fenêtre, il regarde à travers le treillis.","Mon frère bien-aimé ressemble au chevreuil ou au jeune faon sur les montagnes de Béthel. Le voilà derrière notre mur; il se penche par la fenêtre, il regarde à travers le treillis."],[2,10,"Mon frère bien-aimé me parle, et me dit: Lève-toi, ma bien-aimée; viens, ô ma belle, ô ma colombe.","Mon frère bien-aimé me parle, et me dit: Lève-toi, ma bien-aimée; viens, ô ma belle, ô ma colombe."],[2,11,"Car voilà que l’hiver est passé; la pluie s’en est allée, elle est partie.","Car voilà que l’hiver est passé; la pluie s’en est allée, elle est partie."],[2,12,"Les fleurs se montrent sur la terre; le temps de tailler est venu; le roucoulement de la tourterelle s’entend sur notre terre.","Les fleurs se montrent sur la terre; le temps de tailler est venu; le roucoulement de la tourterelle s’entend sur notre terre."],[2,13,"Les jeunes figues montrent leurs bourgeons; les vignes sont en fleur et donnent leur parfum. Lève-toi, ma bien-aimée; viens, ô ma belle, ô ma colombe. Viens,","Les jeunes figues montrent leurs bourgeons; les vignes sont en fleur et donnent leur parfum. Lève-toi, ma bien-aimée; viens, ô ma belle, ô ma colombe. Viens,"],[2,14,"Toi ma colombe, à l’abri sous les roches, dans le creux des murs. Montre-moi ton visage, que j’entende ta voix; car ta voix est douce, et ton visage est plein de grâces.","Toi ma colombe, à l’abri sous les roches, dans le creux des murs. Montre-moi ton visage, que j’entende ta voix; car ta voix est douce, et ton visage est plein de grâces."],[2,15,"Prenez les jeunes renards, qui ravagent les vignes, quand nos vignes sont en fleur.","Prenez les jeunes renards, qui ravagent les vignes, quand nos vignes sont en fleur."],[2,16,"Mon frère bien-aimé est à moi, et moi à lui; et il fait paître son troupeau parmi les lis,","Mon frère bien-aimé est à moi, et moi à lui; et il fait paître son troupeau parmi les lis,"],[2,17,"Jusqu’à ce que se lèvent les premières brises du jour et que les ténèbres se dissipent. Reviens, mon frère bien-aimé; accours comme le chevreuil ou le jeune faon sur les ravins des montagnes.","Jusqu’à ce que se lèvent les premières brises du jour et que les ténèbres se dissipent. Reviens, mon frère bien-aimé; accours comme le chevreuil ou le jeune faon sur les ravins des montagnes."],[3,1,"Sur ma couche, la nuit, j’ai désiré celui qu’aime mon âme; je l’ai cherché, et ne l’ai point trouvé; je l’ai appelé, et il ne m’a pas écouté.","Sur ma couche, la nuit, j’ai désiré celui qu’aime mon âme; je l’ai cherché, et ne l’ai point trouvé; je l’ai appelé, et il ne m’a pas écouté."],[3,2,"Je me lèverai donc; j’irai par la ville, les marchés, les places, et je chercherai celui qu’aime mon âme. Je l’ai cherché, et ne l’ai point trouvé.","Je me lèverai donc; j’irai par la ville, les marchés, les places, et je chercherai celui qu’aime mon âme. Je l’ai cherché, et ne l’ai point trouvé."],[3,3,"Les gardiens m’ont rencontrée, en faisant la ronde dans la ville N’avez-vous pas vu celui qu’aime mon âme?","Les gardiens m’ont rencontrée, en faisant la ronde dans la ville N’avez-vous pas vu celui qu’aime mon âme?"],[3,4,"A peine éloignée d’eux, j’ai trouvé celui qu’aime mon âme; je l’ai pris par la main, et ne l’ai point quitté que je ne l’eusse introduit dans la maison de ma mère, dans la chambre de celle qui m’a conçue.","A peine éloignée d’eux, j’ai trouvé celui qu’aime mon âme; je l’ai pris par la main, et ne l’ai point quitté que je ne l’eusse introduit dans la maison de ma mère, dans la chambre de celle qui m’a conçue."],[3,5,"Filles de Jérusalem, je vous adjure par les puissances et les vertus des campagnes, n’éveillez pas, ne réveillez pas ma bien-aimée, qu’elle ne le désire.","Filles de Jérusalem, je vous adjure par les puissances et les vertus des campagnes, n’éveillez pas, ne réveillez pas ma bien-aimée, qu’elle ne le désire."],[3,6,"Qui est celle qui monte du désert, comme une colonne de fumée sortant de l’encens et de la myrrhe, et de toutes les poudres dont se composent les parfums?","Qui est celle qui monte du désert, comme une colonne de fumée sortant de l’encens et de la myrrhe, et de toutes les poudres dont se composent les parfums?"],[3,7,"Voilà la couche de Salomon; soixante vaillants des forts d’Israël sont rangés en cercle autour d’elle.","Voilà la couche de Salomon; soixante vaillants des forts d’Israël sont rangés en cercle autour d’elle."],[3,8,"Tous exercés aux combats, ils ont l’épée au côté, pour en écarter les terreurs de la nuit.","Tous exercés aux combats, ils ont l’épée au côté, pour en écarter les terreurs de la nuit."],[3,9,"Le roi Salomon s’est fait un lit de cèdres du Liban.","Le roi Salomon s’est fait un lit de cèdres du Liban."],[3,10,"Les montants en sont d’argent, et le siège d’or; le marchepied est de porphyre, et l’intérieur est pavé de pierres précieuses, amour des filles de Jérusalem.","Les montants en sont d’argent, et le siège d’or; le marchepied est de porphyre, et l’intérieur est pavé de pierres précieuses, amour des filles de Jérusalem."],[3,11,"Filles de Sion, sortez, contemplez le roi Salomon avec la couronne que lui a posée sa mère le jour de son mariage, le jour de la joie de son cœur.","Filles de Sion, sortez, contemplez le roi Salomon avec la couronne que lui a posée sa mère le jour de son mariage, le jour de la joie de son cœur."],[4,1,"Que tu es belle, ô ma bien-aimée! que tu es belle! Tes yeux sont ceux des colombes, sans parler de tes beautés cachées. Ta chevelure est comme la toison des troupeaux de chèvres qu’on voit en Galaad.","Que tu es belle, ô ma bien-aimée! que tu es belle! Tes yeux sont ceux des colombes, sans parler de tes beautés cachées. Ta chevelure est comme la toison des troupeaux de chèvres qu’on voit en Galaad."],[4,2,"Tes dents sont comme la laine des brebis sortant du lavoir après la tonte; toutes ont deux petits, et nulle n’est stérile.","Tes dents sont comme la laine des brebis sortant du lavoir après la tonte; toutes ont deux petits, et nulle n’est stérile."],[4,3,"Tes lèvres sont comme un ruban écarlate, et ton langage est plein de grâce; tes joues sont comme la peau de la grenade, sans parler de tes beautés cachées.","Tes lèvres sont comme un ruban écarlate, et ton langage est plein de grâce; tes joues sont comme la peau de la grenade, sans parler de tes beautés cachées."],[4,4,"Ton cou est comme la tour de David, qu’il a bâtie pour être un arsenal; mille boucliers y sont suspendus, et tous les dards des vaillants.","Ton cou est comme la tour de David, qu’il a bâtie pour être un arsenal; mille boucliers y sont suspendus, et tous les dards des vaillants."],[4,5,"Tes deux mamelles sont comme deux faons jumeaux du chevreuil, paissant parmi les lis,","Tes deux mamelles sont comme deux faons jumeaux du chevreuil, paissant parmi les lis,"],[4,6,"Jusqu’à ce que se lèvent les premières brises du jour, et que les ténèbres se dissipent. J’irai à la montagne de myrrhe et à la colline d’encens.","Jusqu’à ce que se lèvent les premières brises du jour, et que les ténèbres se dissipent. J’irai à la montagne de myrrhe et à la colline d’encens."],[4,7,"Tu es toute belle, ô ma bien-aimée; et il n’est point de tache en toi.","Tu es toute belle, ô ma bien-aimée; et il n’est point de tache en toi."],[4,8,"Viens du Liban, mon épouse, viens du Liban; tu iras du puits du serment aux cimes de Sanir et d’Hermon, des antres des lions aux montagnes des panthères.","Viens du Liban, mon épouse, viens du Liban; tu iras du puits du serment aux cimes de Sanir et d’Hermon, des antres des lions aux montagnes des panthères."],[4,9,"Tu m’as ravi mon cœur, ma sœur, mon épouse; tu m’as ravi mon cœur d’un seul de tes regards, d’un seul des cheveux de ton cou.","Tu m’as ravi mon cœur, ma sœur, mon épouse; tu m’as ravi mon cœur d’un seul de tes regards, d’un seul des cheveux de ton cou."],[4,10,"Que tes mamelles sont belles, ma sœur, mon épouse! tes mamelles sont plus précieuses que le vin; et les senteurs de tes vêtements plus douces que tous les aromates.","Que tes mamelles sont belles, ma sœur, mon épouse! tes mamelles sont plus précieuses que le vin; et les senteurs de tes vêtements plus douces que tous les aromates."],[4,11,"De tes lèvres découlent des rayons de miel, ô mon épouse; le miel et le lait sont sous ta langue, et l’odeur de tes vêtements est comme l’odeur de l’encens.","De tes lèvres découlent des rayons de miel, ô mon épouse; le miel et le lait sont sous ta langue, et l’odeur de tes vêtements est comme l’odeur de l’encens."],[4,12,"Ma sœur, mon épouse, est un jardin enclos; c’est un jardin enclos, une fontaine scellée.","Ma sœur, mon épouse, est un jardin enclos; c’est un jardin enclos, une fontaine scellée."],[4,13,"Tes rejetons forment un jardin de grenades avec les fruits du noyer, des grappes en fleur et du nard,","Tes rejetons forment un jardin de grenades avec les fruits du noyer, des grappes en fleur et du nard,"],[4,14,"Du nard et du safran, de la canne et du cinnamome, de tous les arbres du Liban, de la myrrhe, de l’aloès, et des parfums les plus exquis.","Du nard et du safran, de la canne et du cinnamome, de tous les arbres du Liban, de la myrrhe, de l’aloès, et des parfums les plus exquis."],[4,15,"La fontaine de ce jardin est un puits d’eau vive, qui jaillit du Liban.","La fontaine de ce jardin est un puits d’eau vive, qui jaillit du Liban."],[4,16,"Fuis d’ici, vent du nord; viens, vent du midi, souffle sur mon jardin, et que mes parfums en découlent.","Fuis d’ici, vent du nord; viens, vent du midi, souffle sur mon jardin, et que mes parfums en découlent."],[5,1,"Que mon frère bien-aimé descende en son jardin, qu’il mange de ses fruits. Je suis entré dans mon jardin, ma sœur, mon épouse; j’ai récolté ma myrrhe et mes parfums; j’ai mangé mon pain avec un rayon de miel; j’ai bu mon vin et mon lait. Mangez, ô mes amis; buvez, mes frères, et enivrez-vous.","Que mon frère bien-aimé descende en son jardin, qu’il mange de ses fruits. Je suis entré dans mon jardin, ma sœur, mon épouse; j’ai récolté ma myrrhe et mes parfums; j’ai mangé mon pain avec un rayon de miel; j’ai bu mon vin et mon lait. Mangez, ô mes amis; buvez, mes frères, et enivrez-vous."],[5,2,"Pour moi, je dors, et mon cœur veille. C’est la voix de mon frère bien-aimé; il heurte à la porte: Ouvre-moi, dit-il, ma bien-aimée, ma sœur, ma colombe, ma parfaite; ma tête est pleine de rosée, et mes cheveux humides des gouttes de la nuit.","Pour moi, je dors, et mon cœur veille. C’est la voix de mon frère bien-aimé; il heurte à la porte: Ouvre-moi, dit-il, ma bien-aimée, ma sœur, ma colombe, ma parfaite; ma tête est pleine de rosée, et mes cheveux humides des gouttes de la nuit."],[5,3,"J’ai ôté ma tunique; comment la revêtirai-je? Je me suis lavé les pieds; comment puis-je maintenant les salir?","J’ai ôté ma tunique; comment la revêtirai-je? Je me suis lavé les pieds; comment puis-je maintenant les salir?"],[5,4,"Mon frère bien-aimé a passé la main dans l’ouverture de la porte, et si près de mon bien-aimé mes entrailles ont tressailli,","Mon frère bien-aimé a passé la main dans l’ouverture de la porte, et si près de mon bien-aimé mes entrailles ont tressailli,"],[5,5,"Je me suis levée pour ouvrir à mon frère bienaimé; mes mains ont distillé la myrrhe; mes doigts ont rempli de myrrhe la poignée du verrou.","Je me suis levée pour ouvrir à mon frère bienaimé; mes mains ont distillé la myrrhe; mes doigts ont rempli de myrrhe la poignée du verrou."],[5,6,"Et j’ai ouvert à mon frère bien-aimé, et mon frère bien-aimé n’était plus là; et mon âme était défaillante pendant qu’il parlait. Je l’ai cherché, et ne l’ai point trouvé; je l’ai appelé, et il ne m’a point entendue.","Et j’ai ouvert à mon frère bien-aimé, et mon frère bien-aimé n’était plus là; et mon âme était défaillante pendant qu’il parlait. Je l’ai cherché, et ne l’ai point trouvé; je l’ai appelé, et il ne m’a point entendue."],[5,7,"Les gardes m’ont rencontrée, en faisant la ronde dans la ville; ils m’ont battue et meurtrie; les sentinelles des remparts m’ont dépouillée de mon manteau.","Les gardes m’ont rencontrée, en faisant la ronde dans la ville; ils m’ont battue et meurtrie; les sentinelles des remparts m’ont dépouillée de mon manteau."],[5,8,"Filles de Jérusalem, je vous adjure par les puissances et les vertus des campagnes, si vous avez trouvé mon frère bien-aimé, que lui direz-vous? Dites-lui que je suis blessée d’amour.","Filles de Jérusalem, je vous adjure par les puissances et les vertus des campagnes, si vous avez trouvé mon frère bien-aimé, que lui direz-vous? Dites-lui que je suis blessée d’amour."],[5,9,"Qu’est donc ton frère bien-aimé auprès d’un autre frère, ô toi belle entre toutes les femmes? qu’est ton frère bien-aimé auprès d’un autre frère, pour que tu nous adjures ainsi?","Qu’est donc ton frère bien-aimé auprès d’un autre frère, ô toi belle entre toutes les femmes? qu’est ton frère bien-aimé auprès d’un autre frère, pour que tu nous adjures ainsi?"],[5,10,"Mon frère bien-aimé est blanc et rose, choisi entre dix mille.","Mon frère bien-aimé est blanc et rose, choisi entre dix mille."],[5,11,"Sa tête est de l’or fin de Céphaz; ses cheveux sont souples, et noirs comme le corbeau.","Sa tête est de l’or fin de Céphaz; ses cheveux sont souples, et noirs comme le corbeau."],[5,12,"Ses yeux sont comme ceux des colombes sur des étangs pleins d’eau, lavées dans le lait, se reposant sur les étangs.","Ses yeux sont comme ceux des colombes sur des étangs pleins d’eau, lavées dans le lait, se reposant sur les étangs."],[5,13,"Ses joues sont comme des vases d’aromates exhalant des parfums; ses lèvres sont des lis distillant la myrrhe la plus pure.","Ses joues sont comme des vases d’aromates exhalant des parfums; ses lèvres sont des lis distillant la myrrhe la plus pure."],[5,14,"Ses mains sont gracieuses et d’or, et pleines de béryl; sa poitrine est une tablette d’ivoire sur une pierre de saphir.","Ses mains sont gracieuses et d’or, et pleines de béryl; sa poitrine est une tablette d’ivoire sur une pierre de saphir."],[5,15,"Ses jambes sont des colonnes de marbre posées sur des bases d’or; sa beauté est celle du Liban elle excelle comme le cèdre.","Ses jambes sont des colonnes de marbre posées sur des bases d’or; sa beauté est celle du Liban elle excelle comme le cèdre."],[5,16,"Sa bouche est pleine de douceur, et fait naître les désirs; tel est mon frère bien-aimé, tel est mon ami, filles de Jérusalem.","Sa bouche est pleine de douceur, et fait naître les désirs; tel est mon frère bien-aimé, tel est mon ami, filles de Jérusalem."],[5,17,"Où est allé ton frère bien-aimé, ô toi belle entre toutes les femmes? Où ton frère bien-aimé s’est-il retiré? et nous le chercherons avec toi.","Où est allé ton frère bien-aimé, ô toi belle entre toutes les femmes? Où ton frère bien-aimé s’est-il retiré? et nous le chercherons avec toi."],[6,1,"Mon frère bien-aimé est descendu dans son jardin parmi les roses d’aromates, pour paître son troupeau dans sesjardins, et y cueillir des lis.","Mon frère bien-aimé est descendu dans son jardin parmi les roses d’aromates, pour paître son troupeau dans sesjardins, et y cueillir des lis."],[6,2,"Je suis à mon frère bien-aimé, et mon frère bienaimé est à moi; il fait paître son troupeau parmi les lis.","Je suis à mon frère bien-aimé, et mon frère bienaimé est à moi; il fait paître son troupeau parmi les lis."],[6,3,"Tu es belle, ô ma bien-aimée, comme la tendresse, gracieuse comme Jérusalem, terrible comme une armée en bataille.","Tu es belle, ô ma bien-aimée, comme la tendresse, gracieuse comme Jérusalem, terrible comme une armée en bataille."],[6,4,"Détourne de moi tes yeux, car ils m’ont transporté; ta chevelure est comme les troupeaux de chèvres que l’on voit en Galaad.","Détourne de moi tes yeux, car ils m’ont transporté; ta chevelure est comme les troupeaux de chèvres que l’on voit en Galaad."],[6,5,"Tes dents sont comme la toison des brebis sortant du lavoir après la tonte, qui toutes ont deux petits, et dont nulle n’est stérile. Tes lèvres sont comme un ruban écarlate, et ton langage est plein de grâce.","Tes dents sont comme la toison des brebis sortant du lavoir après la tonte, qui toutes ont deux petits, et dont nulle n’est stérile. Tes lèvres sont comme un ruban écarlate, et ton langage est plein de grâce."],[6,6,"Tes joues sont comme la peau de la grenade, sans parler de tes beautés cachées.","Tes joues sont comme la peau de la grenade, sans parler de tes beautés cachées."],[6,7,"Il y a soixante reines et quatre-vingts concubines, et des jeunes filles sans nombre.","Il y a soixante reines et quatre-vingts concubines, et des jeunes filles sans nombre."],[6,8,"Mais ma colombe, ma parfaite est unique; elle est l’unique de sa mère; elle est l’élue de celle qui l’a enfantée. Les jeunes filles l’ont vue, et la déclarent heureuse; les reines et les concubines la loueront.","Mais ma colombe, ma parfaite est unique; elle est l’unique de sa mère; elle est l’élue de celle qui l’a enfantée. Les jeunes filles l’ont vue, et la déclarent heureuse; les reines et les concubines la loueront."],[6,9,"Quelle est celle qui regarde dehors comme le matin; belle comme la lune, élue comme le soleil, terrible comme une armée en bataille?","Quelle est celle qui regarde dehors comme le matin; belle comme la lune, élue comme le soleil, terrible comme une armée en bataille?"],[6,10,"Je suis descendu au jardin des noyers, pour voir les fruits du vallon; si la vigne est en fleur, et si les grenades sont fleuries.","Je suis descendu au jardin des noyers, pour voir les fruits du vallon; si la vigne est en fleur, et si les grenades sont fleuries."],[6,11,"Là je te donnerai mes mamelles. Mon âme n’a rien su, et j’ai été comme emportée par les chars d’Aminadab.","Là je te donnerai mes mamelles. Mon âme n’a rien su, et j’ai été comme emportée par les chars d’Aminadab."],[6,12,"Reviens, reviens, ma Sulamite; reviens, reviens, et nous ne verrons que toi.","Reviens, reviens, ma Sulamite; reviens, reviens, et nous ne verrons que toi."],[7,1,"Que verrez-vous en la Sulamite, qui vient comme les rangs d’une armée? Fille de Nadab, que les sandales donnent de grâce à tes pas! Les contours de tes jambes ressemblent à des colliers, chef-d’œuvre d’un artiste.","Que verrez-vous en la Sulamite, qui vient comme les rangs d’une armée? Fille de Nadab, que les sandales donnent de grâce à tes pas! Les contours de tes jambes ressemblent à des colliers, chef-d’œuvre d’un artiste."],[7,2,"Ton nombril est comme un cratère fait au tour, оù le vin ne manque jamais. Ta poitrine est comme un monceau de froment enveloppé de lis.","Ton nombril est comme un cratère fait au tour, оù le vin ne manque jamais. Ta poitrine est comme un monceau de froment enveloppé de lis."],[7,3,"Tes deux mamelles sont comme les deux faons jumeaux d’un chevreuil.","Tes deux mamelles sont comme les deux faons jumeaux d’un chevreuil."],[7,4,"Ton cou est comme une tour d’ivoire, tes yeux comme les étangs d’Hésebon, près des portes de la fille issue de beaucoup de peuples. Ton nez est comme la tour du Liban qui regarde Damas.","Ton cou est comme une tour d’ivoire, tes yeux comme les étangs d’Hésebon, près des portes de la fille issue de beaucoup de peuples. Ton nez est comme la tour du Liban qui regarde Damas."],[7,5,"Ta tête est posée sur toi semblable au mont Carmel, et ta chevelure est comme de la pourpre; le roi est retenu dans tes galeries.","Ta tête est posée sur toi semblable au mont Carmel, et ta chevelure est comme de la pourpre; le roi est retenu dans tes galeries."],[7,6,"O ma bien-aimée, que de grâce, que de suavité en tes délices!","O ma bien-aimée, que de grâce, que de suavité en tes délices!"],[7,7,"Ta stature est celle d’un palmier; tes mamelles sont comme des grappes de raisin.","Ta stature est celle d’un palmier; tes mamelles sont comme des grappes de raisin."],[7,8,"J’ai dit: Je monterai au palmier; j’atteindrai à son faîte, et tes mamelles seront comme les grappes de la vigne, l’odeur de tes narines comme celle des pommes,","J’ai dit: Je monterai au palmier; j’atteindrai à son faîte, et tes mamelles seront comme les grappes de la vigne, l’odeur de tes narines comme celle des pommes,"],[7,9,"Et ton gosier comme un bon vin. (Épouse) Qu’aime mon frère bien-aimé (époux), et qui plaît à mes dents et à mes lèvres.","Et ton gosier comme un bon vin. (Épouse) Qu’aime mon frère bien-aimé (époux), et qui plaît à mes dents et à mes lèvres."],[7,10,"Je suis à mon frère bien-aimé, et son regard est tourné vers moi.","Je suis à mon frère bien-aimé, et son regard est tourné vers moi."],[7,11,"Viens, mon frère bien-aimé, allons aux champs, dormons dans les bourgades.","Viens, mon frère bien-aimé, allons aux champs, dormons dans les bourgades."],[7,12,"Levons-nous dès l’aurore pour aller aux vignes; voyons si le raisin est en fleur, si les graines sont en fleur, si les grenades fleurissent: c’est là que je te donnerai mes mamelles.","Levons-nous dès l’aurore pour aller aux vignes; voyons si le raisin est en fleur, si les graines sont en fleur, si les grenades fleurissent: c’est là que je te donnerai mes mamelles."],[7,13,"Les mandragores ont donné leur senteur, et, au seuil de nos portes, tous les fruits verts et mùrs, ô mon frère bien-aimé, je les ai gardés pour toi.","Les mandragores ont donné leur senteur, et, au seuil de nos portes, tous les fruits verts et mùrs, ô mon frère bien-aimé, je les ai gardés pour toi."],[8,1,"O mon frère bien-aimé, que n’as-tu sucé les mamelles de ma mère! Si je te trouve dehors, je te baiserai, et nul ne me méprisera.","O mon frère bien-aimé, que n’as-tu sucé les mamelles de ma mère! Si je te trouve dehors, je te baiserai, et nul ne me méprisera."],[8,2,"Je te prendrai par la main, je t’introduirai dans la maison de ma mère, dans la chambre de celle qui m’a conçu. Je te ferai boire du vin parfumé, et du jus de mes grenades.","Je te prendrai par la main, je t’introduirai dans la maison de ma mère, dans la chambre de celle qui m’a conçu. Je te ferai boire du vin parfumé, et du jus de mes grenades."],[8,3,"Il posera sa main gauche sur ma tête, et, de la droite, il m’embrassera.","Il posera sa main gauche sur ma tête, et, de la droite, il m’embrassera."],[8,4,"Je vous adjure, filles de Jérusalem, par les vertus de la campagne, n’éveillez pas, ne réveillez pas ma bien-aimée qu’elle ne le désire.","Je vous adjure, filles de Jérusalem, par les vertus de la campagne, n’éveillez pas, ne réveillez pas ma bien-aimée qu’elle ne le désire."],[8,5,"Quelle est celle qui se lève blanche comme l’aubépine, appuyée sur son frère bien-aimé (époux)? Je t’ai réveillée sous un pommier (4); c’est là que ta mère t’a enfantée; c’est là que t’a enfantée celle qui t’a conçu.","Quelle est celle qui se lève blanche comme l’aubépine, appuyée sur son frère bien-aimé (époux)? Je t’ai réveillée sous un pommier (4); c’est là que ta mère t’a enfantée; c’est là que t’a enfantée celle qui t’a conçu."],[8,6,"Mets-moi comme un sceau sur ton cœur, et comme un sceau sur ton bras. Car l’amour est fort comme la mort, et la jalousie est cruelle comme l’enfer; ses traits sont des traits de feu, ce sont ses flammes.","Mets-moi comme un sceau sur ton cœur, et comme un sceau sur ton bras. Car l’amour est fort comme la mort, et la jalousie est cruelle comme l’enfer; ses traits sont des traits de feu, ce sont ses flammes."],[8,7,"Des torrents d’eau ne pourront point éteindre l’amour, ni les fleuves le submerger. Si un homme donne toute sa vie par amour, les autres hommes auront pour lui le dernier mépris.","Des torrents d’eau ne pourront point éteindre l’amour, ni les fleuves le submerger. Si un homme donne toute sa vie par amour, les autres hommes auront pour lui le dernier mépris."],[8,8,"Notre sœur est petite, et n’a point de mamelles; que ferons-nous pour notre sœur, le jour où je viendrai lui parler?","Notre sœur est petite, et n’a point de mamelles; que ferons-nous pour notre sœur, le jour où je viendrai lui parler?"],[8,9,"Si elle est un mur, couronnons-la de créneaux d’argent; si elle est une porte, incrustons-la de bois de cèdre.","Si elle est un mur, couronnons-la de créneaux d’argent; si elle est une porte, incrustons-la de bois de cèdre."],[8,10,"Moi (l’épouse) je suis un mur, et mes mamelles sont comme des tours; et j’ai été à leurs yeux comme ayant trouvé la paix.","Moi (l’épouse) je suis un mur, et mes mamelles sont comme des tours; et j’ai été à leurs yeux comme ayant trouvé la paix."],[8,11,"(Époux) Salomon avait une vigne en Béelamon; il a donné sa vigne à ceux qui la gardent; chacun rendra de ses fruits mille sicles d’argent.","(Époux) Salomon avait une vigne en Béelamon; il a donné sa vigne à ceux qui la gardent; chacun rendra de ses fruits mille sicles d’argent."],[8,12,"Ma vigne est à moi; elle est devant mes yeux; que Salomon en ait mille sicles; que ceux qui gardent ses fruits en aient deux cents.","Ma vigne est à moi; elle est devant mes yeux; que Salomon en ait mille sicles; que ceux qui gardent ses fruits en aient deux cents."],[8,13,"O toi qui demeures dans les jardins, mes compagnes écoutent ta voix; fais-la-moi entendre.","O toi qui demeures dans les jardins, mes compagnes écoutent ta voix; fais-la-moi entendre."],[8,14,"Fuis, mon frère bien-aimé; et, rapide comme le chevreuil ou comme le faon de la biche, fuis dans les montagnes des parfums.","Fuis, mon frère bien-aimé; et, rapide comme le chevreuil ou comme le faon de la biche, fuis dans les montagnes des parfums."]],"ell-vamvas1850":[[1,1,"Το Άσμα των Ασμάτων, το του Σολομώντος.","To Ásma tōn Asmátōn, to tou Solomṓntos."],[1,2,"Ας με φιλήση με τα φιλήματα του στόματος αυτού. Διότι η αγάπη σου είναι καλητέρα παρά τον οίνον.","As me philḗsē me ta philḗmata tou stómatos autoú. Dióti ē agápē sou eínai kalētéra pará ton oínon."],[1,3,"Διά την ευωδίαν των καλών μύρων σου, το όνομά σου είναι μύρον εκκεχυμένον· διά τούτο αι νεάνιδες σε αγαπώσιν.","Diá tēn euōdían tōn kalṓn mýrōn sou, to ónomá sou eínai mýron ekkechyménon: diá toúto ai neánides se agapṓsin."],[1,4,"Ελκυσόν με· θέλομεν δράμει κατόπιν σου· ο βασιλεύς με εισήγαγεν εις τα ταμεία αυτού· θέλομεν αγάλλεσθαι και ευφραίνεσθαι εις σε, θέλομεν ενθυμείσθαι την αγάπην σου μάλλον παρά οίνον· οι έχοντες ευθύτητα σε αγαπώσι.","Elkysón me: thélomen drámei katópin sou: o basileús me eisḗgagen eis ta tameía autoú: thélomen agállesthai kai euphraínesthai eis se, thélomen enthymeísthai tēn agápēn sou mállon pará oínon: oi échontes euthýtēta se agapṓsi."],[1,5,"Μέλαινα είμαι, πλην εύχαρις, θυγατέρες της Ιερουσαλήμ· ως τα σκηνώματα του Κηδάρ, ως τα παραπετάσματα του Σολομώντος.","Mélaina eímai, plēn eúcharis, thygatéres tēs Ierousalḗm: ōs ta skēnṓmata tou Kēdár, ōs ta parapetásmata tou Solomṓntos."],[1,6,"Μη βλέπετε εις εμέ, ότι είμαι μεμελανωμένη, επειδή ο ήλιος με έκαυσεν· οι υιοί της μητρός μου ωργίσθησαν κατ' εμού· με έβαλον φύλακα εις τους αμπελώνας· τον ίδιόν μου αμπελώνα όμως δεν εφύλαξα.","Mē blépete eis emé, óti eímai memelanōménē, epeidḗ o ḗlios me ékausen: oi yioí tēs mētrós mou ōrgísthēsan kat' emoú: me ébalon phýlaka eis tous ampelṓnas: ton ídión mou ampelṓna ómōs den ephýlaxa."],[1,7,"Απάγγειλόν μοι, συ, τον οποίον αγαπά η ψυχή μου, Που ποιμαίνεις, που αναπαύεις το ποίμνιον την μεσημβρίαν· διά τι να γείνω ως περικεκαλυμμένη μεταξύ των ποιμνίων των συντρόφων σου;","Apángeilón moi, sy, ton opoíon agapá ē psychḗ mou, Pou poimaíneis, pou anapaúeis to poímnion tēn mesēmbrían: diá ti na geínō ōs perikekalymménē metaxý tōn poimníōn tōn syntróphōn sou?"],[1,8,"Εάν δεν γνωρίζης τούτο αφ' εαυτής, ώραία μεταξύ των γυναικών, έξελθε συ κατόπιν εις τα ίχνη του ποιμνίου, και ποίμαινε τα ερίφιά σου πλησίον των σκηνών των βοσκών.","Eán den gnōrízēs toúto aph' eautḗs, ṓraía metaxý tōn gynaikṓn, éxelthe sy katópin eis ta íchnē tou poimníou, kai poímaine ta eríphiá sou plēsíon tōn skēnṓn tōn boskṓn."],[1,9,"Με τας ίππους των αμαξών του Φαραώ σε εξωμοίωσα, ηγαπημένη μου.","Me tas íppous tōn amaxṓn tou Pharaṓ se exōmoíōsa, ēgapēménē mou."],[1,10,"Αι σιαγόνες σου είναι ώραίαι με τας σειράς των μαργαριτών, και ο τράχηλός σου με τα περιδέρραια.","Ai siagónes sou eínai ṓraíai me tas seirás tōn margaritṓn, kai o tráchēlós sou me ta peridérraia."],[1,11,"Θέλομεν κάμει εις σε αλύσεις χρυσάς με στίγματα αργυρίου.","Thélomen kámei eis se alýseis chrysás me stígmata argyríou."],[1,12,"Ενόσω ο βασιλεύς κάθηται εις την τράπεζαν αυτού, ο νάρδος μου διαχέει την οσμήν αυτού.","Enósō o basileús káthētai eis tēn trápezan autoú, o nárdos mou diachéei tēn osmḗn autoú."],[1,13,"Δεμάτιον σμύρνης είναι εις εμέ ο αγαπητός μου· θέλει διανυκτερεύει μεταξύ των μαστών μου.","Demátion smýrnēs eínai eis emé o agapētós mou: thélei dianyktereúei metaxý tōn mastṓn mou."],[1,14,"Ο αγαπητός μου είναι εις εμέ ως βότρυς κύπρινος εις τους αμπελώνας του Εν-γαδδί.","O agapētós mou eínai eis emé ōs bótrys kýprinos eis tous ampelṓnas tou En-gaddí."],[1,15,"Ιδού, είσαι ώραία, αγαπητή μου· ιδού, είσαι ώραία· οι οφθαλμοί σου είναι ως περιστερών.","Idoú, eísai ṓraía, agapētḗ mou: idoú, eísai ṓraía: oi ophthalmoí sou eínai ōs peristerṓn."],[1,16,"Ιδού, είσαι ώραίος, αγαπητέ μου, ναι, εύχαρις· και η κλίνη ημών είναι ευθαλής.","Idoú, eísai ṓraíos, agapēté mou, nai, eúcharis: kai ē klínē ēmṓn eínai euthalḗs."],[1,17,"Αι δοκοί των οίκων ημών είναι κέδροι, τα σανιδώματα ημών εκ κυπαρίσσου.","Ai dokoí tōn oíkōn ēmṓn eínai kédroi, ta sanidṓmata ēmṓn ek kyparíssou."],[2,1,"Εγώ είμαι το άνθος του Σαρών και το κρίνον των κοιλάδων.","Egṓ eímai to ánthos tou Sarṓn kai to krínon tōn koiládōn."],[2,2,"Καθώς το κρίνον μεταξύ των ακανθών, ούτως είναι η αγαπητή μου μεταξύ των νεανίδων.","Kathṓs to krínon metaxý tōn akanthṓn, oútōs eínai ē agapētḗ mou metaxý tōn neanídōn."],[2,3,"Καθώς η μηλέα μεταξύ των δένδρων του δάσους, ούτως είναι ο αγαπητός μου μεταξύ των νεανίσκων· επεθύμησα την σκιάν αυτού και εκάθησα υπ' αυτήν, και ο καρπός αυτού ήτο γλυκύς εις τον ουρανίσκον μου.","Kathṓs ē mēléa metaxý tōn déndrōn tou dásous, oútōs eínai o agapētós mou metaxý tōn neanískōn: epethýmēsa tēn skián autoú kai ekáthēsa yp' autḗn, kai o karpós autoú ḗto glykýs eis ton ouranískon mou."],[2,4,"Με έφερεν εις τον οίκον του οίνου, και η σημαία αυτού επ' εμέ η αγάπη.","Me épheren eis ton oíkon tou oínou, kai ē sēmaía autoú ep' emé ē agápē."],[2,5,"Υποστηρίξατέ με με γλυκίσματα δυναμωτικά, αναψύξατέ με με μήλα· διότι είμαι τετρωμένη υπό αγάπης.","Ypostēríxaté me me glykísmata dynamōtiká, anapsýxaté me me mḗla: dióti eímai tetrōménē ypó agápēs."],[2,6,"Η αριστερά αυτού είναι υπό την κεφαλήν μου, και η δεξιά αυτού με εναγκαλίζεται.","Ē aristerá autoú eínai ypó tēn kephalḗn mou, kai ē dexiá autoú me enankalízetai."],[2,7,"Σας ορκίζω, θυγατέρες Ιερουσαλήμ, εις τας δορκάδας και εις τας ελάφους του αγρού, να μη εξεγείρητε μηδέ να εξυπνήσητε την αγάπην μου, εωσού θελήση.","Sas orkízō, thygatéres Ierousalḗm, eis tas dorkádas kai eis tas eláphous tou agroú, na mē exegeírēte mēdé na exypnḗsēte tēn agápēn mou, eōsoú thelḗsē."],[2,8,"Φωνή του αγαπητού μου Ιδού, αυτός έρχεται πηδών επί τα όρη, σκιρτών επί τους λόφους.","Phōnḗ tou agapētoú mou Idoú, autós érchetai pēdṓn epí ta órē, skirtṓn epí tous lóphous."],[2,9,"Ο αγαπητός μου είναι όμοιος με δορκάδα ή με σκύμνον ελάφου· ιδού, ίσταται όπισθεν του τοίχου ημών, κυττάζει έξω διά των θυρίδων, προκύπτει διά των δικτυωτών.","O agapētós mou eínai ómoios me dorkáda ḗ me skýmnon eláphou: idoú, ístatai ópisthen tou toíchou ēmṓn, kyttázei éxō diá tōn thyrídōn, prokýptei diá tōn diktyōtṓn."],[2,10,"Αποκρίνεται ο αγαπητός μου και λέγει προς εμέ, Σηκώθητι, αγαπητή μου, ώραία μου, και ελθέ·","Apokrínetai o agapētós mou kai légei pros emé, Sēkṓthēti, agapētḗ mou, ṓraía mou, kai elthé:"],[2,11,"Διότι ιδού, ο χειμών παρήλθεν, η βροχή διέβη, απήλθε·","Dióti idoú, o cheimṓn parḗlthen, ē brochḗ diébē, apḗlthe:"],[2,12,"τα άνθη φαίνονται εν τη γή· ο καιρός του άσματος έφθασε, και η φωνή της τρυγόνος ηκούσθη εν τη γη ημών·","ta ánthē phaínontai en tē gḗ: o kairós tou ásmatos éphthase, kai ē phōnḗ tēs trygónos ēkoústhē en tē gē ēmṓn:"],[2,13,"η συκή εξέφερε τους ολύνθους αυτής, και αι άμπελοι με τα άνθη της σταφυλής διαδίδουσιν ευωδίαν· σηκώθητι, αγαπητή μου, ώραία μου, και ελθέ·","ē sykḗ exéphere tous olýnthous autḗs, kai ai ámpeloi me ta ánthē tēs staphylḗs diadídousin euōdían: sēkṓthēti, agapētḗ mou, ṓraía mou, kai elthé:"],[2,14,"Ω περιστερά μου, ήτις είσαι εν ταις σχισμαίς του βράχου, εν τοις αποκρύφοις των κρημνών, δείξόν μοι την όψιν σου, κάμε με να ακούσω την φωνήν σου· διότι η φωνή σου είναι γλυκεία και η όψις σου ώραία.","Ō peristerá mou, ḗtis eísai en tais schismaís tou bráchou, en tois apokrýphois tōn krēmnṓn, deíxón moi tēn ópsin sou, káme me na akoúsō tēn phōnḗn sou: dióti ē phōnḗ sou eínai glykeía kai ē ópsis sou ṓraía."],[2,15,"Πιάσατε εις ημάς τας αλώπεκας, τας μικράς αλώπεκας, αίτινες αφανίζουσι τας αμπέλους· διότι αι άμπελοι ημών ανθούσιν.","Piásate eis ēmás tas alṓpekas, tas mikrás alṓpekas, aítines aphanízousi tas ampélous: dióti ai ámpeloi ēmṓn anthoúsin."],[2,16,"Ο αγαπητός μου είναι εις εμέ και εγώ εις αυτόν· ποιμαίνει μεταξύ των κρίνων.","O agapētós mou eínai eis emé kai egṓ eis autón: poimaínei metaxý tōn krínōn."],[2,17,"Εωσού πνεύση η αύρα της ημέρας και φύγωσιν αι σκιαί, επίστρεψον, αγαπητέ μου· γίνου όμοιος με δορκάδα ή με σκύμνον ελάφου επί τα όρη τα διεσχισμένα.","Eōsoú pneúsē ē aúra tēs ēméras kai phýgōsin ai skiaí, epístrepson, agapēté mou: gínou ómoios me dorkáda ḗ me skýmnon eláphou epí ta órē ta dieschisména."],[3,1,"Την νύκτα επί της κλίνης μου εζήτησα εκείνον, τον οποίον αγαπά η ψυχή μου· εζήτησα αυτόν και δεν εύρηκα αυτόν.","Tēn nýkta epí tēs klínēs mou ezḗtēsa ekeínon, ton opoíon agapá ē psychḗ mou: ezḗtēsa autón kai den eúrēka autón."],[3,2,"Θέλω σηκωθή τώρα και περιέλθει την πόλιν, εν ταις αγοραίς και εν ταις πλατείαις· θέλω ζητήσει εκείνον, τον οποίον αγαπά η ψυχή μου· εζήτησα αυτόν και δεν εύρηκα αυτόν.","Thélō sēkōthḗ tṓra kai periélthei tēn pólin, en tais agoraís kai en tais plateíais: thélō zētḗsei ekeínon, ton opoíon agapá ē psychḗ mou: ezḗtēsa autón kai den eúrēka autón."],[3,3,"Με εύρηκαν οι φύλακες οι περιερχόμενοι την πόλιν. Μη είδετε εκείνον, τον οποίον αγαπά η ψυχή μου;","Me eúrēkan oi phýlakes oi perierchómenoi tēn pólin. Mē eídete ekeínon, ton opoíon agapá ē psychḗ mou?"],[3,4,"Αφού ολίγον επέρασα απ' αυτών, εύρηκα εκείνον, τον οποίον αγαπά η ψυχή μου· επίασα αυτόν και δεν αφήκα αυτόν, εωσού εισήγαγον αυτόν εις τον οίκον της μητρός μου, και εις τον κοιτώνα της συλλαβούσης με.","Aphoú olígon epérasa ap' autṓn, eúrēka ekeínon, ton opoíon agapá ē psychḗ mou: epíasa autón kai den aphḗka autón, eōsoú eisḗgagon autón eis ton oíkon tēs mētrós mou, kai eis ton koitṓna tēs syllaboúsēs me."],[3,5,"Σας ορκίζω, θυγατέρες Ιερουσαλήμ, εις τας δορκάδας και εις τας ελάφους του αγρού, να μη εξεγείρητε μηδέ να εξυπνήσητε την αγάπην μου, εωσού θελήση.","Sas orkízō, thygatéres Ierousalḗm, eis tas dorkádas kai eis tas eláphous tou agroú, na mē exegeírēte mēdé na exypnḗsēte tēn agápēn mou, eōsoú thelḗsē."],[3,6,"Τις αύτη, η αναβαίνουσα από της ερήμου ως στύλοι καπνού, τεθυμιαμένη με σμύρναν και λίβανον, με πάσαν αρωματικήν σκόνην του μυρεψού;","Tis aútē, ē anabaínousa apó tēs erḗmou ōs stýloi kapnoú, tethymiaménē me smýrnan kai líbanon, me pásan arōmatikḗn skónēn tou myrepsoú?"],[3,7,"Ιδού, η κλίνη του Σολομώντος· εξήκοντα δυνατοί άνδρες είναι περί αυτήν, εκ των δυνατών του Ισραήλ·","Idoú, ē klínē tou Solomṓntos: exḗkonta dynatoí ándres eínai perí autḗn, ek tōn dynatṓn tou Israḗl:"],[3,8,"Πάντες ούτοι κρατούσι ρομφαίαν, δεδιδαγμένοι πόλεμον· έκαστος έχει την ρομφαίαν αυτού επί τον μηρόν αυτού διά νυκτερινούς φόβους.","Pántes oútoi kratoúsi romphaían, dedidagménoi pólemon: ékastos échei tēn romphaían autoú epí ton mērón autoú diá nykterinoús phóbous."],[3,9,"Ο βασιλεύς Σολομών έκαμεν εις εαυτόν φορείον εκ ξύλων του Λιβάνου·","O basileús Solomṓn ékamen eis eautón phoreíon ek xýlōn tou Libánou:"],[3,10,"τους στύλους αυτού έκαμεν εξ αργύρου, το ανακλιντήριον αυτού εκ χρυσού, την στρωμνήν αυτού εκ πορφύρας· το μέσον αυτού ήτο εγκεκοσμημένον ερασμίως υπό των θυγατέρων της Ιερουσαλήμ.","tous stýlous autoú ékamen ex argýrou, to anaklintḗrion autoú ek chrysoú, tēn strōmnḗn autoú ek porphýras: to méson autoú ḗto enkekosmēménon erasmíōs ypó tōn thygatérōn tēs Ierousalḗm."],[3,11,"Εξέλθετε και ιδέτε, θυγατέρες Σιών, τον βασιλέα Σολομώντα εν τω διαδήματι, με το οποίον έστειλεν αυτόν η μήτηρ αυτού εν τη ημέρα της νυμφεύσεως αυτού και εν τη ημέρα της ευφροσύνης της καρδίας αυτού.","Exélthete kai idéte, thygatéres Siṓn, ton basiléa Solomṓnta en tō diadḗmati, me to opoíon ésteilen autón ē mḗtēr autoú en tē ēméra tēs nympheúseōs autoú kai en tē ēméra tēs euphrosýnēs tēs kardías autoú."],[4,1,"Ιδού, είσαι ώραία, αγαπητή μου· ιδού, είσαι ώραία· οι οφθαλμοί σου είναι ως περιστερών μεταξύ των πλοκάμων σου· τα μαλλία σου είναι ως ποίμνιον αιγών, καταβαινόντων από του όρους Γαλαάδ.","Idoú, eísai ṓraía, agapētḗ mou: idoú, eísai ṓraía: oi ophthalmoí sou eínai ōs peristerṓn metaxý tōn plokámōn sou: ta mallía sou eínai ōs poímnion aigṓn, katabainóntōn apó tou órous Galaád."],[4,2,"Οι οδόντες σου είναι ως ποίμνιον προβάτων κεκουρευμένων, αναβαινόντων από της λούσεως, τα οποία πάντα γεννώσι δίδυμα, και δεν υπάρχει άτεκνον μεταξύ αυτών·","Oi odóntes sou eínai ōs poímnion probátōn kekoureuménōn, anabainóntōn apó tēs loúseōs, ta opoía pánta gennṓsi dídyma, kai den ypárchei áteknon metaxý autṓn:"],[4,3,"τα χείλη σου ως ταινία ερυθρά, και η λαλιά σου εύχαρις· αι παρειαί σου ως τμήμα ροϊδίου μεταξύ των πλοκάμων σου·","ta cheílē sou ōs tainía erythrá, kai ē laliá sou eúcharis: ai pareiaí sou ōs tmḗma roïdíou metaxý tōn plokámōn sou:"],[4,4,"Ο τράχηλός σου ως ο πύργος του Δαβίδ, ο ωκοδομημένος διά οπλοθήκην, επί του οποίου κρέμανται χίλιοι θυρεοί, πάντες ασπίδες ισχυρών·","O tráchēlós sou ōs o pýrgos tou Dabíd, o ōkodomēménos diá oplothḗkēn, epí tou opoíou krémantai chílioi thyreoí, pántes aspídes ischyrṓn:"],[4,5,"οι δύο μαστοί σου ως δύο σκύμνοι δορκάδος δίδυμοι, βόσκοντες μεταξύ των κρίνων.","oi dýo mastoí sou ōs dýo skýmnoi dorkádos dídymoi, bóskontes metaxý tōn krínōn."],[4,6,"Εωσού πνεύση η αύρα της ημέρας και φύγωσιν αι σκιαί, εγώ θέλω υπάγει εις το όρος της σμύρνης, και εις τον λόφον του θυμιάματος.","Eōsoú pneúsē ē aúra tēs ēméras kai phýgōsin ai skiaí, egṓ thélō ypágei eis to óros tēs smýrnēs, kai eis ton lóphon tou thymiámatos."],[4,7,"Όλη ώραία είσαι, αγαπητή μου· και μώμος δεν υπάρχει εν σοι.","Ólē ṓraía eísai, agapētḗ mou: kai mṓmos den ypárchei en soi."],[4,8,"Ελθέ μετ' εμού από του Λιβάνου, νύμφη από του Λιβάνου μετ' εμού· βλέψον από της κορυφής του Αμανά, από της κορυφής του Σενείρ και του Αερμών, από των φωλεών των λεόντων, από των ορέων των παρδάλεων.","Elthé met' emoú apó tou Libánou, nýmphē apó tou Libánou met' emoú: blépson apó tēs koryphḗs tou Amaná, apó tēs koryphḗs tou Seneír kai tou Aermṓn, apó tōn phōleṓn tōn leóntōn, apó tōn oréōn tōn pardáleōn."],[4,9,"Έτρωσας την καρδίαν μου, αδελφή μου, νύμφη· έτρωσας την καρδίαν μου, δι' ενός των οφθαλμών σου, δι' ενός πλοκάμου του τραχήλου σου.","Étrōsas tēn kardían mou, adelphḗ mou, nýmphē: étrōsas tēn kardían mou, di' enós tōn ophthalmṓn sou, di' enós plokámou tou trachḗlou sou."],[4,10,"Πόσον ώραία είναι η αγάπη σου, αδελφή μου, νύμφη πόσον καλητέρα η αγάπη σου παρά τον οίνον και η οσμή των μύρων σου παρά πάντα τα αρώματα","Póson ṓraía eínai ē agápē sou, adelphḗ mou, nýmphē póson kalētéra ē agápē sou pará ton oínon kai ē osmḗ tōn mýrōn sou pará pánta ta arṓmata"],[4,11,"Τα χείλη σου, νύμφη, στάζουσιν ως κηρήθρα· μέλι και γάλα είναι υπό την γλώσσαν σου· και η οσμή των ιματίων σου ως οσμή του Λιβάνου.","Ta cheílē sou, nýmphē, stázousin ōs kērḗthra: méli kai gála eínai ypó tēn glṓssan sou: kai ē osmḗ tōn imatíōn sou ōs osmḗ tou Libánou."],[4,12,"Κήπος κεκλεισμένος είναι η αδελφή μου, η νύμφη μου· βρύσις κεκλεισμένη, πηγή εσφραγισμένη.","Kḗpos kekleisménos eínai ē adelphḗ mou, ē nýmphē mou: brýsis kekleisménē, pēgḗ esphragisménē."],[4,13,"Οι βλαστοί σου είναι παράδεισος ροϊδίων, μετά εκλεκτών καρπών· κύπρος μετά νάρδου·","Oi blastoí sou eínai parádeisos roïdíōn, metá eklektṓn karpṓn: kýpros metá nárdou:"],[4,14,"νάρδος και κρόκος· κάλαμος και κιννάμωμον, μετά πάντων των δένδρων του θυμιάματος· σμύρνα και αλόη, μετά πάντων των πρωτίστων αρωμάτων·","nárdos kai krókos: kálamos kai kinnámōmon, metá pántōn tōn déndrōn tou thymiámatos: smýrna kai alóē, metá pántōn tōn prōtístōn arōmátōn:"],[4,15,"πηγή κήπων, φρέαρ ύδατος ζώντος, και ρύακες από του Λιβάνου.","pēgḗ kḗpōn, phréar ýdatos zṓntos, kai rýakes apó tou Libánou."],[4,16,"Εγέρθητι, Βορρά· και έρχου, Νότε· πνεύσον εις τον κήπόν μου· διά να εκχυθώσι τα αρώματα αυτού. Ας έλθη ο αγαπητός μου εις τον κήπον αυτού, και ας φάγη τους εξαιρέτους καρπούς αυτού.","Egérthēti, Borrá: kai érchou, Nóte: pneúson eis ton kḗpón mou: diá na ekchythṓsi ta arṓmata autoú. As élthē o agapētós mou eis ton kḗpon autoú, kai as phágē tous exairétous karpoús autoú."],[5,1,"Ήλθον εις τον κήπόν μου, αδελφή μου, νύμφη· ετρύγησα την σμύρναν μου μετά των αρωμάτων μου· έφαγον την κηρήθραν μου μετά του μέλιτός μου· έπιον τον οίνον μου μετά του γάλακτός μου· Φάγετε, φίλοι· πίετε, ναι, πίετε αφθόνως, αγαπητοί.","Ḗlthon eis ton kḗpón mou, adelphḗ mou, nýmphē: etrýgēsa tēn smýrnan mou metá tōn arōmátōn mou: éphagon tēn kērḗthran mou metá tou mélitós mou: épion ton oínon mou metá tou gálaktós mou: Phágete, phíloi: píete, nai, píete aphthónōs, agapētoí."],[5,2,"Εγώ κοιμώμαι, αλλ' η καρδία μου αγρυπνεί· φωνή του αγαπητού μου· κρούει· Ανοιξόν μοι, αδελφή μου, αγαπητή μου, περιστερά μου, αμώμητέ μου· διότι η κεφαλή μου εγέμισεν από δρόσου, οι βόστρυχοί μου από ψεκάδων της νυκτός.","Egṓ koimṓmai, all' ē kardía mou agrypneí: phōnḗ tou agapētoú mou: kroúei: Anoixón moi, adelphḗ mou, agapētḗ mou, peristerá mou, amṓmēté mou: dióti ē kephalḗ mou egémisen apó drósou, oi bóstrychoí mou apó psekádōn tēs nyktós."],[5,3,"Εξεδύθην τον χιτώνα μου· πως να ενδυθώ αυτόν; ένιψα τους πόδας μου· πως θέλω μολύνει αυτούς;","Exedýthēn ton chitṓna mou: pōs na endythṓ autón? énipsa tous pódas mou: pōs thélō molýnei autoús?"],[5,4,"Ο αγαπητός μου εισήξε την χείρα αυτού διά της τρύπης της θύρας, και τα σπλάγχνα μου εταράχθησαν δι' αυτόν.","O agapētós mou eisḗxe tēn cheíra autoú diá tēs trýpēs tēs thýras, kai ta splánchna mou etaráchthēsan di' autón."],[5,5,"Εγώ εσηκώθην διά να ανοίξω εις τον αγαπητόν μου· και αι χείρές μου έσταζον σμύρναν, και οι δάκτυλοί μου σμύρναν σταλακτήν, επί τας λαβάς του μοχλού.","Egṓ esēkṓthēn diá na anoíxō eis ton agapētón mou: kai ai cheírés mou éstazon smýrnan, kai oi dáktyloí mou smýrnan stalaktḗn, epí tas labás tou mochloú."],[5,6,"Εγώ ήνοιξα εις τον αγαπητόν μου· αλλ' ο αγαπητός μου εσύρθη, έφυγεν· η ψυχή μου ελιποθύμησεν εις τον λόγον αυτού· εζήτησα αυτόν και δεν εύρηκα αυτόν, εφώνησα αυτόν και δεν μοι απεκρίθη.","Egṓ ḗnoixa eis ton agapētón mou: all' o agapētós mou esýrthē, éphygen: ē psychḗ mou elipothýmēsen eis ton lógon autoú: ezḗtēsa autón kai den eúrēka autón, ephṓnēsa autón kai den moi apekríthē."],[5,7,"Με εύρηκαν οι φύλακες οι περιερχόμενοι την πόλιν, με εκτύπησαν, με επλήγωσαν· οι φύλακες των τειχών αφήρεσαν απ' εμού το ιμάτιόν μου.","Me eúrēkan oi phýlakes oi perierchómenoi tēn pólin, me ektýpēsan, me eplḗgōsan: oi phýlakes tōn teichṓn aphḗresan ap' emoú to imátión mou."],[5,8,"Σας ορκίζω, θυγατέρες Ιερουσαλήμ, εάν εύρητε τον αγαπητόν μου, Τι θέλετε ειπεί προς αυτόν; Ότι είμαι τετρωμένη υπό αγάπης.","Sas orkízō, thygatéres Ierousalḗm, eán eúrēte ton agapētón mou, Ti thélete eipeí pros autón? Óti eímai tetrōménē ypó agápēs."],[5,9,"Τι διαφέρει άλλου αγαπητού ο αγαπητός σου, ω ώραία μεταξύ των γυναικών; τι διαφέρει άλλου αγαπητού ο αγαπητός σου, και ώρκισας ημάς ούτως;","Ti diaphérei állou agapētoú o agapētós sou, ō ṓraía metaxý tōn gynaikṓn? ti diaphérei állou agapētoú o agapētós sou, kai ṓrkisas ēmás oútōs?"],[5,10,"Ο αγαπητός μου είναι λευκός και ερυθρός, διακρινόμενος μεταξύ μυριάδων·","O agapētós mou eínai leukós kai erythrós, diakrinómenos metaxý myriádōn:"],[5,11,"Η κεφαλή αυτού είναι χρυσίον δεδοκιμασμένον, οι πλόκαμοι αυτού κλάδοι φοινίκων, μέλανες ως κόραξ·","Ē kephalḗ autoú eínai chrysíon dedokimasménon, oi plókamoi autoú kládoi phoiníkōn, mélanes ōs kórax:"],[5,12,"οι οφθαλμοί αυτού ως περιστερών επί των ρυάκων των υδάτων, λελουμένοι εν γάλακτι, καθήμενοι ως λίθοι ενθέσεως·","oi ophthalmoí autoú ōs peristerṓn epí tōn ryákōn tōn ydátōn, lelouménoi en gálakti, kathḗmenoi ōs líthoi enthéseōs:"],[5,13,"Αι σιαγόνες αυτού ως πρασιαί αρωμάτων, ως αλώνια φυτών μυρεψικών· τα χείλη αυτού ως κρίνα, στάζοντα σμύρναν σταλακτήν·","Ai siagónes autoú ōs prasiaí arōmátōn, ōs alṓnia phytṓn myrepsikṓn: ta cheílē autoú ōs krína, stázonta smýrnan stalaktḗn:"],[5,14,"Αι χείρες αυτού δακτυλίδια χρυσά, πεπληρωμένα με βηρύλλιον· η κοιλία αυτού ελεφάντινον τεχνούργημα, περικεκοσμημένον με σαπφείρους·","Ai cheíres autoú daktylídia chrysá, peplērōména me bērýllion: ē koilía autoú elephántinon technoúrgēma, perikekosmēménon me sappheírous:"],[5,15,"αι κνήμαι αυτού στύλοι μαρμάρινοι, εστηριγμένοι επί βάσεων καθαρού χρυσίου· το είδος αυτού ως Λίβανος· έξοχος ως κέδροι.","ai knḗmai autoú stýloi marmárinoi, estērigménoi epí báseōn katharoú chrysíou: to eídos autoú ōs Líbanos: éxochos ōs kédroi."],[5,16,"Ο ουρανίσκος αυτού είναι γλυκασμοί· και αυτός όλος επιθυμητός. Ούτος είναι ο αγαπητός μου, και ούτος ο φίλος μου, θυγατέρες Ιερουσαλήμ.","O ouranískos autoú eínai glykasmoí: kai autós ólos epithymētós. Oútos eínai o agapētós mou, kai oútos o phílos mou, thygatéres Ierousalḗm."],[6,1,"Που υπήγεν ο αγαπητός σου, ω ωραία μεταξύ των γυναικών; που εστράφη ο αγαπητός σου; και θέλομεν ζητήσει αυτόν μετά σου.","Pou ypḗgen o agapētós sou, ō ōraía metaxý tōn gynaikṓn? pou estráphē o agapētós sou? kai thélomen zētḗsei autón metá sou."],[6,2,"Ο αγαπητός μου κατέβη εις τον κήπον αυτού, εις τας πρασιάς των αρωμάτων, διά να ποιμαίνη εν τοις κήποις και να συνάγη κρίνα.","O agapētós mou katébē eis ton kḗpon autoú, eis tas prasiás tōn arōmátōn, diá na poimaínē en tois kḗpois kai na synágē krína."],[6,3,"Εγώ είμαι του αγαπητού μου, και εμού ο αγαπητός μου· ποιμαίνει μεταξύ των κρίνων.","Egṓ eímai tou agapētoú mou, kai emoú o agapētós mou: poimaínei metaxý tōn krínōn."],[6,4,"Είσαι ώραία, αγαπητή μου, ως Θερσά, εύχαρις ως η Ιερουσαλήμ, τρομερά ως στράτευμα με σημαίας.","Eísai ṓraía, agapētḗ mou, ōs Thersá, eúcharis ōs ē Ierousalḗm, tromerá ōs stráteuma me sēmaías."],[6,5,"Απόστρεψον τους οφθαλμούς σου απεναντίον μου, διότι με κατέπληξαν· τα μαλλία σου είναι ως ποίμνιον αιγών καταβαινόντων από Γαλαάδ.","Apóstrepson tous ophthalmoús sou apenantíon mou, dióti me katéplēxan: ta mallía sou eínai ōs poímnion aigṓn katabainóntōn apó Galaád."],[6,6,"Οι οδόντες σου είναι ως ποίμνιον προβάτων, αναβαινόντων από της λούσεως, τα οποία πάντα γεννώσι δίδυμα, και δεν υπάρχει άτεκνον μεταξύ αυτών·","Oi odóntes sou eínai ōs poímnion probátōn, anabainóntōn apó tēs loúseōs, ta opoía pánta gennṓsi dídyma, kai den ypárchei áteknon metaxý autṓn:"],[6,7,"αι παρειαί σου ως τμήμα ροϊδίου μεταξύ των πλοκάμων σου.","ai pareiaí sou ōs tmḗma roïdíou metaxý tōn plokámōn sou."],[6,8,"Εξήκοντα βασίλισσαι είναι και ογδοήκοντα παλλακαί, και νεάνιδες αναρίθμητοι·","Exḗkonta basílissai eínai kai ogdoḗkonta pallakaí, kai neánides anaríthmētoi:"],[6,9,"μία είναι η περιστερά μου, η αμώμητός μου· αυτή είναι η μόνη της μητρός αυτής· είναι η εκλεκτή της τεκούσης αυτήν. Είδον αυτήν αι θυγατέρες και εμακάρισαν αυτήν· αι βασίλισσαι και αι παλλακαί, και επήνεσαν αυτήν.","mía eínai ē peristerá mou, ē amṓmētós mou: autḗ eínai ē mónē tēs mētrós autḗs: eínai ē eklektḗ tēs tekoúsēs autḗn. Eídon autḗn ai thygatéres kai emakárisan autḗn: ai basílissai kai ai pallakaí, kai epḗnesan autḗn."],[6,10,"Τις αύτη, η προκύπτουσα ως αυγή, ώραία ως η σελήνη, λάμπουσα ως ο ήλιος, τρομερά ως στράτευμα με σημαίας;","Tis aútē, ē prokýptousa ōs augḗ, ṓraía ōs ē selḗnē, lámpousa ōs o ḗlios, tromerá ōs stráteuma me sēmaías?"],[6,11,"Κατέβην εις τον κήπον των καρυών διά να ίδω την χλόην της κοιλάδος, να ίδω εάν εβλάστησεν η άμπελος και εξήνθησαν αι ροϊδιαί.","Katébēn eis ton kḗpon tōn karyṓn diá na ídō tēn chlóēn tēs koiládos, na ídō eán eblástēsen ē ámpelos kai exḗnthēsan ai roïdiaí."],[6,12,"Χωρίς να αισθανθώ, η ψυχή μου με κατέστησεν ως τας αμάξας του Αμινναδίβ.","Chōrís na aisthanthṓ, ē psychḗ mou me katéstēsen ōs tas amáxas tou Aminnadíb."],[6,13,"Επίστρεψον, επίστρεψον, ω Σουλαμίτις· επίστρεψον, επίστρεψον, διά να σε θεωρήσωμεν. Τι θέλετε ιδεί εις την Σουλαμίτιν; Ως χορόν δύο στρατοπέδων;","Epístrepson, epístrepson, ō Soulamítis: epístrepson, epístrepson, diá na se theōrḗsōmen. Ti thélete ideí eis tēn Soulamítin? Ōs chorón dýo stratopédōn?"],[7,1,"Πόσον ώραία είναι τα βήματά σου με τα σανδάλια, θύγατερ του ηγεμόνος το τόρνευμα των μηρών σου είναι όμοιον με περιδέραιον, έργον χειρών καλλιτέχνου.","Póson ṓraía eínai ta bḗmatá sou me ta sandália, thýgater tou ēgemónos to tórneuma tōn mērṓn sou eínai ómoion me peridéraion, érgon cheirṓn kallitéchnou."],[7,2,"Ο ομφαλός σου κρατήρ τορνευτός, πλήρης κεκερασμένου οίνου· η κοιλία σου θημωνία σίτου περιπεφραγμένη με κρίνους·","O omphalós sou kratḗr torneutós, plḗrēs kekerasménou oínou: ē koilía sou thēmōnía sítou peripephragménē me krínous:"],[7,3,"οι δύο σου μαστοί ως δύο σκύμνοι δορκάδος δίδυμοι·","oi dýo sou mastoí ōs dýo skýmnoi dorkádos dídymoi:"],[7,4,"ο τράχηλός σου ως πύργος ελεφάντινος· οι οφθαλμοί σου ως αι κολυμβήθραι εν Εσεβών, προς την πύλην Βαθ-ραββίμ· η μύτη σου ως ο πύργος του Λιβάνου, βλέπων προς την Δαμασκόν·","o tráchēlós sou ōs pýrgos elephántinos: oi ophthalmoí sou ōs ai kolymbḗthrai en Esebṓn, pros tēn pýlēn Bath-rabbím: ē mýtē sou ōs o pýrgos tou Libánou, blépōn pros tēn Damaskón:"],[7,5,"Η κεφαλή σου επί σε ως Κάρμηλος, και η κόμη της κεφαλής σου ως πορφύρα· ο βασιλεύς είναι δεδεμένος εις τους πλοκάμους σου.","Ē kephalḗ sou epí se ōs Kármēlos, kai ē kómē tēs kephalḗs sou ōs porphýra: o basileús eínai dedeménos eis tous plokámous sou."],[7,6,"Πόσον ώραία και πόσον επιθυμητή είσαι, αγαπητή, διά τας τρυφάς.","Póson ṓraía kai póson epithymētḗ eísai, agapētḗ, diá tas tryphás."],[7,7,"Τούτο το ανάστημά σου ομοιάζει με φοίνικα, και οι μαστοί σου με βότρυας.","Toúto to anástēmá sou omoiázei me phoínika, kai oi mastoí sou me bótryas."],[7,8,"Είπα, Θέλω αναβή εις τον φοίνικα, θέλω πιάσει τα βάϊα αυτού· και ιδού, οι μαστοί σου θέλουσιν είσθαι ως βότρυες της αμπέλου, και η οσμή της ρινός σου ως μήλα·","Eípa, Thélō anabḗ eis ton phoínika, thélō piásei ta báïa autoú: kai idoú, oi mastoí sou thélousin eísthai ōs bótryes tēs ampélou, kai ē osmḗ tēs rinós sou ōs mḗla:"],[7,9,"και ο ουρανίσκος σου ως ο καλός οίνος ρέων ηδέως διά τον αγαπητόν μου, και κάμνων να λαλώσι τα χείλη των κοιμωμένων.","kai o ouranískos sou ōs o kalós oínos réōn ēdéōs diá ton agapētón mou, kai kámnōn na lalṓsi ta cheílē tōn koimōménōn."],[7,10,"Εγώ είμαι του αγαπητού μου, και η επιθυμία αυτού είναι προς εμέ.","Egṓ eímai tou agapētoú mou, kai ē epithymía autoú eínai pros emé."],[7,11,"Ελθέ, αγαπητέ μου, ας εξέλθωμεν εις τον αγρόν· ας διανυκτερεύσωμεν εν ταις κώμαις.","Elthé, agapēté mou, as exélthōmen eis ton agrón: as dianyktereúsōmen en tais kṓmais."],[7,12,"Ας εξημερωθώμεν εις τους αμπελώνας· ας ίδωμεν εάν εβλάστησεν η άμπελος, εάν ήνοιξε το άνθος της σταφυλής και εξήνθησαν αι ροϊδιαί· εκεί θέλω δώσει την αγάπην μου εις σε.","As exēmerōthṓmen eis tous ampelṓnas: as ídōmen eán eblástēsen ē ámpelos, eán ḗnoixe to ánthos tēs staphylḗs kai exḗnthēsan ai roïdiaí: ekeí thélō dṓsei tēn agápēn mou eis se."],[7,13,"Οι μανδραγόραι έδωκαν οσμήν, και εν ταις θύραις ημών είναι παν είδος καρπών αρεστών, νέων και παλαιών, τους οποίους εφύλαξα, αγαπητέ μου, διά σε.","Oi mandragórai édōkan osmḗn, kai en tais thýrais ēmṓn eínai pan eídos karpṓn arestṓn, néōn kai palaiṓn, tous opoíous ephýlaxa, agapēté mou, diá se."],[8,1,"Είθε να ήσο ως αδελφός μου, θηλάσας τους μαστούς της μητρός μου. Ευρίσκουσά σε έξω ήθελον σε φιλήσει, και δεν ήθελον με καταφρονήσει.","Eíthe na ḗso ōs adelphós mou, thēlásas tous mastoús tēs mētrós mou. Eurískousá se éxō ḗthelon se philḗsei, kai den ḗthelon me kataphronḗsei."],[8,2,"Ήθελον σε σύρει και σε εισάξει εις τον οίκον της μητρός μου, διά να με διδάξης· ήθελον σε ποτίσει οίνον αρωματικόν και χυμόν του ροϊδίου μου.","Ḗthelon se sýrei kai se eisáxei eis ton oíkon tēs mētrós mou, diá na me didáxēs: ḗthelon se potísei oínon arōmatikón kai chymón tou roïdíou mou."],[8,3,"Η αριστερά αυτού ήθελεν είσθαι υπό την κεφαλήν μου, και η δεξιά αυτού ήθελε με εναγκαλισθή.","Ē aristerá autoú ḗthelen eísthai ypó tēn kephalḗn mou, kai ē dexiá autoú ḗthele me enankalisthḗ."],[8,4,"Σας ορκίζω, θυγατέρες Ιερουσαλήμ, να μη εξεγείρητε μηδέ να εξυπνήσητε την αγάπην μου, εωσού θελήση.","Sas orkízō, thygatéres Ierousalḗm, na mē exegeírēte mēdé na exypnḗsēte tēn agápēn mou, eōsoú thelḗsē."],[8,5,"Τις αύτη η αναβαίνουσα από της ερήμου, επιστηριζομένη επί τον αγαπητόν αυτής; Εγώ σε εξύπνησα υπό την μηλέαν· εκεί σε εκοιλοπόνησεν η μήτηρ σου· εκεί σε εγέννησεν η τεκούσά σε.","Tis aútē ē anabaínousa apó tēs erḗmou, epistērizoménē epí ton agapētón autḗs? Egṓ se exýpnēsa ypó tēn mēléan: ekeí se ekoilopónēsen ē mḗtēr sou: ekeí se egénnēsen ē tekoúsá se."],[8,6,"Θέσον με, ως σφραγίδα, επί την καρδίαν σου, ως σφραγίδα επί τον βραχίονά σου· διότι η αγάπη είναι ισχυρά ως ο θάνατος· η ζηλοτυπία σκληρά ως ο άδης· αι φλόγες αυτής φλόγες πυρός, ανάφλεξις ορμητικωτάτη.","Théson me, ōs sphragída, epí tēn kardían sou, ōs sphragída epí ton brachíoná sou: dióti ē agápē eínai ischyrá ōs o thánatos: ē zēlotypía sklērá ōs o ádēs: ai phlóges autḗs phlóges pyrós, anáphlexis ormētikōtátē."],[8,7,"Ύδατα πολλά δεν δύνανται να σβέσωσι την αγάπην, ουδέ ποταμοί δύνανται να πνίξωσιν αυτήν· εάν τις δώση πάντα τα υπάρχοντα του οίκου αυτού διά την αγάπην, παντελώς θέλουσι καταφρονήσει αυτά.","Ýdata pollá den dýnantai na sbésōsi tēn agápēn, oudé potamoí dýnantai na pníxōsin autḗn: eán tis dṓsē pánta ta ypárchonta tou oíkou autoú diá tēn agápēn, pantelṓs thélousi kataphronḗsei autá."],[8,8,"Ημείς έχομεν αδελφήν μικράν, και μαστούς δεν έχει· τι θέλομεν κάμει εις την αδελφήν ημών την ημέραν καθ' ην γείνη λόγος περί αυτής;","Ēmeís échomen adelphḗn mikrán, kai mastoús den échei: ti thélomen kámei eis tēn adelphḗn ēmṓn tēn ēméran kath' ēn geínē lógos perí autḗs?"],[8,9,"Εάν ήναι τείχος, θέλομεν οικοδομήσει επ' αυτήν παλάτιον αργυρούν· και εάν ήναι θύρα, θέλομεν περιασφαλίσει αυτήν με σανίδας κεδρίνας.","Eán ḗnai teíchos, thélomen oikodomḗsei ep' autḗn palátion argyroún: kai eán ḗnai thýra, thélomen periasphalísei autḗn me sanídas kedrínas."],[8,10,"Εγώ είμαι τείχος, και οι μαστοί μου ως πύργοι· τότε ήμην εις τους οφθαλμούς αυτού ως ευρίσκουσα ειρήνην.","Egṓ eímai teíchos, kai oi mastoí mou ōs pýrgoi: tóte ḗmēn eis tous ophthalmoús autoú ōs eurískousa eirḗnēn."],[8,11,"Ο Σολομών είχεν αμπελώνα εν Βάαλ-χαμών· έδωκε τον αμπελώνα εις φύλακας· έκαστος έπρεπε να φέρη διά τον καρπόν αυτού χίλια αργύρια.","O Solomṓn eíchen ampelṓna en Báal-chamṓn: édōke ton ampelṓna eis phýlakas: ékastos éprepe na phérē diá ton karpón autoú chília argýria."],[8,12,"Ο αμπελών εμού είναι έμπροσθέν μου· τα χίλια ας ήναι διά σε, Σολομών, και διακόσια διά τους φυλάττοντας τον καρπόν αυτού.","O ampelṓn emoú eínai émprosthén mou: ta chília as ḗnai diá se, Solomṓn, kai diakósia diá tous phyláttontas ton karpón autoú."],[8,13,"Ω συ η καθημένη εν τοις κήποις, οι σύντροφοι προσέχουσιν εις την φωνήν σου· κάμε με να ακούσω αυτήν.","Ō sy ē kathēménē en tois kḗpois, oi sýntrophoi proséchousin eis tēn phōnḗn sou: káme me na akoúsō autḗn."],[8,14,"Φεύγε, αγαπητέ μου, και γίνου όμοιος με δορκάδα ή με σκύμνον ελάφου επί τα όρη των αρωμάτων.","Pheúge, agapēté mou, kai gínou ómoios me dorkáda ḗ me skýmnon eláphou epí ta órē tōn arōmátōn."]],"grc-swete":[[1,1,"ΑΣΜΑ ἀσμάτων, ὅ ἐστιν τῷ Σαλωμών.","ASMA asmátōn, hó estin tō̂i Salōmṓn."],[1,2,"Φιλησάτω με ἀπὸ φιλημάτων στόματος αὐτοῦ· ὅτι ἀγαθοὶ μαστοί σου ὑπὲρ οἶνον,","Philēsátō me apò philēmátōn stómatos autoû: hóti agathoì mastoí sou hypèr oînon,"],[1,3,"³καὶ ὀσμὴ μύρων σου ὑπέρ πάντα τὰ 3 ἀρώματα· μύρον ἐκκενωθὲν ὄνομά σου. διὰ τοῦτο νεάνιδες ἠγάπησάν σε,","³kaì osmḕ mýrōn sou hypér pánta tà 3 arṓmata: mýron ekkenōthèn ónomá sou. dià toûto neánides ēgápēsán se,"],[1,4,"εἴλκυσάν σε· ὀπίσω σου εἰς ὀσμὴν μύρσων σου δραμομεν. εἰσήνεγκέν με ὁ βασιλεὺς εἰς τὸ ταμεῖον αὐτοῦ. ἀγαλλιασώμεθα καὶ εὐφρανθῶμεν ἐν σοί· ἀγαπήσομεν μαστούς σου ὑπὲρ οἶνον· εὐθύτης ἠγάπησέν σε.","eílkysán se: opísō sou eis osmḕn mýrsōn sou dramomen. eisḗnenkén me ho basileùs eis tò tameîon autoû. agalliasṓmetha kaì euphranthō̂men en soí: agapḗsomen mastoús sou hypèr oînon: euthýtēs ēgápēsén se."],[1,5,"Μέλαινά εἰμι καὶ καλή, θυγατέρες Ἰσραήλ, ὡς σκηνώματα Κηδάρ, ὡς δέρρις Σαλωμών.","Mélainá eimi kaì kalḗ, thygatéres Israḗl, hōs skēnṓmata Kēdár, hōs dérris Salōmṓn."],[1,6,"μὴ βλέψητέ με, ὅτι ἐγώ εἰμι μεμελανωμένη, ὅτι παρέβλεψέν με ὁ ἥλιος· υἱοὶ μητρός μου ἐμαχέσαντο ἐν ἐμοί, ἔθεντό με φυλάκισσαν ἐν ἀμπελῶσιν· ἀμπελῶνα ἐμὸν οὐκ ἐφύλαξα.","mḕ blépsēté me, hóti egṓ eimi memelanōménē, hóti paréblepsén me ho hḗlios: hyioì mētrós mou emachésanto en emoí, éthentó me phylákissan en ampelō̂sin: ampelō̂na emòn ouk ephýlaxa."],[1,7,"ἀπάγγειλόν μοι, ὃν ἠγάπησεν ἡ ψυχή μου. ποῦ ποιμαίνεις, ποῦ κοιτάζεις ἐν μεσημβρίᾳ, μή ποτε γένωμαι ὡς περιβαλλομένη ἐπʼ ἀγέλας ἑταίρων σου.","apángeilón moi, hòn ēgápēsen hē psychḗ mou. poû poimaíneis, poû koitázeis en mesēmbríāi, mḗ pote génōmai hōs periballoménē epʼ agélas hetaírōn sou."],[1,8,"Ἐὰν μὴ γνῷς σεαυτήν, ἡ καλὴ ἐν γυναιξίν, ἔξελθε οὺ ἐν πτέρναις τῶν ποιμνίων, καὶ ποίμαινε τὰς ἐρίφους σου ἐπὶ σκηνώμασιν τῶν ποιμένων.","Eàn mḕ gnō̂is seautḗn, hē kalḕ en gynaixín, éxelthe où en ptérnais tō̂n poimníōn, kaì poímaine tàs eríphous sou epì skēnṓmasin tō̂n poiménōn."],[1,9,"Τῇ ἵππῳ μου ἐν ἅρμασιν Φαραὼ ὡμοἰωσά σε, ἡ πλησίον μου.","Tē̂i híppōi mou en hármasin Pharaṑ hōmoiōsá se, hē plēsíon mou."],[1,10,"τί ὡραιώθησαν σιαγόνες σου ὡς τρυγόνες, τράχηλός σου ὡς ὁρμίσκοις","tí hōraiṓthēsan siagónes sou hōs trygónes, tráchēlós sou hōs hormískois"],[1,11,"ὁμοιώματα χρυσίου ποιήσομέν σοι μετὰ στιγμάτων τοῦ ἀργυρίου.","homoiṓmata chrysíou poiḗsomén soi metà stigmátōn toû argyríou."],[1,12,"Ἕως οὗ ὁ βασιλεὺς ἐν ἀνακλίσει αὐτοῦ, νάρδος μου ἔδωκεν ὀσμὴν αὐτοῦ.","Héōs hoû ho basileùs en anaklísei autoû, nárdos mou édōken osmḕn autoû."],[1,13,"ἀπόδεσμος τῆς στακτῆς ἀδελφιδός μου ἐμοί.","apódesmos tē̂s staktē̂s adelphidós mou emoí."],[1,14,"ἐν ἀμπελῶσιν Ἐνγαδδεί.","en ampelō̂sin En'gaddeí."],[1,15,"Ἰδοὺ εἶ καλή, ἡ πλησίν μου. ἰδοὺ εἶ καλή· ὀφθαλμοί σου περιστεραί.","Idoù eî kalḗ, hē plēsín mou. idoù eî kalḗ: ophthalmoí sou peristeraí."],[1,16,"Ἰδοὺ εἶ καλός. ἀδελφιδός μου. καί γε ὡραῖος· πρὸς κλίνῃ ἡμῶν σύσκιος.","Idoù eî kalós. adelphidós mou. kaí ge hōraîos: pròs klínēi hēmō̂n sýskios."],[1,17,"δοκοὶ σἴκων ἡμῶν κέδροι, φατνώματα ἡμῶν κυπάρισσοι.","dokoì síkōn hēmō̂n kédroi, phatnṓmata hēmō̂n kypárissoi."],[2,1,"ἐγὼ ἄνθος τοῦ πεδίου, κρίνον τῶν κοιλάδων.","egṑ ánthos toû pedíou, krínon tō̂n koiládōn."],[2,2,"Ὡς κρίνον ἐν μέσῳ ἀκανθῶν, οὕτως ἡ πλησίον μου ἀνὰ μέσον τῶν θυγατέρων.","Hōs krínon en mésōi akanthō̂n, hoútōs hē plēsíon mou anà méson tō̂n thygatérōn."],[2,3,"Ὡς μῆλον ἐν τοῖς ξύλοις τοῦ δρυμοῦ, οὕτως ἀδελφιδός μου ἀνὰ μέσον τῶν υἱῶν· ἐν τῇ σκιᾷ αὐτοῦ ἐπεθύμησα καὶ ἐκάθισα, καὶ καρπὸς αὐτοῦ γλυκὺς ἐν λάρυγγί μου.","Hōs mē̂lon en toîs xýlois toû drymoû, hoútōs adelphidós mou anà méson tō̂n hyiō̂n: en tē̂i skiā̂i autoû epethýmēsa kaì ekáthisa, kaì karpòs autoû glykỳs en láryngí mou."],[2,4,"εἰσαγάγετέ με εἰς οἶκον τοῦ οἴνου, τάξατε ἐπʼ ἐμέ ἀγάπην.","eisagágeté me eis oîkon toû oínou, táxate epʼ emé agápēn."],[2,5,"στηρίσατέ με ἐν μύροις, στοιβάσατέ με ἐν μήλοις, ὅτι τετρωμένη ἀγάπης ἐγώ.","stērísaté me en mýrois, stoibásaté me en mḗlois, hóti tetrōménē agápēs egṓ."],[2,6,"εὐώνυμος αὐτοῦ ὑπὸ τὴν κεφαλήν μου, καὶ ἡ δεξιὰ αὐτοῦ περιλήμψεταί με.","euṓnymos autoû hypò tḕn kephalḗn mou, kaì hē dexià autoû perilḗmpsetaí me."],[2,7,"Ὥρκισα ὑμᾶς, θυγατέρες Ἰερουσαλήμ, ἐν δυνάμεσιν καὶ ἐν ἰσχύσεσιν τοῦ ἀγροῦ, ἐὰν ἐγείρητε καὶ ἐξεγείρητε τὴν ἀγάπην ἕως οὗ θελήσῃ.","Hṓrkisa hymâs, thygatéres Ierousalḗm, en dynámesin kaì en ischýsesin toû agroû, eàn egeírēte kaì exegeírēte tḕn agápēn héōs hoû thelḗsēi."],[2,8,"Φωνὴ ἀδελφιδοῦ μου· ἰδοὺ οὗτος ἥκει πηδῶν ἐπὶ τὰ ὄρη, διαλλόμενος ἐπὶ τοὺς βουνούς.","Phōnḕ adelphidoû mou: idoù hoûtos hḗkei pēdō̂n epì tà órē, diallómenos epì toùs bounoús."],[2,9,"ὅμοιός ἐστιν ἀδελφιδός μου τῇ δορκάδι ἢ νεβρῷ ἐλάφων ἐπὶ τὰ ὄρη Βαιθήλ. ἰδοὺ οὗτος ὀπίσω τοῦ τοίχου ἡμῶν, παρακύπτων διὰ τῶν θυρίδων ἐκκύπτων διὰ τῶν δικτύων.","hómoiós estin adelphidós mou tē̂i dorkádi ḕ nebrō̂i eláphōn epì tà órē Baithḗl. idoù hoûtos opísō toû toíchou hēmō̂n, parakýptōn dià tō̂n thyrídōn ekkýptōn dià tō̂n diktýōn."],[2,10,"ἀποκρίνεται ἀδελφιδός μου καὶ λέγει μοι Ἀνάστα ἐλθέ, ἡ πλησίον μου, καλή μου, περιστερά μου.","apokrínetai adelphidós mou kaì légei moi Anásta elthé, hē plēsíon mou, kalḗ mou, peristerá mou."],[2,11,"ὅτι ἰδοὺ ὁ χειμὼν παρῆλθεν, ὁ ὑετὸς ἀπῆλθεν, ἐπορεύθη ἑαυτῷ·","hóti idoù ho cheimṑn parē̂lthen, ho hyetòs apē̂lthen, eporeúthē heautō̂i:"],[2,12,"τὰ ἄνθη ὤφθη ἐν τῇ γῇ, καιρὸς τῆς τομῆς ἔφθακεν, φωνὴ τοῦ τρυγόνος ἠκούσθη ἐν τῇ γῇ ἡμῶν·","tà ánthē ṓphthē en tē̂i gē̂i, kairòs tē̂s tomē̂s éphthaken, phōnḕ toû trygónos ēkoústhē en tē̂i gē̂i hēmō̂n:"],[2,13,"ἡ συκῆ ἐξήνεγκεν ὀλύνθους αὐτῆς, αἱ ἄμπελοι κυπρίζουσιν, ἔδωκαν ὀσμήν. ἀνάστα ἐλθέ, ἡ πλησίον μου, καλή μου, περιστερά μου. καὶ ἐλθέ,","hē sykē̂ exḗnenken olýnthous autē̂s, hai ámpeloi kyprízousin, édōkan osmḗn. anásta elthé, hē plēsíon mou, kalḗ mou, peristerá mou. kaì elthé,"],[2,14,"σὺ περιστερά μου, ἐν σκέπῃ τῆς πέτρας, ἐχόμενα τοῦ προτειχίσματος δεῖξόν μοι τὴν ὄψιν σου, καὶ ἀκούτισόν με τὴν φωνήν σου, ὅτι ἡ φωνή σου ἡδεῖα, καὶ ἡ ὄψις σου ὡραία.","sỳ peristerá mou, en sképēi tē̂s pétras, echómena toû proteichísmatos deîxón moi tḕn ópsin sou, kaì akoútisón me tḕn phōnḗn sou, hóti hē phōnḗ sou hēdeîa, kaì hē ópsis sou hōraía."],[2,15,"πιάσατε ἡμῖν ἀλώπεκας μικροὺς ἀφανίζοντας ἀμπελῶνας· καὶ αἱ ἄμπελοι ἡμῶν κυπρίζουσαι.","piásate hēmîn alṓpekas mikroùs aphanízontas ampelō̂nas: kaì hai ámpeloi hēmō̂n kyprízousai."],[2,16,"βελφιδός μου ἐμοὶ κἀγὼ αὐτῷ· ὁ ποιμαίνων ἐν τοῖς κρίνοις,","belphidós mou emoì kagṑ autō̂i: ho poimaínōn en toîs krínois,"],[2,17,"ἕως οὗ διαπνεύσῃ ἡ ἡμέρα καὶ κινηθῶσιν αἱ σκιαί. ἀπόστρεψον, ὁμοιώθητι σύ, ἀδελφιδέ, τῷ δόρκωνι ἢ νεβρῷ ἐλάφων ἐπὶ ὄρη κοιλωμάτων.","héōs hoû diapneúsēi hē hēméra kaì kinēthō̂sin hai skiaí. apóstrepson, homoiṓthēti sý, adelphidé, tō̂i dórkōni ḕ nebrō̂i eláphōn epì órē koilōmátōn."],[3,1,"ἐπὶ κοίτην μου ἐν νυξὶν ἐζήτησα ὃν ἠγάπησεν ἡ ψυχή μου· ἐζήτησα αὐτὸν καὶ οὐχ εὗρον αὐτόν, ἐκάλεσα αὐτὸν καὶ οὐχ ὑπήκουσέν μου.","epì koítēn mou en nyxìn ezḗtēsa hòn ēgápēsen hē psychḗ mou: ezḗtēsa autòn kaì ouch heûron autón, ekálesa autòn kaì ouch hypḗkousén mou."],[3,2,"ἀναστήσομαι δὴ καὶ κυκλώσω ἐν τῇ πόλει, ἐν ταῖς ἀγοραῖς καὶ ἐν ταῖς πλατείαις, καὶ ζητήσω ὃν ἠγάπησεν ἡ ψυχή μου· ἐζήτησα αὐτὸν καὶ οὐχ εὗρον αὐτόν.","anastḗsomai dḕ kaì kyklṓsō en tē̂i pólei, en taîs agoraîs kaì en taîs plateíais, kaì zētḗsō hòn ēgápēsen hē psychḗ mou: ezḗtēsa autòn kaì ouch heûron autón."],[3,3,"εὕροσάν με οἱ τηροῦντες, οἱ κυκλοῦντες ἐν τῇ πόλει Μὴ ὃν ἠγάπησεν ἡ ψυχή μου εἴδετε;","heúrosán me hoi tēroûntes, hoi kykloûntes en tē̂i pólei Mḕ hòn ēgápēsen hē psychḗ mou eídete?"],[3,4,"ὡς μικρὸν ὅτε παρῆλθον ἀπʼ αὐτῶν, ἕως οὗ εὗρον ὃν ἠγάπησεν ἡ ψυχή μου· ἐκράτησα αὐτὸν καὶ οὐκ ἀφῆκα αὐτόν, ἕως οὗ εἰσήγαγον αὐτὸν εἰς οἶκον μητρός μου καὶ εἰς ταμεῖον τῆς συλλαβούσης με.","hōs mikròn hóte parē̂lthon apʼ autō̂n, héōs hoû heûron hòn ēgápēsen hē psychḗ mou: ekrátēsa autòn kaì ouk aphē̂ka autón, héōs hoû eisḗgagon autòn eis oîkon mētrós mou kaì eis tameîon tē̂s syllaboúsēs me."],[3,5,"Ὥρκισα ὑμᾶς, θυγατέρες Ἰερουσαλήμ, ἐν ταῖς δυνάμεσιν καὶ ἐν ταῖς ἰσχύσεσιν τοῦ ἀγροῦ, ἐὰν ἐγείρητε καὶ ἐξεγείρητε τὴν ἀγάπην ἕως ἂν θελήσῃ.","Hṓrkisa hymâs, thygatéres Ierousalḗm, en taîs dynámesin kaì en taîs ischýsesin toû agroû, eàn egeírēte kaì exegeírēte tḕn agápēn héōs àn thelḗsēi."],[3,6,"Τίς αὕτη ἡ ἀναβαίνουσα ἀπὸ τῆς ἐρήμου. ὡς στελέχη καπνοῦ τεθυμιαμένη σμύρναν καὶ λίβανον ἀπὸ πάντων κονιορτῶν μυρεψοῦ;","Tís haútē hē anabaínousa apò tē̂s erḗmou. hōs steléchē kapnoû tethymiaménē smýrnan kaì líbanon apò pántōn koniortō̂n myrepsoû?"],[3,7,"ἰδοὺ ἡ κλίνη τοῦ Σαλωμών, ἐξήκοντα δυνατοὶ κύκλῳ αὐτῆς ἀπὸ δυνατῶν Ἰσραήλ·","idoù hē klínē toû Salōmṓn, exḗkonta dynatoì kýklōi autē̂s apò dynatō̂n Israḗl:"],[3,8,"πάντες κατέχοντες ῥομφαίαν, δεδιδαγμένοι πόλεμον· ἀνὴρ ῥομφαία αὐτοῦ ἐπὶ μηρὸν αὐτοῦ ἀπὸ θάμβους ἐν νυξίν.","pántes katéchontes rhomphaían, dedidagménoi pólemon: anḕr rhomphaía autoû epì mēròn autoû apò thámbous en nyxín."],[3,9,"φορεῖον ἐποίησεν ἑαυτῷ ὁ βασιλεὺς Σαλωμὼν ἀπὸ ξύλων τοῦ Λιβάνου·","phoreîon epoíēsen heautō̂i ho basileùs Salōmṑn apò xýlōn toû Libánou:"],[3,10,"στύλους αὐτοῦ ἐποίησεν ἀργύριον, καὶ ἀνάκλιτον αὐτοῦ χρύσεον· ἐπίβασις αὐτοῦ πορφυρᾶ, ἐντὸς αὐτοῦ λιθόστρωτον, ἀγάπην ἀπὸ θυγατέρων Ἰερουσαλήμ.","stýlous autoû epoíēsen argýrion, kaì anákliton autoû chrýseon: epíbasis autoû porphyrâ, entòs autoû lithóstrōton, agápēn apò thygatérōn Ierousalḗm."],[3,11,"ἐξέλθατε καὶ ἴδετε ἐν τῷ βασιλεῖ Σαλωμών, ἐν τῷ στεφάνῳ ᾧ ἐστεφάνωσεν αὐτὸν ἡ μήτηρ αὐτοῦ ἐν ἡμέρᾳ νυμφεύσεως αὐτοῦ καὶ ἐν ἡμέρᾳ εὐφροσύνης καρδίας αὐτοῦ.","exélthate kaì ídete en tō̂i basileî Salōmṓn, en tō̂i stephánōi hō̂i estephánōsen autòn hē mḗtēr autoû en hēmérāi nympheúseōs autoû kaì en hēmérāi euphrosýnēs kardías autoû."],[4,1,"Ἰδοὺ εἶ καλὴ πλησίον μου, ἰδοὺ εἶ καλή. ὀφθαλμοί σου περιστεραὶ ἐκτὸς τῆς σιωπήσεώς σου. τρίχαμά σου ὡς ἀγέλαι τῶν αἰγῶν αἳ ἀπεκαλύφθησαν ἀπὸ τοῦ Γαλαάδ.","Idoù eî kalḕ plēsíon mou, idoù eî kalḗ. ophthalmoí sou peristeraì ektòs tē̂s siōpḗseṓs sou. tríchamá sou hōs agélai tō̂n aigō̂n haì apekalýphthēsan apò toû Galaád."],[4,2,"ὀδόντες σου ὡς ἀγέλαι τῶν κεκαρμέναων αἳ ἀνέβησαν ἀπὸ τοῦ λουτροῦ, αἱ πᾶσαι διδυμεύουσαι, καὶ ἀτεκνοῦσα οὐκ ἔστιν ἐν αὐταῖς.","odóntes sou hōs agélai tō̂n kekarménaōn haì anébēsan apò toû loutroû, hai pâsai didymeúousai, kaì ateknoûsa ouk éstin en autaîs."],[4,3,"ὡς σπαρτίον τὸ κόκκινον χείλη σου, καὶ ἡ λαλιά σου ὡραία· ὡς λέπυρον ῥόας μῆλόν σου ἐκτὸς τῆς σιωπήσεως σου.","hōs spartíon tò kókkinon cheílē sou, kaì hē laliá sou hōraía: hōs lépyron rhóas mē̂lón sou ektòs tē̂s siōpḗseōs sou."],[4,4,"ὡς πύργος Δαυεὶδ τράχηλός σου, ὁ ᾠκοδομημένος εἰς Θαλπιώθ. χίλιοι θυρεοὶ κρέμανται ἐπʼ αὐτόν, πᾶσαι βολίδες τῶν δυνατῶν.","hōs pýrgos Daueìd tráchēlós sou, ho ōikodomēménos eis Thalpiṓth. chílioi thyreoì krémantai epʼ autón, pâsai bolídes tō̂n dynatō̂n."],[4,5,"δύο μαστοί σου ὡς δύο νεβροὶ δἰδυμοι δορκάδος οἱ νεμόμενοι ἐν κρίνοις.","dýo mastoí sou hōs dýo nebroì didymoi dorkádos hoi nemómenoi en krínois."],[4,6,"ἕως οὗ διαπνεύσῃ ἡ ἡμέρα καὶ κινηθῶσιν αἱ σκιαί, πορεύσομαι ἐμαυτῷ πρὸς τὸ ὄρος τῆς σμύρνης καὶ πρὸς τὸν βουνὸν τοῦ Λιβάνου.","héōs hoû diapneúsēi hē hēméra kaì kinēthō̂sin hai skiaí, poreúsomai emautō̂i pròs tò óros tē̂s smýrnēs kaì pròs tòn bounòn toû Libánou."],[4,7,"ὅλη καλὴ εἶ πλησίον μου, καὶ μῶμος οὐκ ἔστιν ἐν σοί. δεῦρο ἀπὸ Λιβάνου, νύμφη, δεῦρο ἀπὸ Λιβάνου· ἐλεύσῃ καὶ διελεύσῃ ἀπὸ ἀρχῆς πίστεως. ἀπὸ κεφαλῆς Σανεὶρ καὶ Ἑρμών, ἀπὸ μανδρῶν λεόντων, ἀπὸ ὀρέων παρδάλεων.","hólē kalḕ eî plēsíon mou, kaì mō̂mos ouk éstin en soí. deûro apò Libánou, nýmphē, deûro apò Libánou: eleúsēi kaì dieleúsēi apò archē̂s písteōs. apò kephalē̂s Saneìr kaì Hermṓn, apò mandrō̂n leóntōn, apò oréōn pardáleōn."],[4,9,"ἐκαρδίωσας ἡμᾶς, ἀδελφή μου νύμφη· ἐκαρδίωσας ἡμᾶς ἑνὶ ἀπὸ ὀφθαλμῶν σου, ἐν μιᾷ, ἐν θέματι τραχήλων σου.","ekardíōsas hēmâs, adelphḗ mou nýmphē: ekardíōsas hēmâs henì apò ophthalmō̂n sou, en miā̂i, en thémati trachḗlōn sou."],[4,10,"τί ἐκαλλιώθησαν μαστοί σου ἀπὸ οἴνου, καὶ ὀσμὴ ἱματίων σου ὑπὲρ πάντα ἀρώματα","tí ekalliṓthēsan mastoí sou apò oínou, kaì osmḕ himatíōn sou hypèr pánta arṓmata"],[4,11,"κηρίον ἀποστάζουσιν χείλη σου, νύμφη· μέλι καὶ γάλα ὑπὸ τὴν γλῶσσάν σου, καὶ ὀσμὴ ἱματίων σου ὡς ὀσμὴ Λβάνου.","kēríon apostázousin cheílē sou, nýmphē: méli kaì gála hypò tḕn glō̂ssán sou, kaì osmḕ himatíōn sou hōs osmḕ Lbánou."],[4,12,"κῆπος κεκλεισμένος ἀδελφή μου νύμφη, κῆπος κεκλεισμένος, πηγὴ ἐσφραγισμένη·","kē̂pos kekleisménos adelphḗ mou nýmphē, kē̂pos kekleisménos, pēgḕ esphragisménē:"],[4,13,"ἀποστολαί σου παράδεισος μετὰ καρποῦ ἀκροδρύων, κύπροι μετὰ νάρδων·","apostolaí sou parádeisos metà karpoû akrodrýōn, kýproi metà nárdōn:"],[4,14,"νάρδος καὶ κρόκος, κάλαμος καὶ κιννάμαωμον μετὰ πάντων ξύλων τοῦ Λιβάνου, σμύρνα ἀλὼθ μετὰ πάνταον πρώτων μύρων·","nárdos kaì krókos, kálamos kaì kinnámaōmon metà pántōn xýlōn toû Libánou, smýrna alṑth metà pántaon prṓtōn mýrōn:"],[4,15,"πηγὴ κήπου καὶ φρέαρ ὕδατος ζῶντος καὶ ῥοιζοῦντος ἀπὸ τοῦ Λιβάνου.","pēgḕ kḗpou kaì phréar hýdatos zō̂ntos kaì rhoizoûntos apò toû Libánou."],[4,16,"Ἐξεγέρθητι, βορρᾶ· καὶ ἔρχου. νότε, καὶ διάπνευσον κῆπόν μου, καὶ ῥευσάτωσαν ἀρώματά μου.","Exegérthēti, borrâ: kaì érchou. nóte, kaì diápneuson kē̂pón mou, kaì rheusátōsan arṓmatá mou."],[5,1,"καταβήτω ἀδελφιδός μου εἰς κῆπον αὐτοῦ καὶ φαγέτω καρπὸν ἀκροδρύων αὐτοῦ. (¹)Εἰοῆλθον εἰς κῆπον, ἀδελφή μου νύμφη· ἐτρύγησα σμύρναν μου μετὰ ἀρωμάτων μου, ἔφαγον ἄρτον μου μετὰ μέλιτός μου, ἔπιον οἶνόν μου μετὰ γάλακτός μου. φάγετε, πλησίοι, καὶ πίετε καὶ μεθύσθητε, ἀδελφοί","katabḗtō adelphidós mou eis kē̂pon autoû kaì phagétō karpòn akrodrýōn autoû. (¹)Eioē̂lthon eis kē̂pon, adelphḗ mou nýmphē: etrýgēsa smýrnan mou metà arōmátōn mou, éphagon árton mou metà mélitós mou, épion oînón mou metà gálaktós mou. phágete, plēsíoi, kaì píete kaì methýsthēte, adelphoí"],[5,2,"Ἐγὼ καθεύδω, καὶ ἡ καρδία μου ἀγρυπνεῖ φωνὴ ἀδελφιδοῦ μου, κρούει ἐπὶ τὴν θύραν Ἄνοιξόν μοι, ἀδελφή μου, ἡ πλησίον μου. περιστερά μου, τελεία μου, ὅτι ἡ κεφαλή μου ἐπλήσθη δρόσου καὶ οἱ βόστρυχοί μου ψεκάδων νυκτός.","Egṑ katheúdō, kaì hē kardía mou agrypneî phōnḕ adelphidoû mou, kroúei epì tḕn thýran Ánoixón moi, adelphḗ mou, hē plēsíon mou. peristerá mou, teleía mou, hóti hē kephalḗ mou eplḗsthē drósou kaì hoi bóstrychoí mou psekádōn nyktós."],[5,3,"ἐξεδυσάμην τὸν χιτῶνά μου, πῶς ἐνδύσωμαι αὐτόν; ἐνιψάμην τοὺς πόδας μου, πῶς μολυνῶ αὐτούς;","exedysámēn tòn chitō̂ná mou, pō̂s endýsōmai autón? enipsámēn toùs pódas mou, pō̂s molynō̂ autoús?"],[5,4,"ἀδελφιδός μου ἀπέστειλεν χεῖρα αὐτοῦ ἀπὸ τῆς ὀπῆς. καὶ ἡ κοιλία μου ἐθροήθη ἐπʼ αὐτόν.","adelphidós mou apésteilen cheîra autoû apò tē̂s opē̂s. kaì hē koilía mou ethroḗthē epʼ autón."],[5,5,"ἀνέστην ἐγὼ ἀνοῖξαι τῷ ἀδελφιδῷ μου. χεῖρές μου ἔσταξαν σμύρναν, δάκτυλοί μου σμύρναν πλήρη ἐπὶ χεῖρας τοῦ κλείθρου.","anéstēn egṑ anoîxai tō̂i adelphidō̂i mou. cheîrés mou éstaxan smýrnan, dáktyloí mou smýrnan plḗrē epì cheîras toû kleíthrou."],[5,6,"ἤνοιξα ἐγὼ τῷ ἀδελφιδῷ μου, ἀδελφιδός μου παρῆλθεν· ψυχή μου ἐξῆλθεν ἐν λόγῳ αὐτοῦ· ἐζήτησα αὐτὸν καὶ οὐχ εὖρον αὐτόν, ἐκάλεσα αὐτὸν καὶ οὐχ ὑπήκουσέν μου.","ḗnoixa egṑ tō̂i adelphidō̂i mou, adelphidós mou parē̂lthen: psychḗ mou exē̂lthen en lógōi autoû: ezḗtēsa autòn kaì ouch eûron autón, ekálesa autòn kaì ouch hypḗkousén mou."],[5,7,"εὕροσάν με οἱ φύλακες οἱ κυκλοῦντες ἐν τῇ πόλει. ἐπάταξάν με, ἐτραυμάτισάν με· ἦραν τὸ θέριστρόν μου ἀπʼ ἐμοῦ φύλακες τῶν τειχέων","heúrosán me hoi phýlakes hoi kykloûntes en tē̂i pólei. epátaxán me, etraumátisán me: ē̂ran tò théristrón mou apʼ emoû phýlakes tō̂n teichéōn"],[5,8,"Ὥρκισα ὑμᾶς, θυγατέρες Ἰερουσαλήμ, ἐν ταῖς δυνάμεσιν καὶ ἐν ταῖς ἰσχύσεσιν τοῦ ἀγροῦ, ἐὰν εὕρητε τὸν ἀδελφιδόν μου, τί ἀπαγγείλητε αὐτῷ; ὅτι τετρωμένη ἀγάπης ἐγώ.","Hṓrkisa hymâs, thygatéres Ierousalḗm, en taîs dynámesin kaì en taîs ischýsesin toû agroû, eàn heúrēte tòn adelphidón mou, tí apangeílēte autō̂i? hóti tetrōménē agápēs egṓ."],[5,9,"Τί ἀδελφιδός σου ἀπὸ ἀδελφιδοῦ, ἡ καλὴ ἐν γυναιείν, τἰ ἀδελφιδός σου ἀπὸ ἀδελφιδοῦ, ὅτι οὕτως ὥρκισας ἡμᾶς;","Tí adelphidós sou apò adelphidoû, hē kalḕ en gynaieín, ti adelphidós sou apò adelphidoû, hóti hoútōs hṓrkisas hēmâs?"],[5,10,"Ἀδελφιδός μου λευκὸς καὶ πυρρός, ἐκλελοχισμένος ἀπὸ μυριάδων.","Adelphidós mou leukòs kaì pyrrós, eklelochisménos apò myriádōn."],[5,11,"κεφαλὴ αὐτοῦ χρυσίον καὶ φάζ, βόστρυχοι αὐτοῦ ἐλάται, μέλανες ὡς κόραξ.","kephalḕ autoû chrysíon kaì pház, bóstrychoi autoû elátai, mélanes hōs kórax."],[5,12,"Ζφθαλμοὶ αὐτοῦ ὡς περιστεραὶ ἐπὶ πληρώματα ὑδάτων λελουσμέναι ἐν γάλακτι, καθήμεναι ἐπὶ πληρώματα.","Zphthalmoì autoû hōs peristeraì epì plērṓmata hydátōn lelousménai en gálakti, kathḗmenai epì plērṓmata."],[5,13,"σιαγόνες αὐτοῦ ὡς φιάλαι τοῦ ἀρώματος φύουσαι μυρεψικά, χείλη αὐτοῦ κρίνα στάζοντα σμύρναν πλήρη.","siagónes autoû hōs phiálai toû arṓmatos phýousai myrepsiká, cheílē autoû krína stázonta smýrnan plḗrē."],[5,14,"χεῖρες αὐτοῦ τορευταὶ χρυσαῖ πεπληραομέναι Θαρσείς. κοιλία αὐτοῦ πυξίον ἐλεφάντινον ἐπὶ λίθου σαπφείρου.","cheîres autoû toreutaì chrysaî peplēraoménai Tharseís. koilía autoû pyxíon elephántinon epì líthou sappheírou."],[5,15,"κνῆμαι αὐτοῦ στύλοι μαρμάρινοι τεθεμελιωμένοι ἐπὶ βάσεις χρυσᾶς· εἶδος αὐτοῦ ὡς Λίβανος, ἐκλεκτὸς ὡς κέδροι.","knē̂mai autoû stýloi marmárinoi tethemeliōménoi epì báseis chrysâs: eîdos autoû hōs Líbanos, eklektòs hōs kédroi."],[5,16,"φάρυγξ αὐτοῦ γλυκασμοὶ καὶ ὅλος ἐπιθυμία. οὗτος ἀδελφιδός μου καὶ οὗτος πλησίον μου, θυγατέρες Ἰερουσαλήμ.","phárynx autoû glykasmoì kaì hólos epithymía. hoûtos adelphidós mou kaì hoûtos plēsíon mou, thygatéres Ierousalḗm."],[5,17,"Ποῦ ἀπῆλθεν ὁ ἀδελφιδός σου, ἡ καλὴ ἐν γυναιξίνς; ποῦ ἀπέβλεψεν ὁ ἀδελφιδός σους; καὶ ζητήσομεν αὐτὸν μετὰ σοῦ.","Poû apē̂lthen ho adelphidós sou, hē kalḕ en gynaixíns? poû apéblepsen ho adelphidós sous? kaì zētḗsomen autòn metà soû."],[6,1,"Ἀδελφός μου κατέβη εἰς κῆπον αὐτοῦ εἰς φιάλας τοῦ ἀρῶματος, ποιμαίνειν ἐν κήποις καὶ συλλέγειν κρίνα.","Adelphós mou katébē eis kē̂pon autoû eis phiálas toû arō̂matos, poimaínein en kḗpois kaì syllégein krína."],[6,2,"ἐγκ τῷ ἀδελφιδῷ μου καὶ ἀδελφιδός μου ἐμοί, ὁ ποιμαίνων ἐν τοῖς κρίνοις.","enk tō̂i adelphidō̂i mou kaì adelphidós mou emoí, ho poimaínōn en toîs krínois."],[6,3,"Καλὴ εἶ πλησίον μου, ὡς εὐδοκία, ὡραία ὡς Ἰερουσαλὴμ, θάμβος ὡς τεταγμέναι.","Kalḕ eî plēsíon mou, hōs eudokía, hōraía hōs Ierousalḕm, thámbos hōs tetagménai."],[6,4,"ἀπόστρεψον ὀφθαλμούς σου ἀπεναντίον μου, ὅτι αὐτοὶ ἀνεπτέραοσαν με. τρίχωμά σου ὡς ἀγέλαι τῶν αἰγῶν αἳ ἀνεφάνησαν ἀπὸ τοῦ Γαλαὰδ,","apóstrepson ophthalmoús sou apenantíon mou, hóti autoì aneptéraosan me. tríchōmá sou hōs agélai tō̂n aigō̂n haì anephánēsan apò toû Galaàd,"],[6,5,"ὀδόντες σου ὡς ἀγέλαι τῶν κεκαρμένων αἳ ἀνέβησαν ἀπὸ τοῦ λουτροῦ, αἱ πᾶσαι διδυμεύουσαι, καὶ ἀτεκνοῦσα οὐκ ἔστιν ἐν αὐταῖς. ὡς σπαρτίον τὸ κόκκινον χείλη σου, καὶ ἡ λαλιά σου ὡραία.","odóntes sou hōs agélai tō̂n kekarménōn haì anébēsan apò toû loutroû, hai pâsai didymeúousai, kaì ateknoûsa ouk éstin en autaîs. hōs spartíon tò kókkinon cheílē sou, kaì hē laliá sou hōraía."],[6,6,"ὡς λέπυρον ῥόας μῆλόν σου ἐκτὸς τῆς σιωπήσεως σου.","hōs lépyron rhóas mē̂lón sou ektòs tē̂s siōpḗseōs sou."],[6,7,"ἐξήκοντά εἰσιν βασίύισσαι, καὶ ὀγδοήκοντα παλλακαί, καὶ νεάνιδες ὧν οὐκ ἔστιν ἀριθμός·","exḗkontá eisin basíýissai, kaì ogdoḗkonta pallakaí, kaì neánides hō̂n ouk éstin arithmós:"],[6,8,"μία ἐστὶν περιστερά μου, τελεία μου, μία ἐστὶν τῇ μητρὶ αὐτῆς, ἐκλεκτή ἐστιν τῇ τεκούσῃ αὐτῆς. εἴδοσαν αὐτὴν θυγατέρες καὶ ναεαοωῦσιν αὐτήν, βασίλισσαι καί γε παλλακαί, καὶ αἰνέσουσιν αὐτήν.","mía estìn peristerá mou, teleía mou, mía estìn tē̂i mētrì autē̂s, eklektḗ estin tē̂i tekoúsēi autē̂s. eídosan autḕn thygatéres kaì naeaoōŷsin autḗn, basílissai kaí ge pallakaí, kaì ainésousin autḗn."],[6,9,"Τίς αὕτη ἡ ἐκκύπτουσα ὡσεὶ ὄρθρος. καλὴ ὡς σελήνη, ἐκλεκτὴ ὡς ὁ ἥλιος, θάμβος ὡς τεταγμέναις","Tís haútē hē ekkýptousa hōseì órthros. kalḕ hōs selḗnē, eklektḕ hōs ho hḗlios, thámbos hōs tetagménais"],[6,10,"Εἰς κῆπον καρύας κατέβην ἰδεῖν ἐν γενήμασιν τοῦ χειμάρρου, ἰδεῖν εἰ ἤνθησεν ἡ ἄμπελος, ἐξήνθησαν αἱ ῥόαι· ἐκεῖ δώσω τοὺς μαστούς μου σοί.","Eis kē̂pon karýas katébēn ideîn en genḗmasin toû cheimárrou, ideîn ei ḗnthēsen hē ámpelos, exḗnthēsan hai rhóai: ekeî dṓsō toùs mastoús mou soí."],[6,11,"οὐκ ἔγνω ἡ ψυχή μου· ἔθετό με ἄρματα Ἀμειναδάβ.","ouk égnō hē psychḗ mou: éthetó me ármata Ameinadáb."],[6,12,"Ἐπίστρεφε, ἐπίστρεφε, ἡ Σουμανεῖτις·","Epístrephe, epístrephe, hē Soumaneîtis:"],[7,12,"ἐπίστρεφε, ἐπίστρεφε, καὶ ὀψόμεθα ἐν σοί. ὀρθρίσωμεν εἰς ἀμπελῶνας, ἴδωμεν εἰ ἤνθησεν ἡ ἄμπελος, ἤνθησεν ὁ κυπρισμός, ἤνθησαν αἱ ῥὸαι· ἐκεῖ δώσω τοὺς μαστούς μου σοί.","epístrephe, epístrephe, kaì opsómetha en soí. orthrísōmen eis ampelō̂nas, ídōmen ei ḗnthēsen hē ámpelos, ḗnthēsen ho kyprismós, ḗnthēsan hai rhòai: ekeî dṓsō toùs mastoús mou soí."],[7,1,"Τί δψεοθε ἐν τῆ Σουμανείτιδις ἡ ἐρχομένη ὡς χοροὶ τῶν παρεμβολῶν. (2) Ὡραιώθησαν διαβήματά σου ἐν ὑποδήμασιν, θύγατερ Ναδάβ. ὀυθμοὶ μηρῶν σου ὃμοιοι ὁρμίσκοις. ἔργον τεχνίτου.","Tí dpseothe en tē̂ Soumaneítidis hē erchoménē hōs choroì tō̂n parembolō̂n. (2) Hōraiṓthēsan diabḗmatá sou en hypodḗmasin, thýgater Nadáb. outhmoì mērō̂n sou hòmoioi hormískois. érgon technítou."],[7,2,"ὀμφαλός σου κρατὴρ τορευτός, μὴ ὑστερούμενος κρᾶμα· κοιλία σου θιμωνιὰ σίτου πεφραγμένη ἐν κρίνοις.","omphalós sou kratḕr toreutós, mḕ hysteroúmenos krâma: koilía sou thimōnià sítou pephragménē en krínois."],[7,3,"δύο μαστοί σου ὡς δύο νεβροὶ δίδυμοι δορκάδος·","dýo mastoí sou hōs dýo nebroì dídymoi dorkádos:"],[7,4,"ὁ τράχηλός σου ὡς πύργος ἐλεφάντινος. οἱ ὀφθαλμοί σου ὡς λίμναι ἐν Ἐσεβῶν, ἐν πύλαις θυγατρὸς πολλῶν. μυκτήρ σου ὡς πύργος τοῦ Λιβάνου σκοπεύωυ πρόσαοπον Δαμασκοῦ.","ho tráchēlós sou hōs pýrgos elephántinos. hoi ophthalmoí sou hōs límnai en Esebō̂n, en pýlais thygatròs pollō̂n. myktḗr sou hōs pýrgos toû Libánou skopeúōy prósaopon Damaskoû."],[7,5,"κεφαλή σου ἐπὶ σέ ὡς Κάρμηλος, καὶ πλόκιον κεφαλῆς σου ὡς πορφύρα, βασύιεὺς δεδεμένος ἐν παραδρομαῖς.","kephalḗ sou epì sé hōs Kármēlos, kaì plókion kephalē̂s sou hōs porphýra, basýieùs dedeménos en paradromaîs."],[7,6,"τί ὡραιώθης, καὶ τί ἡδύνθης, ἀγάπη, ἐν τρυφαῖς σους","tí hōraiṓthēs, kaì tí hēdýnthēs, agápē, en tryphaîs sous"],[7,7,"τοῦτο μέγεθός σου· ὡμοιώθης τῷ φοίνικι, καὶ οἱ μαστοί σου τοῖς βότρυσιν.","toûto mégethós sou: hōmoiṓthēs tō̂i phoíniki, kaì hoi mastoí sou toîs bótrysin."],[7,8,"εἶπα Ἀναβήσομαι ἐπὶ τῷ φοίνικι, κρατήσω τῶυ ὕψεωυ αὐτοῦ· καὶ ἔσονται δὴ μαστοί σου ὡς βότρυες τῆς ἀμπέλου, καὶ ὀσμὴ ῥινός σου ὡς μῆλα,","eîpa Anabḗsomai epì tō̂i phoíniki, kratḗsō tō̂y hýpseōy autoû: kaì ésontai dḕ mastoí sou hōs bótryes tē̂s ampélou, kaì osmḕ rhinós sou hōs mē̂la,"],[7,9,"καὶ ὁ λάρυγξ σου ὡς οἶνος ὁ ἀγαθός, πορευόμενος τῷ ἀδελφιδῷ μου εἰς εὐθύτητα, ἱκανούμενος χείλεσίν μου καὶ ὀδοῦσιν.","kaì ho lárynx sou hōs oînos ho agathós, poreuómenos tō̂i adelphidō̂i mou eis euthýtēta, hikanoúmenos cheílesín mou kaì odoûsin."],[7,10,"Ἐγὼ τῷ ἀδελφιδῷ μου. καὶ ἐπʼ ἐμὲ ἡ ἐπιστροφὴ αὐτοῦ.","Egṑ tō̂i adelphidō̂i mou. kaì epʼ emè hē epistrophḕ autoû."],[7,11,"ἐλθὲ, ἀδελφιδέ μου, ἐξέλθωμεν εἰς ἀγρόν. αὐλισθῶμευ ἐν κώμαις·","elthè, adelphidé mou, exélthōmen eis agrón. aulisthō̂meu en kṓmais:"],[7,13,"οἱ μανδραγόραι ἔδωκαν ὀσμήν, καὶ ἐπὶ θύραις ἡμῶν πάντα ἀκρόδρυα, νέα πρὸς παλαιά, ἀδελφιδέ μου, ἐτήρησά σοι.","hoi mandragórai édōkan osmḗn, kaì epì thýrais hēmō̂n pánta akródrya, néa pròs palaiá, adelphidé mou, etḗrēsá soi."],[8,1,"τίς δῴη σε ἀδελφιδόν μου, θηλάζοντα μαστοὺς μητρός μους εὑροῦσά σε ἔξω φιλήσω σε, καί γε οὐκ ἐξουδενώσουσίν μοι.","tís dṓiē se adelphidón mou, thēlázonta mastoùs mētrós mous heuroûsá se éxō philḗsō se, kaí ge ouk exoudenṓsousín moi."],[8,2,"παραλήμψομαί σε, εἰσάξω σε εἰς οἶκον μητρός μου καὶ εἰς ταμεῖον τῆς συλλαβούσης με· ποτιῶ σε ἀπὸ οἴνου τοῦ μυρεψικοῦ,","paralḗmpsomaí se, eisáxō se eis oîkon mētrós mou kaì eis tameîon tē̂s syllaboúsēs me: potiō̂ se apò oínou toû myrepsikoû,"],[8,3,"εὐώνυμος αὐτοῦ ὑπὸ τὴν κεφαλὴν μου. ἀπὸ νάματος ῥοῶν σου. καὶ ἡ δεξιὰ αὐτοῦ περιλήμψεταί με.","euṓnymos autoû hypò tḕn kephalḕn mou. apò námatos rhoō̂n sou. kaì hē dexià autoû perilḗmpsetaí me."],[8,4,"Ὥρκισα ὑμᾶς, θυγατέρες Ἰερουσαλήμ, ἐν ταῖς δυνάμεσιν καὶ ἐν ταῖς ἰσχύσεσιν τοῦ ἀγροῦ, ἐὰν ἐγείρητε καὶ ἐξεγείρητε τὴν ἀγάπην ἕως ἂυ θελήσῃ.","Hṓrkisa hymâs, thygatéres Ierousalḗm, en taîs dynámesin kaì en taîs ischýsesin toû agroû, eàn egeírēte kaì exegeírēte tḕn agápēn héōs ày thelḗsēi."],[8,5,"Tίς αὕτη ἡ ἀναβαίνουσα λελευκαθισμένη. ἐπιστηριζομένη ἐπὶ τὸν ἀδελφιδὸν αὐτῆς; Ὑπὸ μῆλον ἐξήγειρά σε· ἐκεῖ ὠδίνησέν σε ἡ μήτηρ σου, ἐκεῖ ὠδίνησέν σε ἡ τεκοῦσά σου.","Tís haútē hē anabaínousa leleukathisménē. epistērizoménē epì tòn adelphidòn autē̂s? Hypò mē̂lon exḗgeirá se: ekeî ōdínēsén se hē mḗtēr sou, ekeî ōdínēsén se hē tekoûsá sou."],[8,6,"θές με ὡς σφραγῖδα ἐπὶ τὴν καρδίαν σου, ὡς σφραγῖδα ἐπὶ τὸν βραχίονά σου· ὅτι κραταιὰ ὡς θάνατος ἀγάπη, σκληρὸς ὡς ᾂδης ζῆλος· περίπτερα αὐτῆς περίπτερα πυρός, φλόγες αὐτῆς·","thés me hōs sphragîda epì tḕn kardían sou, hōs sphragîda epì tòn brachíoná sou: hóti krataià hōs thánatos agápē, sklēròs hōs ā̀idēs zē̂los: períptera autē̂s períptera pyrós, phlóges autē̂s:"],[8,7,"ὕδωρ πολὺ οὐ δυνήσεται σβέσαι τὴυ ἀγάπην, καὶ ποταμοὶ οὐ συνκλύσουσιν αὐτήν. ἐὰν δῷ ἀνὴρ τὸν πάντα βίον αὐτοῦ ἐν τῆ ἀγάπῃ, ἐξουδενώσει ἐξουδενώσουσιν αὐτόν.","hýdōr polỳ ou dynḗsetai sbésai tḕy agápēn, kaì potamoì ou syn'klýsousin autḗn. eàn dō̂i anḕr tòn pánta bíon autoû en tē̂ agápēi, exoudenṓsei exoudenṓsousin autón."],[8,8,"Ἀδελφὴ ἡμῖν μικρὰ καὶ μαστοὺς οὐκ ἔχει. τί ποιήσωμεν τῇ ἀδελφῇ ἡμῶν ἐν ἡμέρᾳ ᾗ ἐὰν λαληθῇ ἐν αὐτῇ;","Adelphḕ hēmîn mikrà kaì mastoùs ouk échei. tí poiḗsōmen tē̂i adelphē̂i hēmō̂n en hēmérāi hē̂i eàn lalēthē̂i en autē̂i?"],[8,9,"εἰ τεῖχός ἐστιν, οἰκοδομήσωμεν ἐπʼ αὐτὴν ἐπάλξεις ἀργυρᾶς· καὶ εἰ θύρα ἐστίν, διαγράψωμεν ἐπʼ αὐτὴν σανίδα κεδρίνην.","ei teîchós estin, oikodomḗsōmen epʼ autḕn epálxeis argyrâs: kaì ei thýra estín, diagrápsōmen epʼ autḕn sanída kedrínēn."],[8,10,"Ἐγὼ τεῖχος, καὶ μαστοί μου πύργοι· ἐγὼ ἤμην ἐν ὀφθαλμοῖς αὐτῶν ὡς εὑρίσκουσα εἰρήνην.","Egṑ teîchos, kaì mastoí mou pýrgoi: egṑ ḗmēn en ophthalmoîs autō̂n hōs heurískousa eirḗnēn."],[8,11,"ἀμπελὼν ἐγενήθη τῷ Σαλωμὼν ἐν Βεεθλαμών· ἔδωκεν τὸν ἀμπελῶνα αὐτοῦ τοῖς τηροῦσιν, ἀνὴρ οἴσει ἐν καρπῷ αὐτοῦ χιλίους ἀργυρίου.","ampelṑn egenḗthē tō̂i Salōmṑn en Beethlamṓn: édōken tòn ampelō̂na autoû toîs tēroûsin, anḕr oísei en karpō̂i autoû chilíous argyríou."],[8,12,"ἀμπελών μου ἐμὸς ἐνώπιόν μου· οἱ χίλιοι Σαλωμών, καὶ οἱ διακόσιοι τοῖς τηροῦσι τὸν καρπὸν αὐτοῦ.","ampelṓn mou emòs enṓpión mou: hoi chílioi Salōmṓn, kaì hoi diakósioi toîs tēroûsi tòn karpòn autoû."],[8,13,"Ὁ καθήμενος ἐν κήποις, ἑταῖροι προσέχοντες τῇ φωνῇ σου· ἀκούτισόν με.","HO kathḗmenos en kḗpois, hetaîroi proséchontes tē̂i phōnē̂i sou: akoútisón me."],[8,14,"Φύγε, ἀδελφιδέ μου, καὶ ὁμοιώθητι τῇ δορκάδι ἡ τῷ νεβρῷ τῶν ἐλάφων ἐπὶ ὄρη ἀρωμάτων.","Phýge, adelphidé mou, kaì homoiṓthēti tē̂i dorkádi hē tō̂i nebrō̂i tō̂n eláphōn epì órē arōmátōn."]],"chu-elizabeth":[[1,1,"Да лобжет мя от лобзаний уст своих: яко блага сосца твоя паче вина,","Da lobžet mâ ot lobzanij ust svoih: âko blaga sosca tvoâ pače vina,"],[1,2,"и воня мира твоего паче всех аромат. Миро излияное имя твое: сего ради отроковицы возлюбиша тя.","i vonâ mira tvoego pače vseh aromat. Miro izliânoe imâ tvoe: sego radi otrokovicy vozlûbiša tâ."],[1,3,"Привлекоша тя: вслед тебе в воню мира твоего течем. Введе мя царь в ложницу свою: возрадуемся и возвеселимся о тебе, возлюбим сосца твоя паче вина: правость возлюби тя.","Privlekoša tâ: vsled tebe v vonû mira tvoego tečem. Vvede mâ carʹ v ložnicu svoû: vozraduemsâ i vozveselimsâ o tebe, vozlûbim sosca tvoâ pače vina: pravostʹ vozlûbi tâ."],[1,4,"Черна есмь аз и добра, дщери Иерусалимския, якоже селения Кидарска, якоже завесы Соломони.","Černa esmʹ az i dobra, dŝeri Ierusalimskiâ, âkože seleniâ Kidarska, âkože zavesy Solomoni."],[1,5,"Не зрите мене, яко аз есмь очернена, яко опали мя солнце: сынове матере моея сваряхуся о мне, положиша мя стража в виноградех: винограда моего не сохраних.","Ne zrite mene, âko az esmʹ očernena, âko opali mâ solnce: synove matere moeâ svarâhusâ o mne, položiša mâ straža v vinogradeh: vinograda moego ne sohranih."],[1,6,"Возвести ми, егоже возлюби душа моя, где пасеши? Где почиваеши в полудне? Да не когда буду яко облагающаяся над стады другов твоих.","Vozvesti mi, egože vozlûbi duša moâ, gde paseši? Gde počivaeši v poludne? Da ne kogda budu âko oblagaûŝaâsâ nad stady drugov tvoih."],[1,7,"Аще не увеси самую тебе, добрая в женах, изыди ты в пятах паств и паси козлища твоя у кущей пастырских.","Aŝe ne uvesi samuû tebe, dobraâ v ženah, izydi ty v pâtah pastv i pasi kozliŝa tvoâ u kuŝej pastyrskih."],[1,8,"Конем моим в колесницех фараоновых уподобих тя, ближняя моя.","Konem moim v kolesniceh faraonovyh upodobih tâ, bližnââ moâ."],[1,9,"Что украшены ланиты твоя яко горлицы, выя твоя яко монисты?","Čto ukrašeny lanity tvoâ âko gorlicy, vyâ tvoâ âko monisty?"],[1,10,"Подобия злата сотворим ти с пестротами сребра.","Podobiâ zlata sotvorim ti s pestrotami srebra."],[1,11,"Дондеже (будет) царь на восклонении своем, нард мой даде воню свою.","Dondeže (budet) carʹ na vosklonenii svoem, nard moj dade vonû svoû."],[1,12,"Вязание стакти брат мой мне, посреде сосцу моею водворится:","Vâzanie stakti brat moj mne, posrede soscu moeû vodvoritsâ:"],[1,13,"грезн кипров брат мой мне в виноградех Енгаддовых.","grezn kiprov brat moj mne v vinogradeh Engaddovyh."],[1,14,"Се, еси добра, искренняя моя, се, еси добра: очи твои голубине.","Se, esi dobra, iskrennââ moâ, se, esi dobra: oči tvoi golubine."],[1,15,"Се, еси добр, брат мой, и еще красен: одр наш со осенением,","Se, esi dobr, brat moj, i eŝe krasen: odr naš so oseneniem,"],[1,16,"преклади дому нашего кедровии, дски нашя кипарисныя.","prekladi domu našego kedrovii, dski našâ kiparisnyâ."],[2,1,"Аз цвет польный и крин удольный.","Az cvet polʹnyj i krin udolʹnyj."],[2,2,"Якоже крин в тернии, тако искренняя моя посреде дщерей.","Âkože krin v ternii, tako iskrennââ moâ posrede dŝerej."],[2,3,"Яко яблонь посреде древес лесных, тако брат мой посреде сынов: под сень его восхотех и седох, и плод его сладок в гортани моем.","Âko âblonʹ posrede dreves lesnyh, tako brat moj posrede synov: pod senʹ ego voshoteh i sedoh, i plod ego sladok v gortani moem."],[2,4,"Введите мя в дом вина, вчините ко мне любовь:","Vvedite mâ v dom vina, včinite ko mne lûbovʹ:"],[2,5,"утвердите мя в мирех, положите мя во яблоцех: яко уязвлена (есмь) любовию аз.","utverdite mâ v mireh, položite mâ vo âbloceh: âko uâzvlena (esmʹ) lûboviû az."],[2,6,"Шуйца его под главою моею, и десница его оымет мя.","Šujca ego pod glavoû moeû, i desnica ego oymet mâ."],[2,7,"Заклях вас, дщери Иерусалимли, в силах и крепостех села: аще возставите и возбудите любовь, дондеже восхощет.","Zaklâh vas, dŝeri Ierusalimli, v silah i kreposteh sela: aŝe vozstavite i vozbudite lûbovʹ, dondeže voshoŝet."],[2,8,"Глас брата моего: се, той идет, скача на горы и прескача на холмы.","Glas brata moego: se, toj idet, skača na gory i preskača na holmy."],[2,9,"Подобен есть брат мой серне или младу еленю на горах вефильских. Се, сей стоит за стеною нашею, проглядаяй оконцами, приницаяй сквозе мрежи.","Podoben estʹ brat moj serne ili mladu elenû na gorah vefilʹskih. Se, sej stoit za stenoû našeû, proglâdaâj okoncami, prinicaâj skvoze mreži."],[2,10,"Отвещает брат мой и глаголет мне: востани, прииди, ближняя моя, добрая моя, голубице моя.","Otveŝaet brat moj i glagolet mne: vostani, priidi, bližnââ moâ, dobraâ moâ, golubice moâ."],[2,11,"Яко се, зима прейде, дождь отиде, отиде себе:","Âko se, zima prejde, doždʹ otide, otide sebe:"],[2,12,"цвети явишася на земли, время обрезания приспе, глас горлицы слышан в земли нашей:","cveti âvišasâ na zemli, vremâ obrezaniâ prispe, glas gorlicy slyšan v zemli našej:"],[2,13,"смоквь изнесе цвет свой, виногради зреюще даша воню. Востани, прииди, ближняя моя, добрая моя, голубице моя, и прииди.","smokvʹ iznese cvet svoj, vinogradi zreûŝe daša vonû. Vostani, priidi, bližnââ moâ, dobraâ moâ, golubice moâ, i priidi."],[2,14,"Ты, голубице моя, в покрове каменне, близ предстения: яви ми зрак твой, и услышан сотвори ми глас твой: яко глас твой сладок, и образ твой красен.","Ty, golubice moâ, v pokrove kamenne, bliz predsteniâ: âvi mi zrak tvoj, i uslyšan sotvori mi glas tvoj: âko glas tvoj sladok, i obraz tvoj krasen."],[2,15,"Имите нам лисы малыя, губящыя винограды: и виногради наши созревают.","Imite nam lisy malyâ, gubâŝyâ vinogrady: i vinogradi naši sozrevaût."],[2,16,"Брат мой мне, и аз ему, пасый в кринах,","Brat moj mne, i az emu, pasyj v krinah,"],[2,17,"дондеже дхнет день, и двигнутся сени. Обратися, уподобися ты, брате мой, серне или младу еленю на горах юдолий.","dondeže dhnet denʹ, i dvignutsâ seni. Obratisâ, upodobisâ ty, brate moj, serne ili mladu elenû na gorah ûdolij."],[3,1,"На ложи моем в нощех исках, егоже возлюби душа моя, исках его, и не обретох его: воззвах его, и не послуша мене.","Na loži moem v noŝeh iskah, egože vozlûbi duša moâ, iskah ego, i ne obretoh ego: vozzvah ego, i ne posluša mene."],[3,2,"Востану убо и обыду во граде и на торжищих и на стогнах, и поищу, егоже возлюби душа моя. Поисках его, и не обретох его: звах его, и не послуша мене.","Vostanu ubo i obydu vo grade i na toržiŝih i na stognah, i poiŝu, egože vozlûbi duša moâ. Poiskah ego, i ne obretoh ego: zvah ego, i ne posluša mene."],[3,3,"Обретоша мя стрегущии, обходяще во граде: видесте ли, егоже возлюби душа моя?","Obretoša mâ streguŝii, obhodâŝe vo grade: videste li, egože vozlûbi duša moâ?"],[3,4,"Яко мало егда преидох от них, дондеже обретох, егоже возлюби душа моя: удержах его, и не оставих его, дондеже введох его в дом матере моея и в чертог заченшия мя.","Âko malo egda preidoh ot nih, dondeže obretoh, egože vozlûbi duša moâ: uderžah ego, i ne ostavih ego, dondeže vvedoh ego v dom matere moeâ i v čertog začenšiâ mâ."],[3,5,"Заклях вас, дщери Иерусалимския, в силах и в крепостех селных: аще подвижете и воздвижете любовь, дондеже аще восхощет.","Zaklâh vas, dŝeri Ierusalimskiâ, v silah i v kreposteh selnyh: aŝe podvižete i vozdvižete lûbovʹ, dondeže aŝe voshoŝet."],[3,6,"Кто сия восходящая от пустыни, яко стебло дыма кадящее смирну и ливан, от всех благовоний мироварца?","Kto siâ voshodâŝaâ ot pustyni, âko steblo dyma kadâŝee smirnu i livan, ot vseh blagovonij mirovarca?"],[3,7,"Се, одр Соломонь, шестьдесят сильных окрест его от сильных Израилевых,","Se, odr Solomonʹ, šestʹdesât silʹnyh okrest ego ot silʹnyh Izrailevyh,"],[3,8,"вси имуще оружия, научени на брань: муж, оружие его на бедре его от ужаса в нощех.","vsi imuŝe oružiâ, naučeni na branʹ: muž, oružie ego na bedre ego ot užasa v noŝeh."],[3,9,"Одр сотвори себе царь Соломон от древес Ливанских.","Odr sotvori sebe carʹ Solomon ot dreves Livanskih."],[3,10,"Столпы его сотвори сребряны и восклонение его злато: восход его багрян, внутрь его камение постлано, любовь от дщерей Иерусалимских.","Stolpy ego sotvori srebrâny i vosklonenie ego zlato: voshod ego bagrân, vnutrʹ ego kamenie postlano, lûbovʹ ot dŝerej Ierusalimskih."],[3,11,"Дщери Сиони, изыдите и видите в цари Соломоне в венце, имже венча его мати его в день обручения его и в день веселия сердца его.","Dŝeri Sioni, izydite i vidite v cari Solomone v vence, imže venča ego mati ego v denʹ obručeniâ ego i v denʹ veseliâ serdca ego."],[4,1,"Се, еси добра, ближняя моя, се, еси добра: очи твои голубине, кроме замолчания твоего: власи твои яко стада козиц, яже открышася от Галаада.","Se, esi dobra, bližnââ moâ, se, esi dobra: oči tvoi golubine, krome zamolčaniâ tvoego: vlasi tvoi âko stada kozic, âže otkryšasâ ot Galaada."],[4,2,"Зубы твои яко стада остриженых, яже изыдоша из купели, вся двоеплодны, и неродящия несть в них.","Zuby tvoi âko stada ostriženyh, âže izydoša iz kupeli, vsâ dvoeplodny, i nerodâŝiâ nestʹ v nih."],[4,3,"Яко вервь червлена устне твои, и беседа твоя красна: яко оброщение шипка ланиты твоя, кроме замолчания твоего.","Âko vervʹ červlena ustne tvoi, i beseda tvoâ krasna: âko obroŝenie šipka lanity tvoâ, krome zamolčaniâ tvoego."],[4,4,"Яко столп Давидов выя твоя, создан в Фалпиофе: тысяща щитов висит на нем, вся стрелы сильных.","Âko stolp Davidov vyâ tvoâ, sozdan v Falpiofe: tysâŝa ŝitov visit na nem, vsâ strely silʹnyh."],[4,5,"Два сосца твоя яко два млада близнца серны, пасомая во кринах,","Dva sosca tvoâ âko dva mlada bliznca serny, pasomaâ vo krinah,"],[4,6,"дондеже дхнет день, и подвигнутся сени. Пойду себе к горе смирней и к холму ливанску.","dondeže dhnet denʹ, i podvignutsâ seni. Pojdu sebe k gore smirnej i k holmu livansku."],[4,7,"Вся добра еси, ближняя моя, и порока несть в тебе.","Vsâ dobra esi, bližnââ moâ, i poroka nestʹ v tebe."],[4,8,"Гряди от Ливана, невесто, гряди от Ливана: прииди и прейди из начала Веры, от главы Санира и Аермона, от оград львовых, от гор пардалеов.","Grâdi ot Livana, nevesto, grâdi ot Livana: priidi i prejdi iz načala Very, ot glavy Sanira i Aermona, ot ograd lʹvovyh, ot gor pardaleov."],[4,9,"Сердце наше привлекла еси, сестро моя невесто, сердце наше привлекла еси единым от очию твоею, единым монистом выи твоея.","Serdce naše privlekla esi, sestro moâ nevesto, serdce naše privlekla esi edinym ot očiû tvoeû, edinym monistom vyi tvoeâ."],[4,10,"Что удобреста сосца твоя, сестро моя невесто? Что удобреста сосца твоя паче вина, и воня риз твоих паче всех аромат?","Čto udobresta sosca tvoâ, sestro moâ nevesto? Čto udobresta sosca tvoâ pače vina, i vonâ riz tvoih pače vseh aromat?"],[4,11,"Сот искапают устне твои, невесто, мед и млеко под языком твоим, и благовоние риз твоих яко благоухание Ливана.","Sot iskapaût ustne tvoi, nevesto, med i mleko pod âzykom tvoim, i blagovonie riz tvoih âko blagouhanie Livana."],[4,12,"Вертоград заключен сестра моя невеста, вертоград заключен, источник запечатлен.","Vertograd zaklûčen sestra moâ nevesta, vertograd zaklûčen, istočnik zapečatlen."],[4,13,"Леторасли твоя сад шипков с плодом яблочным, кипри с нардами,","Letorasli tvoâ sad šipkov s plodom âbločnym, kipri s nardami,"],[4,14,"нард и шафран, трость и киннамон со всеми древами ливанскими, смирна, алой со всеми первыми мирами,","nard i šafran, trostʹ i kinnamon so vsemi drevami livanskimi, smirna, aloj so vsemi pervymi mirami,"],[4,15,"источник вертограда, и кладязь воды живы и истекающия от Ливана.","istočnik vertograda, i kladâzʹ vody živy i istekaûŝiâ ot Livana."],[4,16,"Востани, севере, и гряди, юже, и повей во вертограде моем, и да потекут ароматы мои.","Vostani, severe, i grâdi, ûže, i povej vo vertograde moem, i da potekut aromaty moi."],[5,1,"Да снидет брат мои в вертоград свой и да яст плод овощий своих. Внидох в вертоград мой, сестро моя невесто: оымах смирну мою со ароматами моими, ядох хлеб мой с медом моим, пих вино мое с млеком моим. Ядите, ближнии, и пийте и упийтеся, братия.","Da snidet brat moi v vertograd svoj i da âst plod ovoŝij svoih. Vnidoh v vertograd moj, sestro moâ nevesto: oymah smirnu moû so aromatami moimi, âdoh hleb moj s medom moim, pih vino moe s mlekom moim. Âdite, bližnii, i pijte i upijtesâ, bratiâ."],[5,2,"Аз сплю, а сердце мое бдит: глас брата моего ударяет в двери: отверзи ми, сестро моя, ближняя моя, голубице моя, совершенная моя: яко глава моя наполнися росы, и власи мои капель нощных.","Az splû, a serdce moe bdit: glas brata moego udarâet v dveri: otverzi mi, sestro moâ, bližnââ moâ, golubice moâ, soveršennaâ moâ: âko glava moâ napolnisâ rosy, i vlasi moi kapelʹ noŝnyh."],[5,3,"Совлекохся ризы моея, како облекуся в ню? Умых нозе мои, како оскверню их?","Sovlekohsâ rizy moeâ, kako oblekusâ v nû? Umyh noze moi, kako oskvernû ih?"],[5,4,"Брат мой посла руку свою сквозе скважню, и чрево мое вострепета от него.","Brat moj posla ruku svoû skvoze skvažnû, i črevo moe vostrepeta ot nego."],[5,5,"Востах аз отверсти брату моему: руце мои искапаша смирну, персты мои смирны полны на руках заключения.","Vostah az otversti bratu moemu: ruce moi iskapaša smirnu, persty moi smirny polny na rukah zaklûčeniâ."],[5,6,"Отверзох аз брату моему: брат мой прейде. Душа моя изыде в слово его: взысках его, и не обретох его: звах его, и не послуша мене.","Otverzoh az bratu moemu: brat moj prejde. Duša moâ izyde v slovo ego: vzyskah ego, i ne obretoh ego: zvah ego, i ne posluša mene."],[5,7,"Обретоша мя стражие обходящии во граде: биша мя, язвиша мя, взяша верхнюю ризу от мене стражие стеннии.","Obretoša mâ stražie obhodâŝii vo grade: biša mâ, âzviša mâ, vzâša verhnûû rizu ot mene stražie stennii."],[5,8,"Заклях вы, дщери Иерусалимския, в силах и в крепостех селных: аще обрящете брата моего, возвестите ему, яко уязвлена любовию аз есмь.","Zaklâh vy, dŝeri Ierusalimskiâ, v silah i v kreposteh selnyh: aŝe obrâŝete brata moego, vozvestite emu, âko uâzvlena lûboviû az esmʹ."],[5,9,"Что брат твой паче брата, добрая в женах? Что брат твой от брата, яко тако закляла еси нас?","Čto brat tvoj pače brata, dobraâ v ženah? Čto brat tvoj ot brata, âko tako zaklâla esi nas?"],[5,10,"Брат мой бел и чермен, избран от тем:","Brat moj bel i čermen, izbran ot tem:"],[5,11,"глава его злато избранно, власы его кудрявы, черны яко вран:","glava ego zlato izbranno, vlasy ego kudrâvy, černy âko vran:"],[5,12,"очи его яко голубицы на исполнениих вод, измовени во млеце, седящыя в наполнениих (вод):","oči ego âko golubicy na ispolneniih vod, izmoveni vo mlece, sedâŝyâ v napolneniih (vod):"],[5,13,"ланиты его аки фиалы аромат, прозябающыя благовоние: устне его крины, каплющии смирну полну:","lanity ego aki fialy aromat, prozâbaûŝyâ blagovonie: ustne ego kriny, kaplûŝii smirnu polnu:"],[5,14,"руце его обточены златы, наполнены фарсиса: чрево его сосуд слоновый на камени сапфирове:","ruce ego obtočeny zlaty, napolneny farsisa: črevo ego sosud slonovyj na kameni sapfirove:"],[5,15,"лыста его столпи марморовы, основани на степенех златых: вид его яко Ливан, избран яко кедрове:","lysta ego stolpi marmorovy, osnovani na stepeneh zlatyh: vid ego âko Livan, izbran âko kedrove:"],[5,16,"гортань его сладость, и весь желание: сей брат мой и сей ближний мой, дщери Иерусалимли. Камо отиде брат твой, добрая в женах? Камо уклонися брат твой? И взыщем его с тобою.","gortanʹ ego sladostʹ, i vesʹ želanie: sej brat moj i sej bližnij moj, dŝeri Ierusalimli. Kamo otide brat tvoj, dobraâ v ženah? Kamo uklonisâ brat tvoj? I vzyŝem ego s toboû."],[6,1,"Брат мой сниде в вертоград свой, в места аромат, паствити в вертоградех и собирати крины.","Brat moj snide v vertograd svoj, v mesta aromat, pastviti v vertogradeh i sobirati kriny."],[6,2,"Аз брату моему и брат мой мне, пасый в кринех.","Az bratu moemu i brat moj mne, pasyj v krineh."],[6,3,"Добра еси, ближняя моя, яко благоволение, красна яко Иерусалим, ужас яко вчиненны.","Dobra esi, bližnââ moâ, âko blagovolenie, krasna âko Ierusalim, užas âko včinenny."],[6,4,"Отврати очи твои от мене, яко тии воскрилиша мя: власи твои, яко стада коз, яже взыдоша от Галаада:","Otvrati oči tvoi ot mene, âko tii voskriliša mâ: vlasi tvoi, âko stada koz, âže vzydoša ot Galaada:"],[6,5,"зубы твои, яко стада остриженых, яже взыдоша от купели, вся близнята родящыя, и безчадныя несть в них: яко вервь червлена устне твои, и беседа твоя красна:","zuby tvoi, âko stada ostriženyh, âže vzydoša ot kupeli, vsâ bliznâta rodâŝyâ, i bezčadnyâ nestʹ v nih: âko vervʹ červlena ustne tvoi, i beseda tvoâ krasna:"],[6,6,"яко оброщение шипка ланиты твоя, кроме замолчания твоего.","âko obroŝenie šipka lanity tvoâ, krome zamolčaniâ tvoego."],[6,7,"Шестьдесят суть цариц и осмьдесят наложниц, и юнот, имже несть числа:","Šestʹdesât sutʹ caric i osmʹdesât naložnic, i ûnot, imže nestʹ čisla:"],[6,8,"едина есть голубица моя, совершенная моя: едина есть матери своей, избранна есть родившей ю: видеша ю дщери и ублажиша ю, царицы и наложницы, и восхвалиша ю.","edina estʹ golubica moâ, soveršennaâ moâ: edina estʹ materi svoej, izbranna estʹ rodivšej û: videša û dŝeri i ublažiša û, caricy i naložnicy, i voshvališa û."],[6,9,"Кто сия проницающая аки утро, добра яко луна, избранна яко солнце, ужас яко вчиненны?","Kto siâ pronicaûŝaâ aki utro, dobra âko luna, izbranna âko solnce, užas âko včinenny?"],[6,10,"В вертоград орехов снидох видети в плодех потока, видети, аще процвете виноград и возрастоша шипки.","V vertograd orehov snidoh videti v plodeh potoka, videti, aŝe procvete vinograd i vozrastoša šipki."],[6,11,"Тамо дам сосца моя тебе: не разуме душа моя, положи мя на колеснице Аминадавли.","Tamo dam sosca moâ tebe: ne razume duša moâ, položi mâ na kolesnice Aminadavli."],[6,12,"Обратися, обратися, суламитино, обратися, обратися, и узрим в тебе.","Obratisâ, obratisâ, sulamitino, obratisâ, obratisâ, i uzrim v tebe."],[7,1,"Что увидите у Суламитины? Приходящая яко лики полков, что украсишася стопы твоя во обутиих твоих, дщи Надавля? Чины бедру твоею подобни усеряземь, делу рук художника:","Čto uvidite u Sulamitiny? Prihodâŝaâ âko liki polkov, čto ukrasišasâ stopy tvoâ vo obutiih tvoih, dŝi Nadavlâ? Činy bedru tvoeû podobni userâzemʹ, delu ruk hudožnika:"],[7,2,"пуп твой чаша источена, не лишаемая мста: чрево твое яко стог пшеницы, огражден в кринах:","pup tvoj čaša istočena, ne lišaemaâ msta: črevo tvoe âko stog pšenicy, ogražden v krinah:"],[7,3,"два сосца твоя, яко два млада близнецы серны:","dva sosca tvoâ, âko dva mlada bliznecy serny:"],[7,4,"выя твоя яко столп слоновый: очи твои яко езера во Есевоне, во вратах дщерей многих: нос твой яко столп Ливанский, сматряяй лице Дамаска:","vyâ tvoâ âko stolp slonovyj: oči tvoi âko ezera vo Esevone, vo vratah dŝerej mnogih: nos tvoj âko stolp Livanskij, smatrââj lice Damaska:"],[7,5,"глава твоя на тебе яко Кармил (гора), и заплетение главы твоея яко багряница, царь увязан в преристаниих.","glava tvoâ na tebe âko Karmil (gora), i zapletenie glavy tvoeâ âko bagrânica, carʹ uvâzan v preristaniih."],[7,6,"Что украсилася еси, и что усладилася еси, любы, во сладостех твоих?","Čto ukrasilasâ esi, i čto usladilasâ esi, lûby, vo sladosteh tvoih?"],[7,7,"Сие величество твое: уподобилася еси финику, и сосца твоя грезном.","Sie veličestvo tvoe: upodobilasâ esi finiku, i sosca tvoâ greznom."],[7,8,"Рекох: взыду на финик, удержу высоту его: и будут сосцы твои яко грезнове винограда, и воня ноздрей твоих яко яблока:","Rekoh: vzydu na finik, uderžu vysotu ego: i budut soscy tvoi âko greznove vinograda, i vonâ nozdrej tvoih âko âbloka:"],[7,9,"и гортань твой яко вино благо, ходящее брату моему в правость, доволно устнам моим и зубом.","i gortanʹ tvoj âko vino blago, hodâŝee bratu moemu v pravostʹ, dovolno ustnam moim i zubom."],[7,10,"Аз брату моему, и ко мне обращение его.","Az bratu moemu, i ko mne obraŝenie ego."],[7,11,"Прииди, брате мой, и взыдем на село, водворимся в селех:","Priidi, brate moj, i vzydem na selo, vodvorimsâ v seleh:"],[7,12,"ураним в винограды, увидим аще процвете виноград, процветоша ли овощие, процветоша ли яблока? Тамо дам тебе сосца моя.","uranim v vinogrady, uvidim aŝe procvete vinograd, procvetoša li ovoŝie, procvetoša li âbloka? Tamo dam tebe sosca moâ."],[7,13,"Мандрагоры даша воню, и при дверех наших вси плоды новии: до ветхих, брате мой, соблюдох ти.","Mandragory daša vonû, i pri dvereh naših vsi plody novii: do vethih, brate moj, soblûdoh ti."],[8,1,"Кто даст тя, брате мой, ссуща сосцы матере моея? Обретши тя вне целую тя, и ктому не уничижат мене.","Kto dast tâ, brate moj, ssuŝa soscy matere moeâ? Obretši tâ vne celuû tâ, i ktomu ne uničižat mene."],[8,2,"Пойму тя, введу тя в дом матере моея и в ложницу заченшия мя: тамо мя научиши: напою тя от вина с вонями строенаго, от воды яблок моих.","Pojmu tâ, vvedu tâ v dom matere moeâ i v ložnicu začenšiâ mâ: tamo mâ naučiši: napoû tâ ot vina s vonâmi stroenago, ot vody âblok moih."],[8,3,"Шуйца его под главою моею, и десница его оымет мя.","Šujca ego pod glavoû moeû, i desnica ego oymet mâ."],[8,4,"Заклях вас, дщери Иерусалимския, в силах и в крепостех селных: аще подвижете и воздвижете любовь, дондеже аще восхощет.","Zaklâh vas, dŝeri Ierusalimskiâ, v silah i v kreposteh selnyh: aŝe podvižete i vozdvižete lûbovʹ, dondeže aŝe voshoŝet."],[8,5,"Кто сия восходящая убелена и утвержаема о брате своем? Под яблонею возбудих тя: тамо роди тя мати твоя, тамо поболе тобою рождшая тя.","Kto siâ voshodâŝaâ ubelena i utveržaema o brate svoem? Pod âbloneû vozbudih tâ: tamo rodi tâ mati tvoâ, tamo pobole toboû roždšaâ tâ."],[8,6,"Положи мя яко печать на сердцы твоем, яко печать на мышце твоей: зане крепка яко смерть любы, жестока яко ад ревность: крила ея крила огня, (углие огненно) пламы ея.","Položi mâ âko pečatʹ na serdcy tvoem, âko pečatʹ na myšce tvoej: zane krepka âko smertʹ lûby, žestoka âko ad revnostʹ: krila eâ krila ognâ, (uglie ognenno) plamy eâ."],[8,7,"Вода многа не может угасити любве, и реки не потопят ея. Аще даст муж все имение свое за любовь, уничижением уничижат его.","Voda mnoga ne možet ugasiti lûbve, i reki ne potopât eâ. Aŝe dast muž vse imenie svoe za lûbovʹ, uničiženiem uničižat ego."],[8,8,"Сестра наша мала и сосцу не имать: что сотворим сестре нашей в день, в оньже аще глаголатися будет ей?","Sestra naša mala i soscu ne imatʹ: čto sotvorim sestre našej v denʹ, v onʹže aŝe glagolatisâ budet ej?"],[8,9,"Аще стена есть, соградим на ней забрала сребряна: и аще дверь есть, напишем на ней дску кедрову.","Aŝe stena estʹ, sogradim na nej zabrala srebrâna: i aŝe dverʹ estʹ, napišem na nej dsku kedrovu."],[8,10,"Аз стена, и сосцы мои яко столпи: аз бех во очию их аки обретающая мир.","Az stena, i soscy moi âko stolpi: az beh vo očiû ih aki obretaûŝaâ mir."],[8,11,"Виноград бысть Соломону во Вееламоне: даде виноград свой стрегущым: муж принесет в плоде его тысящу сребреник.","Vinograd bystʹ Solomonu vo Veelamone: dade vinograd svoj streguŝym: muž prineset v plode ego tysâŝu srebrenik."],[8,12,"Виноград мой предо мною: тысяща Соломону и двести стрегущым плод его.","Vinograd moj predo mnoû: tysâŝa Solomonu i dvesti streguŝym plod ego."],[8,13,"Седяй в вертоградех, и друзие внемлющии гласу твоему: глас твой внуши мне.","Sedâj v vertogradeh, i druzie vnemlûŝii glasu tvoemu: glas tvoj vnuši mne."],[8,14,"Бежи, брате мой, и уподобися серне или юнцу еленей, на горы ароматов.","Beži, brate moj, i upodobisâ serne ili ûncu elenej, na gory aromatov."]],"eng-thomson-partial":[[1,1,"A Song of Songs which is Solomons.","A Song of Songs which is Solomons."],[1,2,"Let him kiss me with the kisses of his mouth. Because thy breasts are better than wine;","Let him kiss me with the kisses of his mouth. Because thy breasts are better than wine;"],[1,3,"and the fragrance of thine odours is above all perfumes—Thy name out-poured oil, therefore the virgins have loved thee.","and the fragrance of thine odours is above all perfumes—Thy name out-poured oil, therefore the virgins have loved thee."],[1,4,"Thou art drawn: after thee we will run to the fragrance of thy perfumes. The king brought me into his inner apartment. Let us rejoice and be gladdened by thee. We will love thy breasts better than wine: rectitude hath loved thee.","Thou art drawn: after thee we will run to the fragrance of thy perfumes. The king brought me into his inner apartment. Let us rejoice and be gladdened by thee. We will love thy breasts better than wine: rectitude hath loved thee."],[1,5,"I am brown but comely, O daughters of Jerusalem; like the tents of Kedar—like the curtains of Solomon.","I am brown but comely, O daughters of Jerusalem; like the tents of Kedar—like the curtains of Solomon."],[1,6,"Look not on me, because I am of a dark complexion—Because the sun hath looked upon me. My mother's children quarrelled with me—They made me a keeper in the vineyards. Mine own vineyard I did not watch.","Look not on me, because I am of a dark complexion—Because the sun hath looked upon me. My mother's children quarrelled with me—They made me a keeper in the vineyards. Mine own vineyard I did not watch."],[1,7,"Tell me thou whom my soul loveth, where thou tendest thy flock—Where thou causest it to rest at noon, perhaps I may be like a wanderer among the tents of thy companions.","Tell me thou whom my soul loveth, where thou tendest thy flock—Where thou causest it to rest at noon, perhaps I may be like a wanderer among the tents of thy companions."],[1,8,"If thou wouldst not make thyself known, O fairest of women; go out by thyself in the track of the flock; and feed thy kids by the shepherds tents.","If thou wouldst not make thyself known, O fairest of women; go out by thyself in the track of the flock; and feed thy kids by the shepherds tents."],[1,9,"To that steed of mine in Pharao's chariot I have compared thee, my love!","To that steed of mine in Pharao's chariot I have compared thee, my love!"],[1,10,"What! thy cheeks are beautiful as a turtle dove's: and thy neck as strings of pearls.","What! thy cheeks are beautiful as a turtle dove's: and thy neck as strings of pearls."],[1,11,"We will make for thee suitable figures of gold with spangles of silver.","We will make for thee suitable figures of gold with spangles of silver."],[1,12,"While the king was at his banquet, my spikenard sent forth its odour.","While the king was at his banquet, my spikenard sent forth its odour."],[1,13,"My dear brother is to me a nosegay of stacte it shall be lodged in my bosom.","My dear brother is to me a nosegay of stacte it shall be lodged in my bosom."],[1,14,"My dear brother is to me a cluster of the cypress, in the vineyards of Engaddi.","My dear brother is to me a cluster of the cypress, in the vineyards of Engaddi."],[1,15,"Behold thou art fair, my love; behold thou art fair. Thine eyes are doves.","Behold thou art fair, my love; behold thou art fair. Thine eyes are doves."],[1,16,"Behold thou art comely, my dear brother—beautiful indeed! Near our bed thou wast shaded.","Behold thou art comely, my dear brother—beautiful indeed! Near our bed thou wast shaded."],[1,17,"The beams of our houses are cedar. Cypress our vaulted cielings.","The beams of our houses are cedar. Cypress our vaulted cielings."],[2,1,"I am a flower of the field, and a lilly of the vallies.","I am a flower of the field, and a lilly of the vallies."],[2,2,"As a lilly among thorns, so is my consort among the daughters.","As a lilly among thorns, so is my consort among the daughters."],[2,3,"As the citron tree among the trees of the forests; so is my dear brother among the youths. In its shade I took great delight and sat, and its fruit was sweet to my taste.","As the citron tree among the trees of the forests; so is my dear brother among the youths. In its shade I took great delight and sat, and its fruit was sweet to my taste."],[2,4,"O conduct me to the house of wine, and order for me what I love.","O conduct me to the house of wine, and order for me what I love."],[2,5,"Strengthen with perfumes—strew around me citrons, for I am wounded with love.","Strengthen with perfumes—strew around me citrons, for I am wounded with love."],[2,6,"Let his left hand be under my head, and his right embrace me!","Let his left hand be under my head, and his right embrace me!"],[2,7,"I have adjured you, O daughters of Jerusalem, by the powers and virtues of the field, that you stir not up nor awake my love till she please.","I have adjured you, O daughters of Jerusalem, by the powers and virtues of the field, that you stir not up nor awake my love till she please."],[2,8,"It is the voice of my dear brother! lo he cometh, bounding over the mountains—skipping over the hills. My dear brother is like a roe; or a young hart on the mountains of Baithor.","It is the voice of my dear brother! lo he cometh, bounding over the mountains—skipping over the hills. My dear brother is like a roe; or a young hart on the mountains of Baithor."],[2,9,"Lo! he is behind our wall, looking in at the windows, taking a near view through the lattice.","Lo! he is behind our wall, looking in at the windows, taking a near view through the lattice."],[2,10,"My dear brother addressing me saith, \"Arise my love, my fair one, my dove! For lo! the winter is past—the rain is over: is gone.","My dear brother addressing me saith, \"Arise my love, my fair one, my dove! For lo! the winter is past—the rain is over: is gone."],[2,11,"The flowers appear on the earth—the pruning season is come.","The flowers appear on the earth—the pruning season is come."],[2,12,"The voice of the turtle is heard in our land.","The voice of the turtle is heard in our land."],[2,13,"The fig tree hath put forth its green figs: the vines are in bloom—they have shed a fragrance.","The fig tree hath put forth its green figs: the vines are in bloom—they have shed a fragrance."],[2,14,"Arise, come my beloved, my fair one, my dove. Yes, come thou dove of mine: in the shelter of the rock near the wall. Shew me thy face and let me hear thy voice: for thy voice is sweet and thy countenance comely.\"","Arise, come my beloved, my fair one, my dove. Yes, come thou dove of mine: in the shelter of the rock near the wall. Shew me thy face and let me hear thy voice: for thy voice is sweet and thy countenance comely.\""],[2,15,"Catch for us the little foxes, that spoil vines: for our vines are in blossom.","Catch for us the little foxes, that spoil vines: for our vines are in blossom."],[2,16,"My dear brother is mine and I am his: he is feeding among the lillies.","My dear brother is mine and I am his: he is feeding among the lillies."],[2,17,"Till the day blow fresh and the shades be removed. Return—Be, O my dear brother, like a roe, or a young hart on the caverned mountains.","Till the day blow fresh and the shades be removed. Return—Be, O my dear brother, like a roe, or a young hart on the caverned mountains."],[3,1,"By night on my bed I sought him whom my soul loved. I sought him but did not find him. I called him but he made me no answer.","By night on my bed I sought him whom my soul loved. I sought him but did not find him. I called him but he made me no answer."],[3,2,"I will rise now and take a circuit in the city in the places of publick resort and in the streets; and seek him whom my soul loveth. I sought him but did not find him.","I will rise now and take a circuit in the city in the places of publick resort and in the streets; and seek him whom my soul loveth. I sought him but did not find him."],[3,3,"The watchmen who take their rounds in the city, met me. Saw ye him whom my soul loveth?","The watchmen who take their rounds in the city, met me. Saw ye him whom my soul loveth?"],[3,4,"It was but a little while after I parted from them, till I found him whom my soul loveth. I took hold of him and did not let him go till I brought him to my mother's house and into the chambers of her who conceived me.","It was but a little while after I parted from them, till I found him whom my soul loveth. I took hold of him and did not let him go till I brought him to my mother's house and into the chambers of her who conceived me."],[3,5,"I charged you, O daughters of Jerusalem by the powers and virtues of the field, not to stir up nor awake my love till he please.","I charged you, O daughters of Jerusalem by the powers and virtues of the field, not to stir up nor awake my love till he please."],[3,6,"What is this coming up from the wilderness; like a column of smoke, fuming with myrrh and incense made of all the perfumer's powders?","What is this coming up from the wilderness; like a column of smoke, fuming with myrrh and incense made of all the perfumer's powders?"],[3,7,"It is the palanquin of Solomon, three score chiefs of the chiefs of Israel are around it.","It is the palanquin of Solomon, three score chiefs of the chiefs of Israel are around it."],[3,8,"All swordsmen expert in war. Every man with his sword on his thigh, for fear of danger by night.","All swordsmen expert in war. Every man with his sword on his thigh, for fear of danger by night."],[3,9,"King Solomon had made himself a palanquin of the wood of Libanus.","King Solomon had made himself a palanquin of the wood of Libanus."],[3,10,"Its columns he made of silver, and his sofa was of gold. Its canopy was purple, and its inside carpeted with love, for the daughters of Jerusalem.","Its columns he made of silver, and his sofa was of gold. Its canopy was purple, and its inside carpeted with love, for the daughters of Jerusalem."],[3,11,"O daughter of Sion go forth and view king Solomon; in the crown with which his mother crowned him; on the day of his espousals—Even on the day of the gladness of his heart.","O daughter of Sion go forth and view king Solomon; in the crown with which his mother crowned him; on the day of his espousals—Even on the day of the gladness of his heart."],[4,1,"Behold, thou art fair, my love! Behold thou art fair! Thine eyes are doves, now thy veil is removed! thy hair is like the flocks of goats which are seen from mount Gralaad:","Behold, thou art fair, my love! Behold thou art fair! Thine eyes are doves, now thy veil is removed! thy hair is like the flocks of goats which are seen from mount Gralaad:"],[4,2,"thy teeth like the flocks of shorn sheep; which have just come up from the washing pool: they are all twins and there is not one defective among them.","thy teeth like the flocks of shorn sheep; which have just come up from the washing pool: they are all twins and there is not one defective among them."],[4,3,"Thy lips are like a braid of scarlet and thy speech is graceful: as the skin of a pomegranate, so are thy cheeks, now thy veil is removed.","Thy lips are like a braid of scarlet and thy speech is graceful: as the skin of a pomegranate, so are thy cheeks, now thy veil is removed."],[4,4,"Thy neck is like the tower of David, which was built for an armoury: on it are hung a thousand shields; all the javelins of the worthies.","Thy neck is like the tower of David, which was built for an armoury: on it are hung a thousand shields; all the javelins of the worthies."],[4,5,"Thy two breasts are like two twin fawns of a roe; which are browzing among lillies.","Thy two breasts are like two twin fawns of a roe; which are browzing among lillies."],[4,6,"Till the day breeze spring up and the shades are removed, I will go by myself to the mountain of myrrh, and to the hill of frankincense.","Till the day breeze spring up and the shades are removed, I will go by myself to the mountain of myrrh, and to the hill of frankincense."],[4,7,"Thou art altogether fair, my love and there is no blemish in thee.","Thou art altogether fair, my love and there is no blemish in thee."],[4,8,"Come from Libanus, my spouse; come from Libanus. Thou canst come, yes come safely from the top of Pistis—from the summit of Sanir and Herinon—from lions dens, from the leopards mountains.","Come from Libanus, my spouse; come from Libanus. Thou canst come, yes come safely from the top of Pistis—from the summit of Sanir and Herinon—from lions dens, from the leopards mountains."],[4,9,"Thou hast ravished my heart, my sister spouse: thou hast ravished my heart with a glance of thine eyes—with an endearing turn of thy neck.","Thou hast ravished my heart, my sister spouse: thou hast ravished my heart with a glance of thine eyes—with an endearing turn of thy neck."],[4,10,"How beautiful are thy breasts, my sister spouse! how much more pleasing than wine are thy breasts! and the smell of thy garments, than all spices!","How beautiful are thy breasts, my sister spouse! how much more pleasing than wine are thy breasts! and the smell of thy garments, than all spices!"],[4,11,"thy lips, my spouse, drop as a honey comb: honey and milk flow from thy tongue: and the fragrance of thy garments is like the smell of Lebanon.","thy lips, my spouse, drop as a honey comb: honey and milk flow from thy tongue: and the fragrance of thy garments is like the smell of Lebanon."],[4,12,"Thou art an enclosed garden, my sister spouse: a close shut garden; a sealed fountain.","Thou art an enclosed garden, my sister spouse: a close shut garden; a sealed fountain."],[4,13,"Thy productions are a paradise of pomegranates with delicious fruits; aromatic plants with the varieties of balsams—spikenard and saffron, sweet cane and cinnamon;","Thy productions are a paradise of pomegranates with delicious fruits; aromatic plants with the varieties of balsams—spikenard and saffron, sweet cane and cinnamon;"],[4,14,"with all kinds of trees of incense—myrrh, aloth with all the principal spices.","with all kinds of trees of incense—myrrh, aloth with all the principal spices."],[4,15,"A garden fountain and a well of living water, flowing with gentle murmurs from Libanus.","A garden fountain and a well of living water, flowing with gentle murmurs from Libanus."],[4,16,"Awake O north wind, come also, O south wind and blow gently through my garden, and let my aromatic spices flow. Let my dear brother come down to his garden; and taste the delicious fruits thereof.","Awake O north wind, come also, O south wind and blow gently through my garden, and let my aromatic spices flow. Let my dear brother come down to his garden; and taste the delicious fruits thereof."],[5,1,"I have come to my garden, my sister spouse: I have gathered my myrrh with my spices: I have eaten my bread with my honey; I have drunk my wine with my milk. Eat, O friends; drink—yes drink plentifully O brethren.","I have come to my garden, my sister spouse: I have gathered my myrrh with my spices: I have eaten my bread with my honey; I have drunk my wine with my milk. Eat, O friends; drink—yes drink plentifully O brethren."],[5,2,"I sleep; but my heart is awake. The voice of my dear brother! he knocketh at the door! \"Open to me, my sister, my dove, my consecrated one! for my head is filled with dew, and my locks with the drops of the night.\"","I sleep; but my heart is awake. The voice of my dear brother! he knocketh at the door! \"Open to me, my sister, my dove, my consecrated one! for my head is filled with dew, and my locks with the drops of the night.\""],[5,3,"I have put off my garment; how can I put it on? I have washed my feet; how can I defile them?","I have put off my garment; how can I put it on? I have washed my feet; how can I defile them?"],[5,4,"My dear brother withdrew his hand from the hole in the door. Whereupon my bowels yearned for him.","My dear brother withdrew his hand from the hole in the door. Whereupon my bowels yearned for him."],[5,5,"I rose to open for my dear brother; my hands dropped myrrh; and my fingers myrrh plenteously on the handles of the bar.","I rose to open for my dear brother; my hands dropped myrrh; and my fingers myrrh plenteously on the handles of the bar."],[5,6,"I opened for my dear brother. He was gone! my soul melted for the speech of him. I sought him but did not find him: I called him but he made me no answer.","I opened for my dear brother. He was gone! my soul melted for the speech of him. I sought him but did not find him: I called him but he made me no answer."],[5,7,"They who go the rounds in the city met me. They smote me—they wounded me. The keepers of the walls took my veil from me.","They who go the rounds in the city met me. They smote me—they wounded me. The keepers of the walls took my veil from me."],[5,8,"I adjured you, O daughters of Jerusalem by the powers and virtues of the field. If you found my dear brother—What should you tell him? Tell him that I am sick of love.","I adjured you, O daughters of Jerusalem by the powers and virtues of the field. If you found my dear brother—What should you tell him? Tell him that I am sick of love."],[5,9,"\"What is thy dear brother more than another brother, O fairest of women? What is thy dear brother more than another brother, that thou hast thus adjured us?\"","\"What is thy dear brother more than another brother, O fairest of women? What is thy dear brother more than another brother, that thou hast thus adjured us?\""],[5,10,"My dear brother is white and ruddy, he is the chiefest among tens of thousands.","My dear brother is white and ruddy, he is the chiefest among tens of thousands."],[5,11,"His head is gold of Kephas; his flowing locks black as a raven.","His head is gold of Kephas; his flowing locks black as a raven."],[5,12,"His eyes are like doves by streams of water—milk white doves sitting by streams.","His eyes are like doves by streams of water—milk white doves sitting by streams."],[5,13,"His cheeks are like beds of spices emitting perfumes; his lips are lillies distilling myrrh plenteously.","His cheeks are like beds of spices emitting perfumes; his lips are lillies distilling myrrh plenteously."],[5,14,"His hands are of gold, finely turned, beset with chrysolites: his body, an ivory cabinet on a sapphire stone:","His hands are of gold, finely turned, beset with chrysolites: his body, an ivory cabinet on a sapphire stone:"],[5,15,"his legs, pillars of marble fixed on pedestals of gold: his countenance like Libanus, majestic as the cedars his mouth is sweetness itself.","his legs, pillars of marble fixed on pedestals of gold: his countenance like Libanus, majestic as the cedars his mouth is sweetness itself."],[5,16,"He is altogether lovely. Such is my dear brother, and such my love, O daughters of Jerusalem.","He is altogether lovely. Such is my dear brother, and such my love, O daughters of Jerusalem."],[6,1,"\"Where did thy dear brother go, O fairest of women? Whither did thy dear brother bend his course; that we may seek him with thee?\"","\"Where did thy dear brother go, O fairest of women? Whither did thy dear brother bend his course; that we may seek him with thee?\""],[6,2,"My dear brother went down to his garden to the beds of spices; to feed in the garden and to gather lillies.","My dear brother went down to his garden to the beds of spices; to feed in the garden and to gather lillies."],[6,3,"I am my dear brother's and he is mine; he is feeding among the lillies!","I am my dear brother's and he is mine; he is feeding among the lillies!"],[6,4,"Thou my consort, art beautiful as Terzah; comely as Jerusalem; dazzling as embattled hosts!","Thou my consort, art beautiful as Terzah; comely as Jerusalem; dazzling as embattled hosts!"],[6,5,"Turn thine eyes aside from me for they have transported me. Thy hair is like a flock of goats which are seen on mount Galaad:","Turn thine eyes aside from me for they have transported me. Thy hair is like a flock of goats which are seen on mount Galaad:"],[6,6,"thy teeth like flocks of shorn sheep, just come up from washing: all twins and there is not one defective among them: thy lips are like a braid of scarlet, and thy speech is graceful.","thy teeth like flocks of shorn sheep, just come up from washing: all twins and there is not one defective among them: thy lips are like a braid of scarlet, and thy speech is graceful."],[6,7,"Thy cheek is like the downy skin of a pomegranate now thy veil is removed.","Thy cheek is like the downy skin of a pomegranate now thy veil is removed."],[6,8,"There are sixty queens and eighty concubines, and virgins without number: one is my dove, my consecrated one.","There are sixty queens and eighty concubines, and virgins without number: one is my dove, my consecrated one."],[6,9,"One is her mother's only child—the darling of her who bore her. Daughters viewed her—nay queens and even concubines will hail her happy and thus extoll her.","One is her mother's only child—the darling of her who bore her. Daughters viewed her—nay queens and even concubines will hail her happy and thus extoll her."],[6,10,"\"Who is she that is looking out like the morning; fair as the moon, distinguishable as the sun, and dazzling as embattled hosts.\"","\"Who is she that is looking out like the morning; fair as the moon, distinguishable as the sun, and dazzling as embattled hosts.\""],[6,11,"I went down to the garden of nuts to look at the productions of the valley: to seek whether the vine had budded or the pomegranate blossomed:","I went down to the garden of nuts to look at the productions of the valley: to seek whether the vine had budded or the pomegranate blossomed:"],[6,12,"I am there to grant thee my breasts. My soul did not recollect this. It made me like the chariots of Aminadab.","I am there to grant thee my breasts. My soul did not recollect this. It made me like the chariots of Aminadab."],[6,13,"Return, return, O Sunamite! return, return that we may see thee! What would you see in the Sunamite, who is coming like the moving bands of an army?","Return, return, O Sunamite! return, return that we may see thee! What would you see in the Sunamite, who is coming like the moving bands of an army?"],[7,1,"How beautiful were thy steps in thy sandals, daughter of Nadab? The infoldings of thy loins are like jewellery, the work of an artist:","How beautiful were thy steps in thy sandals, daughter of Nadab? The infoldings of thy loins are like jewellery, the work of an artist:"],[7,2,"thy clasp is a well turned goblet, not destitute of mingled wine: thy body is like a heap of wheat encompassed about with lillies:","thy clasp is a well turned goblet, not destitute of mingled wine: thy body is like a heap of wheat encompassed about with lillies:"],[7,3,"thy two breasts are like two twin fawns of a roe; thy neck is like a tower of ivory.","thy two breasts are like two twin fawns of a roe; thy neck is like a tower of ivory."],[7,4,"Thine eyes like the pools at Esebon by the gates of the daughter of many: thy nose is like the tower of Lebanon which looketh towards Damascus:","Thine eyes like the pools at Esebon by the gates of the daughter of many: thy nose is like the tower of Lebanon which looketh towards Damascus:"],[7,5,"thy head is like Carmel and the tresses of thy head like Purpura. The king is detained in the antichamber","thy head is like Carmel and the tresses of thy head like Purpura. The king is detained in the antichamber"],[7,6,"How beautiful thou art! and how sweet! O my love! how delightful!","How beautiful thou art! and how sweet! O my love! how delightful!"],[7,7,"In respect to thy stateliness, thou hast been compared to the palm tree, and thy breasts to its clusters.","In respect to thy stateliness, thou hast been compared to the palm tree, and thy breasts to its clusters."],[7,8,"I said, I will climb the palm tree—I will clasp its topmost boughs; and thy breasts shall be now like the clusters of the vine; and the smell of thy nose like citrons; and the roof of thy mouth like choice wine—","I said, I will climb the palm tree—I will clasp its topmost boughs; and thy breasts shall be now like the clusters of the vine; and the smell of thy nose like citrons; and the roof of thy mouth like choice wine—"],[7,9,"Which is poured out rightly for my dear brother properly adapted with my lips and my teeth.","Which is poured out rightly for my dear brother properly adapted with my lips and my teeth."],[7,10,"I am my dear brother's and towards me is his desire.","I am my dear brother's and towards me is his desire."],[7,11,"Come, my dear brother, let us go out to the fields.","Come, my dear brother, let us go out to the fields."],[7,12,"Let us lodge in the villages: let us get up early to the vineyards: let us see whether the vine is budded: whether the young grape has made its appearance: whether the pomegranates are in blossom. There I will grant thee my breasts.","Let us lodge in the villages: let us get up early to the vineyards: let us see whether the vine is budded: whether the young grape has made its appearance: whether the pomegranates are in blossom. There I will grant thee my breasts."],[7,13,"The mandrakes have shed a fragrance: and in our hoards are all manner of delicious fruits, newly gathered as well as old. For thee, my dear brother I have kept them.","The mandrakes have shed a fragrance: and in our hoards are all manner of delicious fruits, newly gathered as well as old. For thee, my dear brother I have kept them."],[8,1,"O that thou, my dear brother, hadst sucked the breasts of my mother; meeting thee abroad I could kiss thee and not be despised;","O that thou, my dear brother, hadst sucked the breasts of my mother; meeting thee abroad I could kiss thee and not be despised;"],[8,2,"I could take thee and conduct thee to my mother's house: and to the inmost apartment of her who conceived me, I could cause thee to drink spiced wine of the juice of my pomegranates;","I could take thee and conduct thee to my mother's house: and to the inmost apartment of her who conceived me, I could cause thee to drink spiced wine of the juice of my pomegranates;"],[8,3,"his left hand might be under my head and his right embrace me.","his left hand might be under my head and his right embrace me."],[8,4,"I have charged you, O daughters of Jerusalem, by the powers and virtues of the field; that you stir not up nor awake my love till she please.","I have charged you, O daughters of Jerusalem, by the powers and virtues of the field; that you stir not up nor awake my love till she please."],[8,5,"Who is this coming up cloathed in white leaning on her beloved? Under a citron tree I awaked thee. It was there thy mother bare thee. There she who brought thee forth suffered the pangs of childbirth.","Who is this coming up cloathed in white leaning on her beloved? Under a citron tree I awaked thee. It was there thy mother bare thee. There she who brought thee forth suffered the pangs of childbirth."],[8,6,"O set me as a seal on thy heart—as a seal on thine arm: for love is strong as death; jealousy inflexible as Hades: its wings are wings of fire its flames—","O set me as a seal on thy heart—as a seal on thine arm: for love is strong as death; jealousy inflexible as Hades: its wings are wings of fire its flames—"],[8,7,"Much water cannot quench love; nor can floods drown it. Though a man give all his substance for love, he may be thoroughly despised.","Much water cannot quench love; nor can floods drown it. Though a man give all his substance for love, he may be thoroughly despised."],[8,8,"Our sister is little and hath no breasts. What can we do for our sister on the day when she shall be demanded in marriage.","Our sister is little and hath no breasts. What can we do for our sister on the day when she shall be demanded in marriage."],[8,9,"If she be a wall we will build on her silver turrets, and if she be a door we will line her with boards of cedar.","If she be a wall we will build on her silver turrets, and if she be a door we will line her with boards of cedar."],[8,10,"I am a wall and my breasts are turrets. I was in their view as one who had found favour.","I am a wall and my breasts are turrets. I was in their view as one who had found favour."],[8,11,"Solomon had a vineyard at Beelamon, he let this vineyard of his to tenants, a man is to give him a thousand pieces of silver for its fruit.","Solomon had a vineyard at Beelamon, he let this vineyard of his to tenants, a man is to give him a thousand pieces of silver for its fruit."],[8,12,"My vineyard which is before me shall continue to be mine. Solomon shall have the thousand pieces of silver, and they who take care of its fruits, two hundred.","My vineyard which is before me shall continue to be mine. Solomon shall have the thousand pieces of silver, and they who take care of its fruits, two hundred."],[8,13,"Thou who art sitting in the gardens, companions are waiting thy voice. Let me hear it—","Thou who art sitting in the gardens, companions are waiting thy voice. Let me hear it—"],[8,14,"Away, my dear brother, and be like a roe; or a young hart on the mountains of spices.","Away, my dear brother, and be like a roe; or a young hart on the mountains of spices."]]}};